CREATE OR REPLACE PROCEDURE calculator.materialize_tickev (p_ticket_id tt.EVENT.ticket_id%type) AS $body$
DECLARE


    ora2pg_rowcount int;
v_out    smallint;
    v_first_event_date timestamp(0);
    v_last_status tt.STATUS.name%type;
    v_status tt.STATUS.name%type;
    v_emerg  varchar(32);
    v_eng    varchar(32);
    v_mcc    varchar(32);
    v_ttype  tt.TICKET_TYPE.NAME%type;
    v_ttype_initial smallint;
    v_label  varchar(32);
    v_last_event_id integer;

  e RECORD;

BEGIN

    v_out := 1;
    v_first_event_date := NULL;
    v_last_status := NULL;
    v_status := 'new';
    v_emerg := 'non-emergency';
    v_eng := '';
    v_mcc := 'MCC';
    v_ttype := '';
    v_ttype_initial := 1;
    v_label := '';
    v_last_event_id := null;


    select ty.name into STRICT v_ttype
    from tt.TICKET_TYPE ty, tt.TICKET t
    where t.ID = p_ticket_id
      and t.TYPE_ID = ty.ID;


    update tickev set update_dt = clock_timestamp(), deleted = 1 where ticket_id = p_ticket_id and deleted = 0;

    for e in (SELECT e.*
              from tt.EVENT e
              where e.TICKET_ID = p_ticket_id
              AND e.ORG_TICKET_ID IS NULL
              order by e.db_date, e.id) loop
        IF v_first_event_date is null
        THEN
          v_first_event_date := e.DB_DATE;
        end if;

        
        
        
        
        
        
        
        
        
        
        

        
        IF (e.TYPE_ID in (101002, 101003, 101101, 101102,  101060, 101004, 101011, 101012, 101061, 101110, 101120) and e.DETAILS_PUBLIC like 'New status: %')
            OR (e.TYPE_ID IN (100004))
        THEN
          
          
          IF e.TYPE_ID in (101002, 101003, 101101, 101102,  101060, 101004, 101011, 101012, 101061, 101110, 101120)
          THEN
            v_status := (SELECT array_to_string(a, '') FROM regexp_matches(e.DETAILS_PUBLIC, '^New status: (.+)$', 'g') AS foo(a) LIMIT 1 OFFSET (1 - 1) );
          
          ELSIF e.TYPE_ID IN (100004)
          THEN
            v_status := 'merged';
          END IF;

          IF v_status != v_last_status
          THEN
            v_out := 1;
          END IF;



        ELSIF e.TYPE_ID = 100003 and e.DETAILS_PRIVATE like 'Engineer changed to:%'
        THEN  
            
          v_eng := (SELECT array_to_string(a, '') FROM regexp_matches(e.DETAILS_PRIVATE, '^Engineer changed to: ([^ .]+)', 'g') AS foo(a) LIMIT 1 OFFSET (1 - 1) );

          v_mcc := (SELECT array_to_string(a, '') FROM regexp_matches(e.DETAILS_PRIVATE, '^Engineer changed to: [^ ]+ \(((non-)?MCC)\)', 'g') AS foo(a) LIMIT 1 OFFSET (1 - 1) );


          IF v_eng = 'MCC'
          THEN
            v_eng := '';
            v_mcc := 'MCC';
          end IF;
          v_out := 1;



        ELSIF e.TYPE_ID = 100003 and e.DETAILS_PUBLIC like '%emergency%'
        THEN 
          IF e.DETAILS_PUBLIC like 'ticket changed to emergency'
          THEN
            IF v_status = 'new' and v_emerg = 'non-emergency'
            THEN
              
              update tickev set emergency_state = 'emergency', update_dt = clock_timestamp()
              where ticket_id = e.ticket_id
                and deleted = 0
                and emergency_state = 'non-emergency'
                and e.eventdate < date_from + 60;
              GET DIAGNOSTICS ora2pg_rowcount = ROW_COUNT;
IF ora2pg_rowcount = 0
              THEN

                v_out := 1;
              end if;
            ELSE
              v_out := 1;
            END IF;
            v_emerg := 'emergency';
          ELSIF e.DETAILS_PUBLIC like 'ticket changed to non-emergency'
          THEN
            v_emerg := 'non-emergency';
            v_out := 1;
          END IF;



        ELSIF e.TYPE_ID = 100003 and e.DETAILS_PRIVATE like 'Ticket label %'
        THEN 
          IF e.DETAILS_PRIVATE like 'Ticket label % added'
          THEN
            v_label := (SELECT array_to_string(a, '') FROM regexp_matches(e.DETAILS_PRIVATE, '^Ticket label ([^ ]+) added', 'g') AS foo(a) LIMIT 1 OFFSET (1 - 1) );
          ELSIF e.DETAILS_PRIVATE like 'Ticket label changed to %'
          THEN
            v_label := (SELECT array_to_string(a, '') FROM regexp_matches(e.DETAILS_PRIVATE, '^Ticket label changed to ([^ ]+)', 'g') AS foo(a) LIMIT 1 OFFSET (1 - 1) );
          ELSIF e.DETAILS_PRIVATE like 'Ticket label removed %'
          THEN
            v_label := NULL;
          END IF;
          v_out := 1;


        ELSIF e.TYPE_ID = 100005 and e.DETAILS_PUBLIC like 'type changed from %'
        THEN 
          IF v_ttype_initial = 1
          THEN
            
            v_ttype := (SELECT array_to_string(a, '') FROM regexp_matches(e.DETAILS_PUBLIC, '^type changed from ([a-z ]+) to ([a-z ]+)$', 'g') AS foo(a) LIMIT 1 OFFSET (1 - 1) );
            update tickev set ticket_type = v_ttype, update_dt = clock_timestamp() where ticket_id = e.ticket_id and deleted = 0;
            v_ttype_initial := 0;
          end IF;
          v_ttype := (SELECT array_to_string(a, '') FROM regexp_matches(e.DETAILS_PUBLIC, '^type changed from ([a-z ]+) to ([a-z ]+)$', 'g') AS foo(a) LIMIT 1 OFFSET (1 - 1) );
          v_out := 1;
        end IF;

        IF v_out = 1
        THEN
          IF v_last_status is null and v_status != 'new'
          THEN
              insert into tickev(EVENT_ID, TICKET_ID, TICKET_STATUS, EMERGENCY_STATE, ASSIGNED_ENGINEER, MCC_STATE, TICKET_TYPE, TICKET_LABEL, DATE_FROM, DATE_TO, update_dt, TICKET_STATUS_ID)
              values (e.ID, e.TICKET_ID, 'new', v_emerg, '', v_mcc, v_ttype, v_label, v_first_event_date, e.DB_DATE, clock_timestamp(), (SELECT min(ID) from TT.STATUS WHERE NAME = 'new'));
          end if;

          IF v_last_event_id is not null
          THEN
            update tickev
            set date_to = e.DB_DATE, update_dt = clock_timestamp()
            where ticket_id = p_ticket_id
              and event_id = v_last_event_id
              and deleted = 0;
          end IF;

          insert into tickev(EVENT_ID, TICKET_ID, TICKET_STATUS, EMERGENCY_STATE, ASSIGNED_ENGINEER, MCC_STATE, TICKET_TYPE, TICKET_LABEL, DATE_FROM, DATE_TO, update_dt, TICKET_STATUS_ID)
          values (e.ID, e.TICKET_ID, v_status, v_emerg, v_eng, v_mcc, v_ttype, v_label, e.DB_DATE, e.DB_DATE, clock_timestamp(), (SELECT min(ID) from TT.STATUS WHERE NAME = v_status));
          v_last_event_id := e.ID;
          v_last_status := v_status;
          v_out := 0;
        end IF;


      end loop;
  end;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE calculator.materialize_tickev (p_ticket_id tt.EVENT.ticket_id%type) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE calculator.materialize_incremental () AS $body$
DECLARE

    v_last_run timestamp(0);
    v_this_run timestamp(0);

  r RECORD;

BEGIN
     v_this_run := clock_timestamp();
     begin
       select value_dt into STRICT v_last_run from state where key = 'LAST_RUN';
     exception
       when no_data_found then
          v_last_run := clock_timestamp() - interval '365 days';
          insert into state(key, value_dt) values ('LAST_RUN', v_last_run);
          commit;
     end;

     for r in (SELECT t.id
              from tt.TICKET t
              where cast(UPDATE_TIMESTAMP as timestamp(0)) > v_last_run ) loop
       CALL calculator.materialize_tickev(r.id);
       commit;
     end loop;

     update state set value_dt = v_this_run where key = 'LAST_RUN';
     commit;
  end;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE calculator.materialize_incremental () FROM PUBLIC;
