CREATE OR REPLACE PROCEDURE connectivity_coordinator.end_interrupt_prod ( p_host_id mss.host.id%TYPE, p_up_date mc.connection_interrupt_closed.up_date%TYPE ) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(32) := 'end_interrupt(): ';
        row_interrupt  mc.connection_interrupt_open%ROWTYPE;


BEGIN

        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        SELECT * INTO STRICT row_interrupt
        FROM connection_interrupt_open
        WHERE host_id = p_host_id
            FOR EXECUTE UPDATE;


        INSERT INTO connection_interrupt_closed(id, down_date, up_date,
                                                 type_id, minutes, details, event_id, host_id, active,
                                                 interrupt_review_status_id)
        VALUES (row_interrupt.id, row_interrupt.down_date, p_up_date, row_interrupt.type_id,
                round((p_up_date - row_interrupt.down_date) * 24*60), row_interrupt.details,
                row_interrupt.event_id, p_host_id, row_interrupt.active, row_interrupt.interrupt_review_status_id);


        
        DELETE FROM connection_interrupt_open
        WHERE id = row_interrupt.id;
        RETURN;


        


    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE connectivity_coordinator.end_interrupt_prod ( p_host_id mss.host.id%TYPE, p_up_date mc.connection_interrupt_closed.up_date%TYPE ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE connectivity_coordinator.sync_interrupt_prod ( p_host_id mss.host.id%TYPE, p_interrupt_type mc.connection_interrupt_open.type_id%TYPE, p_details mc.connection_interrupt_open.details%TYPE, p_timestamp mc.HOST_CONNECTION_STATUS.con_timestamp%TYPE ) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(32) := 'sync_interrupt(): ';
        v_closed_count bigint;
        v_open_count bigint;
        v_interrupt_type_old mc.connection_interrupt_open.type_id%TYPE;
        v_interrupt_type_hostconnectionstatus mc.connection_interrupt_open.type_id%TYPE;
        v_interrupt_type_new mc.connection_interrupt_open.type_id%TYPE;
        v_active         mc.connection_interrupt_open.active%TYPE  := 1;

        p_date mc.connection_interrupt_open.down_date%TYPE;
        row_interrupt  mc.connection_interrupt_open%ROWTYPE;



BEGIN
      plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

		 SELECT CAST( (timestamp  '1970-01-01 00:00:00' + (p_timestamp * ('1'||'second' )::interval), 'UTC' )::timestamp with time zone AT time ZONE 'Europe/Zurich' AS timestamp(0) )  INTO STRICT p_date;


      IF ( p_interrupt_type = 4 ) THEN
        v_interrupt_type_hostconnectionstatus := NULL;
      ELSE
        v_interrupt_type_hostconnectionstatus := p_interrupt_type;
      END IF;

      MERGE INTO MC.HOST_CONNECTION_STATUS HCS USING dual ON ( HOST_ID = p_host_id )
        WHEN MATCHED THEN UPDATE SET
            HCS.CON_TIMESTAMP=p_timestamp,  
            HCS.DETAILS= p_details , 
            HCS.CON_INT_TYPE_ID= v_interrupt_type_hostconnectionstatus 
        WHEN NOT MATCHED THEN INSERT(HOST_ID, CON_TIMESTAMP, DETAILS, CON_INT_TYPE_ID) 
        VALUES ( p_host_id, p_timestamp, p_details, v_interrupt_type_hostconnectionstatus );


        SELECT COUNT(*), MAX(type_id)
        INTO STRICT v_open_count, v_interrupt_type_old
        FROM connection_interrupt_open
        WHERE host_id = p_host_id;


        SELECT COUNT(*)
        INTO STRICT v_closed_count
        FROM connection_interrupt_closed
        WHERE host_id = p_host_id;

        SELECT active INTO STRICT v_active FROM mss.HOST h WHERE id = p_host_id;

        IF ( v_active = 0 ) THEN
            v_interrupt_type_new := 0;
        ELSE
       		v_interrupt_type_new := p_interrupt_type;
        END IF;

        IF ( v_closed_count < 1 ) THEN

            INSERT INTO connection_interrupt_closed(id, up_date, details, host_id, active)
                        VALUES (nextval('connection_interrupt_sequence'), p_date, 'service activation', p_host_id, v_active);
        END IF;



        
        
        

        
        IF ( v_interrupt_type_new IS NULL ) THEN 

            IF ( v_open_count > 0 ) THEN

                CALL connectivity_coordinator.end_interrupt_prod( p_host_id, p_date );

            END IF;

            
        ELSE

            
            IF ( v_interrupt_type_old = v_interrupt_type_new ) THEN
                RETURN;
            END IF;

            IF ( v_open_count > 0 ) THEN 
                CALL connectivity_coordinator.end_interrupt_prod( p_host_id, p_date );
            END IF;

            INSERT INTO connection_interrupt_open(
                id,
                down_date,
                type_id, 
                details, 
                host_id, 
                event_id, 
                active
            ) VALUES (nextval('connection_interrupt_sequence'), p_date, v_interrupt_type_new, p_details, p_host_id, NULL, v_active);

        END IF;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE connectivity_coordinator.sync_interrupt_prod ( p_host_id mss.host.id%TYPE, p_interrupt_type mc.connection_interrupt_open.type_id%TYPE, p_details mc.connection_interrupt_open.details%TYPE, p_timestamp mc.HOST_CONNECTION_STATUS.con_timestamp%TYPE ) FROM PUBLIC;



CREATE OR REPLACE FUNCTION connectivity_coordinator.get_state ( p_mode bigint, p_sang bigint ) RETURNS bigint AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(32) := 'connectivity_coordinator.get_state(): ';
        v_result bigint;


BEGIN
        IF ( p_mode = mc.monitoring_state.MODE_ACTIVE ) THEN
            RETURN p_sang;
        ELSE
            IF ( p_sang = 1 ) THEN
                RETURN mc.monitoring_state.STATE_ISP_SW;
            ELSE
                RETURN mc.monitoring_state.STATE_DOWN_SW;
            END IF;
        END IF;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION connectivity_coordinator.get_state ( p_mode bigint, p_sang bigint ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE connectivity_coordinator.update_isp_link_status_w_date ( p_isp_link_id mc.isp_link_history.isp_link_id%type, p_status mc.isp_link_status_type.id%type, p_previous_status mc.isp_link_status_type.id%type, p_reported_by mc.isp_link_history.reporting_host_id%type, on_date mc.isp_link_history.change_date%type ) AS $body$
DECLARE


    v_previous_status mc.isp_link_status_type.id%type;
    v_change_date     mc.isp_link_history.change_date%type;
    v_event_id        mc.isp_link_history.event_id%type;
    v_isp_count       bigint;


BEGIN
    plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
    SELECT count(*) INTO STRICT v_isp_count
    FROM mss.isp_link
    WHERE id = p_isp_link_id;

    IF ( v_isp_count > 0 ) THEN
      SELECT ISP_LINK_STATUS_TYPE_ID
      INTO STRICT v_previous_status
      FROM mss.isp_link
      WHERE id = p_isp_link_id;



      v_event_id := NULL;

      IF ( v_previous_status IS NULL ) THEN
        v_previous_status := 1;
      END IF;


      
      
      IF ( v_previous_status != p_status ) THEN

        
        IF ( v_previous_status != p_previous_status
          AND p_previous_status != 0
          AND p_previous_status != 1 ) THEN
          
          
          
          plog.warning('[TLDR; ESCALATE TO #sre-team] UNEXPECTED ISP status reported as previous status: ' ||p_previous_status
            ||'. The stored status for ISP '||p_isp_link_id||' in the db is: '||v_previous_status
            ||'. Will write change from status '||v_previous_status
            ||' to '||p_status||'. Please kindly escalate this to #sre-team for investigation');
        END IF;


        INSERT INTO mc.isp_link_history(
          id,
          isp_link_id,
          reporting_host_id,
          old_isp_link_status_type_id,
          new_isp_link_status_type_id,
          change_date,
          event_id)
        VALUES (nextval('isp_link_history_seq'),
                p_isp_link_id,
                p_reported_by,
                v_previous_status,
                p_status,
                on_date,
                v_event_id);


        UPDATE mss.isp_link
        SET mss.isp_link.ISP_LINK_STATUS_TYPE_ID     = p_status
        WHERE mss.isp_link.id                        = p_isp_link_id;

      END IF;
    END IF;

  EXCEPTION
    WHEN no_data_found THEN


      
      INSERT INTO mc.isp_link_history(
        id,
        isp_link_id,
        reporting_host_id,
        old_isp_link_status_type_id,
        new_isp_link_status_type_id,
        change_date,
        event_id)
      VALUES (nextval('isp_link_history_seq'),
              p_isp_link_id,
              p_reported_by,
              v_previous_status,
              p_status,
              on_date,
              v_event_id);


      UPDATE mss.isp_link
      SET ISP_LINK_STATUS_TYPE_ID   = p_status
      WHERE id                      = p_isp_link_id;

  END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE connectivity_coordinator.update_isp_link_status_w_date ( p_isp_link_id mc.isp_link_history.isp_link_id%type, p_status mc.isp_link_status_type.id%type, p_previous_status mc.isp_link_status_type.id%type, p_reported_by mc.isp_link_history.reporting_host_id%type, on_date mc.isp_link_history.change_date%type ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE connectivity_coordinator.update_isp_link_status ( p_isp_link_id mc.isp_link_history.isp_link_id%type, p_status mc.isp_link_status_type.id%type, p_previous_status mc.isp_link_status_type.id%type, p_reported_by mc.isp_link_history.reporting_host_id%type ) AS $body$
DECLARE



    v_previous_status mc.isp_link_status_type.id%type;
    v_change_date     mc.isp_link_history.change_date%type;
    v_event_id        mc.isp_link_history.event_id%type;
    v_isp_count       bigint;


BEGIN
    plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

