CREATE OR REPLACE PROCEDURE connectivity_coordinator.sync_isp_link_status ( p_isp_link_id mc.isp_link_history.isp_link_id%type, p_status mc.isp_link_status_type.id%type ) AS $body$
DECLARE


    v_previous_status mc.isp_link_status_type.id%type;
    v_change_date     mc.isp_link_history.change_date%type;
    v_event_id        mc.isp_link_history.event_id%type;
    v_isp_count       bigint;


BEGIN
    plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
    SELECT count(*) INTO STRICT v_isp_count
    FROM mss.isp_link
    WHERE id = p_isp_link_id;

    IF ( v_isp_count > 0 ) THEN
      SELECT ISP_LINK_STATUS_TYPE_ID
      INTO STRICT v_previous_status
      FROM mss.isp_link
      WHERE id = p_isp_link_id;



      v_event_id := NULL;

      IF ( v_previous_status IS NULL ) THEN
        v_previous_status := 1;
      END IF;


      
      
      IF ( v_previous_status != p_status ) THEN

        
        INSERT INTO mc.isp_link_history(
          id,
          isp_link_id,
          old_isp_link_status_type_id,
          new_isp_link_status_type_id,
          change_date,
          event_id)
        VALUES (nextval('isp_link_history_seq'),
                p_isp_link_id,
                v_previous_status,
                p_status,
                clock_timestamp(),
                v_event_id);

      END IF;



    UPDATE mss.isp_link
    SET mss.isp_link.ISP_LINK_STATUS_TYPE_ID     = p_status
    WHERE mss.isp_link.id                        = p_isp_link_id;

    END IF;

  EXCEPTION
    WHEN no_data_found THEN


      
      INSERT INTO mc.isp_link_history(
        id,
        isp_link_id,
        old_isp_link_status_type_id,
        new_isp_link_status_type_id,
        change_date,
        event_id)
      VALUES (nextval('isp_link_history_seq'),
              p_isp_link_id,
              v_previous_status,
              p_status,
              clock_timestamp(),
              v_event_id);


      UPDATE MSS.ISP_LINK
      SET ISP_LINK_STATUS_TYPE_ID   = p_status
      WHERE id                      = p_isp_link_id;

  END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE connectivity_coordinator.sync_isp_link_status ( p_isp_link_id mc.isp_link_history.isp_link_id%type, p_status mc.isp_link_status_type.id%type ) FROM PUBLIC;
