CREATE OR REPLACE FUNCTION consistency.exec_formatted ( cur text ) RETURNS varchar AS $body$
DECLARE

    col_cnt     integer;
    rec_tab     dbms_sql.desc_tab;
    handle      integer;
    v_v_val     varchar(4000);
    v_n_val     bigint;
    v_d_val     timestamp(0);
    v_finaltxt  varchar(4000);
    ignore integer;

BEGIN
    DECLARE
      err_num bigint;
      err_msg varchar(100);
    BEGIN

      EXECUTE cur;
      GET DIAGNOSTICS ignore = ROW_COUNT;

    return v_finaltxt;

  END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
 STABLE;
