--
-- dblink wrapper to call function consistency.insert_result() as an autonomous transaction
--
CREATE EXTENSION IF NOT EXISTS dblink;

CREATE OR REPLACE PROCEDURE consistency.insert_result (p_check_id text, p_severity text, p_message text, p_xml_msg text, p_check_group text DEFAULT '') AS $body$
DECLARE
	-- Change this to reflect the dblink connection string
	v_conn_str  text := format('port=%s dbname=%s user=%s', current_setting('port'), current_database(), current_user);
	v_query     text;

BEGIN
	v_query := 'CALL consistency.insert_result_atx ( ' || quote_nullable(p_check_id) || ',' || quote_nullable(p_severity) || ',' || quote_nullable(p_message) || ',' || quote_nullable(p_xml_msg) || ',' || quote_nullable(p_check_group) || ' )';
	PERFORM * FROM dblink(v_conn_str, v_query) AS p (ret boolean);

END;
$body$ LANGUAGE plpgsql SECURITY DEFINER;




CREATE OR REPLACE PROCEDURE consistency.insert_result_atx (p_check_id text, p_severity text, p_message text, p_xml_msg text, p_check_group text DEFAULT '') AS $body$
BEGIN
    MERGE INTO MCDB_MONITOR.LAST_CONSISTENCY_CHECK_RESULTS r USING dual ON ( r.check_id = p_check_id )
    WHEN MATCHED THEN UPDATE SET r.LAST_RUN = CURRENT_TIMESTAMP , r.message =  p_message, r.XML_MESSAGE = p_xml_msg, r.LOGLEVEL = p_severity
    WHEN NOT MATCHED THEN INSERT(CHECK_ID, CHECK_GROUP, MESSAGE, XML_MESSAGE, LOGLEVEL, LAST_RUN)
                          VALUES ( p_check_id, p_check_group, p_message, p_xml_msg, p_severity, CURRENT_TIMESTAMP);


  END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE consistency.insert_result (p_check_id text, p_severity text, p_message text, p_xml_msg text, p_check_group text DEFAULT '') FROM PUBLIC; -- REVOKE ALL ON PROCEDURE consistency.insert_result_atx (p_check_id text, p_severity text, p_message text, p_xml_msg text, p_check_group text DEFAULT '') FROM PUBLIC;

--
-- dblink wrapper to call function consistency.execute_checks_group() as an autonomous transaction
--
CREATE EXTENSION IF NOT EXISTS dblink;

CREATE OR REPLACE PROCEDURE consistency.execute_checks_group ( group_name text, level_log boolean DEFAULT false, edge_log boolean DEFAULT true) AS $body$
DECLARE
	-- Change this to reflect the dblink connection string
	v_conn_str  text := format('port=%s dbname=%s user=%s', current_setting('port'), current_database(), current_user);
	v_query     text;

BEGIN
	v_query := 'CALL consistency.execute_checks_group_atx ( ' || quote_nullable(group_name) || ',' || quote_nullable(level_log) || ',' || quote_nullable(edge_log) || ' )';
	PERFORM * FROM dblink(v_conn_str, v_query) AS p (ret boolean);

END;
$body$ LANGUAGE plpgsql SECURITY DEFINER;




CREATE OR REPLACE PROCEDURE consistency.execute_checks_group_atx ( group_name text, level_log boolean DEFAULT false, edge_log boolean DEFAULT true) AS $body$
DECLARE

    stmt_cursor CURSOR FOR
      SELECT c.CHECK_KEY, c.STATEMENT, c.SLOGLEVEL,c.PLOGLEVEL,r.LAST_RESULT_HASH, c.MESSAGE , c.ID
      from MCDB_CHECKS.CONSISTENCY_CHECKS c
           LEFT OUTER JOIN MCDB_CHECKS.CONSISTENCY_CHECK_RUN r
                           ON (c.ID = r.ID)
      where c.CHECK_GROUP = group_name;
    v_message varchar(4000);
    v_xml_msg text;
    v_severity varchar(40);
    v_raw_conversion_buf varchar(10000);
    v_msg_hash bytea;
BEGIN
    for check_rec in stmt_cursor
      LOOP
        DECLARE
          l_cursor   REFCURSOR;
        BEGIN
          v_message := consistency.exec_formatted(check_rec.STATEMENT);
          v_xml_msg := null;
          IF (v_message IS NOT NULL) THEN

            
            IF ( SUBSTR(v_message,1,5) = 'ERROR' ) THEN
              v_message := v_message;
              v_severity := 'QUERY_ERROR';
            else
              v_message := 'MCDB_CHECKS '|| check_rec.MESSAGE || CHR(10) || substr(v_message, 0, 4000 - LENGTH( check_rec.MESSAGE) - 20);
              v_severity := check_rec.SLOGLEVEL;
              v_xml_msg  := dbms_xmlgen.getxml(check_rec.STATEMENT);
            end if;
          ELSE
            v_severity := 'CLEAR';
          END IF;
          v_raw_conversion_buf := v_message;
          v_msg_hash := DBMS_CRYPTO.HASH(encode(v_raw_conversion_buf::bytea, 'hex')::bytea, DBMS_CRYPTO.HASH_SH1);
          if (coalesce(v_msg_hash, '-') != coalesce(check_rec.LAST_RESULT_HASH, '-')) THEN

            
            IF edge_log and v_severity != 'CLEAR' THEN
              CALL OSAG.OSAG_PLOG.LOG(check_rec.PLOGLEVEL, 'MCDB_CHECKS '|| check_rec.MESSAGE);
            END IF;
            CALL consistency.insert_result(check_rec.CHECK_KEY, v_severity, v_message, v_xml_msg, group_name);

            merge into MCDB_CHECKS.CONSISTENCY_CHECK_RUN chkrun
            using(SELECT ID, CHECK_KEY FROM MCDB_CHECKS.CONSISTENCY_CHECKS
                   WHERE ID = check_rec.ID ) chkdef
            on (chkdef.ID = chkrun.ID)
            when matched then update set
                                       chkrun.CHECK_KEY = chkdef.CHECK_KEY,
                                       chkrun.LAST_RUN  = CURRENT_TIMESTAMP,
                                       chkrun.LAST_RESULT_HASH = v_msg_hash
            when not matched then insert(id, check_key, last_run, last_result_hash)
                                  VALUES (chkdef.ID, chkdef.CHECK_KEY, CURRENT_TIMESTAMP, v_msg_hash );
          else
            merge into MCDB_CHECKS.CONSISTENCY_CHECK_RUN chkrun
            using(SELECT ID, CHECK_KEY FROM MCDB_CHECKS.CONSISTENCY_CHECKS
                   WHERE ID = check_rec.ID ) chkdef
            on (chkdef.ID = chkrun.ID)
            when matched then update set
                                       chkrun.CHECK_KEY = chkdef.CHECK_KEY,
                                       chkrun.LAST_RUN  = CURRENT_TIMESTAMP
            when not matched then insert(id, check_key, last_run)
                                  VALUES (chkdef.ID, chkdef.CHECK_KEY, CURRENT_TIMESTAMP);
          end if;

          
          IF level_log AND v_severity != 'CLEAR' THEN
            CALL OSAG.OSAG_PLOG.LOG(check_rec.PLOGLEVEL, 'MCDB_CHECKS '|| check_rec.MESSAGE);
          END IF;

        END;
      end loop;
  END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE consistency.execute_checks_group ( group_name text, level_log boolean DEFAULT false, edge_log boolean DEFAULT true) FROM PUBLIC; -- REVOKE ALL ON PROCEDURE consistency.execute_checks_group_atx ( group_name text, level_log boolean DEFAULT false, edge_log boolean DEFAULT true) FROM PUBLIC;
-- End of Oracle package 'CONSISTENCY' declaration



-- Oracle package 'DMARC_CLEANUP' declaration, please edit to match PostgreSQL syntax.

DROP SCHEMA IF EXISTS dmarc_cleanup CASCADE;
CREATE SCHEMA IF NOT EXISTS dmarc_cleanup;





CREATE OR REPLACE PROCEDURE dmarc_cleanup.cleanup_reports_aged_days (days bigint) AS $body$
BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        DECLARE
            deadlock_detected EXCEPTION;
            PRAGMA EXCEPTION_INIT(deadlock_detected, -60);

            
            invalid_days_range EXCEPTION;
            PRAGMA exception_init(invalid_days_range, -20001);
        BEGIN
            IF (days < 1) THEN
                RAISE EXCEPTION '%', 'Number of days to keep must be positive' USING ERRCODE = '45001';
                plog.ERR('Number of days to keep must be positive');
            END IF;
            LOOP
                BEGIN
                    DELETE
                    from mail.DMARC_REPORT_RECORD
                    where exists(
                                  SELECT 1
                                  from mail.DMARC_REPORT
                                  where mail.DMARC_REPORT_RECORD.DMARC_REPORT_ID = mail.DMARC_REPORT.ID
                                    and mail.DMARC_REPORT.START_DATE < (clock_timestamp() - days)
                              );

                    DELETE
                    from mail.DMARC_REPORT
                    where mail.DMARC_REPORT.START_DATE < (clock_timestamp() - days);
                    exit;
                EXCEPTION
                    WHEN deadlock_detected THEN BEGIN
                        plog.NOTICE('Failed, sleeping');
                        pg_sleep(60);
                    END;
                    WHEN OTHERS THEN
                        raise;
                END;
            END LOOP;
        END;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE dmarc_cleanup.cleanup_reports_aged_days (days bigint) FROM PUBLIC;
-- End of Oracle package 'DMARC_CLEANUP' declaration



