CREATE OR REPLACE PROCEDURE escalation_interface.escalate_os (p_event_id bigint) AS $body$
DECLARE


        v_company_id bigint;
        v_host_id bigint;
        v_ticket_id bigint;
        v_host_active bigint;
        v_escalation_status_id bigint;
        v_event_id bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        plog.debug('escalate_to_os called for event id ' || p_event_id);

        BEGIN

            SELECT e.ticket_id into STRICT v_ticket_id
            FROM tt.event e
            WHERE e.id = p_event_id;


            SELECT escalation_status_id INTO STRICT v_escalation_status_id FROM ticket WHERE id = v_ticket_id;


            SELECT t.host_id into STRICT v_host_id
            FROM tt.ticket t
            WHERE t.id = v_ticket_id;


            
            SELECT h.active INTO STRICT v_host_active
            FROM mss.host h
            WHERE h.id = v_host_id;

        EXCEPTION
            WHEN no_data_found THEN
                v_host_id := NULL;
        END;

        plog.debug('ticket id is ' || v_ticket_id);
        plog.debug('host id is ' || v_host_id);


        
        IF (v_escalation_status_id IN (10,11)) THEN
            RETURN;
        END IF;


        IF (v_host_active = 1 OR v_host_id IS null) THEN
            plog.debug('escalate ticket ' || v_ticket_id);


            
            UPDATE tt.ticket SET escalation_status_id = 10, last_escalation_date = clock_timestamp() WHERE id = v_ticket_id;


            CALL event_interface.addevent_new(v_event_id,
                                         v_ticket_id,
                                         60001,
                                         v_host_id,
                                         'Starting escalation to Open Systems Mission Control',
                                         'Event added by tt.escalation_interface.escalate_os(). Caused by event '||p_event_id);

        END IF;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE escalation_interface.escalate_os (p_event_id bigint) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE escalation_interface.escalate_customer (p_event_id bigint) AS $body$
DECLARE


        ora2pg_rowcount int;
v_ticket_id bigint;
        v_host_id bigint;
        v_host_active bigint;
        v_escalation_status_id bigint;
        v_event_id bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        BEGIN

            SELECT e.ticket_id into STRICT v_ticket_id
            FROM tt.event e
            WHERE e.id = p_event_id;


            
            SELECT t.escalation_status_id, t.host_id INTO STRICT v_escalation_status_id, v_host_id
            FROM tt.ticket t
            WHERE t.id = v_ticket_id;


            
            SELECT h.active INTO STRICT v_host_active
            FROM mss.host h
            WHERE h.id = v_host_id;

        EXCEPTION
            WHEN no_data_found THEN
                v_host_id := NULL;
        END;


        
        IF (v_escalation_status_id <> 0) THEN
            RETURN;
        END IF;


        IF (v_host_active = 1 OR v_host_id IS null) THEN
            UPDATE tt.ticket SET escalation_status_id = 10, last_escalation_date = clock_timestamp() WHERE ticket.id = v_ticket_id AND escalation_status_id <> 10;


            GET DIAGNOSTICS ora2pg_rowcount = ROW_COUNT;
IF ora2pg_rowcount > 0) THEN
                CALL event_interface.addevent_new(v_event_id, v_ticket_id,
                                             60001,
                                             v_host_id,
                                             'Starting escalation to Open Systems Mission Control',
                                             'Event added by tt.escalation_interface.escalate_customer(). Caused by event '||p_event_id);

            END IF;
        END IF;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE escalation_interface.escalate_customer (p_event_id bigint) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE escalation_interface.escalate_isp_outage_to_os (p_event_id bigint) AS $body$
DECLARE



        c_prefix CONSTANT varchar(64) := 'tt.escalation_interface.escalate_isp_outage_to_os(): ';

        v_host_name varchar(32);
        v_company_short varchar(10);
        v_public_details varchar(300);
        v_private_details varchar(400);
        v_org_event_date timestamp(0);
        v_ticket_id bigint;
        v_event_id bigint;

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        BEGIN

            
            SELECT h.name, COALESCE(ec.short, tc.SHORT, sc.SHORT), t.id
            INTO STRICT v_host_name, v_company_short, v_ticket_id
            FROM stop.company sc, mss.host h, tt.event e
LEFT OUTER JOIN stop.company ec ON (e.COMPANY_ID = ec.ID)
, tt.ticket t
LEFT OUTER JOIN stop.company tc ON (t.COMPANY_ID = tc.ID)
WHERE e.id = p_event_id AND e.TICKET_ID = t.ID AND h.id = coalesce(e.host_id, t.HOST_ID)   AND h.SERVICE_COMPANY_ID = sc.ID;

        EXCEPTION
            WHEN no_data_found THEN
                plog.err(c_prefix || 'either ticket, host or company not found for event with id: ' || p_event_id ||' This is needed for escalation. Aborting escalation.');
                RETURN;
            WHEN OTHERS THEN
                plog.err(c_prefix || 'Error while retrieving company and host name for event with id: '|| p_event_id ||' This is needed for escalation. Aborting escalation.');
                RETURN;
        END;

        SELECT eventdate INTO STRICT v_org_event_date FROM event where id = p_event_id;

        v_public_details := 'Critical ISP Outage escalation'||CHR(10)
            ||'Host: '||v_host_name||CHR(10)
            ||'Company: '||v_company_short||CHR(10)
            ||'Time of original event: '||TO_CHAR(v_org_event_date, 'YYYY-MM-DD HH24:MI:SS')||CHR(10)
            ||'Original ticket '|| v_ticket_id;

        v_private_details :=  'To Do:'||CHR(10)
            ||'https://open-systems.atlassian.net/wiki/x/3xYBAQ'||CHR(10)||CHR(10)
            ||'Do not add any further events to this escalation ticket.'||CHR(10)
            ||'Use the original ticket ' || v_ticket_id || ' for tracking any work!'||CHR(10)
            ||'This ticket is intentionally hidden from the customer, so do not merge it. ';


        
        
        tt.CALL ticket_interface.newticket_new(v_ticket_id, v_event_id,
                                          1,'Critical ISP Outage escalation',
                                          30005,NULL,v_public_details, v_private_details, NULL, NULL, TRUE, clock_timestamp(), NULL, 27 );

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE escalation_interface.escalate_isp_outage_to_os (p_event_id bigint) FROM PUBLIC;



