-- Oracle package 'EVENT_INTERFACE' declaration, please edit to match PostgreSQL syntax.

DROP SCHEMA IF EXISTS event_interface CASCADE;
CREATE SCHEMA IF NOT EXISTS event_interface;





CREATE OR REPLACE PROCEDURE event_interface.newevent_new (p_event_id OUT bigint, p_type_id bigint, p_host_id bigint, p_details_public text, p_details_private text DEFAULT NULL, p_contact_id bigint DEFAULT NULL, p_public_event boolean DEFAULT TRUE, p_eventdate timestamp(0) DEFAULT clock_timestamp(), p_ticket_type_id bigint DEFAULT NULL, p_service_component_id bigint DEFAULT NULL) AS $body$
DECLARE


        c_prefix CONSTANT varchar(64) := 'tt.event_interface.newevent(): ';


        pub_event bigint;
        subject varchar(200);
        eventSubject varchar(200);
        v_event_id bigint;
        v_history_event_id bigint;
        v_company_id bigint;
        v_mss_service_id bigint;
        active bigint;
        v_new_source bigint;
        v_ticket_id bigint;
        v_ticket_type_id bigint;
        v_details_public varchar(30000);
        v_details_private varchar(30000);
        v_msg_firstline varchar(30000);
        v_scope_info varchar(30000);

        v_monitoring_ticket_id bigint;
        v_collect_event_ticket_id bigint;
        v_disable_event_ticket_id bigint;
        v_recent_ticket_id bigint;
        v_recent_ticket_type bigint;
        v_recent_ticket_open_date timestamp(0);
        v_recent_event_type bigint;
        v_recent_event_source bigint;

        v_reason varchar(1024) := '';

        v_count bigint;

        v_confirmed bigint;
        v_fast_resolvable bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        v_details_public := substr(p_details_public,1,30000);
        v_details_private := substr(p_details_private,1,30000);



        
        BEGIN
            IF (p_host_id IS NOT NULL) THEN
                SELECT h.service_company_id, h2s.service_id INTO STRICT v_company_id, v_mss_service_id
                FROM mss.host h, mss.host2service h2s
                WHERE h.id = p_host_id AND h.id = h2s.host_id;
            END IF;
        EXCEPTION
            WHEN no_data_found THEN
                plog.warning('host ID '||p_host_id||' is not attached to a service');
            WHEN OTHERS THEN
                RAISE;
        END;


        
        
        IF (p_contact_id is not null AND v_company_id is null) THEN
            SELECT company_id INTO STRICT v_company_id
            FROM stop.contact
            WHERE contact.id = p_contact_id;
        END IF;


        
        

        IF (p_host_id is not null) THEN
            SELECT h.active INTO STRICT active FROM mss.host h WHERE h.id = p_host_id;
            IF (active = 0) THEN
                plog.info(c_prefix||'dropping event of type '|| p_type_id ||' for inactive host '|| p_host_id);
                RETURN;
            END IF;
        END IF;


        
        
        

        IF (v_company_id is not null AND p_host_id is not null) THEN
            
            SELECT COUNT(*) INTO STRICT v_disable_event_ticket_id
            FROM tt.ticket t
                     INNER JOIN tt.service_window s
                                ON (s.ticket_id = t.id)
                     INNER JOIN tt.host2service_window h2s
                                ON (h2s.service_window_id = s.id)

                     LEFT JOIN tt.maintenance_window m
                               ON (s.id = m.service_window_id)
                     LEFT JOIN tt.cust_maintenance_window cm
                               ON (s.id = cm.service_window_id)

            WHERE
                    t.status_id < 101 AND s.end_date > statement_timestamp() AND s.start_date < statement_timestamp()
              AND (m.disable_events = 1 OR cm.disable_events = 1) AND h2s.host_id = p_host_id;

            IF (v_disable_event_ticket_id > 0) THEN
                plog.info(c_prefix||'dropping event of type ' || p_type_id || ' for host ' || p_host_id ||
                          '. Active service window with disable event flag on ticket ' || v_disable_event_ticket_id );
                RETURN;
            END IF;
        END IF;


        
        
        
        
        
        
        
        
        

        
        
        
        

        SELECT source INTO STRICT v_new_source FROM event_type WHERE id = p_type_id;

        v_ticket_type_id := coalesce(p_ticket_type_id, event_interface.ticket_type_for_event_type(p_type_id));

        IF ( v_new_source = 1 AND p_host_id IS NOT NULL ) THEN
            BEGIN
                IF ( v_company_id IS NOT NULL ) THEN

                    SELECT MIN(t.id) INTO STRICT v_monitoring_ticket_id
                    FROM tt.ticket t
                    WHERE t.company_id = v_company_id AND t.type_id = 6 AND t.status_id < 60;

                    IF ( v_monitoring_ticket_id IS NOT NULL ) THEN

                        v_ticket_id := v_monitoring_ticket_id;

                        v_ticket_type_id := 6;
                    ELSE

                        SELECT MAX(t.id) INTO STRICT v_collect_event_ticket_id
                        FROM tt.ticket t
                                 INNER JOIN tt.service_window s
                                            ON (s.ticket_id = t.id)
                                 INNER JOIN tt.host2service_window h2s
                                            ON (h2s.service_window_id = s.id)

                                 LEFT JOIN tt.maintenance_window m
                                           ON (s.id = m.service_window_id)
                                 LEFT JOIN tt.cust_maintenance_window cm
                                           ON (s.id = cm.service_window_id)

                        WHERE
                                t.status_id < 101 AND s.end_date > statement_timestamp() AND s.start_date < statement_timestamp()
                          AND (m.collect_events = 1 OR cm.collect_events = 1) AND h2s.host_id = p_host_id;


                        IF (v_collect_event_ticket_id IS NOT NULL) THEN

                            v_ticket_id := v_collect_event_ticket_id;
                            v_reason := 'found open service window requesting event collection';
                        ELSE

                            v_recent_ticket_id := tt.ticket_interface.get_next_recent_ticket(NULL,p_host_id,NULL,24*3600);
                            WHILE( v_recent_ticket_id IS NOT NULL ) LOOP
                                    BEGIN

                                        SELECT t.type_id, t.open_date, e.type_id, ety.source
                                        INTO STRICT v_recent_ticket_type, v_recent_ticket_open_date, v_recent_event_type, v_recent_event_source
                                        FROM tt.ticket t, tt.event e, tt.event_type ety
                                        WHERE t.id = v_recent_ticket_id
                                          AND e.ticket_id = t.id
                                          AND e.type_id = ety.id
                                          AND e.id = (
                                            SELECT MIN(id) FROM tt.event WHERE ticket_id = t.id
                                        );


                                        
                                        IF ( p_type_id IN ( 10001, 10003 ) AND v_recent_event_type IN ( 10001, 10003, 10018 )) THEN
                                            v_ticket_id := v_recent_ticket_id;
                                            v_reason := 'found recent ticket for connection down/isp outage';


                                            
                                            IF (p_type_id = 10001 AND v_recent_ticket_type = 4) THEN
                                                CALL ticket_interface.change_type(v_history_event_id, v_ticket_id, 1, p_contact_id);
                                            END IF;


                                        ELSIF ( p_type_id IN ( 10002, 10014 ) AND v_recent_event_type IN ( 10002, 10014 )
                                            AND (clock_timestamp() - v_recent_ticket_open_date) < 1/24 ) THEN
                                            v_ticket_id := v_recent_ticket_id;
                                            v_reason := 'found recent ticket for id alert/id/customer id notification';


                                        ELSIF ( p_type_id IN ( 10002, 10014 ) ) THEN
                                            NULL;


                                            
                                        ELSIF (p_type_id IN ( 10017 ) AND v_recent_ticket_type IN ( 8,15 )) THEN
                                            v_ticket_id := v_recent_ticket_id;
                                            v_reason := 'found recent migration/installation ticket for hardware installation event';

                                        ELSIF (p_type_id IN ( 10017 )) THEN
                                            NULL;


                                            
                                            
                                        ELSIF ( p_type_id IN ( 10020 ) AND v_recent_event_type IN ( 10020 )) THEN
                                            v_ticket_id := v_recent_ticket_id;
                                            v_reason := 'found recent ticket for customer id notification';


                                        ELSIF (p_type_id IN (10020)) THEN
                                            NULL;


                                            
                                            
                                        ELSIF (p_type_id IN (10030) AND v_recent_event_type IN (10030)) THEN
                                            v_ticket_id := v_recent_ticket_id;
                                            v_reason := 'found recent ticket for user synchronization error';


                                        ELSIF (p_type_id IN (10030)) THEN
                                            NULL;


                                        ELSIF ( v_recent_event_source = 1 AND v_recent_ticket_type = 1 ) THEN
                                            
                                            
                                            
                                            IF (v_recent_event_type IN (10020,10030,10002,10014,10060)) THEN
                                                NULL;
                                            ELSE
                                                v_ticket_id := v_recent_ticket_id;
                                                v_reason := 'found recent ticket for automatically generated event';
                                            END IF;

                                        END IF;

                                    EXCEPTION
                                        WHEN no_data_found THEN
                                            NULL;
                                    END;

                                    IF ( v_ticket_id IS NOT NULL ) THEN
                                        v_recent_ticket_id := NULL;
                                    ELSE
                                        v_recent_ticket_id := tt.ticket_interface.get_next_recent_ticket(v_recent_ticket_id,p_host_id,NULL,24*3600);
                                    END IF;

                                END LOOP;
                        END IF;
                    END IF;
                END IF;
            EXCEPTION
                WHEN OTHERS THEN
                    plog.err(c_prefix||'unexpected error when trying to find appropriate ticket for automatically generated event: '||sqlerrm);
            END;
        END IF;


        
        

        IF ( v_ticket_id IS NOT NULL ) THEN
            plog.notice(c_prefix || 'appending event '||p_type_id||' from host '||p_host_id||' to ticket '||v_ticket_id||': '||v_reason);


            
             CALL event_interface.addevent_new(p_event_id,
                         v_ticket_id,
                         p_type_id,
                         p_host_id,
                         v_details_public,
                         v_details_private,
                         p_contact_id,
                         p_public_event,
                         p_eventdate);


            v_event_id := p_event_id;


            CALL ticket_interface.change_status(v_ticket_id, 3, p_contact_id,NULL,'new event added');



            
            

        ELSE

            plog.notice(c_prefix || 'creating new ticket for event '||p_type_id||' from host '||p_host_id);

            IF (p_public_event) THEN
                pub_event:=1;
            ELSE
                pub_event:=0;
            END IF;


            SELECT name INTO STRICT subject
            FROM event_type
            WHERE id=p_type_id;


            
            
            IF (p_type_id = 30002 OR p_type_id = 30009 OR p_type_id = 40002 OR p_type_id = 10014 OR p_type_id = 10002) THEN
                subject := SUBSTR(v_details_public, 1, 100);
                subject := SUBSTR(subject, 1, position(CHR(10) in subject) - 1);


                
                
                
                
                
            ELSIF p_type_id = 10004 OR p_type_id = 10005 OR
                  p_type_id = 10006 OR p_type_id = 10007 OR
                  p_type_id = 10008 OR p_type_id = 10009 OR
                  p_type_id = 10020 OR
                  p_type_id = 10021 THEN

                eventSubject := SUBSTR(v_details_public, 1, 95 - length(subject));
                IF (position(CHR(10) in eventSubject) > 0) THEN
                    eventSubject := SUBSTR(eventSubject, 1, position(CHR(10) in eventSubject) - 1);
                ELSIF (length(eventSubject) = (95 - length(subject))) THEN
                    eventSubject := SUBSTR(eventSubject, 1, length(eventSubject) - 3) || '...';
                END IF;
                subject := subject || ': ' || eventSubject;
            END IF;

            v_ticket_type_id := coalesce(p_ticket_type_id, event_interface.ticket_type_for_event_type(p_type_id));
            SELECT nextval('ticket_sequence') INTO STRICT v_ticket_id;


            
            v_count := 0;

            IF (v_mss_service_id IS NULL) THEN
                SELECT count(*) INTO STRICT v_count
                FROM auth.permission p, auth.login l
                WHERE p.login_id = l.id AND l.contact_id = p_contact_id AND p.role_id = 2 AND p.company_id = v_company_id;

            ELSE
                SELECT count(*) INTO STRICT v_count
                FROM auth.mv_service_access sa, auth.login l
                WHERE sa.login_id = l.id AND l.contact_id = p_contact_id AND sa.role_id = 2 AND sa.service_id = v_mss_service_id AND sa.service_company_id = v_company_id;
            END IF;


            v_confirmed := 0;
            v_fast_resolvable := 0;
            IF (v_new_source = 1) THEN
                v_confirmed := 1;
                v_fast_resolvable := 1;
            END IF;

            IF (v_count > 0) THEN

                INSERT INTO ticket(id, type_id, contact_id, company_id, host_id, subject, mss_service_id, service_confirmed, type_confirmed, fast_resolvable, service_component_id)
                VALUES (v_ticket_id, v_ticket_type_id, p_contact_id,v_company_id, p_host_id, subject, v_mss_service_id, v_confirmed, v_confirmed, v_fast_resolvable, p_service_component_id);
            ELSE

                INSERT INTO ticket(id, type_id, contact_id, company_id, host_id, subject, mss_service_id, service_confirmed, type_confirmed, fast_resolvable, service_component_id)
                VALUES (v_ticket_id, v_ticket_type_id, NULL, v_company_id, p_host_id, subject, v_mss_service_id, v_confirmed, v_confirmed, v_fast_resolvable, p_service_component_id);
            END IF;

            plog.debug(c_prefix || 'subject: ' || subject);


            UPDATE tt.ticket SET ux_timeout_start = (cast(open_date as timestamp) AT TIME ZONE 'EUROPE/ZURICH')::timestamp with time zone WHERE id = v_ticket_id;
            CALL tt.ticket_interface.update_ux_timeout_for_ticket(v_ticket_id, TRUE);



            SELECT nextval('event_sequence') INTO STRICT p_event_id;


               
               
               
               
               
               
               
               
               
               
               
               
            IF (v_details_public is not null AND p_type_id IN (
                10007, 10006, 10005, 10004, 10014, 10002, 10013, 10009, 10021, 10008, 10030
            )) THEN
                v_msg_firstline := substr(v_details_public, 1, position(chr(10) in v_details_public) -1 );
                IF (v_company_id is not null) THEN
                    v_scope_info := v_scope_info || ' company_id=' || v_company_id;
                END IF;
                IF (p_host_id is not null) THEN
                    v_scope_info := v_scope_info || ' host_id=' || p_host_id;
                END IF;
                plog.notice(c_prefix || 'insert event' || ' msgshort="' || v_msg_firstline || '" event_type_id=' || p_type_id || ' ticket=' || v_ticket_id || v_scope_info);
            END IF;


            INSERT INTO event(id,type_id,host_id,company_id, ticket_id, eventdate,details_public,details_private,public_event,contact_id)
            VALUES (p_event_id,
                    p_type_id,
                    p_host_id,
                    v_company_id,
                    v_ticket_id,
                    p_eventdate,
                    v_details_public,
                    v_details_private,
                    pub_event,
                    p_contact_id);


            IF (pub_event > 0 AND v_new_source NOT IN (2, 10)) THEN
                UPDATE tt.ticket SET last_public_event_id = p_event_id WHERE id = v_ticket_id;
            END IF;


            
            IF (pub_event > 0 AND v_new_source NOT IN (1,2,6,10)) THEN
                UPDATE tt.ticket
                SET summary_relevant_events_count = 1,
                    todo_relevant_events_count = 1
                WHERE id = v_ticket_id;
            END IF;


            
            IF (v_new_source != 1) THEN
                 CALL event_interface.add_history_event(v_event_id,
                                  v_ticket_id,
                                  101001,
                                  p_host_id,
                                  v_company_id,
                                  'New ticket created',
                                  NULL,
                                  TRUE, 
                                  clock_timestamp(),
                                  p_contact_id);
            END IF;

            CALL tt.ticket_interface.updateTicketFlow(v_ticket_id);

            CALL event_interface.exec_event_type_actions(p_event_id);

        END IF;


        IF ( v_ticket_type_id != 6 ) THEN
            CALL TT.OSAG_NOTIFY.event_notify(p_event_id, v_ticket_id);
        END IF;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE event_interface.newevent_new (p_event_id OUT bigint, p_type_id bigint, p_host_id bigint, p_details_public text, p_details_private text DEFAULT NULL, p_contact_id bigint DEFAULT NULL, p_public_event boolean DEFAULT TRUE, p_eventdate timestamp(0) DEFAULT clock_timestamp(), p_ticket_type_id bigint DEFAULT NULL, p_service_component_id bigint DEFAULT NULL) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE event_interface.addevent_new (p_event_id OUT bigint, p_ticket_id bigint, p_type_id bigint, p_host_id bigint, details_public text, details_private text DEFAULT NULL, p_contact_id bigint DEFAULT NULL, public_event boolean DEFAULT TRUE, eventdate timestamp(0) DEFAULT clock_timestamp(), notify_event boolean DEFAULT FALSE) AS $body$
DECLARE


        C_PREFIX CONSTANT varchar(64) := 'tt.event_interface.addevent_new(): ';

        pub_event bigint;
        ev_id bigint;
        v_company_id bigint;
        v_details_public varchar(30000);
        v_details_private varchar(30000);
        v_ticket_status bigint;
        v_ticket_type bigint;
        v_merged_details_private varchar(30000);
        v_merged_ticket_id bigint;
        v_event_source bigint;
        v_ticket_has_service_window bigint;
        v_history_event_id bigint;
        v_fast_resolvable bigint;
        v_last_public_event_id bigint;
        v_recoverable_status_id bigint;
        v_summary_rel_events_count bigint;
        v_todo_relevant_events_count bigint;
        v_ux_timeout_start TIMESTAMP WITH TIME ZONE;
        v_change_request_pending bigint;
        v_pinned bigint;
        v_msg_firstline varchar(30000);
        v_scope_info varchar(30000);



BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        SELECT t.type_id, t.status_id
        INTO STRICT   v_ticket_type, v_ticket_status
        FROM   tt.ticket t
        WHERE  t.id = p_ticket_id;

        SELECT source INTO STRICT v_event_source FROM tt.event_type WHERE id = p_type_id;
        SELECT autopin INTO STRICT v_pinned FROM tt.event_type WHERE id = p_type_id;


        
        
        

        
        IF (v_ticket_status = 110) THEN
            
            
            
            BEGIN
                SELECT (e.details_private)::numeric  INTO STRICT v_merged_ticket_id
                FROM tt.event e
                WHERE e.ticket_id = p_ticket_id
                  AND e.type_id = 100004
                  AND (e.details_private)::numeric  != p_ticket_id
                  AND EXISTS (SELECT 1 FROM tt.ticket t WHERE t.id = (e.details_private)::numeric  )   LIMIT 1;
            EXCEPTION
                WHEN no_data_found THEN
                    v_merged_ticket_id := -1;
            END;


            IF (v_merged_ticket_id > 0) THEN
                 CALL event_interface.addevent_new(p_event_id,v_merged_ticket_id,
                             p_type_id,
                             p_host_id,
                             details_public,
                             details_private,
                             p_contact_id,
                             public_event,
                             eventdate);

                UPDATE tt.event SET org_ticket_id = p_ticket_id
                WHERE id = p_event_id and org_ticket_id IS NULL;
            END IF;

        ELSIF (v_ticket_status > 101) THEN
            plog.notice(C_PREFIX || ' Ticket with id '|| p_ticket_id || ' is closed/deleted, cannot add event!');
            RAISE EXCEPTION '%', 'Ticket with id '|| p_ticket_id || ' is closed/deleted' USING ERRCODE = EVENT_INTERFACE_STATE.S_ERRNO_TICKET_CLOSED;
        ELSE

            
            SELECT nextval('event_sequence') INTO STRICT ev_id;

            p_event_id := ev_id;


            v_details_public := tt.ticket_interface.replace_id_placeholders(details_public, p_ticket_id, ev_id);
            v_details_private := tt.ticket_interface.replace_id_placeholders(details_private, p_ticket_id, ev_id);

            IF (public_event) THEN
                pub_event:=1;
            ELSE
                pub_event:=0;
            END IF;


            IF (p_host_id is not null) THEN
                SELECT h.service_company_id INTO STRICT v_company_id
                FROM mss.host h
                WHERE h.id = p_host_id;
            ELSE

                SELECT company_id INTO STRICT v_company_id
                FROM tt.ticket
                WHERE ticket.id = p_ticket_id;
            END IF;


            
            
            
            
            
            
            
            
            
            
            
            
            IF (v_details_public is not null AND p_type_id IN (
                                                                10007, 10006, 10005, 10004, 10014, 10002, 10013, 10009, 10021, 10008, 10030
                )) THEN
                v_msg_firstline := substr(v_details_public, 1, position(chr(10) in v_details_public) -1 );
                IF (v_company_id is not null) THEN
                    v_scope_info := v_scope_info || ' company_id=' || v_company_id;
                END IF;
                IF (p_host_id is not null) THEN
                    v_scope_info := v_scope_info || ' host_id=' || p_host_id;
                END IF;
                plog.notice(c_prefix || 'insert event' || ' msgshort="' || v_msg_firstline || '" event_type_id=' || p_type_id || ' ticket=' || p_ticket_id || v_scope_info);
            END IF;

            INSERT INTO event(id,type_id,host_id,company_id,eventdate,details_public,details_private,public_event, ticket_id, contact_id, pinned)
            VALUES (ev_id, p_type_id, p_host_id, v_company_id, eventdate,
                    v_details_public,v_details_private, pub_event, p_ticket_id, p_contact_id, v_pinned);


            IF (public_event AND p_type_id >= 40000 AND p_type_id < 60000) THEN
                SELECT (cast(eventdate as timestamp) AT TIME ZONE 'EUROPE/ZURICH')::timestamp with time zone INTO STRICT v_ux_timeout_start FROM tt.event WHERE id = ev_id;
                UPDATE tt.ticket SET ux_timeout_start = v_ux_timeout_start WHERE id = p_ticket_id;
                CALL tt.ticket_interface.update_ux_timeout_for_ticket(p_ticket_id, FALSE);
            END IF;


            
            

            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            IF (p_type_id IN ( 10002, 10003, 10008, 10013, 10014, 10040, 10050, 10060, 10100, 30002, 30009, 30011, 30004, 30013, 30014, 30016, 30018, 30019, 30020, 30021, 30022 ) AND v_ticket_status <> 3) THEN
                CALL tt.ticket_interface.change_status(p_ticket_id,3,p_contact_id,NULL,'new event added');
            END IF;


            CALL event_interface.exec_event_type_actions(p_event_id);


            
            
            
            IF (v_ticket_type IN (4,5)) THEN
                SELECT source INTO STRICT v_event_source FROM event_type WHERE id = p_type_id;
                IF (v_event_source IN (3,4,5) AND pub_event = 1) THEN
                    tt.CALL ticket_interface.change_type(v_history_event_id, p_ticket_id,1,NULL);
                END IF;
            END IF;


            IF ( p_type_id = 10001 AND (v_ticket_type NOT IN (1,4,6))) THEN
                SELECT COUNT(*) INTO STRICT v_ticket_has_service_window
                FROM tt.service_window s, tt.ticket t
                WHERE t.id = p_ticket_id
                  AND t.id = s.ticket_id
                  AND statement_timestamp() BETWEEN s.start_date AND s.end_date
                  AND t.status_id < 101;

                IF (v_ticket_has_service_window = 0) THEN
                    tt.CALL ticket_interface.change_type(v_history_event_id, p_ticket_id,1,NULL);
                ELSE
                    plog.notice('ticket type of ticket ' || p_ticket_id || ' not changed due to active service window.');
                END IF;
            END IF;


            IF ( v_ticket_type != 6 ) THEN
                IF (notify_event) THEN
                    
                    CALL TT.OSAG_NOTIFY.event_notify(ev_id, p_ticket_id);
                END IF;
            END IF;


            
            
            
            
            
            
            
            
            IF (public_event AND p_type_id IN ( 30001, 30008, 30009, 40002, 50001, 50002, 50003 )) THEN
                CALL tt.util.update_status_valid_until(p_ticket_id);
            END IF;


            SELECT t.fast_resolvable, t.last_public_event_id, t.recoverable_status_id, t.summary_relevant_events_count, t.todo_relevant_events_count
            INTO STRICT   v_fast_resolvable, v_last_public_event_id, v_recoverable_status_id, v_summary_rel_events_count, v_todo_relevant_events_count
            FROM   tt.ticket t
            WHERE  t.id = p_ticket_id;


            
            IF (v_fast_resolvable > 0 AND pub_event > 0 AND v_event_source NOT IN (1, 2, 10)) THEN
                v_fast_resolvable := 0;
            END IF;


            IF (p_type_id = 30016) THEN
                v_fast_resolvable := 1;
            END IF;


            IF (pub_event > 0 AND v_event_source NOT IN (2, 10)) THEN
                v_last_public_event_id := ev_id;

                
                UPDATE tt.ticket
                SET  last_public_event_id = v_last_public_event_id
                WHERE  id = p_ticket_id;
            END IF;


            
            IF (pub_event > 0 AND v_event_source NOT IN (1,2,6,10)) THEN
                v_summary_rel_events_count := v_summary_rel_events_count + 1;
                v_todo_relevant_events_count := v_todo_relevant_events_count + 1;
            END IF;


            
            
            IF ((pub_event > 0 AND v_event_source NOT IN (1, 2, 3, 6, 10) AND p_type_id NOT IN (30022, 50022)) OR p_type_id = 30016) THEN
                v_recoverable_status_id := NULL;
            END IF;


            SELECT COUNT(*) INTO STRICT v_change_request_pending FROM tt.CHANGE_REQUEST cr where cr.TICKET_ID = p_ticket_id AND cr.CHANGE_REQUEST_STATE_ID IN (2, 6);


            If (v_change_request_pending = 0 AND v_recoverable_status_id = 61) THEN
                v_recoverable_status_id := NULL;
            END IF;


            UPDATE tt.ticket
            SET    fast_resolvable = v_fast_resolvable,
                   recoverable_status_id = v_recoverable_status_id,
                   summary_relevant_events_count = v_summary_rel_events_count,
                   todo_relevant_events_count = v_todo_relevant_events_count
            WHERE  id = p_ticket_id;

        END IF;
    EXCEPTION
        WHEN EVENT_INTERFACE_STATE.ticket_closed THEN
            RAISE;
        WHEN OTHERS THEN
            plog.err(c_prefix||'unknown error for ticket:'||p_ticket_id||' : '||sqlerrm);
            plog.notice(DBMS_UTILITY.format_error_backtrace);
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE event_interface.addevent_new (p_event_id OUT bigint, p_ticket_id bigint, p_type_id bigint, p_host_id bigint, details_public text, details_private text DEFAULT NULL, p_contact_id bigint DEFAULT NULL, public_event boolean DEFAULT TRUE, eventdate timestamp(0) DEFAULT clock_timestamp(), notify_event boolean DEFAULT FALSE) FROM PUBLIC;



CREATE OR REPLACE FUNCTION event_interface.ticket_type_for_event_type (p_event_type_id bigint) RETURNS bigint AS $body$
DECLARE


        v_ticket_type_id bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        

        
        
        
        
        
        IF p_event_type_id IN (10003, 10110, 10102, 10019) THEN
            v_ticket_type_id := 4;


        ELSIF p_event_type_id = 30002 OR p_event_type_id = 30009 THEN
            v_ticket_type_id := 2;


        ELSE
            v_ticket_type_id := 1;
        END IF;

        RETURN v_ticket_type_id;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION event_interface.ticket_type_for_event_type (p_event_type_id bigint) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE event_interface.moveevent (p_event_id bigint, p_oldticket_id bigint, p_newticket_id bigint) AS $body$
DECLARE


        c_prefix  CONSTANT varchar(64) := 'tt.event_interface.moveevent()" ';
        v_dummy   bigint;
        v_errmsg   varchar(256);

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        v_errmsg := 'cannot move event '||p_event_id||' from ticket '||p_oldticket_id||' to ticket '||p_newticket_id||': ';
        IF ( p_event_id IS NOT NULL AND p_newticket_id IS NOT NULL AND p_oldticket_id IS NOT NULL ) THEN
            SELECT id INTO STRICT v_dummy FROM tt.ticket WHERE id = p_newticket_id;
            UPDATE tt.event e SET ticket_id = p_newticket_id WHERE ticket_id = p_oldticket_id;
        END IF;
    EXCEPTION
        WHEN no_data_found THEN
            plog.warning(c_prefix||v_errmsg||'new ticket does not exist');
        WHEN unique_violation THEN
            plog.info(c_prefix||v_errmsg||'event is already in new ticket');
        WHEN OTHERS THEN
            plog.err(c_prefix||v_errmsg||'unknown error: '||sqlerrm);
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE event_interface.moveevent (p_event_id bigint, p_oldticket_id bigint, p_newticket_id bigint) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE event_interface.exec_event_type_actions (p_event_id bigint) AS $body$
DECLARE


        c_prefix CONSTANT varchar(64) := 'tt.event_interface.exec_event_type_actions(): ';
        v_event_type_id bigint;
        v_host_id bigint;
        v_proc_str varchar(4000);
        v_ticket_id tt.ticket.id%TYPE;

        event_action_cur CURSOR FOR
            SELECT name, procedure_name, procedure_key_id, event_action_id
            FROM event_action, event_type_action
            WHERE event_type_action.event_type_id = v_event_type_id
              AND event_type_action.event_action_id = event_action.id;

        event_action_rec event_action_cur%ROWTYPE;

        stmt_str varchar(1000);
        v_esc_event_id bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        plog.debug(c_prefix || 'execute exec_event_type_action for event ' || p_event_id);


        SELECT type_id into STRICT v_event_type_id
        FROM event
        WHERE id = p_event_id;

        plog.debug(c_prefix || 'event_type_id is ' || v_event_type_id);



        BEGIN
            SELECT e.host_id INTO STRICT v_host_id FROM tt.event e
            WHERE e.id = p_event_id;
        EXCEPTION
            WHEN no_data_found THEN
                v_host_id := NULL;
            WHEN OTHERS THEN
                plog.err(c_prefix||'unexpected error while determing host for event with id ' ||p_event_id||': '||sqlerrm);
        END;

        plog.debug(c_prefix || 'host_id is ' || v_host_id);


        SELECT ticket_id INTO STRICT v_ticket_id
        FROM tt.event
        WHERE id = p_event_id;

        plog.debug(c_prefix || 'ticket_id is ' || v_ticket_id);


        FOR event_action_rec IN event_action_cur
            LOOP
                IF (NOT event_interface.is_esc_supp_active(v_host_id, event_action_rec.event_action_id, v_event_type_id)) THEN
                    
                    IF (event_action_rec.procedure_key_id IS NOT NULL AND v_host_id IS NOT NULL) THEN

                        plog.debug(c_prefix || 'looking up procedure name in DBPROP using key with id '
 || event_action_rec.procedure_key_id );


                        v_proc_str := mss.OSAG_DBPROP.get_string_by_host_key_id(v_host_id, event_action_rec.procedure_key_id);

                    END IF;

                    IF (v_proc_str IS NULL) THEN
                        v_proc_str := event_action_rec.procedure_name;
                    END IF;

                    plog.debug(c_prefix || 'event action : ' || v_proc_str);


                    
                    IF (v_proc_str IS NOT NULL) THEN
                        BEGIN
                            stmt_str :=  'call ' || v_proc_str || '(:eventid)';
                            plog.debug(c_prefix || 'executing : ' || stmt_str);
                            EXECUTE stmt_str USING p_event_id;
                        EXCEPTION
                            WHEN OTHERS THEN
                                plog.err(c_prefix||%ORA2PG_COMMENT13(|sqlerrm);
                        END;
                    ELSE
                        plog.notice(c_prefix || 'no procedure executed for host: '
 || v_host_id || ' on event of type: '||v_event_type_id);
                    END IF;
                ELSE
                    plog.notice(c_prefix || 'escalation suppressed for event ' || p_event_id || ' due to active service window.');
                     CALL event_interface.addevent_new(v_esc_event_id, v_ticket_id, 60010, v_host_id,
                                 'Escalation suppressed for event ' || p_event_id || ' due to active service window.' ,
                                 'Event added by tt.event_interface.exec_event_type_actions().');
                END IF;
            END LOOP;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE event_interface.exec_event_type_actions (p_event_id bigint) FROM PUBLIC;



CREATE OR REPLACE FUNCTION event_interface.is_esc_supp_active (p_host_id bigint, p_event_action_id bigint, p_event_type_id bigint) RETURNS boolean AS $body$
DECLARE


        v_guma_suppressor_exists integer;
        v_conn_suppressor_exists integer;


BEGIN
        IF (p_event_type_id = 10002 OR
            p_event_type_id = 10005 OR
            p_event_type_id = 10007 OR
            p_event_type_id = 10009) THEN

            

            SELECT COUNT(*) INTO STRICT v_guma_suppressor_exists
            FROM tt.ticket t
                     INNER JOIN tt.service_window s
                                ON (s.ticket_id = t.id)
                     INNER JOIN tt.host2service_window h2s
                                ON (h2s.service_window_id = s.id)

                     LEFT JOIN tt.maintenance_window m
                               ON (s.id = m.service_window_id)
                     LEFT JOIN tt.cust_maintenance_window cm
                               ON (s.id = cm.service_window_id)

            WHERE
                    t.status_id < 101 AND s.end_date > statement_timestamp() AND s.start_date < statement_timestamp()
              AND (m.disable_guma_escalation = 1 OR cm.disable_guma_escalation = 1) AND h2s.host_id = p_host_id;

            IF (v_guma_suppressor_exists > 0) THEN
                RETURN TRUE;
            END IF;
        END IF;

        IF (p_event_action_id = 2
            OR (p_event_action_id = 1 AND p_event_type_id=10050) 
            ) THEN
            
            

            SELECT COUNT(*) INTO STRICT v_conn_suppressor_exists
            FROM tt.ticket t
                     INNER JOIN tt.service_window s
                                ON (s.ticket_id = t.id)
                     INNER JOIN tt.host2service_window h2s
                                ON (h2s.service_window_id = s.id)

                     LEFT JOIN tt.maintenance_window m
                               ON (s.id = m.service_window_id)
                     LEFT JOIN tt.cust_maintenance_window cm
                               ON (s.id = cm.service_window_id)

            WHERE
                    t.status_id < 101 AND s.end_date > statement_timestamp() AND s.start_date < statement_timestamp()
              AND (m.disable_conn_escalation = 1 OR cm.disable_conn_escalation = 1) AND h2s.host_id = p_host_id;

            IF (v_conn_suppressor_exists > 0) THEN
                RETURN TRUE;
            END IF;
        END IF;

        RETURN FALSE;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION event_interface.is_esc_supp_active (p_host_id bigint, p_event_action_id bigint, p_event_type_id bigint) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE event_interface.add_history_event (p_event_id OUT bigint, p_ticket_id bigint, p_event_type_id bigint, p_host_id bigint, p_company_id bigint, p_details_public text, p_details_private text DEFAULT NULL, p_public_event boolean DEFAULT TRUE, p_eventdate timestamp(0) DEFAULT clock_timestamp(), p_contact_id bigint DEFAULT NULL) AS $body$
DECLARE



        
        v_public_event bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        IF (p_public_event) THEN
            v_public_event:= 1;
