        v_history_event_id bigint;
        v_ticket_id bigint;
        v_host_id bigint;
        v_company_id bigint;
        v_private_details varchar(30000);
        v_public_details varchar(30000);
        v_is_public boolean;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        UPDATE tt.event
        SET    demoted = 1
