CREATE OR REPLACE PROCEDURE monitoring.update_host_status ( p_host_id mc.mon_server_connection.host_id%TYPE, p_mon_server_id mc.mon_server_connection.mon_server_id%TYPE, p_con_timestamp mc.mon_server_connection.con_timestamp%TYPE, p_status mc.mon_server_connection.status%TYPE, p_details mc.mon_server_connection.details%TYPE ) AS $body$
