CREATE OR REPLACE PROCEDURE monitoring.update_host_status_with_ip ( p_host_id mc.mon_server_connection.host_id%TYPE, p_mon_server_id mc.mon_server_connection.mon_server_id%TYPE, p_con_timestamp mc.mon_server_connection.con_timestamp%TYPE, p_status mc.mon_server_connection.status%TYPE, p_details mc.mon_server_connection.details%TYPE, p_ipv4_address mc.mon_server_connection.ipv4_address%TYPE, p_ipv6_address_1 mc.mon_server_connection.ipv6_address_1%TYPE, p_ipv6_address_2 mc.mon_server_connection.ipv6_address_2%TYPE ) AS $body$
DECLARE



        ora2pg_rowcount int;
S_PREFIX CONSTANT varchar(32) := 'monitoring.update_host_status_with_ip(): ';


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        UPDATE mon_server_connection
        SET con_timestamp  = p_con_timestamp,
            status         = p_status,
            entry_date     = clock_timestamp(),
            details        = p_details,
            ipv4_address   = p_ipv4_address,
            ipv6_address_1 = p_ipv6_address_1,
            ipv6_address_2 = p_ipv6_address_2
        WHERE host_id        = p_host_id
          AND mon_server_id  = p_mon_server_id;

        GET DIAGNOSTICS ora2pg_rowcount = ROW_COUNT;


        IF (  ora2pg_rowcount=0 ) THEN

            
            INSERT INTO mon_server_connection(
                con_timestamp,
                status,
                entry_date,
                details,
                host_id,
                mon_server_id,
                ipv4_address,
                ipv6_address_1,
                ipv6_address_2)
            VALUES (p_con_timestamp,
                    p_status,
                    statement_timestamp(),
                    p_details,
                    p_host_id,
                    p_mon_server_id,
                    p_ipv4_address,
                    p_ipv6_address_1,
                    p_ipv6_address_2);
        END IF;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE monitoring.update_host_status_with_ip ( p_host_id mc.mon_server_connection.host_id%TYPE, p_mon_server_id mc.mon_server_connection.mon_server_id%TYPE, p_con_timestamp mc.mon_server_connection.con_timestamp%TYPE, p_status mc.mon_server_connection.status%TYPE, p_details mc.mon_server_connection.details%TYPE, p_ipv4_address mc.mon_server_connection.ipv4_address%TYPE, p_ipv6_address_1 mc.mon_server_connection.ipv6_address_1%TYPE, p_ipv6_address_2 mc.mon_server_connection.ipv6_address_2%TYPE ) FROM PUBLIC;



CREATE OR REPLACE FUNCTION monitoring.has_active_sw (p_host_id mss.host.id%TYPE) RETURNS boolean AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(32) := 'monitoring.has_active_sw(): ';
        v_has_SW bigint;


BEGIN
        
        SELECT COUNT(*) INTO STRICT v_has_SW
        FROM tt.ticket t
                 INNER JOIN tt.service_window s
                            ON (s.ticket_id = t.id)
                 INNER JOIN tt.host2service_window h2s
                            ON (h2s.service_window_id = s.id)

                 LEFT JOIN tt.maintenance_window m
                           ON (s.id = m.service_window_id)
                 LEFT JOIN tt.cust_maintenance_window cm
                           ON (s.id = cm.service_window_id)

        WHERE
                t.status_id < mc.monitoring_state.TICKET_STATUS_RESOLVED AND s.end_date > statement_timestamp() AND s.start_date < statement_timestamp()
          AND (m.disable_conn_escalation = 1 OR cm.disable_conn_escalation = 1) AND h2s.host_id = p_host_id;

        IF ( v_has_SW > 0 ) THEN
            RETURN TRUE;
        ELSE
            RETURN FALSE;
        END IF;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION monitoring.has_active_sw (p_host_id mss.host.id%TYPE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE monitoring.migrate_event_id (p_host_id mss.host.id%TYPE, p_switch_date timestamp(0) ) AS $body$
DECLARE

        S_PREFIX CONSTANT varchar(32) := 'monitoring.migrate_event_id(): ';
        v_event_id mc.connection_interrupt_closed.event_id%TYPE;


BEGIN
        SELECT max(event_id) INTO STRICT v_event_id
        FROM mc.connection_interrupt_closed cic
        WHERE cic.host_id = p_host_id
          AND cic.up_date = p_switch_date;

        UPDATE mc.connection_interrupt_open cio
        SET cio.event_id = v_event_id
        WHERE cio.host_id = p_host_id
          AND cio.down_date = p_switch_date;

    EXCEPTION
        WHEN no_data_found THEN

            NULL;
        WHEN others THEN
            plog.err(S_PREFIX||'caught exception:'||sqlerrm);
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE monitoring.migrate_event_id (p_host_id mss.host.id%TYPE, p_switch_date timestamp(0) ) FROM PUBLIC;



CREATE OR REPLACE FUNCTION monitoring.get_old_mode (p_host_id mss.host.id%TYPE) RETURNS bigint AS $body$
DECLARE

        S_PREFIX CONSTANT varchar(32) := 'monitoring.get_old_mode(): ';
        v_interrupt_type mc.connection_interrupt_open.type_id%TYPE;
        v_active mc.connection_interrupt_open.active%TYPE;
        v_result bigint := 0;


BEGIN
        SELECT type_id,active INTO STRICT v_interrupt_type,v_active
        FROM mc.connection_interrupt_open cio
        WHERE cio.host_id = p_host_id;

        IF ( v_active = 0 ) THEN
            v_result := mc.monitoring_state.MODE_INACTIVE;
        ELSE
            v_result := CASE v_interrupt_type
                            WHEN mc.monitoring_state.STATE_ISP
                                THEN mc.monitoring_state.MODE_ACTIVE

                            WHEN mc.monitoring_state.STATE_DOWN
                                THEN mc.monitoring_state.MODE_ACTIVE
                
                            WHEN mc.monitoring_state.STATE_ISP_SW
                                THEN mc.monitoring_state.MODE_SW
                
                            WHEN mc.monitoring_state.STATE_DOWN_SW
                                THEN mc.monitoring_state.MODE_SW
                
                END;
        END IF;
        RETURN v_result;
    EXCEPTION
        WHEN no_data_found THEN

            
            
            RETURN mc.monitoring_state.MODE_INACTIVE;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION monitoring.get_old_mode (p_host_id mss.host.id%TYPE) FROM PUBLIC;



CREATE OR REPLACE FUNCTION monitoring.get_sang_status_from_state ( p_state bigint ) RETURNS bigint AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(32) := 'monitoring.get_sang_status_from_state(): ';
        S_ERROR  bigint := -1;
        v_result bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        v_result := CASE p_state
                        WHEN mc.monitoring_state.STATE_ISP
                            THEN mc.monitoring_state.SANG_ISP
            
                        WHEN mc.monitoring_state.STATE_DOWN
                            THEN mc.monitoring_state.SANG_DOWN
            
                        WHEN mc.monitoring_state.STATE_ISP_SW
                            THEN mc.monitoring_state.SANG_ISP
            
                        WHEN mc.monitoring_state.STATE_DOWN_SW
                            THEN mc.monitoring_state.SANG_DOWN
            
                        ELSE S_ERROR
            END;
        IF ( v_result = S_ERROR ) THEN
            plog.err(S_PREFIX||'unknown state '||p_state);
        END IF;

        RETURN v_result;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION monitoring.get_sang_status_from_state ( p_state bigint ) FROM PUBLIC;



CREATE OR REPLACE FUNCTION monitoring.get_mode_from_state ( p_state bigint ) RETURNS bigint AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(32) := 'monitoring.get_mode_from_state(): ';
        S_ERROR  bigint := -1;
        v_result bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        v_result := CASE p_state
                        WHEN mc.monitoring_state.STATE_ISP
                            THEN mc.monitoring_state.MODE_ACTIVE
            
                        WHEN mc.monitoring_state.STATE_DOWN
                            THEN mc.monitoring_state.MODE_ACTIVE
            
                        WHEN mc.monitoring_state.STATE_ISP_SW
                            THEN mc.monitoring_state.MODE_SW
            
                        WHEN mc.monitoring_state.STATE_DOWN_SW
                            THEN mc.monitoring_state.MODE_SW
            
                        ELSE S_ERROR
            END;
        IF ( v_result = S_ERROR ) THEN
            plog.err(S_PREFIX||'unknown state '||p_state);
        END IF;

        RETURN v_result;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION monitoring.get_mode_from_state ( p_state bigint ) FROM PUBLIC;



CREATE OR REPLACE FUNCTION monitoring.get_state ( p_mode bigint, p_sang bigint ) RETURNS bigint AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(32) := 'monitoring.get_state(): ';
        v_result bigint;


BEGIN
        IF ( p_mode = mc.monitoring_state.MODE_ACTIVE ) THEN
            RETURN p_sang;
        ELSE
            IF ( p_sang = 1 ) THEN
                RETURN mc.monitoring_state.STATE_ISP_SW;
            ELSE
                RETURN mc.monitoring_state.STATE_DOWN_SW;
            END IF;
        END IF;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION monitoring.get_state ( p_mode bigint, p_sang bigint ) FROM PUBLIC;



CREATE OR REPLACE FUNCTION monitoring.get_mode ( p_host_id mss.host.id%TYPE, p_active mss.host.active%TYPE ) RETURNS bigint AS $body$
BEGIN
        IF ( p_active != 0 ) THEN

            IF ( monitoring.has_active_sw(p_host_id) ) THEN
                
                RETURN mc.monitoring_state.MODE_SW;
            ELSE
                RETURN mc.monitoring_state.MODE_ACTIVE;
            END IF;
        ELSE

            RETURN mc.monitoring_state.MODE_INACTIVE;
        END IF;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION monitoring.get_mode ( p_host_id mss.host.id%TYPE, p_active mss.host.active%TYPE ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE monitoring.start_interrupt ( p_host_id mss.host.id%TYPE, p_sang_state bigint, p_mode bigint, p_details mc.connection_interrupt_open.details%TYPE, p_down_date mc.connection_interrupt_open.down_date%TYPE ) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(32) := 'monitoring.start_interrupt(): ';
        v_count bigint;
        v_interrupt_type mc.connection_interrupt_open.type_id%TYPE := p_sang_state;
        v_active         mc.connection_interrupt_open.active%TYPE  := 1;


BEGIN
        IF ( p_sang_state = mc.monitoring_state.SANG_UP ) THEN
            
            RETURN;
        END IF;

        SELECT count(1) INTO STRICT v_count
        FROM mc.connection_interrupt_closed
        WHERE host_id = p_host_id;

        IF ( v_count < 1 ) THEN
            RETURN;
        END IF;


        v_interrupt_type := monitoring.get_state( p_mode, p_sang_state );
        IF ( p_mode = mc.monitoring_state.MODE_INACTIVE ) THEN
            v_active := 0;
        ELSE
            v_active := 1;
        END IF;


        INSERT INTO connection_interrupt_open(id, down_date,
                                               type_id, details, host_id, event_id, active)
        VALUES (nextval('connection_interrupt_sequence'),
                p_down_date, v_interrupt_type, p_details, p_host_id, NULL, v_active);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE monitoring.start_interrupt ( p_host_id mss.host.id%TYPE, p_sang_state bigint, p_mode bigint, p_details mc.connection_interrupt_open.details%TYPE, p_down_date mc.connection_interrupt_open.down_date%TYPE ) FROM PUBLIC;



CREATE OR REPLACE FUNCTION monitoring.end_interrupt ( p_host_id mss.host.id%TYPE, p_up_date mc.connection_interrupt_closed.up_date%TYPE ) RETURNS bigint AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(32) := 'monitoring.end_interrupt(): ';
        row_interrupt  mc.connection_interrupt_open%ROWTYPE;
        v_id           mc.connection_interrupt_closed.id%TYPE;

        v_result       mc.connection_interrupt_open.event_id%TYPE := NULL;
        v_status       mc.host_connection_status.con_int_type_id%TYPE;
        v_active       mss.host.active%TYPE;


BEGIN
        SELECT * INTO STRICT row_interrupt
        FROM connection_interrupt_open
        WHERE host_id = p_host_id
            FOR EXECUTE UPDATE;


        INSERT INTO connection_interrupt_closed(id, down_date, up_date,
                                                 type_id, minutes, details, event_id, host_id, active,
                                                 interrupt_review_status_id)
        VALUES (row_interrupt.id, row_interrupt.down_date, p_up_date, row_interrupt.type_id,
                round((p_up_date - row_interrupt.down_date) * 24*60), row_interrupt.details,
                row_interrupt.event_id, p_host_id, row_interrupt.active, row_interrupt.interrupt_review_status_id);

        v_result := row_interrupt.event_id;


        DELETE FROM connection_interrupt_open
        WHERE id = row_interrupt.id;
        RETURN v_result;

    EXCEPTION
        WHEN no_data_found THEN

            BEGIN
                SELECT id into STRICT v_id
                FROM connection_interrupt_closed
                WHERE host_id = p_host_id;
            EXCEPTION
                WHEN no_data_found THEN

                    SELECT hcs.con_int_type_id, mh.active INTO STRICT v_status,v_active
                    FROM mc.host_connection_status hcs
                             JOIN mss.host mh ON ( mh.id = hcs.host_id ) 
                    WHERE host_id = p_host_id;

                    IF ( coalesce(v_status,0) = 0 AND v_active > 0) THEN
                        INSERT INTO connection_interrupt_closed(id, up_date, details, host_id, active)
                        VALUES (nextval('connection_interrupt_sequence'), p_up_date, 'service activation', p_host_id, v_active);
                    END IF;
                    RETURN v_result;

                WHEN too_many_rows THEN
                    RETURN v_result;
            END;

            RETURN v_result;

        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception:'||sqlerrm);
            RETURN v_result;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION monitoring.end_interrupt ( p_host_id mss.host.id%TYPE, p_up_date mc.connection_interrupt_closed.up_date%TYPE ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE monitoring.check_mode_changed ( p_host_id mss.host.id%TYPE, p_sang_status bigint, p_mode bigint ) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(32) := 'monitoring.check_mode_changed(): ';
        row_old           connection_interrupt_open%ROWTYPE;
        v_now_date        timestamp(0);
        v_event_id        bigint;
        v_old_mode        bigint;
        v_details         mc.host_connection_status.details%TYPE;
        v_last_event_id   bigint := NULL;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        v_old_mode := monitoring.get_old_mode(p_host_id);

        
        IF ( p_mode != v_old_mode) THEN

            BEGIN
                SELECT * INTO STRICT row_old
                FROM connection_interrupt_open
                WHERE host_id = p_host_id;
            EXCEPTION
                WHEN no_data_found THEN

                    v_now_date := clock_timestamp();
                    v_last_event_id := monitoring.end_interrupt(p_host_id,v_now_date);

                    RETURN;
            END;


            v_now_date := clock_timestamp();

            v_last_event_id := monitoring.end_interrupt(p_host_id,v_now_date);


            IF ( p_mode = mc.monitoring_state.MODE_ACTIVE AND v_old_mode != mc.monitoring_state.MODE_ACTIVE ) THEN
                
                SELECT details INTO STRICT v_details
                FROM mc.host_connection_status hcs
                WHERE hcs.host_id = p_host_id;

                CALL monitoring.start_interrupt(p_host_id,p_sang_status,p_mode,v_details,v_now_date);
            ELSE
                CALL monitoring.start_interrupt(p_host_id,p_sang_status,p_mode,row_old.details,v_now_date);
            END IF;
            CALL monitoring.migrate_event_id(p_host_id,v_now_date);
            CALL monitoring_ticket_processes.new_event(p_host_id,p_sang_status,p_mode,v_last_event_id);
        END IF;

    EXCEPTION
        WHEN no_data_found THEN
            
            IF ( p_mode = mc.monitoring_state.MODE_ACTIVE ) THEN
                
                plog.info(S_PREFIX||'could not find old connection_interrupt_open entry for '||p_host_id||'. This should only happen after SANG has been started. ' ||sqlerrm);
            END IF;

        WHEN others THEN
            plog.err(S_PREFIX||'caught exception:'||sqlerrm);
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE monitoring.check_mode_changed ( p_host_id mss.host.id%TYPE, p_sang_status bigint, p_mode bigint ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE monitoring.check_all_status_changed ( p_host_id mss.host.id%TYPE, p_details mc.connection_interrupt_open.details%TYPE, p_mode bigint, p_old_status bigint DEFAULT 0, p_new_status bigint  DEFAULT NULL) AS $body$
DECLARE


        S_PREFIX        CONSTANT varchar(32) := 'monitoring.check_all_status_changed(): ';
        v_now_date      timestamp(0);
        r_interrupt     connection_interrupt_open%ROWTYPE;
        v_last_event_id bigint := NULL;


BEGIN
        IF ( p_old_status = mc.monitoring_state.SANG_UP ) THEN
            IF ( p_new_status = mc.monitoring_state.SANG_DOWN OR p_new_status = mc.monitoring_state.SANG_ISP ) THEN
                
                CALL monitoring.start_interrupt(p_host_id,p_new_status,p_mode,p_details,clock_timestamp());
            END IF;
        ELSIF ( p_old_status = mc.monitoring_state.SANG_DOWN ) THEN
            IF ( p_new_status = mc.monitoring_state.SANG_UP ) THEN

                v_last_event_id := monitoring.end_interrupt(p_host_id,clock_timestamp());
                CALL monitoring_ticket_processes.new_event(p_host_id,p_new_status,p_mode,v_last_event_id);
            ELSIF ( p_new_status = mc.monitoring_state.SANG_ISP ) THEN

                v_now_date      := clock_timestamp();
                v_last_event_id := monitoring.end_interrupt(p_host_id,v_now_date);
                CALL monitoring.start_interrupt(p_host_id,p_new_status,p_mode,p_details,v_now_date);
                CALL monitoring.migrate_event_id(p_host_id,v_now_date);
            END IF;
        ELSIF ( p_old_status = mc.monitoring_state.SANG_ISP ) THEN
            IF ( p_new_status = mc.monitoring_state.SANG_UP ) THEN

                v_last_event_id := monitoring.end_interrupt(p_host_id,clock_timestamp());
                CALL monitoring_ticket_processes.new_event(p_host_id,p_new_status,p_mode,v_last_event_id);
            ELSIF ( p_new_status = mc.monitoring_state.SANG_DOWN ) THEN

                v_now_date      := clock_timestamp();
                v_last_event_id := monitoring.end_interrupt(p_host_id,v_now_date);
                CALL monitoring.start_interrupt(p_host_id,p_new_status,p_mode,p_details,v_now_date);
                CALL monitoring.migrate_event_id(p_host_id,v_now_date);
            END IF;
        ELSE
            plog.debug(S_PREFIX||'unknown old sang status in parameter ('||p_old_status||')!');
        END IF;

    EXCEPTION
        WHEN others THEN
            plog.warning(S_PREFIX||'caught exception:'||sqlerrm);
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE monitoring.check_all_status_changed ( p_host_id mss.host.id%TYPE, p_details mc.connection_interrupt_open.details%TYPE, p_mode bigint, p_old_status bigint DEFAULT 0, p_new_status bigint  DEFAULT NULL) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE monitoring.collate_conn_status (p_host_id mc.mon_server_connection.host_id%TYPE) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(32) := 'monitoring.collate_conn_status(): ';



        S_ERRNO_RESOURCE_BUSY CONSTANT bigint := -30006;


        r_hcs_prev host_connection_status%ROWTYPE;

        v_old_con_int_type_id mc.host_connection_status.con_int_type_id%TYPE;
        v_old_details         mc.host_connection_status.details%TYPE;
        v_old_con_timestamp   mc.host_connection_status.con_timestamp%TYPE;

        v_new_con_int_type_id mc.host_connection_status.con_int_type_id%TYPE;
        v_new_details         mc.host_connection_status.details%TYPE;
        v_new_con_timestamp   mc.host_connection_status.con_timestamp%TYPE;

        v_new_mode        bigint;
        v_active          mss.host.active%TYPE;

        host_connection_status_cur CURSOR FOR
            SELECT con_timestamp,con_int_type_id,details
            FROM mc.host_connection_status
            WHERE host_id = p_host_id
                FOR UPDATE WAIT 3;

        mon_server_connection_cur CURSOR FOR
            SELECT status,details,con_timestamp
            FROM mon_server_connection
            WHERE host_id = p_host_id
              AND COALESCE(status, mc.monitoring_state.SANG_UP) < mc.monitoring_state.SANG_ERROR
            ORDER BY CASE COALESCE(status, mc.monitoring_state.SANG_UP)
                         WHEN mc.monitoring_state.SANG_UP THEN 0
                         WHEN mc.monitoring_state.SANG_DOWN THEN 1
                         WHEN mc.monitoring_state.SANG_ISP THEN 2
                         END;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        OPEN host_connection_status_cur;
        FETCH host_connection_status_cur INTO v_old_con_timestamp,v_old_con_int_type_id,v_old_details;


        OPEN mon_server_connection_cur;
        FETCH mon_server_connection_cur INTO v_new_con_int_type_id,v_new_details,v_new_con_timestamp;
        IF ( NOT FOUND ) THEN

            IF ( host_connection_status_cur%FOUND ) THEN
                DELETE FROM mc.host_connection_status
                WHERE host_id=p_host_id;
                RETURN;
            END IF;

            v_new_con_timestamp :=  (cast(statement_timestamp() at time zone 'UTC' as timestamp(0)) - to_date('1970-01-01','YYYY-MM-DD') ) * 86400;
        END IF;
        CLOSE mon_server_connection_cur;


        IF ( NOT FOUND ) THEN
            v_old_con_int_type_id := mc.monitoring_state.STATE_DOWN;

            BEGIN
                INSERT INTO mc.host_connection_status(host_id,con_timestamp,details,con_int_type_id)
                VALUES (p_host_id,v_new_con_timestamp,v_new_details,v_new_con_int_type_id);
            EXCEPTION
                WHEN unique_violation THEN
                    RETURN;
            END;
        END IF;


        
        SELECT active INTO STRICT v_active
        FROM mss.host
        WHERE id = p_host_id;
        v_new_mode := monitoring.get_mode(p_host_id,v_active);

        CALL monitoring.check_mode_changed(p_host_id,coalesce(v_old_con_int_type_id,0),v_new_mode);
        IF ( coalesce(v_old_con_int_type_id,0) != coalesce(v_new_con_int_type_id,0) ) THEN

            IF (host_connection_status_cur%FOUND) THEN
                UPDATE host_connection_status
                SET con_int_type_id = v_new_con_int_type_id,
                    con_timestamp   = v_new_con_timestamp,
                    details         = v_new_details
                WHERE CURRENT OF host_connection_status_cur;
            END IF;
            CALL monitoring.check_all_status_changed(p_host_id,v_new_details,v_new_mode,coalesce(v_old_con_int_type_id,0),coalesce(v_new_con_int_type_id,0));
        END IF;

        CLOSE host_connection_status_cur;

    EXCEPTION
        WHEN SQLSTATE '50003' THEN

           NULL;


        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE monitoring.collate_conn_status (p_host_id mc.mon_server_connection.host_id%TYPE) FROM PUBLIC;
