CREATE OR REPLACE PROCEDURE monitoring_ticket_processes.resolve_isp_ticket ( p_ticket_id tt.event.ticket_id%TYPE ) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(32) := 'monitoring_ticket_processes.resolve_isp_ticket(): ';
        v_subject_changed bigint;
        v_ticket_subject  varchar(2000);
        v_isp_down_date   timestamp(0);
        v_isp_up_date     timestamp(0);
        v_isp_outages_cnt bigint;
        v_duration        bigint;


BEGIN
        
        
        
        
        SELECT COUNT(*) INTO STRICT v_subject_changed FROM tt.event e
        WHERE e.type_id = mc.monitoring_state.EVENT_TYPE_ATTR_CHG AND e.details_public LIKE 'ticket subject changed:%'
          AND e.ticket_id = p_ticket_id AND e.contact_id IS NOT NULL;
        IF (v_subject_changed = 0 ) THEN

            
            
            SELECT COUNT(*), MIN(cic.down_date), MAX(cic.up_date)
            INTO STRICT v_isp_outages_cnt, v_isp_down_date, v_isp_up_date
            FROM connection_interrupt_closed cic, tt.event e
            WHERE e.ticket_id = p_ticket_id
              AND e.id = cic.event_id
              AND cic.type_id IN (mc.monitoring_state.STATE_ISP,mc.monitoring_state.STATE_ISP_SW);

            v_duration := ROUND((v_isp_up_date - v_isp_down_date) *24*60);


            IF (v_isp_outages_cnt = 1) THEN
                v_ticket_subject := 'ISP outage for '||v_duration||' minutes';
            ELSE

                
                IF (v_duration < 180) THEN
                    v_ticket_subject := v_isp_outages_cnt || ' ISP outages within ' || v_duration || ' minute';
                ELSIF (v_duration < 24*60) THEN

                    v_duration := ROUND(v_duration/60);
                    v_ticket_subject := v_isp_outages_cnt || ' ISP outages within '||v_duration||' hour';
                ELSE

                    v_duration := ROUND(v_duration/(24*60));
                    v_ticket_subject := v_isp_outages_cnt || ' ISP outages within '||v_duration||' day';
                END IF;


                IF (v_duration > 1) THEN
                    v_ticket_subject := v_ticket_subject || 's';
                END IF;
            END IF;
            CALL tt.ticket_interface.change_subject(p_ticket_id,v_ticket_subject, NULL);
        END IF;
        CALL tt.ticket_interface.change_status(p_ticket_id, mc.monitoring_state.TICKET_STATUS_RESOLVED, NULL,'automatic resolve of ISP outage ticket');

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE monitoring_ticket_processes.resolve_isp_ticket ( p_ticket_id tt.event.ticket_id%TYPE ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE monitoring_ticket_processes.new_event_up ( p_host_id mss.host.id%TYPE, p_mode bigint, p_event_id tt.event.id%TYPE DEFAULT NULL) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(32) := 'monitoring_ticket_processes.new_event_up(): ';
        S_SANG_STATUS     bigint       := mc.monitoring_state.SANG_UP;
        v_private               varchar(256) := NULL;
        v_event_details         connection_interrupt_open.details%TYPE;
        v_event_type            tt.event.type_id%TYPE;
        v_ticket_id             tt.ticket.id%TYPE := NULL;
        v_ticket_type_id        tt.ticket.type_id%TYPE;
        v_ticket_event_type_id  tt.event.type_id%TYPE;
        v_event_id              tt.event.id%TYPE;

        v_bypass                bigint;


BEGIN
        v_event_type    := mc.monitoring_state.EVENT_TYPE_UP;
        v_private       := NULL;
        v_event_details := 'service is up again';



        return;


        IF ( p_event_id IS NOT NULL ) THEN
            BEGIN
                SELECT t.id, t.type_id INTO STRICT v_ticket_id, v_ticket_type_id
                FROM tt.ticket t, tt.event e
                WHERE t.id = e.ticket_id AND e.id = p_event_id
                  AND (t.status_id < mc.monitoring_state.TICKET_STATUS_CLOSED OR t.status_id = mc.monitoring_state.TICKET_STATUS_MERGED);

            EXCEPTION
                WHEN no_data_found THEN
                    v_ticket_id := NULL;
            END;
        END IF;


        
        
        
        IF ( v_ticket_id IS NOT NULL ) THEN
            tt.CALL event_interface.addevent_new(v_event_id, v_ticket_id, v_event_type, p_host_id, v_event_details,
                                            NULL, NULL, TRUE, clock_timestamp(), TRUE);

            CALL tt.escalation_interface.clear_customer_escalation(v_ticket_id);
            CALL tt.ticket_interface.change_status(v_ticket_id,mc.monitoring_state.TICKET_STATUS_HOT,NULL,NULL);


            
            
            
            IF ( v_ticket_type_id = 4 ) THEN
                CALL monitoring_ticket_processes.resolve_isp_ticket(v_ticket_id);
            END IF;
            RETURN;

        ELSE
            
            
            v_event_id := NULL;
            RETURN;
        END IF;


        
        
        BEGIN
            
            
            tt.CALL event_interface.newevent_new(v_event_id, v_event_type, p_host_id, v_event_details, v_private, NULL, TRUE, clock_timestamp(), NULL, 1);
        EXCEPTION
            WHEN OTHERS THEN
                plog.err(S_PREFIX||'newevent_new raised exception: '||sqlerrm);
        END;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE monitoring_ticket_processes.new_event_up ( p_host_id mss.host.id%TYPE, p_mode bigint, p_event_id tt.event.id%TYPE DEFAULT NULL) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE monitoring_ticket_processes.new_event_down_or_isp ( p_host_id mss.host.id%TYPE, p_sang_status bigint, p_mode bigint, p_event_id tt.event.id%TYPE DEFAULT NULL) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(32) := 'monitoring_ticket_processes.new_event_down_or_isp(): ';
        r_interrupt             connection_interrupt_open%ROWTYPE;
        v_private               varchar(256) := NULL;
        v_event_details         connection_interrupt_open.details%TYPE;
        v_event_type            tt.event.type_id%TYPE;
        v_ticket_id             tt.ticket.id%TYPE := NULL;
        v_ip_address            varchar(15);
        v_event_id              tt.event.id%TYPE;
        dbms_job_no             bigint;
        v_old_type              bigint;
        v_old_sang              bigint;
        v_old_mode              bigint;
        v_old_active            bigint;
        v_SW_count              bigint;

        v_bypass                bigint;


BEGIN

        
        return;

        IF ( p_event_id IS NOT NULL ) THEN

            
            
            
            BEGIN
                
                SELECT type_id,active INTO STRICT v_old_type,v_old_active
                FROM ( SELECT type_id,active
                       FROM mc.connection_interrupt_closed
                       WHERE event_id = p_event_id
                         AND host_id  = p_host_id
                       ORDER BY up_date ASC) alias1 LIMIT 1;
                v_old_sang := mc.monitoring.get_sang_status_from_state( v_old_type );
                v_old_mode := mc.monitoring.get_mode_from_state( v_old_type );


                
                
                
                IF ( v_old_sang = p_sang_status ) THEN
                    
                    
                    
                    
                    IF ( v_old_mode = p_mode
                        OR v_old_mode = mc.monitoring_state.MODE_ACTIVE ) THEN
                        
                        
                        
                        
                        RETURN;
                    END IF;
                END IF;

            EXCEPTION
                WHEN no_data_found THEN

                    RETURN;
            END;

        END IF;

        IF ( p_sang_status = mc.monitoring_state.SANG_ISP ) THEN
            v_private := mc.monitoring_state.TODO_ISP_DOWN;
            v_event_type := mc.monitoring_state.EVENT_TYPE_ISP;
        ELSIF ( p_sang_status = mc.monitoring_state.SANG_DOWN ) THEN
            v_private := mc.monitoring_state.TODO_CONN_DOWN;
            v_event_type := mc.monitoring_state.EVENT_TYPE_DOWN;
        ELSE
            plog.err(S_PREFIX||'the sang state '||p_sang_status||' is not valid for this function!');
            RETURN;
        END IF;


        SELECT * INTO STRICT r_interrupt
        FROM connection_interrupt_open
        WHERE host_id = p_host_id;

        IF ( p_mode = mc.monitoring_state.MODE_SW ) THEN

            v_event_details := r_interrupt.details || CHR(10) || '(detected during service window that disables escalation)';
        ELSE
            v_event_details := r_interrupt.details;
        END IF;

        
        
        BEGIN
            
            
            tt.CALL event_interface.newevent_new(v_event_id, v_event_type, p_host_id, v_event_details, v_private, NULL, TRUE, clock_timestamp(), NULL, 1);
        EXCEPTION
            WHEN OTHERS THEN
                plog.err(S_PREFIX||'newevent_new raised exception: '||sqlerrm);
        END;


        
        
        IF (v_event_id IS NOT NULL) THEN
            
            
            UPDATE connection_interrupt_open cio
            SET event_id = v_event_id
            WHERE cio.host_id = p_host_id;

            IF ( p_sang_status = mc.monitoring_state.SANG_ISP ) THEN

                UPDATE mc.isp_link_history h
                SET h.event_id = v_event_id
                WHERE h.id IN (
                    
                    WITH numbered_link_history AS (
                        SELECT id, isp_link_id, new_isp_link_status_type_id, event_id, ROW_NUMBER() OVER (PARTITION BY isp_link_id ORDER BY change_date DESC) AS rn FROM mc.isp_link_history
                    )
                    SELECT
                        ilh.id
                    FROM mss.interface2isp_link il
                             JOIN mss.interface i ON il.interface_id = i.id
                             JOIN numbered_link_history ilh ON ilh.isp_link_id = il.isp_link_id AND ilh.rn = 1
                    WHERE i.host_id = p_host_id
                      AND ilh.event_id IS NULL
                      AND ilh.new_isp_link_status_type_id = 2
                );
            END IF;
        END IF;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE monitoring_ticket_processes.new_event_down_or_isp ( p_host_id mss.host.id%TYPE, p_sang_status bigint, p_mode bigint, p_event_id tt.event.id%TYPE DEFAULT NULL) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE monitoring_ticket_processes.new_event ( p_host_id mss.host.id%TYPE, p_sang_status bigint, p_mode bigint, p_event_id tt.event.id%TYPE DEFAULT NULL) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(32) := 'monitoring_ticket_processes.new_event(): ';


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        IF ( p_mode = mc.monitoring_state.MODE_INACTIVE AND p_sang_status > mc.monitoring_state.SANG_UP ) THEN

            
            RETURN;
        END IF;


        IF ( p_sang_status = mc.monitoring_state.SANG_UP ) THEN
            CALL monitoring_ticket_processes.new_event_up(p_host_id,p_mode,p_event_id);
        ELSIF ( p_sang_status = mc.monitoring_state.SANG_ISP OR p_sang_status = mc.monitoring_state.SANG_DOWN ) THEN
            CALL monitoring_ticket_processes.new_event_down_or_isp(p_host_id,p_sang_status,p_mode,p_event_id);
        END IF;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE monitoring_ticket_processes.new_event ( p_host_id mss.host.id%TYPE, p_sang_status bigint, p_mode bigint, p_event_id tt.event.id%TYPE DEFAULT NULL) FROM PUBLIC;
