CREATE OR REPLACE FUNCTION osag_aserto.createeventtemplate () RETURNS varchar AS $body$
DECLARE

    v_src varchar(64);
    v_json varchar(1000);

BEGIN
    select host_name||'/'||instance_name into STRICT v_src from v$instance;
    v_json := '{
"specversion": "1.0.2",
"type": "ch.open.syncify",
"source": "'|| v_src ||'",
"id": "'|| DBMS_RANDOM.varchar(TEXTVALUE260?) ||'",
"time": "'|| TO_CHAR(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS') ||'Z",
"datacontenttype": "application/json",
"data": DATA
}';
    return v_json;
  END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
 STABLE;
-- REVOKE ALL ON FUNCTION osag_aserto.createeventtemplate () FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_aserto.publishasertoaction ( p_action text, p_subj_type text, p_subj_id text, p_relation text, p_obj_type text, p_obj_id text ) AS $body$
DECLARE

    v_json varchar(1000);

BEGIN
    v_json := osag_aserto.createeventtemplate();
    v_json := REPLACE(v_json, 'DATA',
    '[
{
"event_type": "'|| p_action ||'",
"subject_type": "'|| p_subj_type ||'",
"subject_id": "'|| p_subj_id ||'",
"relation": "'|| p_relation ||'",
"object_type": "'|| p_obj_type ||'",
"object_id":"'|| p_obj_id ||'"
}
]');
    CALL OSAG_PLOG.LogRaw(1, replace(v_json, chr(10), ' '));
  END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_aserto.publishasertoaction ( p_action text, p_subj_type text, p_subj_id text, p_relation text, p_obj_type text, p_obj_id text ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_aserto.publishasertoupdate ( p_subj_type text, p_subj_prev_id text, p_subj_id text, p_relation text, p_obj_type text, p_obj_prev_id text, p_obj_id text ) AS $body$
DECLARE

    v_data varchar(600);
    v_json varchar(1000);

BEGIN
    if p_subj_prev_id = p_subj_id and p_obj_prev_id = p_obj_id then
      
      return;
    end if;

    v_data := '';
    if p_subj_prev_id is not null and p_obj_prev_id is not null then
      v_data := '{
"event_type": "delete",
"subject_type": "'|| p_subj_type ||'",
"subject_id": "'|| p_subj_prev_id ||'",
"relation": "'|| p_relation ||'",
"object_type": "'|| p_obj_type ||'",
"object_id":"'|| p_obj_prev_id ||'"
}';
    end if;

    if p_subj_id is not null and p_obj_id is not null then
      if v_data is not null then
        v_data := v_data || ', ';
      end if;
      v_data := v_data || '{
"event_type": "create",
"subject_type": "'|| p_subj_type ||'",
"subject_id": "'|| p_subj_id ||'",
"relation": "'|| p_relation ||'",
"object_type":  "'|| p_obj_type ||'",
"object_id":"'|| p_obj_id ||'"
}';
    end if;

    if v_data is null then
      return;
    end if;

    v_json := osag_aserto.createeventtemplate();
    v_json := REPLACE(v_json, 'DATA', '[ '|| v_data ||' ]');

    CALL OSAG_PLOG.LogRaw(1, replace(v_json, chr(10), ' '));
  END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_aserto.publishasertoupdate ( p_subj_type text, p_subj_prev_id text, p_subj_id text, p_relation text, p_obj_type text, p_obj_prev_id text, p_obj_id text ) FROM PUBLIC;
