CREATE OR REPLACE PROCEDURE osag_audit.add_record_raw2 (i_application_id mcaudit.record.application_id%TYPE, i_component_id mcaudit.record.component_id%TYPE, i_record_type_id mcaudit.record.record_type_id%TYPE, i_severity_id mcaudit.record.severity_id%TYPE, io_transaction_id INOUT mcaudit.record.transaction_id%TYPE, i_message mcaudit.record.message%TYPE, i_details mcaudit.record.details%TYPE, i_company_id mcaudit.record.company_id%TYPE DEFAULT NULL, i_contact_id mcaudit.record.contact_id%TYPE DEFAULT NULL, i_table_name text DEFAULT NULL, i_object_id mcaudit.record.object_id%TYPE DEFAULT NULL, i_ticket_id mcaudit.record.ticket_id%TYPE DEFAULT NULL, io_record_id INOUT mcaudit.record.id%TYPE DEFAULT NULL) AS $body$
BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        IF (io_transaction_id IS NULL) THEN
          io_transaction_id := nextval('transaction_seq');
        END IF;

        IF io_record_id IS NULL THEN
          io_record_id := nextval('record_seq');
        END IF;

        INSERT INTO record(id, timestamp, application_id, component_id, record_type_id, severity_id, message,
         details, transaction_id, company_id, contact_id, object_id, object_type_id, ticket_id)
        VALUES (io_record_id, statement_timestamp(), i_application_id, i_component_id,
                i_record_type_id, i_severity_id, i_message, i_details, io_transaction_id, i_company_id, i_contact_id,
                i_object_id, (SELECT id FROM mss.object_type WHERE table_name = i_table_name), i_ticket_id);

    END;
$body$
LANGUAGE PLPGSQL
