DROP SCHEMA IF EXISTS osag_auth CASCADE;
CREATE SCHEMA IF NOT EXISTS osag_auth;





CREATE OR REPLACE PROCEDURE osag_auth.delete_login (p_login_id login.id%TYPE) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH.delete_login(): ';

        v_contact_id stop.contact.id%TYPE;
        v_token_id auth.token.id%TYPE;
        v_replacementtoken_id auth.token.id%TYPE;

        c_all_user_permission_ids CURSOR FOR
            SELECT up.id FROM auth.login2profile l2p
                                  JOIN auth.profile p ON l2p.profile_id = p.id
                                  JOIN auth.user_permission up ON p.id = up.profile_id
            WHERE l2p.login_id = p_login_id;


  lv_p RECORD;

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        SELECT contact_id, token_id, replacementtoken_id INTO STRICT v_contact_id, v_token_id, v_replacementtoken_id
        FROM login
        WHERE id = p_login_id;

        CALL TT.OSAG_NOTIFY.delete_notifications_for_login(p_login_id);

        DELETE FROM auth.consented_term WHERE login_id = p_login_id;
        DELETE FROM mss.news_entry_2_login WHERE login_id = p_login_id;

        BEGIN

            FOR lv_user_permission IN c_all_user_permission_ids LOOP
                    DELETE FROM auth.user_company_scope where permission_id = lv_user_permission.id;
                    DELETE FROM auth.user_company_unit_scope where permission_id = lv_user_permission.id;
                    DELETE FROM auth.user_unit_scope where permission_id = lv_user_permission.id;
                    DELETE FROM auth.user_service_scope where permission_id = lv_user_permission.id;
                    DELETE FROM auth.user_service_type_scope where permission_id = lv_user_permission.id;
                    DELETE FROM auth.user_permission WHERE id = lv_user_permission.id;
            END LOOP;

            FOR lv_p IN ( SELECT p.id
                          FROM auth.login2profile l2p JOIN auth.profile p ON l2p.profile_id = p.id
                          WHERE l2p.login_id = p_login_id AND p.is_automatic = 1) LOOP
                DELETE FROM auth.login2profile WHERE profile_id = lv_p.id;
                DELETE FROM auth.profile WHERE id = lv_p.id;
            END LOOP;
        EXCEPTION
            WHEN no_data_found THEN

                NULL;
            WHEN OTHERS THEN
                RAISE;
        END;


        DELETE FROM auth.login WHERE id = p_login_id;


        BEGIN

            DELETE FROM stop.contact
            WHERE id = v_contact_id
              AND id NOT IN (SELECT contact_id FROM login WHERE id != p_login_id)
              AND NOT EXISTS (select 1 from mcaudit.record where contact_id = v_contact_id);
        EXCEPTION
            WHEN OTHERS THEN
                plog.notice(S_PREFIX||'caught exception when deleting contact: '||sqlerrm);
        END;


        BEGIN
            DELETE FROM auth.token
            WHERE (id = v_token_id OR id = v_replacementtoken_id) AND tokenform_id = 3;
        EXCEPTION
            WHEN OTHERS THEN
                plog.err(S_PREFIX||'caught exception when deleting softokens: '||sqlerrm);
        END;

        plog.notice(S_PREFIX||'deleted login id "'||p_login_id||'"');

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth.delete_login (p_login_id login.id%TYPE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_auth.grant_role (p_login_id login.id%TYPE, p_role_id role.id%TYPE) AS $body$
DECLARE

        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH.grant_user_role(): ';

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        IF (p_role_id = 3) THEN

            CALL AUTH.OSAG_AUTH.grant_user_role(p_login_id, 1000);
        ELSE
            plog.notice(S_PREFIX||'Can only grant permissions to the mc-cust-radius radius role, use grant_user_role instead');
            RAISE data_exception;
        END IF;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth.grant_role (p_login_id login.id%TYPE, p_role_id role.id%TYPE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_auth.grant_user_role (p_login_id login.id%TYPE, p_user_role_id user_role.id%TYPE) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH.grant_user_role(): ';

        v_count bigint := 0;
        v_ap_id bigint :=0;
        v_new_permission_id bigint :=0;
        v_company_id bigint :=0;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        SELECT COUNT(*) INTO STRICT v_count
        FROM auth.user_permission up join auth.profile p on up.PROFILE_ID = p.id join auth.login2profile l2p on p.id = l2p.profile_id
        WHERE user_role_id = p_user_role_id and l2p.login_id = p_login_id  LIMIT 1;

        SELECT coalesce(min(p.id), 0) INTO STRICT v_ap_id
        FROM auth.profile p join auth.login2profile l2p on p.id = l2p.profile_id
        WHERE p.is_automatic = 1 and l2p.login_id = p_login_id  LIMIT 1;

        SELECT company_id into STRICT v_company_id
        FROM auth.login where id = p_login_id;


        IF (v_count = 0) THEN
            IF (v_ap_id = 0) THEN
                
                SELECT nextval('seq_profile') INTO STRICT v_ap_id;
                INSERT INTO auth.profile(id, name, is_automatic) values (v_ap_id, 'automatic profile', 1);
                INSERT INTO auth.login2profile(login_id, profile_id) values (p_login_id, v_ap_id);
            END IF;
            SELECT nextval('seq_user_permission') INTO STRICT v_new_permission_id;

            INSERT INTO auth.user_permission(id, user_role_id, profile_id) values (v_new_permission_id, p_user_role_id, v_ap_id);
            INSERT INTO auth.user_company_scope(id, company_id, permission_id, sdp_access) values (nextval('seq_user_company_scope'), v_company_id, v_new_permission_id, 1);
        END IF;

        plog.debug(S_PREFIX||'granted company scope role id "'||p_user_role_id||'" to login id "'||p_login_id||'"');

    EXCEPTION
        WHEN OTHERS THEN

            
            IF (SQLSTATE != -00001) THEN
                plog.err(S_PREFIX||'caught exception: '||sqlerrm);
                RAISE;
            END IF;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth.grant_user_role (p_login_id login.id%TYPE, p_user_role_id user_role.id%TYPE) FROM PUBLIC;
