CREATE OR REPLACE PROCEDURE osag_auth_passport.add_alias (p_login_id passport_login.id%TYPE, p_alias passport_alias.alias%TYPE, p_nocheck bigint DEFAULT 0) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.add_alias(): ';
        v_homeauthhost_id passport_login.homeauthhost_id%TYPE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        SELECT homeauthhost_id INTO STRICT v_homeauthhost_id
        FROM passport_login
        WHERE id = p_login_id;

        IF (osag_auth_passport.check_login_unique(p_alias, v_homeauthhost_id)) THEN
            INSERT INTO passport_alias(id, login_id, alias)
            VALUES (nextval('seq_alias_id'), p_login_id, p_alias);

            plog.notice(S_PREFIX||'added alias "'||p_alias||'" for login id "'||p_login_id||'"');
        ELSE
            RAISE EXCEPTION '%', 'alias "'||p_alias||'" is not unique' USING ERRCODE = OSAG_AUTH_STATE.S_ERRNO_DUPLICATE_ALIAS;
        END IF;

    EXCEPTION
        WHEN OTHERS THEN
            IF (SQLSTATE != -00001) THEN
                IF (p_nocheck != 1) THEN
                    plog.err(S_PREFIX||'caught exception: '||sqlerrm);
                END IF;
                RAISE;
            END IF;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth_passport.add_alias (p_login_id passport_login.id%TYPE, p_alias passport_alias.alias%TYPE, p_nocheck bigint DEFAULT 0) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_auth_passport.add_softtoken (p_token_id OUT token.id%TYPE, p_tokenserial OUT token.serial%TYPE, p_company_id token.company_id%TYPE, p_softtokenexpiry token.expirydate%TYPE, p_softtokenseed token.seed%TYPE, p_softtoken_validfrom token.validfrom%TYPE) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.add_softtoken(): ';


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        SELECT nextval('seq_token_id') INTO STRICT p_token_id
;
        SELECT 'MC-'||to_char(p_token_id,'FM000000000') into STRICT p_tokenserial
;

        INSERT INTO token(id, company_id, enabled, expirydate, seed, serial, seciddrift,
                           actercount, dpblob, tokenform_id,
                           tokentype_id, token_pool_id, validfrom, activated)
        VALUES (p_token_id, p_company_id, 1, p_softtokenexpiry, p_softtokenseed, p_tokenserial, 0,
                0, NULL, OSAG_AUTH_STATE.C_OSAG_TOKENFORM_SOFT,
                OSAG_AUTH_STATE.C_OSAG_TOKENTYPE_SOFTTOKEN, NULL, p_softtoken_validfrom, 0);

        plog.debug(S_PREFIX||'created token "'||p_tokenserial||'"');

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth_passport.add_softtoken (p_token_id OUT token.id%TYPE, p_tokenserial OUT token.serial%TYPE, p_company_id token.company_id%TYPE, p_softtokenexpiry token.expirydate%TYPE, p_softtokenseed token.seed%TYPE, p_softtoken_validfrom token.validfrom%TYPE) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_auth_passport.check_auth_login_email_unique (p_email auth.passport_login.email%TYPE) RETURNS boolean AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.check_auth_login_email_unique(): ';

        v_count bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        IF (p_email IS NULL) THEN
            RETURN(TRUE);
        END IF;

        SELECT count(*) INTO STRICT v_count
        FROM auth.passport_login l
        WHERE LOWER(l.email) = LOWER(p_email);

        IF (v_count = 0) THEN
            plog.debug(S_PREFIX||'auth email is unique: "'||p_email||'"');
            RETURN(TRUE);
        END IF;

        plog.debug(S_PREFIX||'auth email is not unique: "'||p_email||'"');
        RETURN(FALSE);

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION osag_auth_passport.check_auth_login_email_unique (p_email auth.passport_login.email%TYPE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_auth_passport.check_auth_email_unique (p_email auth.passport_login.email%TYPE) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.check_auth_email_unique(): ';


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        IF (NOT osag_auth_passport.check_auth_login_email_unique(p_email)) THEN
            RAISE EXCEPTION '%', 'email "'||p_email||'" is not unique' USING ERRCODE = OSAG_AUTH_STATE.S_ERRNO_DUPLICATE_EMAIL;
            plog.notice(S_PREFIX||'auth email address is not unique "'||p_email||'"');
        END IF;

        plog.debug(S_PREFIX||'checked auth email "'||p_email||'"');

    EXCEPTION
        WHEN OTHERS THEN
            IF (SQLSTATE != -00001) THEN
                plog.err(S_PREFIX||'caught exception: '||sqlerrm);
                RAISE;
            END IF;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth_passport.check_auth_email_unique (p_email auth.passport_login.email%TYPE) FROM PUBLIC;



