CREATE OR REPLACE FUNCTION osag_auth_passport.check_login_unique (p_login passport_login.login%TYPE, p_homeauthhost_id passport_login.homeauthhost_id%TYPE) RETURNS boolean AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.check_login_unique(): ';

        v_count bigint;
        v_company_id stop.company.id%TYPE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        
        SELECT company_id INTO STRICT v_company_id
        FROM authhost2authsys a2a, authsys
        WHERE a2a.authhost_id = p_homeauthhost_id
          AND a2a.authsys_id = authsys.id;

        SELECT count(*) INTO STRICT v_count
        FROM passport_login l
        WHERE lower(l.login) = lower(p_login)
          AND company_id = v_company_id;

        IF (v_count = 0) THEN
            SELECT count(*) INTO STRICT v_count
            FROM passport_alias a, passport_login l
            WHERE lower(a.alias) = lower(p_login)
              AND a.login_id = l.id
              AND l.company_id = v_company_id;

            IF (v_count = 0) THEN
                plog.debug(S_PREFIX||'login/alias "'||p_login||'" is unique');
                RETURN(true);
            END IF;
            plog.debug(S_PREFIX||'login/alias "'||p_login||'" collides with existing alias');
        END IF;

        plog.debug(S_PREFIX||'login/alias "'||p_login||'" is not unique');
        RETURN(false);

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION osag_auth_passport.check_login_unique (p_login passport_login.login%TYPE, p_homeauthhost_id passport_login.homeauthhost_id%TYPE) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_auth_passport.check_email_unique (p_email stop.passport_contact.email%TYPE) RETURNS boolean AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.check_email_unique(): ';

        v_count bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        IF (p_email IS NULL) THEN
            RETURN(TRUE);
        END IF;

        SELECT count(*) INTO STRICT v_count
        FROM stop.passport_contact sc
        WHERE LOWER(sc.email) = LOWER(p_email);

        IF (v_count = 0) THEN
            RETURN(TRUE);
        END IF;

        RETURN(FALSE);

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION osag_auth_passport.check_email_unique (p_email stop.passport_contact.email%TYPE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_auth_passport.check_recent_password (p_login_id passport_login.id%TYPE, p_password text) AS $body$
DECLARE

        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.check_recent_password(): ';

        v_passwordexpiryenabled AUTHSYS.PASSWORDEXPIRYENABLED%TYPE;
        v_recentpassword_count bigint;

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        SELECT authsys.passwordexpiryenabled INTO STRICT v_passwordexpiryenabled
        FROM auth.passport_login l, auth.authhost2authsys h2a, auth.authsys
        WHERE l.id = p_login_id
          AND l.homeauthhost_id = h2a.authhost_id
          AND h2a.authsys_id = authsys.id;

        IF (v_passwordexpiryenabled = 1) THEN
            SELECT count(id) INTO STRICT v_recentpassword_count
            FROM passport_recentpassword
            WHERE login_id = p_login_id
              AND password = osag_auth_passport.hash_password(p_password, salt);

            IF (v_recentpassword_count > 0) THEN

                RAISE EXCEPTION '%', 'The password has been recently used.' USING ERRCODE = OSAG_AUTH_STATE.S_ERRNO_PASSWORD_RECENTLY_USED;
            END IF;
        END IF;

    EXCEPTION
        WHEN OSAG_AUTH_STATE.password_recently_used THEN
            plog.debug(S_prefix||'recently used password detected: '||sqlerrm);
            RAISE;

        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth_passport.check_recent_password (p_login_id passport_login.id%TYPE, p_password text) FROM PUBLIC;



