CREATE OR REPLACE PROCEDURE osag_auth_passport.delete_login (p_login_id passport_login.id%TYPE) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.delete_login(): ';

        v_contact_id stop.passport_contact.id%TYPE;
        v_token_id auth.token.id%TYPE;
        v_replacementtoken_id auth.token.id%TYPE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        SELECT contact_id, token_id, replacementtoken_id INTO STRICT v_contact_id, v_token_id, v_replacementtoken_id
        FROM passport_login
        WHERE id = p_login_id;

        DELETE FROM auth.passport_login2groups WHERE login_id = p_login_id;
        DELETE FROM auth.passport_login2tunnelgroup WHERE login_id = p_login_id;
        DELETE FROM auth.passport_alias WHERE login_id = p_login_id;
        DELETE FROM auth.passport_recentpassword WHERE login_id = p_login_id;
        DELETE FROM auth.passport_temp_access_key WHERE login_id = p_login_id;

        DELETE FROM auth.passport_login WHERE id = p_login_id;


        BEGIN
            DELETE FROM stop.passport_contact_sync
            WHERE contact_id = v_contact_id;

            DELETE FROM stop.passport_contact
            WHERE id = v_contact_id
              AND id NOT IN (SELECT contact_id FROM passport_login WHERE id != p_login_id);
        EXCEPTION
            WHEN OTHERS THEN
                plog.notice(S_PREFIX||'caught exception when deleting contact: '||sqlerrm);
        END;


        BEGIN
            DELETE FROM auth.token
            WHERE (id = v_token_id OR id = v_replacementtoken_id) AND tokenform_id = 3;
        EXCEPTION
            WHEN OTHERS THEN
                plog.err(S_PREFIX||'caught exception when deleting softokens: '||sqlerrm);
        END;

        plog.notice(S_PREFIX||'deleted login id "'||p_login_id||'"');

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth_passport.delete_login (p_login_id passport_login.id%TYPE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_auth_passport.delete_login_sync (p_login_id OUT passport_login.id%TYPE, p_contact_id OUT passport_login.contact_id%TYPE, p_login passport_login.login%TYPE, p_syncdomain_id syncdomain.id%TYPE) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.delete_login_ads(): ';

        v_login passport_login%ROWTYPE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        BEGIN
            SELECT l.* INTO STRICT v_login FROM passport_login l, stop.passport_contact_sync scs
            WHERE l.login = p_login
              AND l.contact_id = scs.contact_id
              AND scs.syncdomain_id = p_syncdomain_id;

        EXCEPTION
            WHEN no_data_found THEN
                RAISE EXCEPTION '%', 'no record found for login="'||p_login||'", syncdomain_id='||p_syncdomain_id USING ERRCODE = OSAG_AUTH_STATE.S_ERRNO_NO_LOGIN_RECORD;
            WHEN OTHERS THEN
                RAISE;

        END;


        p_login_id := v_login.id;
        p_contact_id := v_login.contact_id;

        CALL osag_auth_passport.delete_login(v_login.id);

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth_passport.delete_login_sync (p_login_id OUT passport_login.id%TYPE, p_contact_id OUT passport_login.contact_id%TYPE, p_login passport_login.login%TYPE, p_syncdomain_id syncdomain.id%TYPE) FROM PUBLIC;



