CREATE OR REPLACE PROCEDURE osag_auth_passport.insert_login (p_login_id OUT passport_login.id%TYPE, p_login passport_login.login%TYPE, p_passwordtype_id passwordtype.id%TYPE, p_password text, p_twofactorenabled passport_login.twofactorenabled%TYPE, p_token_id token.id%TYPE, p_replacementtoken_id token.id%TYPE, p_homeauthhost_id authhost.id%TYPE, p_locked passport_login.locked%TYPE, p_maxretries passport_login.maxretries%TYPE, p_firstname stop.passport_contact.firstname%TYPE, p_lastname stop.passport_contact.lastname%TYPE, p_direct stop.passport_contact.direct%TYPE, p_mobile stop.passport_contact.mobile%TYPE, p_home stop.passport_contact.home%TYPE, p_fax stop.passport_contact.fax%TYPE, p_email stop.passport_contact.email%TYPE, p_authemail auth.passport_login.email%TYPE, p_company_id stop.company.id%TYPE, p_anytunnelgroup passport_login.anytunnelgroup%TYPE DEFAULT 0, p_passwordexpiry passport_login.passwordexpiry%TYPE DEFAULT NULL, p_cost_center_id mss.cost_center.id%TYPE DEFAULT NULL, p_function stop.passport_contact.function%TYPE DEFAULT NULL, p_comments stop.passport_contact.comments%TYPE DEFAULT NULL, p_authtype_id auth.authtype.id%TYPE DEFAULT NULL, p_smsauthnumber passport_login.smsauthnumber%TYPE DEFAULT NULL) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.insert_login(): ';

        v_contact_id stop.passport_contact.id%TYPE;
        v_nopasswordonly bigint;
        v_default_uuid auth.user_unit.id%TYPE;
        v_logintype auth.passport_login.logintype_id%TYPE;

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        plog.debug(S_PREFIX||'inserting into auth.passport_login.email: "'||p_authemail||'" for login "'||p_login||'"');

        IF (NOT osag_auth_passport.check_login_unique(p_login, p_homeauthhost_id)) THEN
            RAISE EXCEPTION '%', 'login "'||p_login||'" is not unique' USING ERRCODE = OSAG_AUTH_STATE.S_ERRNO_DUPLICATE_LOGIN;
        END IF;



        
        
        

        
        
        
        IF p_twofactorenabled = 0 AND p_locked = 0 AND (NOT osag_auth_passport.is_password_only_allowed(p_homeauthhost_id)) THEN
            RAISE EXCEPTION '%', 'Password-only authentication is not allowed for unlocked users.' USING ERRCODE = OSAG_AUTH_STATE.S_ERRNO_NO_PASSWORD_ONLY;
        END IF;


        SELECT id INTO STRICT v_default_uuid FROM auth.user_unit WHERE company_id = p_company_id AND default_unit = 1;


        SELECT nextval('contact_seq') INTO STRICT v_contact_id
;


        INSERT INTO stop.passport_contact(id, firstname, lastname, direct, mobile, home, fax,
                                  email, company_id, function, created, modified, comments)
        VALUES (v_contact_id,
                substr(p_firstname, 1, 50),
                substr(p_lastname, 1, 50),
                substr(p_direct, 1, 30),
                substr(p_mobile, 1, 30),
                substr(p_home, 1, 30),
                substr(p_fax, 1, 30),
                substr(p_email, 1, 250),
                p_company_id,
                substr(p_function, 1, 100),
                statement_timestamp(),
                statement_timestamp(),
                substr(p_comments, 1, 200));

        plog.debug(S_PREFIX||'created contact id "'||v_contact_id||'" for login "'||p_login||'"');

        BEGIN


            SELECT nextval('seq_login_id') INTO STRICT p_login_id
;


            v_logintype := NULL;
            IF p_anytunnelgroup = 1 THEN
              v_logintype := 1;
            END IF;

            INSERT INTO passport_login(id, login, contact_id, passwordtype_id, twofactorenabled, token_id, replacementtoken_id,
                               enabled, homeauthhost_id, locked, maxretries, anytunnelgroup, passwordexpiry, cost_center_id, user_unit_id, email, authtype_id, smsauthnumber, creationdate, logintype_id)
            VALUES (p_login_id, p_login, v_contact_id, p_passwordtype_id, p_twofactorenabled, p_token_id, p_replacementtoken_id,
                    1, p_homeauthhost_id, p_locked, p_maxretries, p_anytunnelgroup, p_passwordexpiry, p_cost_center_id, v_default_uuid, p_authemail, p_authtype_id, p_smsauthnumber, statement_timestamp(), v_logintype);

        EXCEPTION
            WHEN OTHERS THEN
                IF (SQLSTATE = -00001) THEN
                    RAISE EXCEPTION '%', 'login "'||p_login||'" is not unique' USING ERRCODE = OSAG_AUTH_STATE.S_ERRNO_DUPLICATE_LOGIN;
                ELSE
                    RAISE;
                END IF;
        END;


        IF (p_password IS NOT NULL) THEN
            CALL osag_auth_passport.set_password(p_login_id, p_password, FALSE, TRUE);
        END IF;

        plog.notice(S_PREFIX||'created login id  "'||p_login_id||'" for login "'||p_login||'"');

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth_passport.insert_login (p_login_id OUT passport_login.id%TYPE, p_login passport_login.login%TYPE, p_passwordtype_id passwordtype.id%TYPE, p_password text, p_twofactorenabled passport_login.twofactorenabled%TYPE, p_token_id token.id%TYPE, p_replacementtoken_id token.id%TYPE, p_homeauthhost_id authhost.id%TYPE, p_locked passport_login.locked%TYPE, p_maxretries passport_login.maxretries%TYPE, p_firstname stop.passport_contact.firstname%TYPE, p_lastname stop.passport_contact.lastname%TYPE, p_direct stop.passport_contact.direct%TYPE, p_mobile stop.passport_contact.mobile%TYPE, p_home stop.passport_contact.home%TYPE, p_fax stop.passport_contact.fax%TYPE, p_email stop.passport_contact.email%TYPE, p_authemail auth.passport_login.email%TYPE, p_company_id stop.company.id%TYPE, p_anytunnelgroup passport_login.anytunnelgroup%TYPE DEFAULT 0, p_passwordexpiry passport_login.passwordexpiry%TYPE DEFAULT NULL, p_cost_center_id mss.cost_center.id%TYPE DEFAULT NULL, p_function stop.passport_contact.function%TYPE DEFAULT NULL, p_comments stop.passport_contact.comments%TYPE DEFAULT NULL, p_authtype_id auth.authtype.id%TYPE DEFAULT NULL, p_smsauthnumber passport_login.smsauthnumber%TYPE DEFAULT NULL) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_auth_passport.insert_login_sync (p_contact_id OUT stop.passport_contact.id%TYPE, p_login_id OUT passport_login.id%TYPE, p_login passport_login.login%TYPE, p_homeauthhost_id authhost.id%TYPE, p_maxretries passport_login.maxretries%TYPE, p_passwordtype_id passport_login.passwordtype_id%TYPE, p_password text, p_passwordexpiryoffset authsys.passwordexpiryoffset%TYPE, p_twofactorenabled passport_login.twofactorenabled%TYPE, p_locked passport_login.locked%TYPE, p_firstname stop.passport_contact.firstname%TYPE, p_lastname stop.passport_contact.lastname%TYPE, p_direct stop.passport_contact.direct%TYPE, p_mobile stop.passport_contact.mobile%TYPE, p_home stop.passport_contact.home%TYPE, p_fax stop.passport_contact.fax%TYPE, p_email stop.passport_contact.email%TYPE, p_authemail auth.passport_login.email%TYPE, p_syncdomain_id auth.syncdomain.id%TYPE, p_synctype auth.synctype.short%TYPE, p_sid stop.passport_contact_sync.sid%TYPE, p_guid stop.passport_contact_sync.guid%TYPE, p_domain stop.passport_contact_sync.domain%TYPE, p_usnchanged stop.passport_contact_sync.usnchanged%TYPE, p_cost_center_id mss.cost_center.id%TYPE DEFAULT NULL, p_function stop.passport_contact.function%TYPE DEFAULT NULL, p_merge bigint DEFAULT 0, p_comments stop.passport_contact.comments%TYPE DEFAULT NULL, p_authtype_id auth.authtype.id%TYPE DEFAULT NULL, p_smsauthnumber passport_login.smsauthnumber%TYPE DEFAULT NULL, p_softtokenseed token.seed%TYPE DEFAULT NULL, p_softtokenexpiry text DEFAULT NULL, p_softtoken_validfrom text DEFAULT NULL) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.insert_login_sync(): ';

        v_company_id stop.company.id%TYPE;
        v_autoemailaliasesenabled authsys.autoemailaliasesenabled%TYPE;
        v_token_id token.id%TYPE;
        v_tokenserial token.serial%TYPE;
        v_login passport_login%ROWTYPE;
        v_contact stop.passport_contact%ROWTYPE;
        v_authemail auth.passport_login.email%TYPE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);


        SELECT company_id, authsys.autoemailaliasesenabled INTO STRICT v_company_id, v_autoemailaliasesenabled FROM authsys, syncdomain
        WHERE authsys.id = syncdomain.authsys_id
          AND syncdomain.id = p_syncdomain_id;

        BEGIN

             CALL osag_auth_passport.insert_login(p_login_id, p_login, p_passwordtype_id, NULL, p_twofactorenabled, NULL, NULL, p_homeauthhost_id,
                         p_locked, p_maxretries, p_firstname, p_lastname, p_direct, p_mobile, p_home, p_fax, p_email, p_authemail, v_company_id,
                         0, NULL, p_cost_center_id, p_function, p_comments, p_authtype_id, p_smsauthnumber);

            IF (p_password IS NOT NULL) THEN
                CALL osag_auth_passport.set_password(p_login_id, p_password, TRUE, TRUE, p_passwordexpiryoffset, FALSE);
            END IF;

            IF (p_softtokenseed IS NOT NULL) THEN
                 CALL osag_auth_passport.add_softtoken(v_token_id, v_tokenserial, v_company_id, to_date(p_softtokenexpiry,'DD-MM-YYYY'), p_softtokenseed, to_date(p_softtoken_validfrom,'DD-MM-YYYY'));

                UPDATE passport_login SET token_id=v_token_id WHERE id=p_login_id;
                plog.notice(S_PREFIX||'assigned token "'||v_tokenserial||'" to login "'||p_login||'" ('||p_login_id||')');
            END IF;


        EXCEPTION
            WHEN OSAG_AUTH_STATE.duplicate_login OR OSAG_AUTH_STATE.duplicate_email THEN

                
                
                IF (p_merge != 0) THEN
                    plog.notice('encountered non-unique login '''||p_login||''' when ''merge'' flag set');


                    
                    

                    
                    BEGIN
                        SELECT l.* INTO STRICT v_login FROM passport_login l, stop.passport_contact sc
                        WHERE (LOWER(l.login) = LOWER(p_login))
                          AND l.homeauthhost_id = p_homeauthhost_id
                          AND l.contact_id = sc.id 
                        EXCEPT
                        SELECT l.* FROM passport_login l, stop.passport_contact_sync scs
                        WHERE LOWER(l.login) = LOWER(p_login)
                          AND l.homeauthhost_id = p_homeauthhost_id
                          AND l.contact_id = scs.contact_id;


                        
                        
                        
                        
                        SELECT * INTO STRICT v_contact FROM stop.passport_contact
                        WHERE v_login.contact_id = id;

                        p_contact_id := v_contact.id;
                        p_login_id := v_login.id;
                        v_authemail := v_login.email;

                        plog.notice('found eligible login ID '''||p_login_id||''', contact ID '''||p_contact_id||''' to merge with');


                        CALL osag_auth_passport.update_login(v_login.id, p_login, p_passwordtype_id, NULL, v_login.twofactorenabled, v_login.token_id, v_login.replacementtoken_id,
                                     v_login.homeauthhost_id, v_login.locked, v_login.maxretries, p_firstname, p_lastname, p_direct, p_mobile, p_home, p_fax, coalesce(p_email,
                                                                                                                                                                  v_contact.email), v_authemail, v_contact.company_id, v_login.anytunnelgroup, v_login.passwordexpiry, p_cost_center_id, p_function, p_comments, p_smsauthnumber);

                    EXCEPTION
                        WHEN no_data_found THEN
                            RAISE EXCEPTION '%', 'duplicate login "'||p_login||'" doesn''t qualify for merging (assigned to different authhost or sync domain)' USING ERRCODE = OSAG_AUTH_STATE.S_ERRNO_DUPLICATE_LOGIN;
                        WHEN OTHERS THEN
                            RAISE;
                    END;

                ELSE
                    RAISE;
                END IF;

            WHEN OTHERS THEN
                RAISE;


        END;

        SELECT contact_id INTO STRICT p_contact_id FROM passport_login
        WHERE id = p_login_id;


        INSERT INTO stop.passport_contact_sync(contact_id, syncdomain_id, synctype_id, sid, guid, domain, usnchanged)
        VALUES (p_contact_id, p_syncdomain_id, (SELECT id FROM auth.synctype WHERE short = p_synctype),
                p_sid, p_guid, p_domain, p_usnchanged);

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth_passport.insert_login_sync (p_contact_id OUT stop.passport_contact.id%TYPE, p_login_id OUT passport_login.id%TYPE, p_login passport_login.login%TYPE, p_homeauthhost_id authhost.id%TYPE, p_maxretries passport_login.maxretries%TYPE, p_passwordtype_id passport_login.passwordtype_id%TYPE, p_password text, p_passwordexpiryoffset authsys.passwordexpiryoffset%TYPE, p_twofactorenabled passport_login.twofactorenabled%TYPE, p_locked passport_login.locked%TYPE, p_firstname stop.passport_contact.firstname%TYPE, p_lastname stop.passport_contact.lastname%TYPE, p_direct stop.passport_contact.direct%TYPE, p_mobile stop.passport_contact.mobile%TYPE, p_home stop.passport_contact.home%TYPE, p_fax stop.passport_contact.fax%TYPE, p_email stop.passport_contact.email%TYPE, p_authemail auth.passport_login.email%TYPE, p_syncdomain_id auth.syncdomain.id%TYPE, p_synctype auth.synctype.short%TYPE, p_sid stop.passport_contact_sync.sid%TYPE, p_guid stop.passport_contact_sync.guid%TYPE, p_domain stop.passport_contact_sync.domain%TYPE, p_usnchanged stop.passport_contact_sync.usnchanged%TYPE, p_cost_center_id mss.cost_center.id%TYPE DEFAULT NULL, p_function stop.passport_contact.function%TYPE DEFAULT NULL, p_merge bigint DEFAULT 0, p_comments stop.passport_contact.comments%TYPE DEFAULT NULL, p_authtype_id auth.authtype.id%TYPE DEFAULT NULL, p_smsauthnumber passport_login.smsauthnumber%TYPE DEFAULT NULL, p_softtokenseed token.seed%TYPE DEFAULT NULL, p_softtokenexpiry text DEFAULT NULL, p_softtoken_validfrom text DEFAULT NULL) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_auth_passport.insert_login_sync2 (p_contact_id OUT stop.passport_contact.id%TYPE, p_login_id OUT passport_login.id%TYPE, p_login passport_login.login%TYPE, p_homeauthhost_id authhost.id%TYPE, p_maxretries passport_login.maxretries%TYPE, p_passwordtype_id passport_login.passwordtype_id%TYPE, p_password text, p_passwordexpiryoffset authsys.passwordexpiryoffset%TYPE, p_twofactorenabled passport_login.twofactorenabled%TYPE, p_locked passport_login.locked%TYPE, p_firstname stop.passport_contact.firstname%TYPE, p_lastname stop.passport_contact.lastname%TYPE, p_direct stop.passport_contact.direct%TYPE, p_mobile stop.passport_contact.mobile%TYPE, p_home stop.passport_contact.home%TYPE, p_fax stop.passport_contact.fax%TYPE, p_email stop.passport_contact.email%TYPE, p_authemail auth.passport_login.email%TYPE, p_syncdomain_id auth.syncdomain.id%TYPE, p_synctype auth.synctype.short%TYPE, p_sid stop.passport_contact_sync.sid%TYPE, p_guid stop.passport_contact_sync.guid%TYPE, p_domain stop.passport_contact_sync.domain%TYPE, p_usnchanged stop.passport_contact_sync.usnchanged%TYPE, p_cost_center_id mss.cost_center.id%TYPE DEFAULT NULL, p_function stop.passport_contact.function%TYPE DEFAULT NULL, p_merge bigint DEFAULT 0, p_comments stop.passport_contact.comments%TYPE DEFAULT NULL, p_authtype_id auth.authtype.id%TYPE DEFAULT NULL, p_smsauthnumber passport_login.smsauthnumber%TYPE DEFAULT NULL, p_softtokenseed token.seed%TYPE DEFAULT NULL, p_softtokenexpiry text DEFAULT NULL, p_softtoken_validfrom text DEFAULT NULL, p_distinguishedname stop.passport_contact_sync.distinguishedname%TYPE DEFAULT NULL) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.insert_login_sync2(): ';

        v_company_id stop.company.id%TYPE;
        v_autoemailaliasesenabled authsys.autoemailaliasesenabled%TYPE;
        v_token_id token.id%TYPE;
        v_tokenserial token.serial%TYPE;
        v_login passport_login%ROWTYPE;
        v_contact stop.passport_contact%ROWTYPE;
        v_authemail auth.passport_login.email%TYPE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);


        SELECT company_id, authsys.autoemailaliasesenabled INTO STRICT v_company_id, v_autoemailaliasesenabled FROM authsys, syncdomain
        WHERE authsys.id = syncdomain.authsys_id
          AND syncdomain.id = p_syncdomain_id;

        BEGIN
             CALL osag_auth_passport.insert_login(p_login_id, p_login, p_passwordtype_id, NULL, p_twofactorenabled, NULL, NULL, p_homeauthhost_id,
                         p_locked, p_maxretries, p_firstname, p_lastname, p_direct, p_mobile, p_home, p_fax, p_email, p_authemail, v_company_id,
                         0, NULL, p_cost_center_id, p_function, p_comments, p_authtype_id, p_smsauthnumber);

            IF (p_password IS NOT NULL) THEN
                CALL osag_auth_passport.set_password(p_login_id, p_password, TRUE, TRUE, p_passwordexpiryoffset, FALSE);
            END IF;

            IF (p_softtokenseed IS NOT NULL) THEN
                 CALL osag_auth_passport.add_softtoken(v_token_id, v_tokenserial, v_company_id, to_date(p_softtokenexpiry,'DD-MM-YYYY'), p_softtokenseed, to_date(p_softtoken_validfrom,'DD-MM-YYYY'));

                UPDATE passport_login SET token_id=v_token_id WHERE id=p_login_id;
                plog.notice(S_PREFIX||'assigned token "'||v_tokenserial||'" to login "'||p_login||'" ('||p_login_id||')');
            END IF;


        EXCEPTION
            WHEN OSAG_AUTH_STATE.duplicate_login OR OSAG_AUTH_STATE.duplicate_email THEN

                
                
                IF (p_merge != 0) THEN
                    plog.notice('encountered non-unique login '''||p_login||''' when ''merge'' flag set');


                    
                    
                    
                    BEGIN
                        SELECT l.* INTO STRICT v_login FROM passport_login l, stop.passport_contact sc
                        WHERE (LOWER(l.login) = LOWER(p_login))
                          AND l.homeauthhost_id = p_homeauthhost_id
                          AND l.contact_id = sc.id 
                        EXCEPT
                        SELECT l.* FROM passport_login l, stop.passport_contact_sync scs
                        WHERE LOWER(l.login) = LOWER(p_login)
                          AND l.homeauthhost_id = p_homeauthhost_id
                          AND l.contact_id = scs.contact_id;


                        
                        
                        
                        
                        SELECT * INTO STRICT v_contact FROM stop.passport_contact
                        WHERE v_login.contact_id = id;

                        p_contact_id := v_contact.id;
                        p_login_id := v_login.id;
                        v_authemail := v_login.email;

                        plog.notice('found eligible login ID '''||p_login_id||''', contact ID '''||p_contact_id||''' to merge with');


                        CALL osag_auth_passport.update_login(v_login.id, p_login, p_passwordtype_id, NULL, v_login.twofactorenabled, v_login.token_id, v_login.replacementtoken_id,
                                     v_login.homeauthhost_id, v_login.locked, v_login.maxretries, p_firstname, p_lastname, p_direct, p_mobile, p_home, p_fax, coalesce(p_email,
                                                                                                                                                                  v_contact.email), v_authemail, v_contact.company_id, v_login.anytunnelgroup, v_login.passwordexpiry, p_cost_center_id, p_function, p_comments, p_smsauthnumber);

                    EXCEPTION
                        WHEN no_data_found THEN
                            RAISE EXCEPTION '%', 'duplicate login "'||p_login||'" doesn''t qualify for merging (assigned to different authhost or sync domain)' USING ERRCODE = OSAG_AUTH_STATE.S_ERRNO_DUPLICATE_LOGIN;
                        WHEN OTHERS THEN
                            RAISE;
                    END;

                ELSE
                    RAISE;
                END IF;
            WHEN OTHERS THEN
                RAISE;
        END;

        SELECT contact_id INTO STRICT p_contact_id FROM passport_login
        WHERE id = p_login_id;

        INSERT INTO stop.passport_contact_sync(contact_id, syncdomain_id, synctype_id, sid, guid, domain, usnchanged, distinguishedname)
        VALUES (p_contact_id, p_syncdomain_id, (SELECT id FROM auth.synctype WHERE short = p_synctype),
                p_sid, p_guid, p_domain, p_usnchanged, p_distinguishedname);

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth_passport.insert_login_sync2 (p_contact_id OUT stop.passport_contact.id%TYPE, p_login_id OUT passport_login.id%TYPE, p_login passport_login.login%TYPE, p_homeauthhost_id authhost.id%TYPE, p_maxretries passport_login.maxretries%TYPE, p_passwordtype_id passport_login.passwordtype_id%TYPE, p_password text, p_passwordexpiryoffset authsys.passwordexpiryoffset%TYPE, p_twofactorenabled passport_login.twofactorenabled%TYPE, p_locked passport_login.locked%TYPE, p_firstname stop.passport_contact.firstname%TYPE, p_lastname stop.passport_contact.lastname%TYPE, p_direct stop.passport_contact.direct%TYPE, p_mobile stop.passport_contact.mobile%TYPE, p_home stop.passport_contact.home%TYPE, p_fax stop.passport_contact.fax%TYPE, p_email stop.passport_contact.email%TYPE, p_authemail auth.passport_login.email%TYPE, p_syncdomain_id auth.syncdomain.id%TYPE, p_synctype auth.synctype.short%TYPE, p_sid stop.passport_contact_sync.sid%TYPE, p_guid stop.passport_contact_sync.guid%TYPE, p_domain stop.passport_contact_sync.domain%TYPE, p_usnchanged stop.passport_contact_sync.usnchanged%TYPE, p_cost_center_id mss.cost_center.id%TYPE DEFAULT NULL, p_function stop.passport_contact.function%TYPE DEFAULT NULL, p_merge bigint DEFAULT 0, p_comments stop.passport_contact.comments%TYPE DEFAULT NULL, p_authtype_id auth.authtype.id%TYPE DEFAULT NULL, p_smsauthnumber passport_login.smsauthnumber%TYPE DEFAULT NULL, p_softtokenseed token.seed%TYPE DEFAULT NULL, p_softtokenexpiry text DEFAULT NULL, p_softtoken_validfrom text DEFAULT NULL, p_distinguishedname stop.passport_contact_sync.distinguishedname%TYPE DEFAULT NULL) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_auth_passport.is_dirty (p_authsys_id authsys.id%TYPE) RETURNS bigint AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.is_dirty(): ';

        c_dirtyauthhost CURSOR FOR
            SELECT (login + token + groups + login2groups + tunnelgroup + login2tunnelgroup + alias) dirty
            FROM dirtyauthhost
            WHERE authhost_id IN (SELECT authhost_id
                                  FROM authhost2authsys
                                  WHERE authsys_id = p_authsys_id);


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        FOR r_dirtyauthhost IN c_dirtyauthhost LOOP
                IF (r_dirtyauthhost.dirty != 0) THEN
                    RETURN(1);
                END IF;
            END LOOP;

        RETURN(0);

    EXCEPTION

        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION osag_auth_passport.is_dirty (p_authsys_id authsys.id%TYPE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_auth_passport.lock_login (p_login_id passport_login.id%TYPE) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.lock_login(): ';


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        UPDATE passport_login
        SET locked = 1
        WHERE id = p_login_id;

        IF (NOT FOUND) THEN
            plog.err(S_PREFIX||'failed to lock login id "'||p_login_id||'"');
            RAISE no_data_found;
        ELSE
            plog.notice(S_PREFIX||'locked login id "'||p_login_id);
        END IF;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth_passport.lock_login (p_login_id passport_login.id%TYPE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_auth_passport.set_authsys_dirty (p_authsys_id authsys.id%TYPE) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.set_authsys_dirty(): ';

        v_authhost_id authhost2authsys.authhost_id%TYPE;

        c_authhost2authsys CURSOR FOR
            SELECT authhost_id
            FROM authhost2authsys
            WHERE authsys_id = p_authsys_id;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        FOR r_authhost2authsys IN c_authhost2authsys LOOP
                UPDATE dirtyauthhost
                SET login = 1, token = 1, groups = 1, login2groups = 1, tunnelgroup = 1, login2tunnelgroup = 1, alias = 1
                WHERE authhost_id = r_authhost2authsys.authhost_id;

                IF (FOUND) THEN
                    plog.debug(S_PREFIX||'set authhost id "'||r_authhost2authsys.authhost_id||'" ('||p_authsys_id||') to dirty');
                ELSE
                    INSERT INTO dirtyauthhost(authhost_id, login, token, groups, login2groups, tunnelgroup, login2tunnelgroup, alias)
                    VALUES (r_authhost2authsys.authhost_id, 1, 1, 1, 1, 1, 1, 1);
                END IF;
            END LOOP;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth_passport.set_authsys_dirty (p_authsys_id authsys.id%TYPE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_auth_passport.set_password (p_login_id passport_login.id%TYPE, p_password text, p_update_password_expiry boolean DEFAULT FALSE, p_update_recent_password boolean DEFAULT TRUE, p_password_expiry_offset authsys.passwordexpiryoffset%TYPE DEFAULT NULL, p_check_password boolean DEFAULT FALSE) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.set_password(): ';

        v_passwordexpiry timestamp(0);
        v_passwordexpiryoffset AUTHSYS.PASSWORDEXPIRYOFFSET%TYPE;
        v_passwordexpiryenabled AUTHSYS.PASSWORDEXPIRYENABLED%TYPE;
        v_password_hash PASSPORT_LOGIN.PWHASH%TYPE;
        v_salt passport_login.SALT%TYPE;

        v_version PASSPORT_RECENTPASSWORD.VERSION%TYPE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        v_salt := lower(rawtohex(DBMS_CRYPTO.RANDOMBYTES(32)));
        v_password_hash := osag_auth_passport.hash_password(p_password, v_salt);

        UPDATE passport_login
        SET salt = v_salt,
            pwhash = v_password_hash,
            lastpwchange = clock_timestamp()
        WHERE id = p_login_id;

        IF (p_update_password_expiry) THEN
            IF (p_password_expiry_offset IS NOT NULL) THEN
                v_passwordexpiry := clock_timestamp() + p_password_expiry_offset / (24 * 60 * 60);
            ELSE

                
                SELECT l.passwordexpiry, authsys.passwordexpiryoffset, authsys.passwordexpiryenabled INTO STRICT v_passwordexpiry, v_passwordexpiryoffset, v_passwordexpiryenabled
                FROM auth.passport_login l, auth.authhost2authsys h2a, auth.authsys
                WHERE l.id = p_login_id
                  AND l.homeauthhost_id = h2a.authhost_id
                  AND h2a.authsys_id = authsys.id;


                
                IF (v_passwordexpiryenabled = 0) THEN
                    v_passwordexpiry := NULL;


                    
                    
                ELSIF (v_passwordexpiry IS NOT NULL AND v_passwordexpiryoffset IS NOT NULL
                    AND v_passwordexpiryoffset > 0) THEN
                    
                    v_passwordexpiry := clock_timestamp() + v_passwordexpiryoffset / (24 * 60 * 60);
                END IF;
            END IF;

            UPDATE passport_login
            SET passwordexpiry = v_passwordexpiry
            WHERE id = p_login_id;
            plog.notice(S_PREFIX||'updated password expiry for login id "'||p_login_id||'" to ' || v_passwordexpiry);
        END IF;

        IF (p_update_recent_password) THEN

            
            SELECT coalesce(MAX(version), 0) + 1 INTO STRICT v_version
            FROM passport_recentpassword
            WHERE login_id = p_login_id;

            INSERT INTO passport_recentpassword(id, login_id, password, version, salt)
            VALUES (nextval('seq_recentpassword_id'), p_login_id, v_password_hash, v_version, v_salt);


            DELETE FROM passport_recentpassword
            WHERE login_id = p_login_id
              AND version < (v_version-4);
        END IF;

        plog.notice(S_PREFIX||'updated password for login id "'||p_login_id||'"');

    EXCEPTION
        WHEN OTHERS THEN
            IF (SQLSTATE = -00001) THEN
                plog.err(S_PREFIX||'login id "'||p_login_id||'" is not unique:: '||sqlerrm);
                RAISE EXCEPTION '%', 'login id "'||p_login_id||'" is not unique' USING ERRCODE = OSAG_AUTH_STATE.S_ERRNO_DUPLICATE_LOGIN;
            ELSE
                plog.err(S_PREFIX||'caught exception: '||sqlerrm);
                RAISE;
            END IF;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth_passport.set_password (p_login_id passport_login.id%TYPE, p_password text, p_update_password_expiry boolean DEFAULT FALSE, p_update_recent_password boolean DEFAULT TRUE, p_password_expiry_offset authsys.passwordexpiryoffset%TYPE DEFAULT NULL, p_check_password boolean DEFAULT FALSE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_auth_passport.update_authsys (p_authsys_id authsys.id%TYPE) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.update_authsys(): ';

        S_COMMAND CONSTANT varchar(128) := OSAG_AUTH_STATE.C_OSAG_AUTHSYNC_HOME||'/bin/update_authsys --config '||
                                            OSAG_AUTH_STATE.C_OSAG_AUTHSYNC_HOME||'/etc/update_authsys.conf '||p_authsys_id;

        S_PROXY_COMMAND CONSTANT varchar(256) := OSAG_AUTH_STATE.GET_JUMP_SSH_CALL||OSAG_AUTH_STATE.C_OSAG_AUTHSYNC_HOME||'/bin/update_authsys --config '||
                                                  OSAG_AUTH_STATE.C_OSAG_AUTHSYNC_HOME||'/etc/update_authsys.conf '||p_authsys_id||'"';

        v_exit bigint;
        v_output varchar(2048);
        v_name authsys.name%TYPE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        select name into STRICT v_name from authsys where id = p_authsys_id;

        CALL OSAG_EXT.runOsCmdGetResult(S_PROXY_COMMAND, 512, v_output, v_exit);


        v_output := ltrim(rtrim(v_output, ' '||chr(10)||chr(13)), ' '||chr(10)||chr(13));

        IF (v_exit != 0) THEN
          if v_output is null or length(v_output) = 0 then

            if v_exit = 1 then
              v_output := 'exit code 1: No update of authentication system '||v_name||': No active hosts';
            elsif v_exit = -1 then
              v_output := 'exit code -1: Update of authentication system '||v_name||' failed: internal error.';
            elsif v_exit = -2 then
              v_output := 'exit code -2: Update of authentication system '||v_name||' failed: initialization error.';
            elsif v_exit = -3 then
              v_output := 'exit code -3: Update of authentication system '||v_name||' failed: database error.';
            elsif v_exit = -4 then
              v_output := 'exit code -4: Update of authentication system '||v_name||' failed: data dump error.';
            elsif v_exit = -5 then
              v_output := 'exit code -5: Update of authentication system  '||v_name||' failed: synchronization error.';
            elsif v_exit = -6 then
              v_output := 'exit code -6: Update of authentication system  '||v_name||' failed for some passport servers.';
            elsif v_exit = 254 then
              v_output := 'exit code 254: Update of authentication system  '||v_name||' failed: signal received (likely timeout or kill).';
            elsif v_exit = 255 then
              v_output := 'exit code 255: Update of authentication system  '||v_name||' failed: config error.';
            else
              v_output := 'unknown exit code '||v_exit||' from update_authsys for authentication system '|| v_name ||', check /var/log/messages on auth host';
            end if;
          end if;
        END IF;


        IF (v_exit = 250) THEN
            plog.notice(S_PREFIX||'update failed partly for authsys id "'||p_authsys_id||'"');
            RAISE EXCEPTION '%', v_output USING ERRCODE = OSAG_AUTH_STATE.S_ERRNO_AUTHSYS_UPDATE_PARTIAL;
        ELSIF (v_exit = 1) THEN
            RAISE EXCEPTION '%', v_output USING ERRCODE = OSAG_AUTH_STATE.S_ERRNO_AUTHSYS_UPDATE_WARNING;
        ELSIF (v_exit != 0) THEN
            RAISE EXCEPTION '%', v_output USING ERRCODE = OSAG_AUTH_STATE.S_ERRNO_AUTHSYS_UPDATE_FAILED;
        END IF;

        plog.notice(S_PREFIX||'updated authsys id "'||p_authsys_id||'"');

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
