CREATE OR REPLACE PROCEDURE osag_auth_passport.sync_domain (p_syncdomain_id syncdomain.id%TYPE, p_scheduled boolean DEFAULT FALSE, p_force boolean DEFAULT FALSE) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.sync_domain(): ';

        S_COMMAND CONSTANT varchar(128) := OSAG_AUTH_STATE.C_OSAG_AUTHSYNC_HOME||'/bin/authsync --config '||
                                            OSAG_AUTH_STATE.C_OSAG_AUTHSYNC_HOME||'/etc/authsync.conf -D';

        v_exit bigint;
        v_output varchar(512);
        v_command varchar(128) := S_COMMAND;
        v_proxy_command varchar(512);
        v_short SYNCDOMAIN.SHORT%TYPE;


        
    
BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        select short into STRICT v_short from AUTH.SYNCDOMAIN d where d.id = p_syncdomain_id;

        IF (p_scheduled) THEN
            v_command := v_command||' -S';
        END IF;

        IF (p_force) THEN
            v_command := v_command|| ' -f';
        END IF;

        v_command := v_command||' '||p_syncdomain_id ||'"';
        v_proxy_command := OSAG_AUTH_STATE.GET_JUMP_SSH_CALL|| v_command;


        
        CALL OSAG_EXT.runOsCmdGetResult(v_proxy_command, 512, v_output, v_exit);


        v_output := ltrim(rtrim(v_output, ' '||chr(10)||chr(13)), ' '||chr(10)||chr(13));

        IF (v_exit != 0) THEN
            if v_output is null or length(v_output) = 0 then

              if v_exit = 1 then
                v_output := 'exit code 1: syncdump config error, check /var/log/messages on auth host';
              elsif v_exit = 2 then
                v_output := 'exit code 2: syncdump LDAP problem, check /var/log/messages on auth host';
              elsif v_exit = 3 then
                v_output := 'exit code 3: syncdump can not resolve DC/GC, check /var/log/messages on auth host';
              elsif v_exit = 4 then
                v_output := 'exit code 4: syncdump could not contact any DC/GC, check /var/log/messages on auth host';
              elsif v_exit = 5 then
                v_output := 'exit code 5: syncdump timeout, check /var/log/messages on auth host';
              elsif v_exit = 255 then
                v_output := 'exit code 255: authsync communication error, auth host reachable?';
              else
                v_output := 'unknown exit code '||v_exit||', check /var/log/messages on auth host';
              end if;
            end if;

            if v_output like 'Could not get an exclusive lock for authsys%' then
              RAISE EXCEPTION '%', v_output USING ERRCODE = OSAG_AUTH_STATE.S_ERRNO_AUTHSYS_UPDATE_WARNING;
            end if;

            RAISE EXCEPTION '%', v_output USING ERRCODE = OSAG_AUTH_STATE.S_ERRNO_DOMAIN_SYNC_FAILED;
        END IF;

        plog.notice(S_PREFIX||'synchronized domain id "'||p_syncdomain_id||'"');

    EXCEPTION
        WHEN OSAG_AUTH_STATE.authsys_update_warning THEN

            plog.notice(S_PREFIX||'caught exception in authsys '|| v_short ||': '||sqlerrm);
            null;
        WHEN SQLSTATE '50001' THEN
            RAISE;
        WHEN OTHERS THEN

            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth_passport.sync_domain (p_syncdomain_id syncdomain.id%TYPE, p_scheduled boolean DEFAULT FALSE, p_force boolean DEFAULT FALSE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_auth_passport.sync_domain_scheduler () AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.sync_domain_scheduler(): ';
        v_backoff_wait bigint := 0;
        v_runattempt bigint := 0;
        v_last_return_code bigint := 0;
        v_last_err_msg varchar(4000) := '';

    
        

        c_syncdomain CURSOR FOR
            SELECT * FROM syncdomain WHERE syncperiod IS NOT NULL AND SYNCPERIOD > 0;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        FOR r_syncdomain IN c_syncdomain LOOP
                IF ((r_syncdomain.nextrun IS NULL) OR (r_syncdomain.nextrun <= statement_timestamp())) THEN
                    IF (r_syncdomain.nextrun IS NULL) THEN
                        plog.notice('started initial synchronization for domain '||r_syncdomain.id);
                    ELSE
                        plog.notice('started synchronization for domain '||r_syncdomain.id||' scheduled at '||
                                    TO_CHAR(r_syncdomain.nextrun, 'YYYY-MM-DD HH24:MI:SS TZH:TZM'));
                    END IF;

                    BEGIN
                        v_last_err_msg := '';
                        v_last_return_code := 0;
                        v_backoff_wait := 0;
                        v_runattempt := 0;
                        CALL OSAG_AUTH_PASSPORT.sync_domain(r_syncdomain.id, true);
                        CALL OSAG_AUTH_PASSPORT.update_authsys(r_syncdomain.authsys_id);
                    EXCEPTION
                        WHEN OSAG_AUTH_STATE.domain_sync_failed THEN

                            v_runattempt := r_syncdomain.RUN_ATTEMPT + 1;

                        WHEN SQLSTATE '50001' THEN BEGIN

                            v_last_err_msg := SQLERRM;
                            v_last_return_code := SQLSTATE;
                            v_runattempt := r_syncdomain.RUN_ATTEMPT + 1;
                            IF (COALESCE(r_syncdomain.RUN_ATTEMPT,0) = COALESCE(r_syncdomain.MAX_ATTEMPT,0))

                                THEN
                                plog.err(S_PREFIX||'No further retry of ' || r_syncdomain.DESCRIPTION || ' permitted after caught exception: '||sqlerrm);
                            ELSIF (COALESCE(r_syncdomain.RUN_ATTEMPT,0) = 0)

                                THEN
                                IF (r_syncdomain.SYNCPERIOD >3600)
                                    
                                    THEN
                                    v_backoff_wait := 3600;
                                ELSE
                                    
                                    v_backoff_wait := GREATEST(r_syncdomain.TIMEOUT, 360);
                                end if;
                            ELSE

                                v_backoff_wait := LEAST(GREATEST(r_syncdomain.RUN_ATTEMPT * r_syncdomain.TIMEOUT, 360), 3600);
                            end if;
                        end;
                        WHEN OTHERS THEN
                            v_last_err_msg := SQLERRM;
                            v_last_return_code := SQLSTATE;
                            v_runattempt := r_syncdomain.RUN_ATTEMPT + 1;
                            plog.err(S_PREFIX||'caught exception while running ' || r_syncdomain.DESCRIPTION || ': '||sqlerrm);
                    END;


                    
                    
                    
                    
                    WHILE(coalesce(r_syncdomain.nextrun, statement_timestamp()) <= statement_timestamp()) LOOP
                        
                        
                        
                        
                        
                        
                        if v_backoff_wait > 0 then
                          r_syncdomain.nextrun := statement_timestamp() +  (v_backoff_wait * ('1'||'SECOND')::interval);
                        else
                          r_syncdomain.nextrun := coalesce(r_syncdomain.nextrun, statement_timestamp())
                            + (r_syncdomain.syncperiod * ('1'||'SECOND')::interval);
                        end if;
                    END LOOP;

                    UPDATE AUTH.syncdomain
                    SET nextrun = r_syncdomain.nextrun,
                        LAST_RESULTCODE = v_last_return_code,
                        LAST_RESULTMSG  = v_last_err_msg,
                        RUN_ATTEMPT     = v_runattempt
                    WHERE id = r_syncdomain.id;

                    plog.notice('next synchronization for domain '||r_syncdomain.id||' scheduled at '||
                                TO_CHAR(r_syncdomain.nextrun, 'YYYY-MM-DD HH24:MI:SS TZH:TZM'));
                END IF;

                COMMIT;
            END LOOP;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE osag_auth_passport.sync_domain_scheduler () FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_auth_passport.unlock_login (p_login_id passport_login.id%TYPE) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.unlock_login(): ';


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        UPDATE passport_login
        SET locked = 0
        WHERE id = p_login_id;

        IF (NOT FOUND) THEN
            plog.err(S_PREFIX||'failed to unlock login id "'||p_login_id||'"');
            RAISE no_data_found;
        ELSE
            plog.notice(S_PREFIX||'unlocked login id "'||p_login_id);
        END IF;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth_passport.unlock_login (p_login_id passport_login.id%TYPE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_auth_passport.update_login (p_login_id passport_login.id%TYPE, p_login passport_login.login%TYPE, p_passwordtype_id passwordtype.id%TYPE, p_password text, p_twofactorenabled passport_login.twofactorenabled%TYPE, p_token_id token.id%TYPE, p_replacementtoken_id token.id%TYPE, p_homeauthhost_id authhost.id%TYPE, p_locked passport_login.locked%TYPE, p_maxretries passport_login.maxretries%TYPE, p_firstname stop.passport_contact.firstname%TYPE, p_lastname stop.passport_contact.lastname%TYPE, p_direct stop.passport_contact.direct%TYPE, p_mobile stop.passport_contact.mobile%TYPE, p_home stop.passport_contact.home%TYPE, p_fax stop.passport_contact.fax%TYPE, p_email stop.passport_contact.email%TYPE, p_authemail auth.passport_login.email%TYPE, p_company_id stop.company.id%TYPE DEFAULT NULL, p_anytunnelgroup passport_login.anytunnelgroup%TYPE DEFAULT 0, p_passwordexpiry passport_login.passwordexpiry%TYPE DEFAULT NULL, p_cost_center_id mss.cost_center.id%TYPE DEFAULT NULL, p_function stop.passport_contact.function%TYPE DEFAULT NULL, p_comments stop.passport_contact.comments%TYPE DEFAULT NULL, p_smsauthnumber passport_login.smsauthnumber%TYPE DEFAULT NULL) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.update_login(): ';

        v_contact_id stop.passport_contact.id%TYPE;
        v_homeauthhost_id passport_login.homeauthhost_id%TYPE;
        v_login passport_login.login%TYPE;
        v_email stop.passport_contact.email%TYPE;
        v_cost_center_company stop.company.id%TYPE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        IF (p_login_id IS NULL) THEN
            RAISE data_exception;
        END IF;


        SELECT login, contact_id, homeauthhost_id, sc.email
        INTO STRICT v_login, v_contact_id, v_homeauthhost_id, v_email
        FROM passport_login l, stop.passport_contact sc
        WHERE l.id = p_login_id
          AND l.contact_id = sc.id;

        BEGIN

            
            IF (p_homeauthhost_id IS NOT NULL) THEN
                SELECT authhost_id INTO STRICT v_homeauthhost_id
                FROM authhost2authsys
                WHERE authhost_id = p_homeauthhost_id
                  AND authsys_id = (SELECT authsys_id FROM authhost2authsys WHERE authhost_id = v_homeauthhost_id);
            END IF;

        EXCEPTION
            WHEN no_data_found THEN
                RAISE EXCEPTION '%', 'authhost id "'||p_homeauthhost_id||
                                                                                   '" not same authentication system' USING ERRCODE = OSAG_AUTH_STATE.S_ERRNO_HOMEAH_CONSTRAINT;
        END;


        IF ((p_login IS NOT NULL) AND (lower(p_login) != lower(v_login))) THEN
            IF (NOT osag_auth_passport.check_login_unique(p_login, v_homeauthhost_id)) THEN
                RAISE EXCEPTION '%', 'login "'||p_login||'" is not unique' USING ERRCODE = OSAG_AUTH_STATE.S_ERRNO_DUPLICATE_LOGIN;
            END IF;
        END IF;


        
        
        

        
        
        
        IF ((p_twofactorenabled = 0) AND (p_locked = 0) AND (NOT osag_auth_passport.is_password_only_allowed(p_homeauthhost_id))) THEN
            RAISE EXCEPTION '%', 'Password-only authentication is not allowed for unlocked users.' USING ERRCODE = OSAG_AUTH_STATE.S_ERRNO_NO_PASSWORD_ONLY;
        END IF;


        BEGIN

            
            UPDATE passport_login
            SET login = coalesce(p_login, login), passwordtype_id = coalesce(p_passwordtype_id, passwordtype_id),
                twofactorenabled = coalesce(p_twofactorenabled, twofactorenabled),
                token_id = p_token_id, replacementtoken_id = p_replacementtoken_id,
                homeauthhost_id = coalesce(p_homeauthhost_id, homeauthhost_id), locked = coalesce(p_locked, locked),
                maxretries = coalesce(p_maxretries, maxretries), anytunnelgroup = p_anytunnelgroup,
                passwordexpiry = p_passwordexpiry, cost_center_id = p_cost_center_id, email = p_authemail, smsauthnumber = p_smsauthnumber
            WHERE id = p_login_id;

        EXCEPTION
            WHEN OTHERS THEN
                IF (SQLSTATE = -00001) THEN
                    RAISE EXCEPTION '%', 'login "'||p_login||'" is not unique' USING ERRCODE = OSAG_AUTH_STATE.S_ERRNO_DUPLICATE_LOGIN;
                ELSE
                    RAISE;
                END IF;
        END;


        IF (p_password IS NOT NULL) THEN
            CALL osag_auth_passport.set_password(p_login_id, p_password, FALSE, TRUE);
        END IF;

        plog.notice(S_PREFIX||'updated login id "'||p_login_id||'"');



        UPDATE stop.passport_contact
        SET firstname = substr(p_firstname, 1, 50),
            lastname = substr(p_lastname, 1, 50),
            comments = substr(p_comments, 1, 200),
            direct = substr(p_direct, 1, 30),
            mobile = substr(p_mobile, 1, 30),
            home = substr(p_home, 1, 30),
            fax = substr(p_fax, 1, 30),
            email = substr(p_email, 1, 250),
            company_id = coalesce(p_company_id, company_id),
            function = substr(p_function, 1, 100),
            modified = statement_timestamp()
        WHERE id = v_contact_id;

        plog.notice(S_PREFIX||'updated contact id "'||v_contact_id||'"');

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth_passport.update_login (p_login_id passport_login.id%TYPE, p_login passport_login.login%TYPE, p_passwordtype_id passwordtype.id%TYPE, p_password text, p_twofactorenabled passport_login.twofactorenabled%TYPE, p_token_id token.id%TYPE, p_replacementtoken_id token.id%TYPE, p_homeauthhost_id authhost.id%TYPE, p_locked passport_login.locked%TYPE, p_maxretries passport_login.maxretries%TYPE, p_firstname stop.passport_contact.firstname%TYPE, p_lastname stop.passport_contact.lastname%TYPE, p_direct stop.passport_contact.direct%TYPE, p_mobile stop.passport_contact.mobile%TYPE, p_home stop.passport_contact.home%TYPE, p_fax stop.passport_contact.fax%TYPE, p_email stop.passport_contact.email%TYPE, p_authemail auth.passport_login.email%TYPE, p_company_id stop.company.id%TYPE DEFAULT NULL, p_anytunnelgroup passport_login.anytunnelgroup%TYPE DEFAULT 0, p_passwordexpiry passport_login.passwordexpiry%TYPE DEFAULT NULL, p_cost_center_id mss.cost_center.id%TYPE DEFAULT NULL, p_function stop.passport_contact.function%TYPE DEFAULT NULL, p_comments stop.passport_contact.comments%TYPE DEFAULT NULL, p_smsauthnumber passport_login.smsauthnumber%TYPE DEFAULT NULL) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_auth_passport.update_login_sync (p_contact_id OUT stop.passport_contact.id%TYPE, p_login_id passport_login.id%TYPE, p_login passport_login.login%TYPE, p_password text, p_locked passport_login.locked%TYPE, p_firstname stop.passport_contact.firstname%TYPE, p_lastname stop.passport_contact.lastname%TYPE, p_direct stop.passport_contact.direct%TYPE, p_mobile stop.passport_contact.mobile%TYPE, p_home stop.passport_contact.home%TYPE, p_fax stop.passport_contact.fax%TYPE, p_email stop.passport_contact.email%TYPE, p_authemail auth.passport_login.email%TYPE, p_syncdomain_id auth.syncdomain.id%TYPE, p_domain stop.passport_contact_sync.domain%TYPE, p_usnchanged stop.passport_contact_sync.usnchanged%TYPE, p_cost_center_id mss.cost_center.id%TYPE DEFAULT NULL, p_function stop.passport_contact.function%TYPE DEFAULT NULL, p_comments stop.passport_contact.comments%TYPE DEFAULT NULL, p_smsauthnumber passport_login.smsauthnumber%TYPE DEFAULT NULL) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.update_login_sync(): ';

        v_login passport_login%ROWTYPE;
        v_contact stop.passport_contact%ROWTYPE;
        v_autoemailaliasesenabled authsys.autoemailaliasesenabled%TYPE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        SELECT authsys.autoemailaliasesenabled INTO STRICT v_autoemailaliasesenabled FROM authsys, syncdomain
        WHERE authsys.id = syncdomain.authsys_id
          AND syncdomain.id = p_syncdomain_id;


        
        
        
        BEGIN
            SELECT l.* INTO STRICT v_login FROM passport_login l
            WHERE l.id = p_login_id;

        EXCEPTION
            WHEN no_data_found THEN
                RAISE EXCEPTION '%', 'no record found for login ID "'||p_login_id||'"' USING ERRCODE = OSAG_AUTH_STATE.S_ERRNO_NO_LOGIN_RECORD;
            WHEN OTHERS THEN
                RAISE;
        END;

        SELECT * INTO STRICT v_contact FROM stop.passport_contact
        WHERE id = v_login.contact_id;

        p_contact_id := v_contact.id;

        CALL osag_auth_passport.update_login(v_login.id, p_login, v_login.passwordtype_id, NULL, v_login.twofactorenabled, v_login.token_id, v_login.replacementtoken_id,
                     v_login.homeauthhost_id, p_locked, v_login.maxretries, p_firstname, p_lastname, p_direct, p_mobile, p_home, p_fax, p_email, p_authemail,
                     v_contact.company_id, v_login.anytunnelgroup, v_login.passwordexpiry, p_cost_center_id, p_function, p_comments, p_smsauthnumber);

        UPDATE stop.passport_contact_sync
        SET domain = p_domain, usnchanged = p_usnchanged
        WHERE contact_id = v_contact.id;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth_passport.update_login_sync (p_contact_id OUT stop.passport_contact.id%TYPE, p_login_id passport_login.id%TYPE, p_login passport_login.login%TYPE, p_password text, p_locked passport_login.locked%TYPE, p_firstname stop.passport_contact.firstname%TYPE, p_lastname stop.passport_contact.lastname%TYPE, p_direct stop.passport_contact.direct%TYPE, p_mobile stop.passport_contact.mobile%TYPE, p_home stop.passport_contact.home%TYPE, p_fax stop.passport_contact.fax%TYPE, p_email stop.passport_contact.email%TYPE, p_authemail auth.passport_login.email%TYPE, p_syncdomain_id auth.syncdomain.id%TYPE, p_domain stop.passport_contact_sync.domain%TYPE, p_usnchanged stop.passport_contact_sync.usnchanged%TYPE, p_cost_center_id mss.cost_center.id%TYPE DEFAULT NULL, p_function stop.passport_contact.function%TYPE DEFAULT NULL, p_comments stop.passport_contact.comments%TYPE DEFAULT NULL, p_smsauthnumber passport_login.smsauthnumber%TYPE DEFAULT NULL) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_auth_passport.update_login_sync2 (p_contact_id OUT stop.passport_contact.id%TYPE, p_login_id passport_login.id%TYPE, p_login passport_login.login%TYPE, p_password text, p_locked passport_login.locked%TYPE, p_firstname stop.passport_contact.firstname%TYPE, p_lastname stop.passport_contact.lastname%TYPE, p_direct stop.passport_contact.direct%TYPE, p_mobile stop.passport_contact.mobile%TYPE, p_home stop.passport_contact.home%TYPE, p_fax stop.passport_contact.fax%TYPE, p_email stop.passport_contact.email%TYPE, p_authemail auth.passport_login.email%TYPE, p_syncdomain_id auth.syncdomain.id%TYPE, p_domain stop.passport_contact_sync.domain%TYPE, p_usnchanged stop.passport_contact_sync.usnchanged%TYPE, p_cost_center_id mss.cost_center.id%TYPE DEFAULT NULL, p_function stop.passport_contact.function%TYPE DEFAULT NULL, p_comments stop.passport_contact.comments%TYPE DEFAULT NULL, p_smsauthnumber passport_login.smsauthnumber%TYPE DEFAULT NULL, p_distinguishedname stop.passport_contact_sync.distinguishedname%TYPE DEFAULT NULL) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.update_login_sync2(): ';

        v_login passport_login%ROWTYPE;
        v_contact stop.passport_contact%ROWTYPE;
        v_autoemailaliasesenabled authsys.autoemailaliasesenabled%TYPE;
        v_function stop.passport_contact.function%TYPE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        SELECT authsys.autoemailaliasesenabled INTO STRICT v_autoemailaliasesenabled FROM authsys, syncdomain
        WHERE authsys.id = syncdomain.authsys_id
          AND syncdomain.id = p_syncdomain_id;


        
        
        
        BEGIN
            SELECT l.* INTO STRICT v_login FROM passport_login l
            WHERE l.id = p_login_id;

        EXCEPTION
            WHEN no_data_found THEN
                RAISE EXCEPTION '%', 'no record found for login ID "'||p_login_id||'"' USING ERRCODE = OSAG_AUTH_STATE.S_ERRNO_NO_LOGIN_RECORD;
            WHEN OTHERS THEN
                RAISE;
        END;

        SELECT * INTO STRICT v_contact FROM stop.passport_contact
        WHERE id = v_login.contact_id;

        p_contact_id := v_contact.id;
        v_function := SUBSTR(CONVERT(p_function, 'US7ASCII'), 1, 100);

        CALL osag_auth_passport.update_login(v_login.id, p_login, v_login.passwordtype_id, NULL, v_login.twofactorenabled, v_login.token_id, v_login.replacementtoken_id,
                     v_login.homeauthhost_id, p_locked, v_login.maxretries, p_firstname, p_lastname, p_direct, p_mobile, p_home, p_fax, p_email,
                     p_authemail, v_contact.company_id, v_login.anytunnelgroup, v_login.passwordexpiry, p_cost_center_id, v_function, p_comments, p_smsauthnumber);

        UPDATE stop.passport_contact_sync
        SET domain = p_domain, usnchanged = p_usnchanged, distinguishedname = p_distinguishedname
        WHERE contact_id = v_contact.id;
    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
