CREATE OR REPLACE PROCEDURE osag_auth_passport.update_login_details (p_login_id passport_login.id%TYPE, p_lastaccept passport_login.lastaccept%TYPE, p_lastreject passport_login.lastreject%TYPE, p_locked passport_login.locked%TYPE) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.update_login_details(): ';


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        UPDATE passport_login
        SET lastaccept = coalesce(p_lastaccept, lastaccept),
            lastreject = coalesce(p_lastreject, lastreject)
        WHERE id = p_login_id;


        
        IF (p_locked IS NOT NULL) THEN
            IF (p_locked = 0) THEN
                CALL OSAG_AUTH_PASSPORT.unlock_login(p_login_id);
            ELSE
                CALL OSAG_AUTH_PASSPORT.lock_login(p_login_id);
            END IF;
        END IF;

        IF (NOT FOUND) THEN
            plog.err(S_PREFIX||'failed to update details of login ID "'||p_login_id||'"');
            RAISE no_data_found;
        ELSE
            plog.notice(S_PREFIX||'updated details of login id "'||p_login_id||'" to "'||p_lastaccept||':'||
                        p_lastreject||':'||p_locked||'"');
        END IF;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth_passport.update_login_details (p_login_id passport_login.id%TYPE, p_lastaccept passport_login.lastaccept%TYPE, p_lastreject passport_login.lastreject%TYPE, p_locked passport_login.locked%TYPE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_auth_passport.update_login_details2 (p_login_id passport_login.id%TYPE, p_lastaccept passport_login.lastaccept%TYPE, p_lastreject passport_login.lastreject%TYPE, p_locked passport_login.locked%TYPE, p_token_id token.id%TYPE DEFAULT NULL, p_replacementtoken_id token.id%TYPE DEFAULT NULL) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.update_login_details2(): ';

        l_token_id            token.id%TYPE;
        l_replacementtoken_id token.id%TYPE;
        l_tokentype_id        token.tokentype_id%TYPE;
        l_locked              passport_login.locked%TYPE;
        l_company_id          passport_login.company_id%TYPE;
        l_login_name          passport_login.login%TYPE;
        l_transaction_id	  bigint;
        l_lock_pfix           varchar(3);
        l_replacement_token_count bigint;
        l_token_count         bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        plog.debug(S_PREFIX||'login ID: '||p_login_id||', locked: '||p_locked||', token ID: '||p_token_id||
                   ', replacement token ID: '||p_replacementtoken_id);

        UPDATE passport_login
        SET lastaccept = coalesce(p_lastaccept, lastaccept),
            lastreject = coalesce(p_lastreject, lastreject)
        WHERE id = p_login_id;

        IF (NOT FOUND) THEN
          plog.err(S_PREFIX||'login ID "'||p_login_id||' does not exist", mod '|| SYS_CONTEXT('USERENV', 'MODULE') ||' of client '|| SYS_CONTEXT('USERENV', 'CLIENT_PROGRAM_NAME') ||' from '|| SYS_CONTEXT('USERENV','IP_ADDRESS'));
          RAISE no_data_found;
        ELSE
          plog.notice(S_PREFIX||'updated details of login id "'||p_login_id||'" to "'||p_lastaccept||':'||
                      p_lastreject||':'||p_locked||':'||p_token_id||':'||p_replacementtoken_id||'"');
        END IF;


        
        
        
        SELECT token_id, replacementtoken_id, locked, company_id, login
        INTO STRICT l_token_id, l_replacementtoken_id, l_locked, l_company_id, l_login_name
        FROM passport_login
        WHERE id = p_login_id;


        IF (l_token_id IS NOT NULL) THEN
            l_transaction_id := NULL;
            l_replacement_token_count := 0;
            l_token_count := 0;


            SELECT COUNT(*) INTO STRICT l_token_count FROM auth.token WHERE id = p_token_id;
            SELECT COUNT(*) INTO STRICT l_replacement_token_count FROM auth.token WHERE id = p_replacementtoken_id;


            

            IF (l_token_count = 0 OR (p_replacementtoken_id IS NOT NULL AND l_replacement_token_count = 0)) THEN

                plog.notice(S_PREFIX||'Could not find token with ID '||p_token_id || ' or replacement token with ID '|| p_replacementtoken_id ||' provided for login ID '||p_login_id|| ', company '||l_company_id||'. Stopping update attempt.');
                RETURN;

            ELSIF ((coalesce(p_token_id, -1) != coalesce(l_token_id, -1)) AND (coalesce(p_replacementtoken_id, -1) != coalesce(l_replacementtoken_id, -1))  AND (l_replacementtoken_id IS NOT NULL) ) THEN

                UPDATE passport_login
                SET token_id = p_token_id, replacementtoken_id = p_replacementtoken_id
                WHERE id = p_login_id;

                SELECT tokentype_id
                INTO STRICT l_tokentype_id
                FROM token
                WHERE id = l_token_id;

                IF (l_tokentype_id = OSAG_AUTH_STATE.C_OSAG_TOKENTYPE_SOFTTOKEN) THEN
                    DELETE FROM auth.passport_temp_access_key WHERE token_id = l_token_id;
                    DELETE FROM auth.token WHERE id = l_token_id;
                ELSE
                    UPDATE token
                    SET enabled = 0
                    WHERE id = l_token_id;
                END IF;

                CALL osag_audit.add_record('guma', 'authsys', 'login_modify', 'info', l_transaction_id,
                                      'replacement token activated for user '||l_login_name, '<details><auth.passport_login ID="'||p_login_id||'" TOKEN_ID="'||p_token_id||'" REPLACEMENTTOKEN_ID="'
                                          ||p_replacementtoken_id||'" /><AUTH.TOKEN ID="'||l_token_id||'" ENABLED="0" /></details>',
                                      l_company_id, NULL, 'AUTH.PASSPORT_LOGIN', p_login_id, NULL);


                
                IF ((p_token_id = l_replacementtoken_id) AND p_replacementtoken_id is NULL) THEN
                    plog.notice(S_PREFIX||'assigned replacement token ID '||p_token_id||' as primary token for login ID '||p_login_id||
                                ', disabled previous primary token ID '||l_token_id);
                END IF;
            END IF;
        ELSE
            plog.debug(S_PREFIX||'user '||p_login_id|| ', company '||l_company_id||' has no token assigned.');
        END IF;


        
        IF (p_locked IS NOT NULL AND p_locked != l_locked) THEN
            IF (p_locked = 0) THEN
                CALL OSAG_AUTH_PASSPORT.unlock_login(p_login_id);
                l_lock_pfix := 'un';
            ELSE
                CALL OSAG_AUTH_PASSPORT.lock_login(p_login_id);
                l_lock_pfix := '';
            END IF;

            CALL osag_audit.add_record('guma', 'authsys', 'login_modify', 'info', l_transaction_id,
                                  l_lock_pfix||'locked user '||l_login_name, '<details><auth.passport_login ID="'||p_login_id||'" LOCKED="'||p_locked||'" /></details>',
                                  l_company_id, NULL, 'AUTH.PASSPORT_LOGIN', p_login_id, NULL);
        END IF;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth_passport.update_login_details2 (p_login_id passport_login.id%TYPE, p_lastaccept passport_login.lastaccept%TYPE, p_lastreject passport_login.lastreject%TYPE, p_locked passport_login.locked%TYPE, p_token_id token.id%TYPE DEFAULT NULL, p_replacementtoken_id token.id%TYPE DEFAULT NULL) FROM PUBLIC;



