CREATE OR REPLACE PROCEDURE osag_auth_passport.update_token_details2 (p_token_id token.id%TYPE, p_details text) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.update_token_details2(): ';

        l_tokentype_id tokentype.id%TYPE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        SELECT tokentype_id
        INTO STRICT l_tokentype_id
        FROM token
        WHERE id = p_token_id;

        IF (l_tokentype_id = 0 OR l_tokentype_id = 8 OR l_tokentype_id = 9) THEN
            UPDATE token
            SET seciddrift = coalesce((p_details)::numeric , seciddrift)
            WHERE id = p_token_id;
        ELSIF (l_tokentype_id = 1 OR l_tokentype_id = 7) THEN
            UPDATE token
            SET actercount = coalesce((p_details)::numeric , actercount)
            WHERE id = p_token_id;
        ELSIF ((l_tokentype_id = 2) OR (l_tokentype_id = 3) OR (l_tokentype_id = 5) OR (l_tokentype_id = 6)) THEN
            plog.debug(S_PREFIX||'foo:'||p_details);
            UPDATE token
            SET dpblob = coalesce(p_details, dpblob)
            WHERE id = p_token_id;
        ELSE
            plog.err(S_PREFIX||'caught exception: unknown token type ID '||l_tokentype_id);
            RAISE no_data_found;
        END IF;

        IF (NOT FOUND) THEN
            plog.err(S_PREFIX||'failed to update token ID "'||p_token_id||'"');
            RAISE no_data_found;
        ELSE
            plog.notice(S_PREFIX||'updated seciddrift/actercount/dpblob of token ID "'||p_token_id||'"');
        END IF;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth_passport.update_token_details2 (p_token_id token.id%TYPE, p_details text) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_auth_passport.reset_dpblob (p_token_id token.id%TYPE) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.reset_dpblob(): ';

        v_authhost_id passport_login.homeauthhost_id%TYPE;
        v_old_dpblob token.dpblob%TYPE;
        v_exit bigint;
        v_output varchar(512);
        v_proxy_command varchar(512);


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        SELECT dpblob INTO STRICT v_old_dpblob FROM token
        WHERE id = p_token_id;

        IF ((v_old_dpblob IS NULL) OR (v_old_dpblob = '')) THEN
            RAISE no_data_found;
        END IF;

        v_proxy_command := OSAG_AUTH_STATE.GET_JUMP_SSH_CALL||'/opt/OSAGrad/bin/dpcheck -r \"'||v_old_dpblob||'\""';

        CALL OSAG_EXT.runOsCmdGetResult(v_proxy_command, 512, v_output, v_exit);


        IF (v_exit != 0) THEN
            RAISE EXCEPTION '%', v_output||', rc: '||v_exit USING ERRCODE = OSAG_AUTH_STATE.S_COMMAND_FAILED;
        END IF;


        v_output := ltrim(rtrim(v_output, ' '||chr(10)||chr(13)), ' '||chr(10)||chr(13));

        plog.debug(S_PREFIX||'cmd output: '''||v_output||'''');


        IF (length(v_output) != 248) THEN
            RAISE EXCEPTION '%', 'output does not have expected length (249), is '||length(v_output)||' instead' USING ERRCODE = OSAG_AUTH_STATE.S_COMMAND_FAILED;
        END IF;

        UPDATE token
        SET dpblob = v_output
        WHERE id = p_token_id;


        BEGIN
            SELECT homeauthhost_id INTO STRICT v_authhost_id FROM passport_login
            WHERE token_id = p_token_id
               OR replacementtoken_id = p_token_id;

            UPDATE dirtyauthhost
            SET token = 1
            WHERE authhost_id = v_authhost_id;

            IF (FOUND) THEN
                plog.debug(S_PREFIX||'updated dirtyauthhost.token entry for authhost id "'||v_authhost_id||'"');
            ELSE
                INSERT INTO dirtyauthhost(authhost_id, login, token, groups, login2groups, tunnelgroup, login2tunnelgroup, alias)
                VALUES (v_authhost_id, 0, 1, 0, 0, 0, 0, 0);
                plog.debug(S_PREFIX||'inserted dirtyauthhost.token entry for authhost id "'||v_authhost_id||'"');
            END IF;

        EXCEPTION
            WHEN no_data_found THEN

                NULL;
            WHEN OTHERS THEN
                RAISE;
        END;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth_passport.reset_dpblob (p_token_id token.id%TYPE) FROM PUBLIC;



