CREATE OR REPLACE PROCEDURE osag_auth_passport.reset_token (p_token_id token.id%TYPE) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.reset_token(): ';

        v_tokentype_id token.tokentype_id%TYPE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        SELECT tokentype_id INTO STRICT v_tokentype_id FROM token
        WHERE id = p_token_id;

        IF (v_tokentype_id = 2) THEN
            plog.debug(S_PREFIX||'resetting digipass token: "'||p_token_id||'"');
            CALL osag_auth_passport.reset_dpblob(p_token_id);
        ELSIF (v_tokentype_id = 8) THEN
            plog.debug(S_PREFIX||'resetting TOTP token: "'||p_token_id||'"');
            CALL osag_auth_passport.reset_totp(p_token_id);
        ELSE
            plog.notice(S_PREFIX||'resetting token not supported: "'||p_token_id||'"');
        END IF;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth_passport.reset_token (p_token_id token.id%TYPE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_auth_passport.unlock_dptoken (p_token_id token.id%TYPE, p_random_number text, p_unlock_code OUT text) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'OSAG_AUTH_PASSPORT.unlock_dptoken(): ';

        v_authhost_id passport_login.homeauthhost_id%TYPE;
        v_old_dpblob token.dpblob%TYPE;

        v_exit bigint;
        v_output varchar(512);
        v_proxy_command varchar(512);

        pos bigint;
        n bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        IF ((length(p_random_number) > 8) OR (length(p_random_number) < 1)) THEN
            RAISE EXCEPTION '%', 'user supplied code must be 1..8 digits long' USING ERRCODE = OSAG_AUTH_STATE.S_COMMAND_FAILED;
        END IF;

        SELECT dpblob INTO STRICT v_old_dpblob FROM token
        WHERE id = p_token_id;

        IF ((v_old_dpblob IS NULL) OR (v_old_dpblob = '')) THEN
            RAISE no_data_found;
        END IF;

        v_proxy_command := OSAG_AUTH_STATE.GET_JUMP_SSH_CALL||'/opt/OSAGrad/bin/dpcheck -u \"'||v_old_dpblob||'\"'||p_random_number||'"';

        CALL OSAG_EXT.runOsCmdGetResult(v_proxy_command, 512, v_output, v_exit);


        IF (v_exit != 0) THEN
            RAISE EXCEPTION '%', v_output||', rc: '||v_exit USING ERRCODE = OSAG_AUTH_STATE.S_COMMAND_FAILED;
        END IF;


        v_output := ltrim(rtrim(v_output, ' '||chr(10)||chr(13)), ' '||chr(10)||chr(13));

        plog.debug(S_PREFIX||'cmd output: '''||v_output||'''');


        pos := INSTR(v_output, ':', -1);
        pos := pos - 1;


        
        
        
        
        IF (pos != 248) THEN
            RAISE EXCEPTION '%', 'Digipass blob does not have expected length (expected=248, actual='||pos||')' USING ERRCODE = OSAG_AUTH_STATE.S_COMMAND_FAILED;
        END IF;

        IF (length(v_output) <= 249) THEN
            RAISE EXCEPTION '%', 'command output does not contain an unlock code' USING ERRCODE = OSAG_AUTH_STATE.S_COMMAND_FAILED;
        END IF;

        p_unlock_code := substr(v_output, pos + 2);


        n := (p_unlock_code)::numeric;

        UPDATE token
        SET dpblob = substr(v_output, 1, pos)
        WHERE id = p_token_id;


        BEGIN
            SELECT homeauthhost_id INTO STRICT v_authhost_id FROM passport_login
            WHERE token_id = p_token_id;

            UPDATE dirtyauthhost
            SET token = 1
            WHERE authhost_id = v_authhost_id;

            IF (FOUND) THEN
                plog.debug(S_PREFIX||'updated dirtyauthhost.token entry for authhost id "'||v_authhost_id||'"');
            ELSE
                INSERT INTO dirtyauthhost(authhost_id, login, token, groups, login2groups, tunnelgroup, login2tunnelgroup, alias)
                VALUES (v_authhost_id, 0, 1, 0, 0, 0, 0, 0);
                plog.debug(S_PREFIX||'inserted dirtyauthhost.token entry for authhost id "'||v_authhost_id||'"');
            END IF;

        EXCEPTION
            WHEN no_data_found THEN

                NULL;
            WHEN OTHERS THEN
                RAISE;
        END;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_auth_passport.unlock_dptoken (p_token_id token.id%TYPE, p_random_number text, p_unlock_code OUT text) FROM PUBLIC;



