CREATE OR REPLACE FUNCTION osag_auth_passport.is_password_only_allowed (p_homeauthhost_id authhost.id%TYPE) RETURNS boolean AS $body$
DECLARE


        v_passwordonlyallowed bigint;

BEGIN

        SELECT passwordonlyallowed INTO STRICT v_passwordonlyallowed FROM auth.authsys asys, auth.authhost2authsys ah2as
        WHERE asys.id = ah2as.authsys_id AND ah2as.authhost_id = p_homeauthhost_id;


        IF v_passwordonlyallowed IS NULL OR v_passwordonlyallowed = 0 THEN
