CREATE OR REPLACE FUNCTION osag_auth_state.get_jump_ssh_call () RETURNS varchar AS $body$
DECLARE

    C_OSAG_AUTHSYNC_SSH_CALL CONSTANT varchar(64) := '/usr/bin/ssh -q -t -t -x radiator@XXXXXX "stty hup; ';
    v_jump varchar(64);

BEGIN
    begin
      select j.jump_host into STRICT v_jump
      from auth.jumphost j, v$instance i
      where j.db_host = i.host_name;
    exception
      when no_data_found then
        RETURN 'echo "';
    end;
    RETURN REPLACE(C_OSAG_AUTHSYNC_SSH_CALL, 'XXXXXX', v_jump);
  END;
$body$
LANGUAGE PLPGSQL
