-- Oracle package 'OSAG_CHANNEL' declaration, please edit to match PostgreSQL syntax.

DROP SCHEMA IF EXISTS osag_channel CASCADE;
CREATE SCHEMA IF NOT EXISTS osag_channel;





CREATE OR REPLACE PROCEDURE osag_channel.run_queries () AS $body$
DECLARE


        c_prefix CONSTANT varchar(64) := 'OSAG_CHANNEL.run_queries(): ';
        l_time    timestamp(0)   := clock_timestamp();
        l_minute  bigint := (to_char(l_time, 'MI'))::numeric;
        l_hour    bigint := (to_char(l_time, 'HH24'))::numeric;
        l_day     bigint := (to_char(l_time, 'D'))::numeric  - 1;
        v_channelvalue report.channelvalue.VALUE%TYPE;
        v_channelvalue_id report.channelvalue.ID%TYPE;

        l_key_cursor CURSOR FOR
            SELECT k.id, k.sqlquery, k.exechour, k.execminute, k.execday, k.execinterval, k.historysize, k.lastupdated FROM report.channelkey k
            WHERE
                ((k.execinterval IS NOT NULL AND (l_time - k.lastupdated) * 24 * 60 >= k.execinterval)
                    OR (k.execinterval IS NULL
                        AND (k.execminute IS NULL
                            OR (k.execminute = l_minute
                                AND ((k.exechour IS NULL AND (to_char(k.lastupdated, 'HH24'))::numeric  != l_hour)
                                    OR (k.exechour = l_hour AND date_trunc('day', k.lastupdated) != date_trunc('day', l_time)
                                        AND (k.execday IS NULL OR k.execday = l_day)
                                         )
                                    )
                                 )
                            )
                     )
                    );



BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        FOR l_key IN l_key_cursor LOOP

                BEGIN

                    EXECUTE trim(both TRAILING ';' FROM l_key.sqlquery) INTO STRICT v_channelvalue;
                    SELECT nextval('seq_channelvalue_id') INTO STRICT v_channelvalue_id;
                    INSERT INTO report.channelvalue(channelkey_id, timestamp, value, id) VALUES (l_key.id, l_time, v_channelvalue, v_channelvalue_id);

                    UPDATE report.channelkey SET lastupdated = l_time, last_value_id = v_channelvalue_id WHERE id = l_key.id;


                    DELETE FROM report.channelvalue WHERE id IN (SELECT id FROM (SELECT id, row_number() OVER (ORDER BY timestamp DESC) r FROM report.channelvalue WHERE channelkey_id = l_key.id) alias2 
                                                           WHERE r > l_key.historysize);

                EXCEPTION
                    WHEN no_data_found THEN
                        plog.warning(c_prefix||'REPORT.CHANNEL_KEY#'|| l_key.id ||': no data found');
                    WHEN OTHERS THEN
                        plog.err(c_prefix||'unexpected error for REPORT.CHANNEL_KEY#' || l_key.id || ': '||sqlerrm);

                END;

            END LOOP;

    EXCEPTION
        WHEN no_data_found THEN
            plog.warning(c_prefix||'no data found');
        WHEN OTHERS THEN
            plog.err(c_prefix||'unexpected error: '||sqlerrm);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_channel.run_queries () FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_channel.count_hosts () AS $body$
DECLARE


        c_prefix CONSTANT varchar(64) := 'OSAG_CHANNEL.count_hosts(): ';
        v_host_count bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        SELECT COUNT(*) INTO STRICT v_host_count FROM mss.host WHERE active = 1;

        INSERT INTO report.host_count(ID, DATE_COUNTED, HOSTCOUNT)
            (SELECT nextval('host_count_seq'), statement_timestamp(),v_host_count );

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(c_prefix||'unexpected error: '||sqlerrm);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_channel.count_hosts () FROM PUBLIC;
-- End of Oracle package 'OSAG_CHANNEL' declaration



