 STABLE;
-- REVOKE ALL ON FUNCTION osag_dbprop.get_number_by_host (i_host_id bigint, i_property_name text) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_dbprop.get_string_by_host_key_id (i_host_id bigint, i_property_key_id bigint) RETURNS varchar AS $body$
DECLARE

        l_string	mss.value.string_value%TYPE	:= NULL;
        c_prefix 	CONSTANT varchar(64)		:= 'OSAG_DBPROP.get_string_by_host_key_id(): ';

  r RECORD;

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        l_string := NULL;
        for r in (
            SELECT *
            from mss.V_HOST_KEY_VALUE hkv, mss.KEY k
            where hkv.HOST_ID = i_host_id
              and k.id = i_property_key_id
              and hkv.KEY_NAME = k.name) loop
                if (l_string IS NULL)  then
                    l_string := r.string_value;
                elsif (l_string = r.string_value) then
                    plog.warning(c_prefix||' dbprop '|| r.key_name ||' for host_id='|| i_host_id
                        ||', scope='|| r.scope ||' has multiple but consistent values: '|| l_string);
                else
                    plog.err(c_prefix||' dbprop '|| r.key_name ||' for host_id='|| i_host_id
                        ||', scope='|| r.scope ||' has multiple inconsistently values: '|| l_string ||' vs. '|| r.string_value);
                end if;
            end loop;

        RETURN l_string;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION osag_dbprop.get_string_by_host_key_id (i_host_id bigint, i_property_key_id bigint) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_dbprop.get_string_by_host (i_host_id bigint, i_property_name text) RETURNS varchar AS $body$
DECLARE

        v_key_id bigint;
        c_prefix 	CONSTANT varchar(64)		:= 'OSAG_DBPROP.get_string_by_host(): ';

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        BEGIN
            SELECT id INTO STRICT v_key_id FROM mss.key WHERE name = i_property_name;
        EXCEPTION
            WHEN no_data_found THEN
                plog.err(c_prefix||'unknown db property '||i_property_name);
                RAISE EXCEPTION '%', 'unknown db property '''||i_property_name||'''' USING ERRCODE = OSAG_DBPROP_STATE.S_ERRNO_UNKNOWN_DBPROP;
            WHEN OTHERS THEN
                plog.err(c_prefix||'unexpected error while fetching key id for db property '||i_property_name||': '||sqlerrm);
                RAISE OSAG_DBPROP_STATE.e_abort;
        END;

        RETURN osag_dbprop.get_string_by_host_key_id(i_host_id, v_key_id);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION osag_dbprop.get_string_by_host (i_host_id bigint, i_property_name text) FROM PUBLIC;
-- End of Oracle package 'OSAG_DBPROP' declaration



