CREATE SCHEMA IF NOT EXISTS osag_duty;





CREATE OR REPLACE FUNCTION osag_duty.get_next_swiss_business_day (p_date TIMESTAMP WITH TIME ZONE DEFAULT statement_timestamp()) RETURNS timestamp AS $body$
DECLARE


        c_prefix CONSTANT varchar(64)  := 'OSAG_DUTY.get_next_swiss_business_day(): ';

        v_business_day TIMESTAMP WITH TIME ZONE;

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        IF (TO_CHAR(p_date AT TIME ZONE 'Europe/Zurich','HH24') < 8) THEN
            v_business_day := (to_timestamp(date_trunc('day', p_date)), TZ_OFFSET('Europe/Zurich'))::timestamp with time zone + INTERVAL '8' HOUR + INTERVAL '30' MINUTE;
        ELSE
            v_business_day := (to_timestamp(date_trunc('day', p_date)), TZ_OFFSET('Europe/Zurich'))::timestamp with time zone + INTERVAL '1' DAY + INTERVAL '8' HOUR + INTERVAL '30' MINUTE;
        END IF;


        WHILE(TO_CHAR(v_business_day AT TIME ZONE 'Europe/Zurich','D') IN (1,7) OR osag_duty.is_legal_holiday(v_business_day) = 1) LOOP
                v_business_day := v_business_day + INTERVAL '1' DAY;
            END LOOP;

        RETURN v_business_day;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(c_prefix || 'caught exception: '||sqlerrm);
            RETURN p_date AT TIME ZONE 'Europe/Zurich';
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
 STABLE;
-- REVOKE ALL ON FUNCTION osag_duty.get_next_swiss_business_day (p_date TIMESTAMP WITH TIME ZONE DEFAULT statement_timestamp()) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_duty.is_legal_holiday (p_date TIMESTAMP WITH TIME ZONE DEFAULT statement_timestamp()) RETURNS bigint AS $body$
DECLARE


        c_prefix  CONSTANT varchar(64) := 'OSAG_DUTY.is_legal_holiday(): ';

        v_legal_holiday ESP.SPECIAL_DAY.LEGAL_HOLIDAY%TYPE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        SELECT COUNT(*) INTO STRICT v_legal_holiday
        FROM esp.special_day sd
        WHERE p_date - sd.day_date < (1 * ('1'||'day')::interval)
          AND p_date - sd.day_date >= (0 * ('1'||'day')::interval)
          AND sd.legal_holiday = 1;

        IF (v_legal_holiday > 0) THEN
            RETURN 1;
        ELSE
            RETURN 0;
        END IF;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(c_prefix || 'caught exception: '||sqlerrm);
            RETURN 0;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION osag_duty.is_legal_holiday (p_date TIMESTAMP WITH TIME ZONE DEFAULT statement_timestamp()) FROM PUBLIC;
-- End of Oracle package 'OSAG_DUTY' declaration



