CREATE OR REPLACE PROCEDURE osag_ext.runoscmdgetresult (p_cmd text, p_length bigint, p_cmd_out OUT text, p_cmd_exit OUT bigint) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(32) := 'osag_ext.runoscmdgetresult(): ';
        S_MAX_CMD_OUT_LENGTH CONSTANT bigint := 32767;

        v_length bigint := p_length;
        v_ell_length bigint;


        
    
BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        IF (v_length > S_MAX_CMD_OUT_LENGTH) then
            plog.debug(S_PREFIX||'truncating command output length to '||S_MAX_CMD_OUT_length||' characters');
            v_length := S_MAX_CMD_OUT_LENGTH;
        END IF;

        runOsCmdExt(p_cmd, v_length, p_cmd_out, p_cmd_exit);

        plog.debug(S_PREFIX||'command exit code: '||p_cmd_exit);

        IF (p_cmd_out IS NULL) THEN
            plog.debug(S_PREFIX||'command output is null');
        ELSE
            v_ell_length := LENGTH(p_cmd_out) / 3;
            IF (v_ell_length > 35) THEN
                v_ell_length := 35;
            END IF;

            plog.debug(S_PREFIX||'command output: "'||substr(p_cmd_out, 1, v_ell_length)||'.........'||
                       substr(p_cmd_out, -v_ell_length)||'"');
        END IF;

    EXCEPTION
        WHEN SQLSTATE '50004' THEN

            RAISE;
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: "'||SQLERRM);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_ext.runoscmdgetresult (p_cmd text, p_length bigint, p_cmd_out OUT text, p_cmd_exit OUT bigint) FROM PUBLIC;
-- End of Oracle package 'OSAG_EXT' declaration



