CREATE SCHEMA IF NOT EXISTS osag_fyi;





CREATE OR REPLACE PROCEDURE osag_fyi.check_old_entries () AS $body$
DECLARE


        oldest_event_time TIMESTAMP WITH TIME ZONE := (statement_timestamp() - INTERVAL '93' DAY);


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        DELETE
        FROM fyi.message_history fm
        WHERE fm.notification_event_id IN (SELECT id
                                           FROM notification_event
                                           WHERE event_time < oldest_event_time);

        DELETE
        FROM fyi.affected_host fa
        WHERE fa.notification_event_id IN (SELECT id
                                           FROM fyi.notification_event
                                           WHERE (event_time < oldest_event_time) );

        DELETE
        FROM fyi.notification_event
        WHERE (event_time < oldest_event_time);

        DELETE
        FROM fyi.last_seen
        WHERE (last_seen < oldest_event_time);

        DELETE
        FROM fyi.target ft
        WHERE NOT EXISTS (SELECT *
                          FROM fyi.last_seen fl
                          WHERE fl.target_id = ft.id);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_fyi.check_old_entries () FROM PUBLIC;
-- End of Oracle package 'OSAG_FYI' declaration



