CREATE OR REPLACE FUNCTION osag_getnodes.get_tams_by_company_id (p_company_id bigint) RETURNS varchar AS $body$
DECLARE

        c_prefix    CONSTANT varchar(64)  := 'OSAG_GETNODES.get_tams_by_company_id(): ';

        v_res       varchar(4000) := NULL;

        tams CURSOR FOR
            SELECT stop.contact.short
            FROM stop.contact
                     JOIN stop.company_tam ON (stop.contact.id=stop.company_tam.contact_id)
                     JOIN stop.company     ON (stop.company_tam.company_id = stop.company.id)
            WHERE stop.company.id = p_company_id
            ORDER BY stop.company_tam.priority ASC;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        FOR tam IN tams LOOP
                IF ( v_res IS NULL ) THEN
                    v_res := tam.short;
                ELSE
                    v_res := v_res||','||tam.short;
                END IF;

            END LOOP;

        RETURN v_res;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(c_prefix||'unexpected exception: '||sqlerrm);
            RETURN v_res;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
 STABLE;
-- REVOKE ALL ON FUNCTION osag_getnodes.get_tams_by_company_id (p_company_id bigint) FROM PUBLIC;



