CREATE OR REPLACE PROCEDURE osag_guma.free_pattern_pos ( i_pos bigint ) AS $body$
DECLARE

        c_prefix CONSTANT varchar(32) := 'free_pattern_pos: ';
        l_count  bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        SELECT count(*) INTO STRICT l_count
        FROM pattern
        WHERE position = i_pos;


        IF (l_count = 0) THEN
            RETURN;
        END IF;

        UPDATE PATTERN
        SET position = position + 1
        WHERE position >= i_pos;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(c_prefix||'unexpected error: '||sqlerrm);
            RAISE OSAG_GUMA_STATE.e_abort;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_guma.free_pattern_pos ( i_pos bigint ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_guma.pack_pattern_pos () AS $body$
DECLARE

        c_prefix CONSTANT varchar(32) := 'pack_pattern_pos: ';
        l_pos    bigint := 1;

        l_pattern_cur CURSOR FOR
            SELECT position
            FROM pattern
            ORDER BY position ASC
                FOR UPDATE OF position;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        FOR l_pattern_rec IN l_pattern_cur LOOP
                UPDATE pattern
                SET position = l_pos
                WHERE CURRENT OF l_pattern_cur;

                l_pos := l_pos + 1;
            END LOOP;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(c_prefix||'unexpected error: '||sqlerrm);
            RAISE OSAG_GUMA_STATE.e_abort;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_guma.pack_pattern_pos () FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_guma.prune_syslog_message ( age bigint ) AS $body$
DECLARE

        ora2pg_rowcount int;
c_prefix CONSTANT varchar(32) := 'prune_syslog_message: ';


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        DELETE FROM guma2.syslog_message
        WHERE log_date < clock_timestamp() - age;

        GET DIAGNOSTICS ora2pg_rowcount = ROW_COUNT;


        plog.notice(c_prefix||'removed '|| ora2pg_rowcount||' entries older than '||age||' days from syslog_message');

        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(c_prefix||'unexpected error: '||sqlerrm);

    END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE osag_guma.prune_syslog_message ( age bigint ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_guma.dump_to_hw_history ( p_host_id mss.host.id%TYPE, p_old_hardware_id mss.hardware.id%TYPE ) AS $body$
DECLARE

        c_prefix CONSTANT varchar(32) := 'dump_to_hw_history: ';

        v_oldhardware  mss.hardware%ROWTYPE;
        v_hostname mss.host.name%TYPE;
        v_compshort stop.company.short%TYPE;
        v_stypeicode mss.service_type.internal_code%TYPE;
        v_log mss.hardware_history.log%TYPE;


BEGIN

        
        SELECT * INTO STRICT v_oldhardware
        FROM mss.hardware WHERE id = p_old_hardware_id;


        IF v_oldhardware.hardware_disposal_contact_id IS NULL
        THEN
            plog.err(c_prefix||'hardware_disposal_contact_id is NULL while replacing hw for host_id: '||p_host_id||' hw_id: '||p_old_hardware_id);
            RAISE OSAG_GUMA_STATE.e_abort;
        END IF;
        IF v_oldhardware.hardware_disposal_reason_id IS NULL
        THEN
            plog.err(c_prefix||'hardware_disposal_reason_id is NULL while replacing hw for host_id: '||p_host_id||' hw_id: '||p_old_hardware_id);
            RAISE OSAG_GUMA_STATE.e_abort;
        END IF;


        SELECT 'hardware_type='||mss.hardware_type.short||';disposal_contact='||stop.contact.email||';disposal_reason='
                   ||mss.hardware_disposal_reason.name
        INTO STRICT v_log
        FROM mss.hardware
                 INNER JOIN mss.hardware_type ON (mss.hardware.hardware_type_id = mss.hardware_type.id)
                 INNER JOIN mss.hardware_disposal_reason ON (mss.hardware.hardware_disposal_reason_id = mss.hardware_disposal_reason.id)
                 INNER JOIN stop.contact ON (mss.hardware.hardware_disposal_contact_id = stop.contact.id) 
        WHERE mss.hardware.id = p_old_hardware_id;


        SELECT mss.host.name, stop.company.short, mss.service_type.internal_code
        INTO STRICT v_hostname, v_compshort, v_stypeicode
        FROM mss.host
                 INNER JOIN stop.company ON (mss.host.service_company_id = stop.company.id)
                 INNER JOIN mss.host2service ON (mss.host.id = mss.host2service.host_id)
                 INNER JOIN mss.service ON (mss.host2service.service_id = mss.service.id)
                 INNER JOIN mss.service_type ON (mss.service.service_type_id = mss.service_type.id) 
        WHERE mss.host.id = p_host_id;



        
        INSERT INTO mss.hardware_history(id, barcode, company_short, disposal_date, hardware_disposal_comments,
                                          hardware_disposal_contact_id, hardware_disposal_reason_id, hardware_type_id, history_date,
                                          host_name, log, mac_address, purchase_date, serial_number, service_type_internal_code, hardware_deploy_reason_id)
        VALUES (nextval('hardwarehistory_seq'), v_oldhardware.barcode,  v_compshort, coalesce(v_oldhardware.disposal_date, clock_timestamp()),
                v_oldhardware.hardware_disposal_comments, v_oldhardware.hardware_disposal_contact_id,
                v_oldhardware.hardware_disposal_reason_id, v_oldhardware.hardware_type_id, clock_timestamp(),
                v_hostname, v_log, v_oldhardware.mac_address, v_oldhardware.purchase_date, v_oldhardware.serial_number,
                v_stypeicode, v_oldhardware.hardware_deploy_reason_id);


    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_guma.dump_to_hw_history ( p_host_id mss.host.id%TYPE, p_old_hardware_id mss.hardware.id%TYPE ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_guma.add_hardware_lifecycle_item ( p_hardware_id mss.hardware.id%TYPE, p_hardware_lc_state_id mss.hardware_lifecycle_item.hardware_lc_state_id%TYPE, p_hardware_lc_location_id mss.hardware_lifecycle_item.hardware_lc_location_id%TYPE, p_creator mss.hardware_lifecycle_item.creator%TYPE) AS $body$
DECLARE

        l_hardware_lifecycle_item_id  mss.hardware_lifecycle_item.id%TYPE;

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        SELECT nextval('hardware_lifecycle_item_seq') INTO STRICT l_hardware_lifecycle_item_id
;


        INSERT INTO mss.hardware_lifecycle_item(id, hardware_id, hardware_lc_state_id, hardware_lc_location_id, creator)
        VALUES (l_hardware_lifecycle_item_id, p_hardware_id, p_hardware_lc_state_id, p_hardware_lc_location_id, p_creator);


        UPDATE mss.hardware
        SET hardware_lifecycle_item_id = l_hardware_lifecycle_item_id
        WHERE hardware.id = p_hardware_id;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_guma.add_hardware_lifecycle_item ( p_hardware_id mss.hardware.id%TYPE, p_hardware_lc_state_id mss.hardware_lifecycle_item.hardware_lc_state_id%TYPE, p_hardware_lc_location_id mss.hardware_lifecycle_item.hardware_lc_location_id%TYPE, p_creator mss.hardware_lifecycle_item.creator%TYPE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_guma.replace_hardware ( p_host_id mss.host.id%TYPE, p_old_hw_id mss.hardware.id%TYPE, p_new_hw_id mss.hardware.id%TYPE) AS $body$
DECLARE

        l_hardware_lc_location_id mss.hardware_lifecycle_item.hardware_lc_location_id%TYPE;

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        CALL osag_guma.dump_to_hw_history(p_host_id, p_old_hw_id);


        UPDATE mss.hardware
        SET disposal_date = clock_timestamp()
        WHERE mss.hardware.id = p_old_hw_id;


        UPDATE mss.host
        SET hardware_id = p_new_hw_id,
            replacement_hardware_id  = NULL
        WHERE id = p_host_id;

        SELECT CASE
                   WHEN EXISTS (
                           SELECT *
                           FROM mss.host h
                           WHERE h.id = p_host_id AND h.service_company_id = 6
                       )
                       THEN 9
                   ELSE 3
                   END INTO STRICT l_hardware_lc_location_id
;


        CALL osag_guma.add_hardware_lifecycle_item(p_old_hw_id, 6, l_hardware_lc_location_id, NULL);
        CALL osag_guma.add_hardware_lifecycle_item(p_new_hw_id, 4, l_hardware_lc_location_id, NULL);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_guma.replace_hardware ( p_host_id mss.host.id%TYPE, p_old_hw_id mss.hardware.id%TYPE, p_new_hw_id mss.hardware.id%TYPE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_guma.check_replaced_hw_for_host ( p_host_id mss.host.id%TYPE, p_reported_mac mss.hardware.mac_address%TYPE ) AS $body$
DECLARE

        c_prefix CONSTANT varchar(32) := 'check_replaced_hw_for_host: ';
        l_replacement_mac mss.hardware.mac_address%TYPE;
        l_old_hardware_id mss.hardware.id%TYPE;
        l_hostname        mss.host.name%TYPE;
        v_event_id        bigint;
        l_replacement_id  mss.hardware.id%TYPE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        SELECT new_hardware.mac_address,old_hardware.id,mss.host.name,new_hardware.id INTO STRICT l_replacement_mac,l_old_hardware_id,l_hostname, l_replacement_id
        FROM mss.host
                 JOIN mss.hardware new_hardware ON (mss.host.replacement_hardware_id = new_hardware.id)
                 JOIN mss.hardware old_hardware ON (mss.host.hardware_id = old_hardware.id) 
        WHERE mss.host.id = p_host_id
          AND new_hardware.mac_address = p_reported_mac;

        IF ( l_replacement_mac = p_reported_mac ) THEN
            CALL osag_guma.replace_hardware(p_host_id, l_old_hardware_id, l_replacement_id);


            tt.CALL event_interface.newevent_new(v_event_id,current_setting('osag_guma.hw_changed_event_type')::bigint,p_host_id,
                                            'First heartbeat received '||CHR(10)||CHR(10)||
                                            'Received first heartbeat from hardware with the MAC address: '||l_replacement_mac||'. '||
                                            'The heartbeat was sent from the host: '||l_hostname||'. '||
                                            'This usually happens when a replacement hardware is plugged in for the first time.', 
                                            current_setting('osag_guma.todo_private_hw_mig')::varchar(1024)'To Do:'||CHR(10)||' - Check ticket type. Must be: migration'||CHR(10)||' - Check that this ticket is a hardware migration tracking ticket.'||CHR(10));
        END IF;

    EXCEPTION
        WHEN no_data_found THEN
            return;

        WHEN OSAG_GUMA_STATE.e_abort THEN
            plog.warning(c_prefix||'skipped host '||p_host_id);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_guma.check_replaced_hw_for_host ( p_host_id mss.host.id%TYPE, p_reported_mac mss.hardware.mac_address%TYPE ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_guma.log_version (p_host_id bigint, p_old_version text, p_new_version text, p_build text) AS $body$
DECLARE

        c_prefix         CONSTANT varchar(32) := 'log_version: ';
        v_application    mcaudit.application.id%TYPE := 1;
        v_component      mcaudit.component.id%TYPE   := 39;
        v_record_type    mcaudit.record_type.id%TYPE := 168;
        v_severity       bigint                      := 10;
        v_transaction_id mcaudit.record.transaction_id%TYPE;
        v_details        mcaudit.record.details%TYPE;
        v_message        mcaudit.record.message%TYPE := 'OS version changed to '
            ||p_new_version||' ('||p_build||')';

        v_company        stop.company.id%TYPE;
        v_object_id      mcaudit.record.object_id%TYPE := p_host_id;

        c_contact_id     mcaudit.record.contact_id%TYPE := NULL;
        c_table_name     varchar(32) := 'MSS.HOST';


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        v_details := '<details>'
            || '<OSVERSION'
            || ' OLDVERSION="' || p_old_version || '"'
            || ' NEWVERSION="' || p_new_version || '"'
            || ' BUILD="' || p_build || '"'
            || '/>'
            || '</details>';

        SELECT service_company_id INTO STRICT v_company
        FROM mss.host
        WHERE id = p_host_id;

        CALL OSAG_AUDIT.add_record_raw(v_application,
                                  v_component,
                                  v_record_type,
                                  v_severity,
                                  v_transaction_id,
                                  v_message,
                                  v_details,
                                  v_company,
                                  c_contact_id,
                                  c_table_name,
                                  v_object_id);
    EXCEPTION
        WHEN others THEN
            plog.info(c_prefix||'unexpected error while processing host '||p_host_id||': '||sqlerrm);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_guma.log_version (p_host_id bigint, p_old_version text, p_new_version text, p_build text) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_guma.clean_suppressed_signature () AS $body$
DECLARE


        guma_old_suppressions CURSOR FOR
            SELECT so.id, so.host_id, so.signature_id, so.date_start, so.date_end, so.ticket_id,
                   s.short_name, h.name, h.service_company_id
            FROM guma2.suppressed_signature so, mss.host h, guma2.signature s
            WHERE so.date_end < statement_timestamp() and h.id = so.host_id and s.id = so.signature_id
                FOR UPDATE of so.id;

        c_prefix         CONSTANT varchar(32) := 'clean_suppressed_signature: ';
        c_application    mcaudit.application.id%TYPE := 8;
        c_component      mcaudit.component.id%TYPE   := 24;
        c_record_type    mcaudit.record_type.id%TYPE := 195;
        c_severity       bigint                      := 10;

        c_contact_id     mcaudit.record.contact_id%TYPE := NULL;
        c_transaction_id mcaudit.record.transaction_id%TYPE := NULL;
        c_table_name     varchar(32) := 'GUMA2.SUPPRESSED_SIGNATURE';

        v_details        mcaudit.record.details%TYPE;
        v_message        mcaudit.record.message%TYPE := '';


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        FOR sig IN guma_old_suppressions LOOP

                v_details := '<details>'
                    || '<GUMA2.SUPPRESSED_SIGNATURE'
                    || ' HOST_ID="' || sig.host_id || '"'
                    || ' SIGNATURE_ID="' || sig.signature_id || '"'
                    || ' START_DATE="' || TO_CHAR(sig.date_start, 'DD.MM.YYYY HH24:MI:SS TZH:TZM') || '"'
                    || ' END_DATE="' || TO_CHAR(sig.date_end, 'DD.MM.YYYY HH24:MI:SS TZH:TZM') || '"'
                    || ' TICKET_ID="' || sig.ticket_id || '"'
                    || ' _action="deleted" '
                    || '/>'
                    || '</details>';

                v_message := 'Deleted signature suppression for signature '''
                    || sig.short_name
                    || ''' and host ''' || sig.name || '''.';

                CALL OSAG_AUDIT.add_record_raw(c_application,
                                          c_component,
                                          c_record_type,
                                          c_severity,
                                          c_transaction_id,
                                          v_message,
                                          v_details,
                                          sig.service_company_id,
                                          c_contact_id,
                                          c_table_name,
                                          sig.id);

                DELETE FROM GUMA2.SUPPRESSED_SIGNATURE WHERE ID = sig.id;

            END LOOP;


    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_guma.clean_suppressed_signature () FROM PUBLIC;
-- End of Oracle package 'OSAG_GUMA' declaration



