CREATE OR REPLACE PROCEDURE osag_hardware.dump_to_hw_history ( p_host_id mss.host.id%TYPE, p_old_hardware_id mss.hardware.id%TYPE ) AS $body$
DECLARE

        c_prefix CONSTANT varchar(32) := 'dump_to_hw_history: ';

        v_oldhardware  mss.hardware%ROWTYPE;
        v_hostname mss.host.name%TYPE;
        v_compshort stop.company.short%TYPE;
        v_stypeicode mss.service_type.internal_code%TYPE;
        v_log mss.hardware_history.log%TYPE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);


        SELECT * INTO STRICT v_oldhardware
        FROM mss.hardware WHERE id = p_old_hardware_id;


        IF v_oldhardware.hardware_disposal_contact_id IS NULL
        THEN
            plog.err(c_prefix||'hardware_disposal_contact_id is NULL while replacing hw for host_id: '||p_host_id||' hw_id: '||p_old_hardware_id);
            RAISE OSAG_EXCEPTIONS.e_abort;
        END IF;
        IF v_oldhardware.hardware_disposal_reason_id IS NULL
        THEN
            plog.err(c_prefix||'hardware_disposal_reason_id is NULL while replacing hw for host_id: '||p_host_id||' hw_id: '||p_old_hardware_id);
            RAISE OSAG_EXCEPTIONS.e_abort;
        END IF;


        SELECT 'hardware_type='||mss.hardware_type.short||';disposal_contact='||stop.contact.email||';disposal_reason='
                   ||mss.hardware_disposal_reason.name
        INTO STRICT v_log
        FROM mss.hardware
                 INNER JOIN mss.hardware_type ON (mss.hardware.hardware_type_id = mss.hardware_type.id)
                 INNER JOIN mss.hardware_disposal_reason ON (mss.hardware.hardware_disposal_reason_id = mss.hardware_disposal_reason.id)
                 INNER JOIN stop.contact ON (mss.hardware.hardware_disposal_contact_id = stop.contact.id) 
        WHERE mss.hardware.id = p_old_hardware_id;


        SELECT mss.host.name, stop.company.short, mss.service_type.internal_code
        INTO STRICT v_hostname, v_compshort, v_stypeicode
        FROM mss.host
                 INNER JOIN stop.company ON (mss.host.service_company_id = stop.company.id)
                 INNER JOIN mss.host2service ON (mss.host.id = mss.host2service.host_id)
                 INNER JOIN mss.service ON (mss.host2service.service_id = mss.service.id)
                 INNER JOIN mss.service_type ON (mss.service.service_type_id = mss.service_type.id) 
        WHERE mss.host.id = p_host_id;



        
        INSERT INTO mss.hardware_history(id, barcode, company_short, disposal_date, hardware_disposal_comments,
                                          hardware_disposal_contact_id, hardware_disposal_reason_id, hardware_type_id, history_date,
                                          host_name, log, mac_address, purchase_date, serial_number, service_type_internal_code, hardware_deploy_reason_id)
        VALUES (nextval('hardwarehistory_seq'), v_oldhardware.barcode,  v_compshort, coalesce(v_oldhardware.disposal_date, clock_timestamp()),
                v_oldhardware.hardware_disposal_comments, v_oldhardware.hardware_disposal_contact_id,
                v_oldhardware.hardware_disposal_reason_id, v_oldhardware.hardware_type_id, clock_timestamp(),
                v_hostname, v_log, v_oldhardware.mac_address, v_oldhardware.purchase_date, v_oldhardware.serial_number,
                v_stypeicode, v_oldhardware.hardware_deploy_reason_id);


    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_hardware.dump_to_hw_history ( p_host_id mss.host.id%TYPE, p_old_hardware_id mss.hardware.id%TYPE ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_hardware.add_hardware_lifecycle_item ( p_hardware_id mss.hardware.id%TYPE, p_hardware_lc_state_id mss.hardware_lifecycle_item.hardware_lc_state_id%TYPE, p_hardware_lc_location_id mss.hardware_lifecycle_item.hardware_lc_location_id%TYPE, p_creator mss.hardware_lifecycle_item.creator%TYPE) AS $body$
DECLARE

        l_hardware_lifecycle_item_id  mss.hardware_lifecycle_item.id%TYPE;

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        SELECT nextval('hardware_lifecycle_item_seq') INTO STRICT l_hardware_lifecycle_item_id
;


        INSERT INTO mss.hardware_lifecycle_item(id, hardware_id, hardware_lc_state_id, hardware_lc_location_id, creator)
        VALUES (l_hardware_lifecycle_item_id, p_hardware_id, p_hardware_lc_state_id, p_hardware_lc_location_id, p_creator);


        UPDATE mss.hardware
        SET hardware_lifecycle_item_id = l_hardware_lifecycle_item_id
        WHERE hardware.id = p_hardware_id;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_hardware.add_hardware_lifecycle_item ( p_hardware_id mss.hardware.id%TYPE, p_hardware_lc_state_id mss.hardware_lifecycle_item.hardware_lc_state_id%TYPE, p_hardware_lc_location_id mss.hardware_lifecycle_item.hardware_lc_location_id%TYPE, p_creator mss.hardware_lifecycle_item.creator%TYPE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_hardware.replace_hardware ( p_host_id mss.host.id%TYPE, p_old_hw_id mss.hardware.id%TYPE, p_new_hw_id mss.hardware.id%TYPE) AS $body$
DECLARE

        l_hardware_lc_location_id mss.hardware_lifecycle_item.hardware_lc_location_id%TYPE;

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        CALL osag_hardware.dump_to_hw_history(p_host_id, p_old_hw_id);


        UPDATE mss.hardware
        SET disposal_date = clock_timestamp()
        WHERE mss.hardware.id = p_old_hw_id;


        UPDATE mss.host
        SET hardware_id = p_new_hw_id,
            replacement_hardware_id  = NULL
        WHERE id = p_host_id;

        SELECT CASE
                   WHEN EXISTS (
                           SELECT *
                           FROM mss.host h
                           WHERE h.id = p_host_id AND h.service_company_id = 6
                       )
                       THEN 9
                   ELSE 3
                   END INTO STRICT l_hardware_lc_location_id
;


        CALL osag_hardware.add_hardware_lifecycle_item(p_old_hw_id, 6, l_hardware_lc_location_id, NULL);
        CALL osag_hardware.add_hardware_lifecycle_item(p_new_hw_id, 4, l_hardware_lc_location_id, NULL);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_hardware.replace_hardware ( p_host_id mss.host.id%TYPE, p_old_hw_id mss.hardware.id%TYPE, p_new_hw_id mss.hardware.id%TYPE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_hardware.check_replaced_hw_for_host ( p_host_id mss.host.id%TYPE, p_reported_mac mss.hardware.mac_address%TYPE ) AS $body$
DECLARE

        c_prefix CONSTANT varchar(32) := 'check_replaced_hw_for_host: ';
        l_replacement_mac mss.hardware.mac_address%TYPE;
        l_old_hardware_id mss.hardware.id%TYPE;
        l_hostname        mss.host.name%TYPE;
        v_event_id        bigint;
        l_replacement_id  mss.hardware.id%TYPE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        SELECT new_hardware.mac_address,old_hardware.id,mss.host.name,new_hardware.id INTO STRICT l_replacement_mac,l_old_hardware_id,l_hostname, l_replacement_id
        FROM mss.host
                 JOIN mss.hardware new_hardware ON (mss.host.replacement_hardware_id = new_hardware.id)
                 JOIN mss.hardware old_hardware ON (mss.host.hardware_id = old_hardware.id) 
        WHERE mss.host.id = p_host_id
          AND new_hardware.mac_address = p_reported_mac;

        IF ( l_replacement_mac = p_reported_mac ) THEN
            CALL osag_hardware.replace_hardware(p_host_id, l_old_hardware_id, l_replacement_id);


            tt.CALL event_interface.newevent_new(v_event_id,current_setting('osag_hardware.hw_changed_event_type')::bigint,p_host_id,
                                            'First heartbeat received '||CHR(10)||CHR(10)||
                                            'Received first heartbeat from hardware with the MAC address: '||l_replacement_mac||'. '||
                                            'The heartbeat was sent from the host: '||l_hostname||'. '||
                                            'This usually happens when a replacement hardware is plugged in for the first time.', 
                                            current_setting('osag_hardware.todo_private_hw_mig')::varchar(1024)'To Do:'||CHR(10)||' - Check ticket type. Must be: migration'||CHR(10)||' - Check that this ticket is a hardware migration tracking ticket.'||CHR(10));
        END IF;

    EXCEPTION
        WHEN no_data_found THEN
            return;

        WHEN OSAG_EXCEPTIONS.e_abort THEN
            plog.warning(c_prefix||'skipped host '||p_host_id);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_hardware.check_replaced_hw_for_host ( p_host_id mss.host.id%TYPE, p_reported_mac mss.hardware.mac_address%TYPE ) FROM PUBLIC;
