-- Oracle package 'OSAG_IMPLICATION' declaration, please edit to match PostgreSQL syntax.

DROP SCHEMA IF EXISTS osag_implication CASCADE;
CREATE SCHEMA IF NOT EXISTS osag_implication;






CREATE OR REPLACE PROCEDURE osag_implication.get_next_token ( i_delim text, i_string text, o_token OUT text, o_rest OUT text ) AS $body$
DECLARE

        C_PREFIX      CONSTANT varchar(64) := 'OSAG_IMPLICATION.get_next_token(): ';
        l_pos         bigint;


BEGIN
        o_token := NULL;
        o_rest := NULL;


        IF (LENGTH(i_string) = 0) THEN
            RETURN;
        END IF;

        l_pos := INSTR(i_string, i_delim, 1, 1);


        IF (l_pos = 0) THEN
            o_token := i_string;
            RETURN;
        END IF;

        IF (l_pos != 1) THEN
            o_token := substr(i_string, 0, l_pos - 1);
        END IF;

        IF ((l_pos + LENGTH(i_delim)) <= LENGTH(i_string)) THEN
            o_rest := substr(i_string, l_pos + length(i_delim));
        END IF;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(C_PREFIX||'unexpected error 99: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_implication.get_next_token ( i_delim text, i_string text, o_token OUT text, o_rest OUT text ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_implication.auth_update ( i_logdate syslog_message.log_date%TYPE, i_data syslog_message.message%TYPE ) AS $body$
DECLARE

        C_PREFIX                CONSTANT varchar(64) := 'OSAG_IMPLICATION.auth_update(): ';


        l_msg_type              varchar(128);
        l_update_string         varchar(512);
        l_id                    bigint;
        l_result                varchar(64);
        l_token_id              bigint;
        l_replacementtoken_id   bigint;
        l_locked                bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);


         CALL osag_implication.get_next_token('AUTH:UPDATE2 ', i_data, l_msg_type, l_update_string);


         CALL osag_implication.get_next_token(' ', l_update_string, l_msg_type, l_update_string);

        plog.debug(C_PREFIX||'authentication update message type '''||l_msg_type||'''');

         CALL osag_implication.get_next_token(':', l_update_string, l_id, l_update_string);

        IF (l_id IS NULL) THEN
            plog.err(C_PREFIX||'malformed authentication update message: no object ID present: '''||i_data||'''');
            RAISE EXCEPTION 'e_abort' USING ERRCODE = '50002';
        END IF;

        IF (l_msg_type = 'LOGIN') THEN
            plog.debug(C_PREFIX||'Authentication update LOGIN ID '||l_id||': '''||l_update_string||'''');


             CALL osag_implication.get_next_token(':', l_update_string, l_result, l_update_string);

            plog.debug(C_PREFIX||'Authentication result: '||l_result||'''');


             CALL osag_implication.get_next_token(':', l_update_string, l_locked, l_update_string);
             CALL osag_implication.get_next_token(':', l_update_string, l_token_id, l_update_string);
             CALL osag_implication.get_next_token(':', l_update_string, l_replacementtoken_id, l_update_string);

            IF (l_result = 'ACCEPT') THEN
                CALL osag_auth_passport.update_login_details2(l_id, i_logdate, NULL, NULL, l_token_id, l_replacementtoken_id);
            ELSIF (l_result = 'REJECT') THEN
                CALL osag_auth_passport.update_login_details2(l_id, NULL, i_logdate, l_locked, l_token_id, l_replacementtoken_id);
            ELSE
                plog.err(C_PREFIX||'unknown authentication result: '''||l_result||'''');
                RAISE EXCEPTION 'e_abort' USING ERRCODE = '50002';
            END IF;
        ELSIF (l_msg_type = 'TOKEN') THEN
            plog.debug(C_PREFIX||'Authentication update TOKEN ID '||l_id||': '''||l_update_string||'''');

            CALL osag_auth_passport.update_token_details2(l_id, l_update_string);
        END IF;

    EXCEPTION
        WHEN SQLSTATE '50002' THEN
            NULL;
        WHEN OTHERS THEN
            plog.err(C_PREFIX||'unexpected error 99: '||sqlerrm||', GUMA msg: '''||i_data||'''');
            RAISE;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_implication.auth_update ( i_logdate syslog_message.log_date%TYPE, i_data syslog_message.message%TYPE ) FROM PUBLIC;
-- End of Oracle package 'OSAG_IMPLICATION' declaration



-- Oracle package 'OSAG_IP' declaration, please edit to match PostgreSQL syntax.

DROP SCHEMA IF EXISTS osag_ip CASCADE;
CREATE SCHEMA IF NOT EXISTS osag_ip;





CREATE OR REPLACE FUNCTION osag_ip.getbcast (p_ip bigint, p_mask bigint) RETURNS bigint AS $body$
DECLARE

        v_maskrange	bigint			:= 0;
        c_prefix 	CONSTANT varchar(64)	:= 'OSAG_IP.getbcast(): ';

BEGIN
        v_maskrange := POWER(2,(32-p_mask));
        RETURN ((date_trunc(0, p_ip/v_maskrange)+1)*v_maskrange)-1;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
 IMMUTABLE;
-- REVOKE ALL ON FUNCTION osag_ip.getbcast (p_ip bigint, p_mask bigint) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_ip.getnet (p_ip bigint, p_mask bigint) RETURNS bigint AS $body$
DECLARE

        v_maskrange	bigint			:= 0;
        v_offset	bigint			:= 0;
        c_prefix 	CONSTANT varchar(64)	:= 'OSAG_IP.getnet(): ';

BEGIN
        v_maskrange := POWER(2,(32-p_mask));
        v_offset := MOD(p_ip,v_maskrange);
        RETURN( p_ip - v_offset );
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
 IMMUTABLE;
-- REVOKE ALL ON FUNCTION osag_ip.getnet (p_ip bigint, p_mask bigint) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_ip.ip2num (p_string text) RETURNS bigint AS $body$
DECLARE

        v_byte_no 	bigint			:= 0;
        v_byte_start 	bigint			:= 0;
        v_byte_length 	bigint			:= 0;
        v_byte_string 	varchar(32);
        v_result 	bigint			:= 0;
        c_prefix 	CONSTANT varchar(64)	:= 'OSAG_IP.ip2num(): ';

BEGIN
        if p_string is null then
          return null;
        end if;
        FOR v_byte_no IN 1..4 LOOP



                IF (v_byte_no > 1) THEN
                    v_byte_start := INSTR(p_string,'.',1,v_byte_no-1)+1;
                    IF (v_byte_start < 2) THEN
                        plog.debug(c_prefix||'not enough dots in ip address [pos1]: '||p_string);
                        RETURN NULL;
                    END IF;
                ELSE
                    v_byte_start := 1;
                END IF;



                IF (v_byte_no < 4) THEN
                    v_byte_length := INSTR(p_string,'.',1,v_byte_no) - v_byte_start;
                ELSE
                    v_byte_length := LENGTH(p_string) - INSTR(p_string,'.',1,3);
                END IF;
                IF (v_byte_start < 1) THEN
                    plog.debug(c_prefix||'not enough dots in ip address [pos2]: '||p_string);
                    RETURN NULL;
                END IF;


                

                v_byte_string := substr(p_string,v_byte_start,v_byte_length);

                IF ((v_byte_string)::numeric ::text != v_byte_string) THEN
                    plog.debug(c_prefix||'invalid byte 1 in ip address: '||p_string);
                    RETURN NULL;
                END IF;
                IF ((v_byte_string)::numeric  > 255) THEN
                    plog.debug(c_prefix||'number too big in byte '||v_byte_no||' in ip address: '||p_string);
                    RETURn NULL;
                END IF;



                v_result := v_result * 256 + (v_byte_string)::numeric;
            END LOOP;
        RETURN v_result;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
 IMMUTABLE;
-- REVOKE ALL ON FUNCTION osag_ip.ip2num (p_string text) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_ip.num2ip (p_number bigint) RETURNS varchar AS $body$
DECLARE

        v_byte 		bigint			:= NULL;
        v_reminder 	bigint			:= NULL;
        v_result 	varchar(15)		:= NULL;
        c_prefix 	CONSTANT varchar(64)	:= 'OSAG_IP.num2ip(): ';

BEGIN
        if p_number is null or p_number < 0 then
          return null;
        end if;
        v_byte := date_trunc('day', p_number/16777216);
        IF (v_byte > 255) THEN
            plog.debug(c_prefix||'invalid byte 1 in ip address: '||v_byte);
            RETURn NULL;
        END IF;
        v_reminder := p_number - v_byte * 16777216;
        v_result := v_byte::text;

        v_byte := date_trunc('day', v_reminder/65536);
        IF (v_byte > 255) THEN
            plog.debug(c_prefix||'invalid byte 2 in ip address: '||v_byte);
            RETURn NULL;
        END IF;
        v_reminder := v_reminder - v_byte * 65536;
        v_result := v_result || '.' || v_byte::text;

        v_byte := date_trunc('day', v_reminder/256);
        IF (v_byte > 255) THEN
            plog.debug(c_prefix||'invalid byte 3 in ip address: '||v_byte);
            RETURn NULL;
        END IF;
        v_reminder := v_reminder - v_byte * 256;
        v_result := v_result || '.' || v_byte::text || '.' || v_reminder;
        RETURN v_result;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
 IMMUTABLE;
-- REVOKE ALL ON FUNCTION osag_ip.num2ip (p_number bigint) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_ip.ipv6pad0 (p_ip text) RETURNS varchar AS $body$
DECLARE

      v_colons_pos integer;
      v_groups integer;
      v_pad varchar(64);
      v_res varchar(64);

BEGIN
      v_colons_pos := position('::' in p_ip);
      if v_colons_pos = 0 then
        return p_ip;
      end if;
      if p_ip = '::' then
        return '0:0:0:0:0:0:0:0';
      end if;


      v_groups := length(p_ip) - coalesce(length(replace(p_ip, ':', '')), 0);

      
      if v_colons_pos = 1 or v_colons_pos = length(p_ip)-1 then
        v_groups := v_groups - 1;
      end if;

      if v_groups >= 8 then
        
        
        
        return replace(p_ip, '::', ':');
      end if;


      v_pad := LPAD(':0', 2*(8-v_groups), ':0') ||':';
      v_res := replace(p_ip, '::', v_pad);


      if v_res like ':%' then
        v_res := substr(v_res, 2);
      end if;
      if v_res like '%:' then
        v_res := substr(v_res, 1, length(v_res)-1);
      end if;
      return v_res;
    end;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
 IMMUTABLE;
-- REVOKE ALL ON FUNCTION osag_ip.ipv6pad0 (p_ip text) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_ip.ipv6left (p_ip text) RETURNS integer AS $body$
DECLARE

      v_ip varchar(64);
      v_beg integer;
      v_end integer;
      v_grp varchar(64);
      v_left integer;

BEGIN
      v_ip := osag_ip.ipv6pad0(p_ip);
      v_left := 0;
      v_end := 0;


      for v_i in 1..4 loop
          v_beg := v_end+1;
          v_end := instr(v_ip, ':', v_beg);
          v_grp := substr(v_ip, v_beg, v_end-v_beg);

          v_left := v_left * 65536;
          v_left := v_left + to_number(v_grp, 'xxxx');
        end loop;

      return v_left;
    end;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
 IMMUTABLE;
-- REVOKE ALL ON FUNCTION osag_ip.ipv6left (p_ip text) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_ip.ipv6right (p_ip text) RETURNS integer AS $body$
DECLARE

      v_ip varchar(64);
      v_beg integer;
      v_end integer;
      v_grp varchar(64);
      v_right integer;

BEGIN
      v_ip := osag_ip.ipv6pad0(p_ip);
      v_right := 0;
      v_end := instr(v_ip, ':', 1, 4);


      for v_i in 1..4 loop
          v_beg := v_end+1;
          v_end := instr(v_ip, ':', v_beg);
          if v_end = 0 then
            v_end := length(v_ip)+1;
          end if;
          v_grp := substr(v_ip, v_beg, v_end-v_beg);

          v_right := v_right * 65536;
          v_right := v_right + to_number(v_grp, 'xxxx');
        end loop;

      return v_right;
    end;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
 IMMUTABLE;
-- REVOKE ALL ON FUNCTION osag_ip.ipv6right (p_ip text) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_ip.ipv6shorten (p_ip text) RETURNS varchar AS $body$
DECLARE

      v_start integer;
      v_end integer;
      v_j integer;
      v_len integer;
      v_ip varchar(64);
      v_res varchar(64);

BEGIN
      v_start := 255;
      v_end := 255;
      v_ip := p_ip || ':';
      for v_i in 1..(length(v_ip) - 1) loop
          
          if substr(v_ip, v_i, 1) != ':' then
            continue;
          end if;
          v_j := v_i + 1;
          while v_j < length(v_ip) and (substr(v_ip, v_j, 1) = '0' or substr(v_ip, v_j, 1) = ':') loop
              v_j := v_j + 1;
            end loop;

          while v_j >= v_i and substr(v_ip, v_j, 1) != ':' loop
              v_j := v_j - 1;
            end loop;
          v_len := v_j - v_i;
          if v_len > 3 and v_len > (v_end - v_start) then
            v_start := v_i;
            v_end := v_j;
          end if;
        end loop;

      v_res := v_ip;
      if (v_end - v_start) > 0 then
        v_res := substr(v_ip, 1, v_start) || substr(v_ip, v_end);
      end if;


      if v_res like '%:' and v_res not like '%::' then
        v_res := substr(v_res, 1, length(v_res)-1);
      end if;


      if v_res like '0::%' then
        v_res := substr(v_res, 2);
      end if;

      return v_res;
    end;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
 IMMUTABLE;
-- REVOKE ALL ON FUNCTION osag_ip.ipv6shorten (p_ip text) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_ip.num2ipv6 (p_left integer, p_right integer) RETURNS varchar AS $body$
DECLARE

      v_n integer;
      v_grp integer;
      v_res varchar(64);

BEGIN
      v_res := '';

      v_n := p_right;
      for v_i in 1..4 loop
          v_grp := mod(v_n, 65536;)
          v_n := (v_n - v_grp) / 65536;
          v_res := trim(both to_char(v_grp, 'xxxx')) ||':'|| v_res;
        end loop;

      v_n := p_left;
      for v_i in 1..4 loop
          v_grp := mod(v_n, 65536;)
          v_n := (v_n - v_grp) / 65536;
          v_res := trim(both to_char(v_grp, 'xxxx')) ||':'|| v_res;
        end loop;


      v_res := substr(v_res, 1, length(v_res)-1);
      v_res := osag_ip.ipv6shorten(v_res);
      return v_res;
    end;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
 IMMUTABLE;
-- REVOKE ALL ON FUNCTION osag_ip.num2ipv6 (p_left integer, p_right integer) FROM PUBLIC;
