DROP SCHEMA IF EXISTS osag_isp_monitoring CASCADE;
CREATE SCHEMA IF NOT EXISTS osag_isp_monitoring;





CREATE OR REPLACE FUNCTION osag_isp_monitoring.unixts_to_date (unixts integer) RETURNS timestamp(0) AS $body$
DECLARE


    
    unix_epoch timestamp(0) := to_date('19700101000000','YYYYMMDDHH24MISS');
    max_ts integer := 2145916799;
    min_ts integer := -2114380800;
    oracle_date timestamp(0);
    oracle_date_local timestamp(0);

BEGIN
    IF unixts > max_ts THEN
      RAISE EXCEPTION '%', 'UNIX timestamp too large for 32 bit limit'
         USING ERRCODE = '45901';
    ELSIF unixts < min_ts THEN
      RAISE EXCEPTION '%', 'UNIX timestamp too small for 32 bit limit'  USING ERRCODE = '45901';
    ELSE

      oracle_date := unix_epoch + (unixts * ('1'||'SECOND')::interval);
    END IF;


    oracle_date_local := CAST(
    (oracle_date AT TIME ZONE 'UTC')::timestamp with time zone
      AT LOCAL
      AS timestamp(0) );

    RETURN(oracle_date_local);
  END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
 STABLE;
-- REVOKE ALL ON FUNCTION osag_isp_monitoring.unixts_to_date (unixts integer) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_isp_monitoring.update_isp_link_status ( p_isp_link_id mc.isp_link_history.isp_link_id%type, p_status mc.isp_link_status_type.id%type, p_previous_status mc.isp_link_status_type.id%type, p_change_timestamp integer, p_reported_by mc.isp_link_history.reporting_host_id%type ) AS $body$
BEGIN
    plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
    CALL osag_isp_monitoring.update_isp_link_status2( p_isp_link_id,
                             p_status,
                             p_previous_status,
                             p_reported_by );

  END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_isp_monitoring.update_isp_link_status ( p_isp_link_id mc.isp_link_history.isp_link_id%type, p_status mc.isp_link_status_type.id%type, p_previous_status mc.isp_link_status_type.id%type, p_change_timestamp integer, p_reported_by mc.isp_link_history.reporting_host_id%type ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_isp_monitoring.update_isp_link_status2 ( p_isp_link_id mc.isp_link_history.isp_link_id%type, p_status mc.isp_link_status_type.id%type, p_previous_status mc.isp_link_status_type.id%type, p_reported_by mc.isp_link_history.reporting_host_id%type ) AS $body$
DECLARE


    v_previous_status mc.isp_link_status_type.id%type;
    v_change_date     mc.isp_link_history.change_date%type;
    v_event_id        mc.isp_link_history.event_id%type;
    v_isp_count       bigint;


BEGIN
    plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
    SELECT count(*) INTO STRICT v_isp_count
    FROM mss.isp_link
    WHERE id = p_isp_link_id;

    IF ( v_isp_count > 0 ) THEN
      SELECT isp_link_status_type_id
      INTO STRICT v_previous_status
      FROM mss.isp_link
      WHERE id = p_isp_link_id;



      v_event_id := NULL;

      IF ( v_previous_status IS NULL ) THEN
        v_previous_status := 1;
      END IF;


      
      
      IF ( v_previous_status != p_status ) THEN

        
        IF ( v_previous_status != p_previous_status
          AND p_previous_status != 0
          AND p_previous_status != 1 ) THEN
          
          
          
          plog.warning('UNEXPECTED ISP status reported as previous status: ' ||p_previous_status
            ||'. The stored status for ISP '||p_isp_link_id||' in the db is: '||v_previous_status
            ||'. Will write change from status '||v_previous_status
            ||' to '||p_status||'.');
        END IF;


        INSERT INTO mc.isp_link_history(
          id,
          isp_link_id,
          reporting_host_id,
          old_isp_link_status_type_id,
          new_isp_link_status_type_id,
          change_date,
          event_id)
        VALUES (nextval('isp_link_history_seq'),
                p_isp_link_id,
                p_reported_by,
                v_previous_status,
                p_status,
                clock_timestamp(),
                v_event_id);


        UPDATE mss.isp_link
        SET mss.isp_link.isp_link_status_type_id = p_status
        WHERE mss.isp_link.id                      = p_isp_link_id;

      END IF;
    END IF;

  EXCEPTION
    WHEN no_data_found THEN


      
      INSERT INTO mc.isp_link_history(
        id,
        isp_link_id,
        reporting_host_id,
        old_isp_link_status_type_id,
        new_isp_link_status_type_id,
        change_date,
        event_id)
      VALUES (nextval('isp_link_history_seq'),
              p_isp_link_id,
              p_reported_by,
              v_previous_status,
              p_status,
              clock_timestamp(),
              v_event_id);


      UPDATE mss.isp_link
      SET isp_link_status_type_id = p_status
      WHERE id                      = p_isp_link_id;

  END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_isp_monitoring.update_isp_link_status2 ( p_isp_link_id mc.isp_link_history.isp_link_id%type, p_status mc.isp_link_status_type.id%type, p_previous_status mc.isp_link_status_type.id%type, p_reported_by mc.isp_link_history.reporting_host_id%type ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_isp_monitoring.update_capacity_measurements ( p_isp_link_id mss.isp_link.id%type, p_download mss.isp_link.measured_download%type, p_upload mss.isp_link.measured_upload%type, p_interface_id mss.isp_link.usage_interface_id%type ) AS $body$
DECLARE

    v_interface_count  bigint;


BEGIN
    plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
    SELECT count(*) INTO STRICT v_interface_count
    FROM mss.interface
    WHERE id = p_interface_id;

    IF ( v_interface_count > 0 ) THEN

      UPDATE mss.isp_link
      SET measured_download  = p_download,
          measured_upload    = p_upload,
          usage_interface_id = p_interface_id
      WHERE id                 = p_isp_link_id;

    END IF;

  EXCEPTION WHEN OTHERS THEN

    plog.err('mc.osag_isp_monitoring.update_capacity_measurements(): Failed to update link ' || p_isp_link_id || ' using interface ' ||
             p_interface_id || '. Error: ' || sqlerrm);

  END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_isp_monitoring.update_capacity_measurements ( p_isp_link_id mss.isp_link.id%type, p_download mss.isp_link.measured_download%type, p_upload mss.isp_link.measured_upload%type, p_interface_id mss.isp_link.usage_interface_id%type ) FROM PUBLIC;
