DROP SCHEMA IF EXISTS osag_maintsync CASCADE;
CREATE SCHEMA IF NOT EXISTS osag_maintsync;





CREATE OR REPLACE PROCEDURE osag_maintsync.update_host_maint_status () AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'osag_maintsync.update_host_maint_status(): ';


        
        
        c_maint_status_changed CURSOR FOR
            
            SELECT h.id as host_id,
                   CASE WHEN h.active = 0 THEN 3
                        WHEN sw.ticket_id IS NULL THEN 2
                        ELSE 4
                       END as maintenance_status_new,
                   h.maintenance_status_id as maintenance_status_old,
                   sw.ticket_id as ticket_id
            FROM mss.host h
LEFT OUTER JOIN (SELECT max(t.id) AS ticket_id, h2s.host_id

                  FROM tt.ticket t
                           INNER JOIN tt.service_window s
                                      ON (s.ticket_id = t.id)
                           INNER JOIN tt.host2service_window h2s
                                      ON (h2s.service_window_id = s.id)

                           LEFT JOIN tt.maintenance_window m
                                     ON (s.id = m.service_window_id)
                           LEFT JOIN tt.cust_maintenance_window cm
                                     ON (s.id = cm.service_window_id)

                  WHERE
                          t.status_id < 101 AND s.end_date > statement_timestamp() AND s.start_date < statement_timestamp()
                    AND (m.disable_conn_escalation = 1 OR m.disable_events = 1 OR cm.disable_conn_escalation = 1 OR cm.disable_events = 1) 
                  GROUP BY h2s.host_id) sw ON (h.id = sw.host_id)
WHERE h.operating_system_id != 21 AND (h.maintenance_status_id IS NULL OR (h.active = 0 AND h.maintenance_status_id != 3) OR (sw.ticket_id IS NULL AND h.active = 1 AND h.maintenance_status_id != 2) OR (sw.ticket_id IS NOT NULL AND h.active = 1 AND h.maintenance_status_id != 4))
                FOR UPDATE OF h.maintenance_status_id;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        FOR r_maint_status_changed IN c_maint_status_changed
            LOOP

                INSERT INTO mc.host_maintenance_history(id, host_id, change_date, new_maintenance_status_id, old_maintenance_status_id, ticket_id)
                VALUES (nextval('host_maint_history_seq'), r_maint_status_changed.host_id, statement_timestamp(), r_maint_status_changed.maintenance_status_new,
                        coalesce(r_maint_status_changed.maintenance_status_old, 1), r_maint_status_changed.ticket_id);

                UPDATE mss.host h SET h.maintenance_status_id = r_maint_status_changed.maintenance_status_new WHERE h.id = r_maint_status_changed.host_id;

            END LOOP;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_maintsync.update_host_maint_status () FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_maintsync.update_isp_link_maint_status () AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'osag_maintsync.update_isp_link_maint_status(): ';


        
        c_maint_status_changed CURSOR FOR
            
            SELECT l.id AS isp_link_id,
                   CASE WHEN hosts.host_active = 0 THEN 3
                        WHEN sw.ticket_id IS NULL THEN 2
                        ELSE 4
                       END as maintenance_status_new,
                   l.maintenance_status_id as maintenance_status_old,
                   sw.ticket_id as ticket_id
            FROM (SELECT MAX(h.active) as host_active, i2l_a.isp_link_id as isp_link_id FROM mss.host h, mss.interface i_a, mss.interface2isp_link i2l_a
                   WHERE h.id = i_a.host_id and i2l_a.interface_id = i_a.id group by i2l_a.isp_link_id) hosts, mss.isp_link l
LEFT OUTER JOIN (SELECT max(t.id) as ticket_id, i2l.isp_link_id

                   FROM tt.ticket t
                            INNER JOIN tt.service_window s
                                       ON (s.ticket_id = t.id)
                            INNER JOIN tt.host2service_window h2s
                                       ON (h2s.service_window_id = s.id)
                            INNER JOIN mss.interface i
                                       ON (h2s.host_id = i.host_id)
                            INNER JOIN mss.interface2isp_link i2l
                                       ON (i.id = i2l.interface_id)

                            LEFT JOIN tt.maintenance_window m
                                      ON (s.id = m.service_window_id)
                            LEFT JOIN tt.cust_maintenance_window cm
                                      ON (s.id = cm.service_window_id)

                   WHERE
                           t.status_id < 101 AND s.end_date > statement_timestamp() AND s.start_date < statement_timestamp()
                     AND (m.disable_conn_escalation = 1 OR m.disable_events = 1 OR cm.disable_conn_escalation = 1 OR cm.disable_events = 1) 
                   GROUP BY i2l.isp_link_id) sw ON (l.id = sw.isp_link_id)
WHERE l.id = hosts.isp_link_id  AND (l.maintenance_status_id IS NULL or l.maintenance_status_id = 1 OR (hosts.host_active = 0 AND l.maintenance_status_id != 3) OR (sw.ticket_id IS NULL AND hosts.host_active = 1 AND l.maintenance_status_id != 2) OR (sw.ticket_id IS NOT NULL AND hosts.host_active = 1 AND l.maintenance_status_id != 4))
                FOR UPDATE OF l.maintenance_status_id;


        
        c_maint_status_obsolete CURSOR FOR

            SELECT l.id AS isp_link_id,
                   l.maintenance_status_id as maintenance_status_old
            FROM mss.isp_link l
            WHERE (l.maintenance_status_id != 1 OR l.maintenance_status_id IS NULL) AND NOT EXISTS (SELECT 1 FROM mss.interface2isp_link i2l WHERE i2l.isp_link_id = l.id)
                FOR UPDATE OF l.maintenance_status_id;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        FOR r_maint_status_changed IN c_maint_status_changed
            LOOP

                plog.notice('updating status for link ' || r_maint_status_changed.isp_link_id
                    || ': new status is ' || r_maint_status_changed.maintenance_status_new
                    || ': old status is ' || r_maint_status_changed.maintenance_status_old);

                INSERT INTO mc.isp_link_maintenance_history(id, isp_link_id, change_date, new_maintenance_status_id, old_maintenance_status_id, ticket_id)
                VALUES (nextval('isp_link_maint_history_seq'), r_maint_status_changed.isp_link_id, statement_timestamp(), r_maint_status_changed.maintenance_status_new,
                        coalesce(r_maint_status_changed.maintenance_status_old, 1), r_maint_status_changed.ticket_id);

                UPDATE mss.isp_link l SET l.maintenance_status_id = r_maint_status_changed.maintenance_status_new WHERE l.id = r_maint_status_changed.isp_link_id;

            END LOOP;


        FOR r_maint_status_obsolete IN c_maint_status_obsolete
            LOOP

                INSERT INTO mc.isp_link_maintenance_history(id, isp_link_id, change_date, new_maintenance_status_id, old_maintenance_status_id)
                VALUES (nextval('isp_link_maint_history_seq'), r_maint_status_obsolete.isp_link_id, statement_timestamp(), 1, coalesce(r_maint_status_obsolete.maintenance_status_old,1));

                UPDATE mss.isp_link l SET l.maintenance_status_id = 1 WHERE l.id =r_maint_status_obsolete.isp_link_id;

            END LOOP;


    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_maintsync.update_isp_link_maint_status () FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_maintsync.update_single_host (p_host_id MSS.HOST.ID%TYPE) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(32) := 'osag_maintsync.update_single_host(): ';

        v_current_status MC.MAINTENANCE_STATUS.ID%TYPE;
        v_old_status MC.MAINTENANCE_STATUS.ID%TYPE;
        v_maint_ticket TT.TICKET.ID%TYPE;

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        SELECT CASE WHEN h.active = 0 THEN 3
                    WHEN sw.ticket_id IS NULL THEN 2
                    ELSE 4
                   END as maintenance_status_new,
               h.maintenance_status_id as maintenance_status_old,
               sw.ticket_id
        INTO STRICT v_current_status, v_old_status, v_maint_ticket
        FROM mss.host h
LEFT OUTER JOIN (SELECT max(t.id) AS ticket_id, h2s.host_id

              FROM tt.ticket t
                       INNER JOIN tt.service_window s
                                  ON (s.ticket_id = t.id)
                       INNER JOIN tt.host2service_window h2s
                                  ON (h2s.service_window_id = s.id)

                       LEFT JOIN tt.maintenance_window m
                                 ON (s.id = m.service_window_id)
                       LEFT JOIN tt.cust_maintenance_window cm
                                 ON (s.id = cm.service_window_id)

              WHERE
                      t.status_id < 101 AND s.end_date > statement_timestamp() AND s.start_date < statement_timestamp()
                AND (m.disable_conn_escalation = 1 OR m.disable_events = 1 OR cm.disable_conn_escalation = 1 OR cm.disable_events = 1) 
              GROUP BY h2s.host_id) sw ON (h.id = sw.host_id)
WHERE h.id = p_host_id  and h.operating_system_id != 21 AND (h.maintenance_status_id IS NULL OR (h.active = 0 AND h.maintenance_status_id != 3) OR (sw.ticket_id IS NULL AND h.active = 1 AND h.maintenance_status_id != 2) OR (sw.ticket_id IS NOT NULL AND h.active = 1 AND h.maintenance_status_id != 4));

        IF (v_current_status != v_old_status OR v_old_status IS NULL) THEN

            INSERT INTO mc.host_maintenance_history(id, host_id, change_date, new_maintenance_status_id, old_maintenance_status_id, ticket_id)
            VALUES (nextval('host_maint_history_seq'), p_host_id, statement_timestamp(), v_current_status,
                    coalesce(v_old_status, 1), v_maint_ticket);

            UPDATE mss.host h SET h.maintenance_status_id = v_current_status WHERE h.id = p_host_id;

        END IF;


    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_maintsync.update_single_host (p_host_id MSS.HOST.ID%TYPE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_maintsync.update_single_isp_link (p_isp_link_id MSS.ISP_LINK.ID%TYPE) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(32) := 'osag_maintsync.update_single_isp_link(): ';

        v_current_status MC.MAINTENANCE_STATUS.ID%TYPE;
        v_old_status MC.MAINTENANCE_STATUS.ID%TYPE;
        v_maint_ticket TT.TICKET.ID%TYPE;

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        SELECT l.maintenance_status_id INTO STRICT v_old_status FROM mss.isp_link l WHERE l.id = p_isp_link_id;

        BEGIN
            SELECT CASE WHEN hosts.host_active = 0 THEN 3
                        WHEN sw.ticket_id IS NULL THEN 2
                        ELSE 4
                       END as maintenance_status_new,
                   sw.ticket_id
            INTO STRICT v_current_status, v_maint_ticket
            FROM (SELECT MAX(h.active) as host_active, i2l_a.isp_link_id as isp_link_id FROM mss.host h, mss.interface i_a, mss.interface2isp_link i2l_a
                   WHERE h.id = i_a.host_id and i2l_a.interface_id = i_a.id group by i2l_a.isp_link_id) hosts, mss.isp_link l
LEFT OUTER JOIN (SELECT max(t.id) as ticket_id, i2l.isp_link_id

                   FROM tt.ticket t
                            INNER JOIN tt.service_window s
                                       ON (s.ticket_id = t.id)
                            INNER JOIN tt.host2service_window h2s
                                       ON (h2s.service_window_id = s.id)
                            INNER JOIN mss.interface i
                                       ON (h2s.host_id = i.host_id)
                            INNER JOIN mss.interface2isp_link i2l
                                       ON (i.id = i2l.interface_id)

                            LEFT JOIN tt.maintenance_window m
                                      ON (s.id = m.service_window_id)
                            LEFT JOIN tt.cust_maintenance_window cm
                                      ON (s.id = cm.service_window_id)

                   WHERE
                           t.status_id < 101 AND s.end_date > statement_timestamp() AND s.start_date < statement_timestamp()
                     AND (m.disable_conn_escalation = 1 OR m.disable_events = 1 OR cm.disable_conn_escalation = 1 OR cm.disable_events = 1)
                   GROUP BY i2l.isp_link_id) sw ON (l.id = sw.isp_link_id)
WHERE l.id = hosts.isp_link_id  AND (l.maintenance_status_id  IS NULL or l.maintenance_status_id = 1 OR (hosts.host_active = 0 AND l.maintenance_status_id != 3) OR (sw.ticket_id IS NULL AND hosts.host_active = 1 AND l.maintenance_status_id != 2) OR (sw.ticket_id IS NOT NULL AND hosts.host_active = 1 AND l.maintenance_status_id != 4));

        EXCEPTION
            WHEN no_data_found THEN

                
                v_current_status := 1;
                v_maint_ticket := NULL;
        END;

        IF (v_old_status != v_current_status OR v_old_status IS NULL) THEN
            INSERT INTO mc.isp_link_maintenance_history(id, isp_link_id, change_date, new_maintenance_status_id, old_maintenance_status_id, ticket_id)
            VALUES (nextval('isp_link_maint_history_seq'), p_isp_link_id, statement_timestamp(), v_current_status, coalesce(v_old_status, 1), v_maint_ticket);

            UPDATE mss.isp_link l SET l.maintenance_status_id = v_current_status WHERE l.id = p_isp_link_id;
        END IF;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(S_PREFIX||'caught exception: '||sqlerrm);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_maintsync.update_single_isp_link (p_isp_link_id MSS.ISP_LINK.ID%TYPE) FROM PUBLIC;
