-- Oracle package 'OSAG_MSG' declaration, please edit to match PostgreSQL syntax.

DROP SCHEMA IF EXISTS osag_msg CASCADE;
CREATE SCHEMA IF NOT EXISTS osag_msg;
CREATE DOMAIN OSAG_MSG.smtp_header_name_t AS varchar(64);
CREATE DOMAIN OSAG_MSG.smtp_header_value_t AS varchar(256);
CREATE TYPE osag_msg.smtp_header_t AS (
h_name OSAG_MSG.smtp_header_name_t, h_value OSAG_MSG.smtp_header_value_t
);

CREATE TYPE osag_msg.smtp_headers_t AS (smtp_headers_t OSAG_MSG.smtp_header_t[]);






CREATE OR REPLACE PROCEDURE osag_msg.send_mail (p_reply_to text, p_from text, p_mail_from text, p_recipient text, p_subject text, p_body text, p_opt_headers smtp_headers_t DEFAULT NULL) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64)    := 'OSAG.OSAG_MSG.send_mail(): ';
        S_SMTP_PORT CONSTANT integer  := 25;

        S_SMTP_HOST CONSTANT varchar(32) := 'localhost';
        CRLF CONSTANT varchar(2)          := CHR(13)||CHR(10);

        mail_conn UTL_SMTP.connection;
        l_rfc822_reply_to varchar(128);
        l_rfc822_mail_from varchar(128);
        l_rfc822_recipient varchar(128);
        l_message varchar(32767);
        l_opt_header smtp_header_t;
        S_SMTP_HELO varchar(32);

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        select host_name into STRICT S_SMTP_HELO from v$instance;
        l_rfc822_reply_to := REGEXP_REPLACE(p_reply_to, '^([^\<])(.*)([^\>]$)', '<\1\2\3>', 'g');
        l_rfc822_recipient := REGEXP_REPLACE(p_recipient, '^([^\<])(.*)([^\>]$)', '<\1\2\3>', 'g');
        l_rfc822_mail_from := REGEXP_REPLACE(p_mail_from, '^([^\<])(.*)([^\>]$)', '<\1\2\3>', 'g');

        plog.debug(S_PREFIX||'from: '''||coalesce(l_rfc822_mail_from,l_rfc822_reply_to)||''', recipient: '''||l_rfc822_recipient||''', subject: '''||p_subject||'''');


        IF (p_opt_headers IS NOT NULL AND p_opt_headers.count > 0) THEN
            FOR l_row IN p_opt_headers.first .. p_opt_headers.last LOOP
                    l_opt_header := p_opt_headers(l_row);
                    l_message := l_message||l_opt_header.h_name;

                    l_message := l_message||': '||l_opt_header.h_value||CRLF;
                END LOOP;
        END IF;

        l_message := l_message||
                     'Date: '||TO_CHAR(statement_timestamp(), 'Dy, dd Mon YYYY HH24:MI:SS TZHTZM')||CRLF||
                     'From: '||coalesce(p_from, p_reply_to)||CRLF||
                     'Reply-To: '||p_reply_to||CRLF||
                     'To: '||l_rfc822_recipient||CRLF||
                     'Subject: '||p_subject||CRLF||CRLF||
                     p_body;


        l_message := REGEXP_REPLACE(l_message, '^\.', '..', 1, 0, 'm', 'g');

        mail_conn := UTL_SMTP.OPEN_CONNECTION(S_SMTP_HOST, S_SMTP_PORT);
        UTL_SMTP.HELO(mail_conn, S_SMTP_HELO);
        UTL_SMTP.MAIL(mail_conn, coalesce(l_rfc822_mail_from,l_rfc822_reply_to));
        UTL_SMTP.RCPT(mail_conn, l_rfc822_recipient);
        UTL_SMTP.DATA(mail_conn, l_message);
        UTL_SMTP.QUIT(mail_conn);

        plog.notice(S_PREFIX||'sent mail from '''||coalesce(l_rfc822_mail_from,l_rfc822_reply_to)||''' to '''||l_rfc822_recipient||''' subject: '''||p_subject||'''');

    EXCEPTION
        WHEN OTHERS THEN
            RAISE NOTICE '%exception: %: %', S_PREFIX, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, sqlerrm;
            plog.err(S_PREFIX||'send mail to '''||l_rfc822_recipient||''' failed: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE||': '||sqlerrm);
            BEGIN
              UTL_SMTP.CLOSE_CONNECTION(mail_conn);
            EXCEPTION
              when others then
                null;
            END;
            RAISE;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_msg.send_mail (p_reply_to text, p_from text, p_mail_from text, p_recipient text, p_subject text, p_body text, p_opt_headers smtp_headers_t DEFAULT NULL) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_msg.send_sms (p_sms_no text, p_body text) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64)          := 'OSAG.OSAG_MSG.send_sms(): ';

        S_EMAIL_REPLY_TO CONSTANT varchar(32)  := 'support@open.ch';
        S_SMS_DOMAIN CONSTANT varchar(32)      := 'mx-sms.open.ch';

        l_sms_no varchar(32);


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        l_sms_no := REPLACE(p_sms_no, ' ', '');
        CALL osag_msg.send_mail(S_EMAIL_REPLY_TO, NULL, NULL, l_sms_no||'@'||S_SMS_DOMAIN, '', p_body);

        plog.notice(S_PREFIX||'sent SMS to '''||l_sms_no||''' subject: '''||p_body||'''');

    EXCEPTION
        WHEN OTHERS THEN
            RAISE NOTICE '%exception: %: %', S_PREFIX, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, sqlerrm;
            plog.err(S_PREFIX||'sending SMS to '''||l_sms_no||''' failed: '||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE||': '||sqlerrm);
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_msg.send_sms (p_sms_no text, p_body text) FROM PUBLIC;
-- End of Oracle package 'OSAG_MSG' declaration



-- Oracle package 'OSAG_NIDS' declaration, please edit to match PostgreSQL syntax.

DROP SCHEMA IF EXISTS osag_nids CASCADE;
CREATE SCHEMA IF NOT EXISTS osag_nids;






CREATE OR REPLACE FUNCTION osag_nids.get_signature ( i_signature_gid signature.gid%TYPE, i_signature_sid signature.sid%TYPE) RETURNS SIGNATURE AS $body$
DECLARE

        l_signature signature%ROWTYPE;

BEGIN
        SELECT * INTO STRICT l_signature FROM signature
        WHERE gid = i_signature_gid AND sid = i_signature_sid;
        RETURN l_signature;
    EXCEPTION
        WHEN no_data_found THEN

            IF i_signature_gid = 501 OR i_signature_gid = 502 THEN RETURN NULL;
            ELSE RAISE EXCEPTION 'e_sig_not_found' USING ERRCODE = '50023';
            END IF;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION osag_nids.get_signature ( i_signature_gid signature.gid%TYPE, i_signature_sid signature.sid%TYPE) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_nids.get_signature_class_name (i_signature_class_id signature_class.id%TYPE) RETURNS SIGNATURE_CLASS.NAME%TYPE AS $body$
DECLARE

        l_name signature_class.name%TYPE;

BEGIN
        SELECT name INTO STRICT l_name FROM signature_class
        WHERE id = i_signature_class_id;
        RETURN l_name;
    EXCEPTION
        WHEN no_data_found THEN RETURN 'unknown';
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION osag_nids.get_signature_class_name (i_signature_class_id signature_class.id%TYPE) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_nids.get_sensor_host_id ( i_sensor_name text, i_sender_host_id mss.host.id%TYPE) RETURNS MSS.HOST.ID%TYPE AS $body$
DECLARE

        l_sensor_host_id     mss.host.id%TYPE;

BEGIN
        SELECT id INTO STRICT l_sensor_host_id FROM mss.host
        WHERE mss.host.name = i_sensor_name AND
                mss.host.service_company_id IN (SELECT service_company_id FROM mss.host WHERE id = i_sender_host_id);
        RETURN l_sensor_host_id;
    EXCEPTION
        WHEN no_data_found THEN RAISE EXCEPTION 'e_sensor_id_not_found' USING ERRCODE = '50024';
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION osag_nids.get_sensor_host_id ( i_sensor_name text, i_sender_host_id mss.host.id%TYPE) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_nids.get_direction_name (i_direction_id direction.id%TYPE) RETURNS DIRECTION.NAME%TYPE AS $body$
DECLARE

        l_direction_name     direction.name%TYPE;

BEGIN
        SELECT name INTO STRICT l_direction_name FROM direction
        WHERE id = i_direction_id;
        RETURN l_direction_name;
    EXCEPTION
        WHEN no_data_found THEN
            RETURN 'unknown';
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION osag_nids.get_direction_name (i_direction_id direction.id%TYPE) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_nids.ip_proto_to_string (i_protocol bigint) RETURNS varchar AS $body$
DECLARE

        l_protocol   varchar(64);

BEGIN
        IF i_protocol    IS NULL THEN  l_protocol := 'not available';
        ELSIF i_protocol =  1    THEN  l_protocol := 'ICMP';
        ELSIF i_protocol =  6    THEN  l_protocol := 'TCP';
        ELSIF i_protocol =  17   THEN  l_protocol := 'UDP';
        ELSIF i_protocol =  50   THEN  l_protocol := 'IPSEC ESP';
        ELSIF i_protocol =  51   THEN  l_protocol := 'IPSEC AH';
        ELSIF i_protocol =  89   THEN  l_protocol := 'OSPF';
        ELSE                           l_protocol := 'IP('||i_protocol||')';
        END IF;
        RETURN l_protocol;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION osag_nids.ip_proto_to_string (i_protocol bigint) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_nids.submit_msg_new ( i_log_date nids_event.log_date%TYPE, i_sensor_name text, i_sender_host_id nids_event.sender_host_id%TYPE, i_event_id nids_event.local_event_id%TYPE, i_tt_event_id OUT bigint, i_ticket_id bigint, i_signature_gid signature.gid%TYPE, i_signature_sid signature.sid%TYPE, i_signature_class text, i_suppressed nids_event.suppressed%TYPE, i_ip_source_address nids_event.ip_source_address%TYPE, i_ip_source_port nids_event.ip_source_port%TYPE, i_ip_destination_address nids_event.ip_destination_address%TYPE, i_ip_destination_port nids_event.ip_destination_port%TYPE, i_ip_protocol nids_event.ip_protocol%TYPE, i_direction_id nids_event.direction_id%TYPE, i_description text, i_escalation_level integer ) AS $body$
DECLARE


        C_PREFIX             CONSTANT varchar(64)   := 'OSAG_NIDS.submit_msg_new(): ';
        C_EVENT_TYPE_ID_NOTIFICATION CONSTANT bigint := 10014;
        C_EVENT_TYPE_ID_ESCALATION CONSTANT bigint   := 10002;

        l_signature          signature%ROWTYPE;
        l_description        signature.name%TYPE;
        l_signature_class    signature_class.NAME%TYPE;
        l_sensor_host_id     mss.host.id%TYPE;
        l_pubmsg             varchar(4000);
        l_privmsg            varchar(4000);
        l_tt_event_id        bigint := NULL;
        l_tt_ticket_id       bigint := NULL;
        l_event_type         bigint;
        l_ticket_status_id   tt.ticket.status_id%TYPE;
        l_new_ticket_id      tt.ticket.id%TYPE;
        l_disable_event_ticket_id bigint;
        l_collect_event_ticket_id bigint;
        l_active             mss.host.active%TYPE;

        subject              varchar(200);
        eventSubject         varchar(200);
        ticket_type_id       bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        l_signature         := osag_nids.get_signature(i_signature_gid, i_signature_sid);
        l_sensor_host_id    := osag_nids.get_sensor_host_id(i_sensor_name, i_sender_host_id);

        IF (i_description IS NULL) AND (l_signature.id IS NOT NULL) THEN
            l_description := l_signature.name;
        ELSE
            l_description := i_description;
        END IF;

        IF (l_signature.id IS NOT NULL) THEN
            l_signature_class := osag_nids.get_signature_class_name(l_signature.signature_class_id);
        ELSE
            l_signature_class := i_signature_class;
        END IF;


        
        
        l_pubmsg := l_description || chr(10) || chr(10);
        l_pubmsg := l_pubmsg || 'Date            : ' || TO_CHAR(i_log_date, 'YYYY-mm-dd HH24:MI:SSTZHTZM') || chr(10);
        l_pubmsg := l_pubmsg || 'Sensor          : ' || i_sensor_name || chr(10);
        l_pubmsg := l_pubmsg || 'Event Id        : ' || i_event_id || chr(10);
        l_pubmsg := l_pubmsg || 'Signature Id    : ';
        l_pubmsg := l_pubmsg || i_signature_gid || ':' || i_signature_sid || chr(10);
        l_pubmsg := l_pubmsg || 'Signature Name  : ' || l_description || chr(10);
        l_pubmsg := l_pubmsg || 'Signature Class : ' || l_signature_class || chr(10);
        l_pubmsg := l_pubmsg || 'Direction       : ' || osag_nids.get_direction_name(i_direction_id) || chr(10);
        l_pubmsg := l_pubmsg || 'Source          : ' || OSAG_IP.num2ip(i_ip_source_address);
        IF i_ip_source_port IS NOT NULL THEN
            l_pubmsg := l_pubmsg || ':' || i_ip_source_port;
        END IF;
        l_pubmsg := l_pubmsg || chr(10);
        l_pubmsg := l_pubmsg || 'Destination     : ' || OSAG_IP.num2ip(i_ip_destination_address);
        IF i_ip_destination_port IS NOT NULL THEN
            l_pubmsg := l_pubmsg || ':' || i_ip_destination_port;
        END IF;
        l_pubmsg := l_pubmsg || chr(10);
        l_pubmsg := l_pubmsg || 'Protocol        : ' || osag_nids.ip_proto_to_string(i_ip_protocol) || chr(10);
        l_pubmsg := l_pubmsg || 'Related Events  : ' ||
                    CASE WHEN i_suppressed IS NULL OR i_suppressed = 0 THEN 'none' ELSE i_suppressed || ' with same source and signature' END;

        l_privmsg := 'MCC: Proceed according to to the <a href="https://control.open.ch/docs/x/VQDS">NIDS Ticketing Howto</a>.';


        IF i_escalation_level = 2 THEN
            l_event_type := C_EVENT_TYPE_ID_ESCALATION;
        ELSE
            l_event_type := C_EVENT_TYPE_ID_NOTIFICATION;
        END IF;


        
        IF ( i_ticket_id IS NOT NULL AND i_ticket_id > 0 ) THEN
            l_tt_ticket_id := i_ticket_id;
        END IF;


        IF (i_sender_host_id is not null) THEN
            SELECT h.active INTO STRICT l_active FROM mss.host h WHERE h.id = i_sender_host_id;
            IF (l_active = 0) THEN
                plog.info(c_prefix||'dropping event of type '|| l_event_type ||' for inactive host '|| i_sender_host_id);
                RETURN;
            END IF;
        END IF;


        IF (i_sender_host_id is not null) THEN
            
            SELECT COUNT(*) INTO STRICT l_disable_event_ticket_id
            FROM tt.ticket t
                     INNER JOIN tt.service_window s
                                ON (s.ticket_id = t.id)
                     INNER JOIN tt.host2service_window h2s
                                ON (h2s.service_window_id = s.id)

                     LEFT JOIN tt.maintenance_window m
                               ON (s.id = m.service_window_id)
                     LEFT JOIN tt.cust_maintenance_window cm
                               ON (s.id = cm.service_window_id)

            WHERE
                    t.status_id < 101 AND s.end_date > statement_timestamp() AND s.start_date < statement_timestamp()
              AND (m.disable_events = 1 OR cm.disable_events = 1) AND h2s.host_id = i_sender_host_id;

            IF (l_disable_event_ticket_id > 0) THEN
                plog.info(c_prefix||'dropping event of type ' || l_event_type || ' for host ' || i_sender_host_id ||
                          '. Active service window with disable event flag on ticket ' || l_disable_event_ticket_id );
                RETURN;
            END IF;
        END IF;


        if (i_sender_host_id IS NOT NULL) THEN
            SELECT MAX(t.id) INTO STRICT l_collect_event_ticket_id

            FROM tt.ticket t
                     INNER JOIN tt.service_window s
                                ON (s.ticket_id = t.id)
                     INNER JOIN tt.host2service_window h2s
                                ON (h2s.service_window_id = s.id)

                     LEFT JOIN tt.maintenance_window m
                               ON (s.id = m.service_window_id)
                     LEFT JOIN tt.cust_maintenance_window cm
                               ON (s.id = cm.service_window_id)

            WHERE
                    t.status_id < 101 AND s.end_date > statement_timestamp() AND s.start_date < statement_timestamp()
              AND (m.collect_events = 1 OR cm.collect_events = 1) AND h2s.host_id = i_sender_host_id;

            IF (l_collect_event_ticket_id IS NOT NULL) THEN

                
                l_tt_ticket_id := l_collect_event_ticket_id;
                plog.info(c_prefix||'overwriting ticket id because open service window '
                    ||'requests event collection in ticket '||l_collect_event_ticket_id);
            END IF;
        END IF;

        IF ( l_tt_ticket_id IS NOT NULL AND l_tt_ticket_id > 0 ) THEN


            tt.CALL event_interface.addevent_new(
                    l_tt_event_id,
                    l_tt_ticket_id,
                    l_event_type,
                    l_sensor_host_id,
                    l_pubmsg,
                    l_privmsg,
                    NULL,
                    TRUE,
                    i_log_date);


            CALL tt.event_interface.exec_event_type_actions(l_tt_event_id);

        ELSE

            SELECT name INTO STRICT subject
            FROM tt.event_type
            WHERE id=l_event_type;

            ticket_type_id := tt.event_interface.ticket_type_for_event_type( l_event_type );

            eventSubject := SUBSTR(l_pubmsg, 1, 95 - length(subject));
            IF (position(CHR(10) in eventSubject) > 0) THEN
                eventSubject := SUBSTR(eventSubject, 1, position(CHR(10) in eventSubject) - 1);
            ELSIF (length(eventSubject) = (95 - length(subject))) THEN
                eventSubject := SUBSTR(eventSubject, 1, length(eventSubject) - 3) || '...';
            END IF;
            subject := subject || ': ' || eventSubject;

            tt.CALL ticket_interface.newticket_new(
                    l_tt_ticket_id,
                    l_tt_event_id,
                    ticket_type_id,
                    subject,
                    l_event_type,
                    l_sensor_host_id,
                    l_pubmsg,
                    l_privmsg,
                    NULL,
                    NULL, 
                    TRUE, 
                    i_log_date,
                    NULL 
                );
        END IF;


        i_tt_event_id := l_tt_event_id;



        INSERT INTO nids.nids_event(
            id, log_date, sensor_host_id, sender_host_id, local_event_id, signature_id, suppressed, ip_source_address,
            ip_source_port, ip_destination_address, ip_destination_port, ip_protocol, direction_id, tt_event_id)
        VALUES (
                   nextval('nidsevent_seq'), i_log_date, l_sensor_host_id, i_sender_host_id, i_event_id, l_signature.id,
                   i_suppressed, i_ip_source_address, i_ip_source_port, i_ip_destination_address, i_ip_destination_port,
                   i_ip_protocol, i_direction_id, l_tt_event_id);



    EXCEPTION
        WHEN SQLSTATE '50023' THEN
            plog.err(C_PREFIX||'no matching signature found for GID '||i_signature_gid||' and SID '||i_signature_sid ||' (sensor host: ' || i_sensor_name || ')');
        WHEN SQLSTATE '50024' THEN
            plog.err(C_PREFIX||'no matching host found for sensor name '||i_sensor_name);
        WHEN unique_violation THEN
            plog.warning(C_PREFIX||'dropped duplicate ids event (local event id: ' || i_event_id || ', sensor: ' || i_sensor_name || ', signature: ' || i_signature_gid || ':' || i_signature_sid || ')');
        WHEN OTHERS THEN
            plog.err(C_PREFIX||'caught exception while processing '||i_sender_host_id||': '||sqlerrm);
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_nids.submit_msg_new ( i_log_date nids_event.log_date%TYPE, i_sensor_name text, i_sender_host_id nids_event.sender_host_id%TYPE, i_event_id nids_event.local_event_id%TYPE, i_tt_event_id OUT bigint, i_ticket_id bigint, i_signature_gid signature.gid%TYPE, i_signature_sid signature.sid%TYPE, i_signature_class text, i_suppressed nids_event.suppressed%TYPE, i_ip_source_address nids_event.ip_source_address%TYPE, i_ip_source_port nids_event.ip_source_port%TYPE, i_ip_destination_address nids_event.ip_destination_address%TYPE, i_ip_destination_port nids_event.ip_destination_port%TYPE, i_ip_protocol nids_event.ip_protocol%TYPE, i_direction_id nids_event.direction_id%TYPE, i_description text, i_escalation_level integer ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_nids.submit_msg ( i_log_date nids_event.log_date%TYPE, i_sensor_name text, i_sender_host_id nids_event.sender_host_id%TYPE, i_event_id nids_event.local_event_id%TYPE, i_signature_gid signature.gid%TYPE, i_signature_sid signature.sid%TYPE, i_signature_class text, i_suppressed nids_event.suppressed%TYPE, i_ip_source_address nids_event.ip_source_address%TYPE, i_ip_source_port nids_event.ip_source_port%TYPE, i_ip_destination_address nids_event.ip_destination_address%TYPE, i_ip_destination_port nids_event.ip_destination_port%TYPE, i_ip_protocol nids_event.ip_protocol%TYPE, i_direction_id nids_event.direction_id%TYPE, i_description text, i_escalation_level integer ) AS $body$
DECLARE


        l_signature          signature%ROWTYPE;
        l_description        signature.name%TYPE;
        l_signature_class    signature_class.NAME%TYPE;
        l_sensor_host_id     mss.host.id%TYPE;
        l_pubmsg             varchar(4000);
        l_tt_event_id        bigint := NULL;
        l_event_type         bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
         CALL osag_nids.submit_msg_new(
                i_log_date,
                i_sensor_name,
                i_sender_host_id,
                i_event_id,
                l_tt_event_id,
                NULL, 
                i_signature_gid,
                i_signature_sid,
                i_signature_class,
                i_suppressed,
                i_ip_source_address,
                i_ip_source_port,
                i_ip_destination_address,
                i_ip_destination_port,
                i_ip_protocol,
                i_direction_id,
                i_description,
                i_escalation_level
            );

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_nids.submit_msg ( i_log_date nids_event.log_date%TYPE, i_sensor_name text, i_sender_host_id nids_event.sender_host_id%TYPE, i_event_id nids_event.local_event_id%TYPE, i_signature_gid signature.gid%TYPE, i_signature_sid signature.sid%TYPE, i_signature_class text, i_suppressed nids_event.suppressed%TYPE, i_ip_source_address nids_event.ip_source_address%TYPE, i_ip_source_port nids_event.ip_source_port%TYPE, i_ip_destination_address nids_event.ip_destination_address%TYPE, i_ip_destination_port nids_event.ip_destination_port%TYPE, i_ip_protocol nids_event.ip_protocol%TYPE, i_direction_id nids_event.direction_id%TYPE, i_description text, i_escalation_level integer ) FROM PUBLIC;
-- End of Oracle package 'OSAG_NIDS' declaration



-- Oracle package 'OSAG_NOTIFY' declaration, please edit to match PostgreSQL syntax.

DROP SCHEMA IF EXISTS osag_notify CASCADE;
CREATE SCHEMA IF NOT EXISTS osag_notify;





CREATE OR REPLACE PROCEDURE osag_notify.event_notify (p_event_id bigint, p_ticket_id bigint DEFAULT NULL, p_question text DEFAULT NULL) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'tt.osag_notify.event_notify(): ';
        MAX_EVENT_NOTIFY_COUNT CONSTANT bigint := 5;
        ELAPSED_TIME_BARRIER CONSTANT integer := 500;

        v_host_name mss.host.name%TYPE;
        v_host_id bigint;
        v_service_id bigint;
        v_ticket_worker_id bigint;
        v_service_type_id bigint;
        v_company_id bigint;
        v_company_unit_id bigint;
        v_ticket_id bigint;
        v_ticket_type_id bigint;
        v_ticket_type_name tt.ticket_type.name%TYPE;
        v_ticket_subject tt.ticket.subject%TYPE;
        v_emergency_flag tt.ticket.emergency%TYPE;
        v_status_valid_until_date tt.ticket.status_valid_until_date%TYPE;
        v_eventdate timestamp(0);
        v_details varchar(30000);
        v_details_private varchar(30000);
        v_event_subject varchar(300);
        v_customer_reference tt.ticket.customer_reference%TYPE;
        v_event_notify_count_cust tt.ticket.event_notify_count%TYPE;
        v_event_notify_count_osag tt.ticket.event_notify_count_osag%TYPE;
        v_event_type_id tt.event_type.id%TYPE;
        v_event_type_group_id tt.event_type_group.id%TYPE;
        v_event_type_name varchar(40);
        v_event_source_id bigint;
        v_notified_customer boolean;
        v_notified_osag boolean;
        v_local_contact_notified boolean;
        v_number_of_permissions bigint;
        v_notif_event_is_public DECIMAL;
        v_is_public_event bigint;
        v_email_message_subject varchar(512);
        v_email_message_body varchar(30000);
        v_sms_message varchar(8000);



        
        
        
        
        
        v_procedure_threshold integer;
        v_send_noti_threshold integer;
        v_elapsed_time_procedure integer;
        v_elapsed_time_send_noti integer;



BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        v_procedure_threshold := DBMS_UTILITY.GET_TIME;
        v_elapsed_time_send_noti := 0;
        v_notified_customer := FALSE;
        v_notified_osag := FALSE;

        v_ticket_id := p_ticket_id;


        IF (v_ticket_id IS NULL) THEN
            SELECT e.ticket_id
            INTO STRICT v_ticket_id
            FROM tt.event e
            WHERE e.id = p_event_id;
        END IF;


        SELECT coalesce(event.host_id, ticket.host_id), coalesce(h2s.service_id, ticket.mss_service_id), event.type_id,  event.eventdate, event.details_public, event.details_private, event.public_event,
               ticket.event_notify_count, ticket.event_notify_count_osag, ticket.customer_reference, ticket.subject, ticket.status_valid_until_date, ticket.emergency,
               event_type.name, coalesce(h.name, 'unspecified'), event_type.source
        INTO STRICT v_host_id, v_service_id, v_event_type_id, v_eventdate, v_details, v_details_private, v_is_public_event,
            v_event_notify_count_cust, v_event_notify_count_osag, v_customer_reference, v_ticket_subject, v_status_valid_until_date, v_emergency_flag,
            v_event_type_name, v_host_name, v_event_source_id
        FROM tt.ticket, tt.event_type, tt.event, event
LEFT OUTER JOIN mss.host h ON (event.host_id = h.id)
LEFT OUTER JOIN mss.host2service h2s ON (event.host_id = h2s.host_id)
WHERE event.id = p_event_id AND ticket.id = event.ticket_id AND event.type_id = event_type.id;


        
        IF (v_event_notify_count_cust >= MAX_EVENT_NOTIFY_COUNT AND v_event_notify_count_osag >= MAX_EVENT_NOTIFY_COUNT  AND v_event_source_id = 1) THEN
            plog.debug(S_PREFIX || 'No more notifications for this ticket for automatic events because max notify count reached: ' || MAX_EVENT_NOTIFY_COUNT);
            RETURN;
        END IF;

        v_event_subject := SUBSTR(v_details, 1, 100);
        IF (position(CHR(10) in v_event_subject) > 0) THEN
            v_event_subject := SUBSTR(v_event_subject, 1, position(CHR(10) in v_event_subject) - 1);
        END IF;


        
        IF (NOT osag_notify.is_notify_suppressor_active(v_host_id) OR v_event_type_id = 50008) THEN

            
            
            SELECT t.company_id, t.type_id, t.worker_id
            INTO STRICT v_company_id, v_ticket_type_id, v_ticket_worker_id
            FROM tt.ticket t
            WHERE t.id = v_ticket_id;

            SELECT ty.name
            INTO STRICT v_ticket_type_name
            FROM tt.ticket_type ty
            WHERE ty.id = v_ticket_type_id;

            IF (v_service_id IS NOT NULL) THEN
                SELECT company_unit_id, service_type_id
                INTO STRICT v_company_unit_id, v_service_type_id
                FROM mss.service
                WHERE service.id = v_service_id;


                IF (v_company_unit_id IS NULL) THEN
                    SELECT c.default_company_unit_id
                    INTO STRICT v_company_unit_id
                    FROM stop.company c, mss.service s
                    WHERE s.id = v_service_id
                      AND s.company_id = c.id;
                END IF;
            ELSIF (v_company_id IS NOT NULL) THEN

                
                
                SELECT c.default_company_unit_id INTO STRICT v_company_unit_id
                FROM stop.company c
                WHERE v_company_id = c.id;
                v_service_type_id := NULL;
            ELSE
                v_company_unit_id := NULL;
                v_service_type_id := NULL;
            END IF;

            plog.debug(S_PREFIX || 'event_type_name: ' || v_event_type_name || ', host.id: ' || v_host_id || ', company_id: ' || v_company_id || ', service_id: ' || v_service_id || ', company_unit_id: ' || v_company_unit_id
                || ', service_type_id: ' || v_service_type_id);

            v_notif_event_is_public := 1;

            
            IF (v_event_type_id = 10003) THEN
                CALL osag_notify.notify_isp(p_event_id,
                           v_event_type_id,
                           v_ticket_id,
                           v_host_id,
                           v_host_name,
                           v_customer_reference);
            END IF;


            BEGIN
                SELECT event_type2event_type_group.event_type_group_id
                INTO STRICT v_event_type_group_id
                FROM tt.event, tt.event_type2event_type_group
                WHERE event.id = p_event_id
                  AND event.type_id = event_type2event_type_group.event_type_id;
            EXCEPTION
                WHEN no_data_found THEN
                    v_event_type_group_id := NULL;
            END;


            
            
            IF (v_event_type_group_id = 1 AND v_host_id IS NOT NULL) THEN
                v_local_contact_notified := FALSE;
                 CALL osag_notify.notify_local_contacts(p_event_id,
                                      v_event_type_id,
                                      v_ticket_id,
                                      v_host_id,
                                      v_host_name,
                                      v_customer_reference,
                                      v_company_id,
                                      v_service_id,
                                      v_eventdate,
                                      v_status_valid_until_date,
                                      v_ticket_subject,
                                      v_local_contact_notified);
                IF v_local_contact_notified THEN
                    v_notified_customer := TRUE;
                END IF;
            END IF;


            v_sms_message := osag_notify.compose_sms_msg(v_ticket_id,
                                             v_host_name,
                                             v_event_type_id,
                                             v_event_type_name,
                                             v_eventdate,
                                             v_status_valid_until_date,
                                             v_ticket_subject,
                                             v_emergency_flag);


            
             CALL osag_notify.compose_email_msg(v_email_message_subject,
                              v_email_message_body,
                              v_ticket_id,
                              v_ticket_subject,
                              v_ticket_type_name,
                              v_customer_reference,
                              v_host_name,
                              v_event_type_id,
                              v_event_type_name,
                              v_event_subject,
                              v_eventdate,
                              v_status_valid_until_date,
                              v_details,
                              v_details_private,
                              v_emergency_flag);



            
            
            IF (v_event_notify_count_cust >= MAX_EVENT_NOTIFY_COUNT AND v_event_source_id = 1) THEN
                plog.debug(S_PREFIX || 'No more customer notifications for this ticket for automatic events because max notify count reached: ' || MAX_EVENT_NOTIFY_COUNT);
            ELSIF (v_details IS NULL OR v_is_public_event = 0) THEN

                NULL;
            ELSIF (v_service_id IS NULL) THEN
                DECLARE


                    

                    notify_cur CURSOR FOR
                        SELECT DISTINCT en.login_id, en.event_notification_type_id
                        FROM tt.event_notification en, tt.event_type2event_type_group et2etg, auth.login l, auth.permission p
                        WHERE (en.event_type_id = v_event_type_id
                            OR (en.event_type_group_id = et2etg.event_type_group_id
                                AND et2etg.event_type_id = v_event_type_id))
                          AND en.login_id = l.id
                          AND l.company_id != 6  
                          AND en.company_id = l.company_id 
                          AND en.login_id = p.login_id

                          
                          AND p.company_id = en.company_id
                          AND p.company_unit_id IS NULL AND p.service_id IS NULL AND p.user_unit_id IS NULL
                          AND p.role_id = 1

                          
                          
                          
                          
                          AND (en.company_unit_id IS NULL OR en.company_unit_id = v_company_unit_id) AND en.service_id IS NULL AND en.service_type_id IS NULL
                          AND (en.company_id = v_company_id) 
                          AND (en.ticket_id IS NULL OR en.ticket_id = v_ticket_id)
                          AND (en.ticket_type_id IS NULL OR en.ticket_type_id = v_ticket_type_id);

                    notify_rec notify_cur%ROWTYPE;

                BEGIN
                    FOR notify_rec in notify_cur
                        LOOP
                    v_notified_customer := TRUE;

                    v_send_noti_threshold := DBMS_UTILITY.GET_TIME;
                    CALL osag_notify.send_notification_by_type(notify_rec.event_notification_type_id,
                                              v_ticket_id,
                                              notify_rec.login_id,
                                              v_event_type_name,
                                              v_host_name,
                                              v_eventdate,
                                              v_details,
                                              v_email_message_subject,
                                              v_email_message_body,
                                              v_sms_message,
                                              v_notif_event_is_public);
                    v_elapsed_time_send_noti := v_elapsed_time_send_noti + (DBMS_UTILITY.GET_TIME - v_send_noti_threshold);

                        END LOOP;
                END;
            ELSE
                DECLARE

                    
                    

                    notify_cur CURSOR FOR
                        SELECT DISTINCT en.login_id, en.event_notification_type_id
                        FROM tt.event_notification en, tt.event_type2event_type_group et2etg, auth.login l, auth.mv_service_access mvsa
                        WHERE (en.event_type_id = v_event_type_id
                            OR (en.event_type_group_id = et2etg.event_type_group_id
                                AND et2etg.event_type_id = v_event_type_id))
                          AND en.login_id = l.id
                          AND l.company_id != 6  
                          AND en.company_id = l.company_id 
                          AND en.login_id = mvsa.login_id
                          
                          
                          
                          
                          AND (mvsa.service_id = v_service_id AND mvsa.role_id =1 )
                          AND (en.company_id = v_company_id) 
                          AND (en.service_id IS NULL OR en.service_id = v_service_id)
                          AND (en.company_unit_id IS NULL OR en.company_unit_id = v_company_unit_id)
                          AND (en.service_type_id IS NULL OR en.service_type_id = v_service_type_id)
                          AND (en.ticket_id IS NULL OR en.ticket_id = v_ticket_id)
                          AND (en.ticket_type_id IS NULL OR en.ticket_type_id = v_ticket_type_id);

                    notify_rec notify_cur%ROWTYPE;

                BEGIN
                    FOR notify_rec in notify_cur
                        LOOP
                    v_notified_customer := TRUE;

                    v_send_noti_threshold := DBMS_UTILITY.GET_TIME;
                    CALL osag_notify.send_notification_by_type(notify_rec.event_notification_type_id,
                                              v_ticket_id,
                                              notify_rec.login_id,
                                              v_event_type_name,
                                              v_host_name,
                                              v_eventdate,
                                              v_details,
                                              v_email_message_subject,
                                              v_email_message_body,
                                              v_sms_message,
                                              v_notif_event_is_public);
                    v_elapsed_time_send_noti := v_elapsed_time_send_noti + (DBMS_UTILITY.GET_TIME - v_send_noti_threshold);

                        END LOOP;
                END;
            END IF;




            
            
            IF (v_event_notify_count_osag >= MAX_EVENT_NOTIFY_COUNT AND v_event_source_id = 1) THEN
                plog.debug(S_PREFIX || 'No more notifications for OSAG employees for this ticket for automatic events because max notify count reached: ' || MAX_EVENT_NOTIFY_COUNT);
            ELSE

                
                
                IF (v_company_id IS NOT NULL AND v_company_id != 6) THEN
                    v_notif_event_is_public := 0;
                END IF;

                DECLARE


                    

                    notify_cur CURSOR FOR
                        SELECT DISTINCT en.login_id, en.event_notification_type_id
                        FROM tt.event_notification en, tt.event e, tt.event_type2event_type_group et2etg, auth.login l, auth.permission p
                        WHERE e.id = p_event_id
                          AND (en.event_type_id = e.type_id
                            OR (en.event_type_group_id = et2etg.event_type_group_id
                                AND et2etg.event_type_id = e.type_id))
                          AND en.login_id = l.id
                          AND l.company_id = 6  
                          AND l.id = p.login_id
                          AND p.role_id = 6 
                          AND (en.company_id IS NULL OR en.company_id = v_company_id)
                          AND (en.service_id IS NULL OR en.service_id = v_service_id)
                          AND (en.company_unit_id IS NULL OR en.company_unit_id = v_company_unit_id)
                          AND (en.service_type_id IS NULL OR en.service_type_id = v_service_type_id)
                          AND (en.ticket_id IS NULL OR en.ticket_id = v_ticket_id)
                          AND (en.ticket_type_id IS NULL OR en.ticket_type_id = v_ticket_type_id)
                          AND (en.regexp IS NULL OR regexp_match(e.details_public, en.regexp,'n') IS NOT NULL)
                          AND (en.only_if_worker = 0 OR l.contact_id = v_ticket_worker_id);

                    notify_rec notify_cur%ROWTYPE;

                BEGIN
                    FOR notify_rec in notify_cur
                        LOOP
                    v_notified_osag := TRUE;
                    v_send_noti_threshold := DBMS_UTILITY.GET_TIME;
                    CALL osag_notify.send_notification_by_type(notify_rec.event_notification_type_id,
                                              v_ticket_id,
                                              notify_rec.login_id,
                                              v_event_type_name,
                                              v_host_name,
                                              v_eventdate,
                                              v_details,
                                              v_email_message_subject,
                                              v_email_message_body,
                                              v_sms_message,
                                              v_notif_event_is_public);
                    v_elapsed_time_send_noti := v_elapsed_time_send_noti + (DBMS_UTILITY.GET_TIME - v_send_noti_threshold);
                        END LOOP;
                END;
            END IF;
        END IF;

        IF v_notified_customer THEN


            IF (v_event_notify_count_cust IS NULL) THEN
                v_event_notify_count_cust := 1;
            ELSE
                v_event_notify_count_cust := v_event_notify_count_cust + 1;
            END IF;

            UPDATE ticket
            SET event_notify_count = v_event_notify_count_cust
            WHERE id = v_ticket_id;

            IF (v_event_notify_count_cust = MAX_EVENT_NOTIFY_COUNT) THEN

                
                INSERT INTO event(id, type_id, ticket_id, eventdate, details_public)
                VALUES (nextval('event_sequence'),
                        20010, v_ticket_id,
                        clock_timestamp(),
                        'notification limit (' || MAX_EVENT_NOTIFY_COUNT || ') reached' || CHR(10) ||
                        'There will be no more notifications for system events added to this ticket.');

            END IF;
        END IF;

        IF v_notified_osag THEN


            IF (v_event_notify_count_osag IS NULL) THEN
                v_event_notify_count_osag := 1;
            ELSE
                v_event_notify_count_osag := v_event_notify_count_osag + 1;
            END IF;

            UPDATE ticket
            SET event_notify_count_osag = v_event_notify_count_osag
            WHERE id = v_ticket_id;

            IF (v_event_notify_count_osag = MAX_EVENT_NOTIFY_COUNT) THEN

                
                INSERT INTO event(id, type_id, ticket_id, eventdate, details_private, public_event)
                VALUES (nextval('event_sequence'),
                        20010, v_ticket_id,
                        clock_timestamp(),
                        'notification limit (' || MAX_EVENT_NOTIFY_COUNT || ') reached' || CHR(10) ||
                        'There will be no more notifications for OSAG employees for system events added to this ticket.',
                        0);

            END IF;
        END IF;


        v_elapsed_time_procedure := DBMS_UTILITY.GET_TIME - v_procedure_threshold;
        IF ((v_elapsed_time_procedure - v_elapsed_time_send_noti) > ELAPSED_TIME_BARRIER) THEN
            plog.warning(S_PREFIX || 'procedure elapsed time (' || (v_elapsed_time_procedure - v_elapsed_time_send_noti)*10 || 'ms) exceeded the barrier ('
                || ELAPSED_TIME_BARRIER*10 || 'ms), the queries in this procedure should be optimized'
);
        END IF;

    EXCEPTION
        WHEN OTHERS THEN
            plog.warning(S_PREFIX || 'sending of notification for event ID ' || p_event_id || ' and ticket ID ' || p_ticket_id || ' failed');
            plog.warning(S_PREFIX || 'exception: ' || sqlerrm);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_notify.event_notify (p_event_id bigint, p_ticket_id bigint DEFAULT NULL, p_question text DEFAULT NULL) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_notify.send_test_notification (p_destination_address text, p_notification_type_id bigint, p_ticket_id bigint, p_ticket_subject text, p_host_name text, p_event_type_id bigint, p_eventdate TIMESTAMP WITH TIME ZONE, p_contact_last_name text DEFAULT NULL, p_contact_first_name text DEFAULT NULL) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'tt.osag_notify.send_test_notification(): ';
        S_REPLY_TO_ADDR varchar(32)   := 'support@open.ch';
        S_FROM_ADDR varchar(32) := 'monitoring@open.ch';

        v_event_type_name tt.event_type.name%TYPE;
        v_message_subject varchar(4000);
        v_message varchar(4000);
        v_message_prefix varchar(512);


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        SELECT name
        INTO STRICT v_event_type_name
        FROM tt.event_type et
        WHERE et.id = p_event_type_id;

        v_message_prefix := ' ---------------------------------------------------------------------- ' || CHR(10) ||
                            '|                   THIS IS ONLY A TEST NOTIFICATION                   |' || CHR(10) ||
                            ' ----------------------------------------------------------------------'  || CHR(10) || CHR(10);


        IF (p_notification_type_id = 1) THEN

            v_message := osag_notify.compose_sms_msg(p_ticket_id,
                                         p_host_name,
                                         p_event_type_id,
                                         v_event_type_name,
                                         p_eventdate,
                                         p_eventdate + 1,
                                         p_ticket_subject,
                                         0 
                );

            CALL OSAG_MSG.send_sms(p_destination_address, 'TEST - ' || v_message);

            plog.notice(S_PREFIX || 'test notification (SMS) sent to ' || p_contact_first_name || ' ' || p_contact_last_name ||
                        ' (' || p_destination_address || ')' );
            plog.notice(S_PREFIX || p_destination_address || ' - TEST - ' || v_message);
        ELSIF (p_notification_type_id = 2) THEN
             CALL osag_notify.compose_email_msg(v_message_subject,
                              v_message,         
                              p_ticket_id,
                              p_ticket_subject,
                              'test ticket',
                              NULL,  
                              p_host_name,
                              p_event_type_id,  
                              v_event_type_name,
                              p_ticket_subject,
                              p_eventdate,
                              p_eventdate + 1,
                              'This is a test notification.',
                              'This is a test notification',
                              0 
                );


            IF (p_contact_last_name IS NOT NULL AND p_contact_first_name IS NOT NULL) THEN
                v_message := 'Dear ' || p_contact_first_name || ' ' || p_contact_last_name  || ',' || CHR(10) || CHR(10) || v_message;
            ELSE
                v_message := 'Dear customer,' || CHR(10)|| CHR(10) || v_message;
            END IF;

            CALL OSAG_MSG.send_mail(S_REPLY_TO_ADDR, S_FROM_ADDR, NULL, p_destination_address, v_message_subject, v_message_prefix || v_message);

            plog.notice(S_PREFIX || 'test notification (email) sent to ' || p_contact_first_name || ' ' || p_contact_last_name ||
                        ' (' || p_destination_address || ')' );
        END IF;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_notify.send_test_notification (p_destination_address text, p_notification_type_id bigint, p_ticket_id bigint, p_ticket_subject text, p_host_name text, p_event_type_id bigint, p_eventdate TIMESTAMP WITH TIME ZONE, p_contact_last_name text DEFAULT NULL, p_contact_first_name text DEFAULT NULL) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_notify.delete_notifications_for_login (p_login_id bigint) AS $body$
DECLARE



        notification_cursor CURSOR FOR
            SELECT DISTINCT en.ticket_id
            FROM tt.event_notification en
            WHERE en.login_id = p_login_id
              AND en.ticket_id IS NOT NULL;

        notification_record notification_cursor%ROWTYPE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        FOR notification_record in notification_cursor
            LOOP
        
                CALL osag_notify.delete_ticket_notifications(notification_record.ticket_id, p_login_id, 'because the user was deleted');
            END LOOP;

        DELETE FROM tt.event_notification WHERE login_id = p_login_id;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_notify.delete_notifications_for_login (p_login_id bigint) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_notify.delete_ticket_notifications (p_ticket_id bigint, p_login_id bigint DEFAULT NULL, p_event_details_suffix text DEFAULT NULL) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'tt.osag_notify.delete_ticket_notifications(): ';


        
        notification_cursor CURSOR FOR
            SELECT en.id, en.login_id, en.event_notification_type_id, c.lastname, c.firstname,
                   c.mobile, c.email, l.company_id AS login_company_id, t.company_id AS ticket_company_id
            FROM tt.event_notification en, auth.login l, stop.contact c, ticket t
            WHERE en.ticket_id = p_ticket_id
              AND t.id = p_ticket_id
              AND l.id = en.login_id
              AND (p_login_id IS NULL OR en.login_id = p_login_id) 
              AND c.id = l.contact_id;

        notification_record notification_cursor%ROWTYPE;

        
        
        
        v_event_details_public varchar(4000);
        v_event_details_private varchar(4000);


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        FOR notification_record in notification_cursor
            LOOP
        IF (notification_record.login_company_id = 6 AND notification_record.ticket_company_id  != 6) THEN
            
            v_event_details_private := v_event_details_private || '  -deleted ' || osag_notify.get_notification_type_name(notification_record.event_notification_type_id) ||
                                       ' notification for ' || notification_record.firstname || ' ' || notification_record.lastname || CHR(10);
        ELSE
            v_event_details_public := v_event_details_public || '  -deleted ' || osag_notify.get_notification_type_name(notification_record.event_notification_type_id) ||
                                      ' notification for ' || notification_record.firstname || ' ' || notification_record.lastname || CHR(10);
        END IF;
        DELETE FROM tt.event_notification en WHERE en.id = notification_record.id;
            END LOOP;


        IF (v_event_details_public IS NOT NULL) THEN
            v_event_details_public := v_event_details_public || p_event_details_suffix;
        END IF;
        IF (v_event_details_private IS NOT NULL) THEN
            v_event_details_private := v_event_details_private || p_event_details_suffix;
        END IF;


        
        IF (v_event_details_public IS NOT NULL OR v_event_details_private IS NOT NULL) THEN
            CALL TT.TICKET_INTERFACE.change_notification(p_ticket_id,
                                                    v_event_details_public,
                                                    v_event_details_private,
                                                    NULL);
        END IF;

    EXCEPTION
        WHEN OTHERS THEN
            plog.warning(S_PREFIX || 'deletion of notifications for ticket ' || p_ticket_id || ' failed');
            plog.warning(S_PREFIX || 'exception: ' || sqlerrm);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_notify.delete_ticket_notifications (p_ticket_id bigint, p_login_id bigint DEFAULT NULL, p_event_details_suffix text DEFAULT NULL) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_notify.add_notification_event (p_ticket_id bigint, p_event_type_id bigint, p_text text, p_contact_id bigint, p_peer_contact_id bigint DEFAULT NULL, p_is_public_event DECIMAL DEFAULT 1) AS $body$
DECLARE


        v_details_public varchar(30000);
        v_details_private varchar(30000);


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        IF (p_is_public_event = 1) THEN
            v_details_public := p_text;
            v_details_private := null;
        ELSE
            v_details_public := null;
            v_details_private := p_text;
        END IF;

        INSERT INTO event(id,contact_id,peer_contact_id,type_id,ticket_id,eventdate,details_public,details_private,public_event)
        VALUES (nextval('event_sequence'),
                p_contact_id,
                p_peer_contact_id,
                p_event_type_id,
                p_ticket_id,
                clock_timestamp(),
                v_details_public,
                v_details_private,
                p_is_public_event);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_notify.add_notification_event (p_ticket_id bigint, p_event_type_id bigint, p_text text, p_contact_id bigint, p_peer_contact_id bigint DEFAULT NULL, p_is_public_event DECIMAL DEFAULT 1) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_notify.is_notify_suppressor_active (p_host_id bigint) RETURNS boolean AS $body$
DECLARE

        v_entry_exists integer;
        v_host_id tt.ticket.host_id%TYPE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        
        SELECT COUNT(*)
        INTO STRICT v_entry_exists
        FROM tt.ticket t
                 INNER JOIN tt.service_window s
                            ON (s.ticket_id = t.id)
                 INNER JOIN tt.host2service_window h2s
                            ON (h2s.service_window_id = s.id)

                 LEFT JOIN tt.maintenance_window m
                           ON (s.id = m.service_window_id)
                 LEFT JOIN tt.cust_maintenance_window cm
                           ON (s.id = cm.service_window_id)

        WHERE
                t.status_id < 101 AND s.end_date > statement_timestamp() AND s.start_date < statement_timestamp()
          AND (m.disable_notification = 1 OR cm.disable_notification = 1) AND h2s.host_id = p_host_id;

        IF (v_entry_exists > 0) THEN
            RETURN TRUE;
        END IF;
        RETURN FALSE;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION osag_notify.is_notify_suppressor_active (p_host_id bigint) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_notify.send_notification_by_type (p_event_notification_type_id bigint, p_ticket_id bigint, p_login_id bigint, p_event_type_name text, p_host_name text, p_eventdate timestamp(0), p_event_details_public text, p_email_message_subject text, p_email_message_body text, p_sms_message text, p_is_public_event DECIMAL DEFAULT 1) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'tt.osag_notify.send_notification_by_type(): ';
        S_REPLY_TO_ADDR varchar(32)   := 'support@open.ch';
        S_FROM_ADDR varchar(32) := 'monitoring@open.ch';

        v_contact_id bigint;
        v_target_address varchar(50);
        v_contact_last_name stop.contact.lastname%TYPE;
        v_contact_first_name stop.contact.firstname%TYPE;
        v_email_message_body varchar(30000);
        v_envelope_from varchar(64);


        v_smtp_headers OSAG_MSG.smtp_headers_t := OSAG_MSG.smtp_headers_t();
        v_smtp_header_rec OSAG_MSG.smtp_header_t;


BEGIN
        
        IF p_event_notification_type_id = 1 THEN
            
            SELECT contact.id,  contact.mobile, contact.lastname, contact.firstname
            INTO STRICT v_contact_id, v_target_address, v_contact_last_name, v_contact_first_name
            FROM auth.login, stop.contact
            WHERE login.id = p_login_id
              AND contact.id = login.contact_id;

            IF (v_target_address IS NOT NULL) THEN

                plog.notice(S_PREFIX || 'sending SMS to ' || v_contact_first_name || ' ' || v_contact_last_name || ' (login[' || p_login_id || ']), ' || v_target_address );

                CALL OSAG_MSG.send_sms(v_target_address, p_sms_message);

                CALL osag_notify.add_notification_event(p_ticket_id, 20003,
                                       'sent to ' || v_contact_first_name || ' ' || v_contact_last_name || ', ' || v_target_address ||  CHR(10) ||
                                       p_sms_message, NULL, v_contact_id, p_is_public_event);
            ELSE
                plog.notice(S_PREFIX || 'event notification not sent to auth.login[' || p_login_id || '], assigned contact has no mobile number specified');
            END IF;
        END IF;

        IF p_event_notification_type_id = 2 THEN
            
            SELECT contact.id,  contact.email, contact.lastname, contact.firstname
            INTO STRICT v_contact_id, v_target_address, v_contact_last_name, v_contact_first_name
            FROM auth.login, stop.contact
            WHERE login.id = p_login_id
              AND contact.id = login.contact_id;

            IF (v_target_address IS NOT NULL) THEN
                plog.notice(S_PREFIX || 'sending email to ' || v_contact_first_name || ' ' || v_contact_last_name || ' (login[' || p_login_id || ']), ' || v_target_address);


                
                v_smtp_headers.extend(2);

                v_smtp_header_rec.h_name := 'Auto-Submitted';
                v_smtp_header_rec.h_value := 'auto-generated';

                v_smtp_headers(1) := v_smtp_header_rec;

                v_smtp_header_rec.h_name := 'Precedence';
                v_smtp_header_rec.h_value := 'bulk';

                v_smtp_headers(2) := v_smtp_header_rec;


                IF (v_contact_last_name IS NOT NULL AND v_contact_first_name IS NOT NULL) THEN
                    v_email_message_body := 'Dear ' || v_contact_first_name || ' ' || v_contact_last_name  || ',' || CHR(10) || CHR(10) || p_email_message_body;
                ELSE
                    v_email_message_body := 'Dear customer,' || CHR(10)|| CHR(10) || p_email_message_body;
                END IF;

                IF (p_is_public_event = 1) THEN
                    v_envelope_from := 'ttbounce+' || p_ticket_id || '@open.ch';
                ELSE
                    v_envelope_from := 'ttbounce-private+' || p_ticket_id || '@open.ch';
                END IF;

                CALL OSAG_MSG.send_mail(S_REPLY_TO_ADDR, S_FROM_ADDR, v_envelope_from, v_target_address, p_email_message_subject, v_email_message_body, v_smtp_headers);

                CALL osag_notify.add_notification_event(p_ticket_id, 20001,
                                       'sent to ' || v_contact_first_name || ' ' || v_contact_last_name || ', ' || v_target_address || CHR(10) ||
                                       v_email_message_body, NULL, v_contact_id, p_is_public_event);
            ELSE
                plog.notice(S_PREFIX || 'event notification not sent to auth.login[' || p_login_id || '], assigned contact has no email address specified');
            END IF;
        END IF;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_notify.send_notification_by_type (p_event_notification_type_id bigint, p_ticket_id bigint, p_login_id bigint, p_event_type_name text, p_host_name text, p_eventdate timestamp(0), p_event_details_public text, p_email_message_subject text, p_email_message_body text, p_sms_message text, p_is_public_event DECIMAL DEFAULT 1) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_notify.compose_email_msg (p_message_subject OUT text, p_message OUT text, p_ticket_id bigint, p_ticket_subject text, p_ticket_type_name text, p_customer_reference text, p_host_name text, p_event_type_id bigint, p_event_type_name text, p_event_subject text, p_eventdate timestamp(0), p_status_valid_until_date timestamp(0), p_details_public text, p_details_private text, p_emergency_flag tt.ticket.emergency%TYPE) AS $body$
DECLARE


        v_message_subject varchar(512);
        v_subject_prefix varchar(512);
        v_message varchar(30000);
        v_subject_template varchar(512);
        v_message_template varchar(30000);
        v_email_msg_template_id bigint;
        v_details varchar(2000);
        v_emergency_text varchar(20) := '';


BEGIN
        SELECT email_message_template_id
        INTO STRICT v_email_msg_template_id
        FROM tt.event_type et
        WHERE et.id = p_event_type_id;

        SELECT subject_template, message_template
        INTO STRICT v_subject_template, v_message_template
        FROM tt.event_type_message etm
        WHERE etm.id = v_email_msg_template_id;

        IF p_emergency_flag = 1 THEN
            v_emergency_text := 'EMERGENCY: ';
        END IF;


        v_subject_prefix := '[OS-' || p_ticket_id || ']' || osag_notify.format_customer_reference(p_customer_reference);
        v_subject_template := REPLACE(v_subject_template, '$#TICKET_SUBJECT#$', p_ticket_subject);
        v_subject_template := REPLACE(v_subject_template, '$#EVENT_TYPE_NAME#$', p_event_type_name);
        v_subject_template := REPLACE(v_subject_template, '$#TICKET_TYPE#$', p_ticket_type_name);
        v_subject_template := REPLACE(v_subject_template, '$#EMERGENCY#$', v_emergency_text);

        IF (p_host_name IS NOT NULL AND p_host_name != 'unspecified') THEN
            v_subject_template := REPLACE(v_subject_template, '$#HOST_NAME#$', p_host_name);
        ELSE
            v_subject_template := REPLACE(v_subject_template, '$#HOST_NAME#$', '<unspecified service>');
        END IF;


        v_subject_template := REPLACE(v_subject_template, '$#STATUS_VALID_UNTIL#$', TO_CHAR(p_status_valid_until_date,'DD.MM.YYYY HH24:MI') || ' ' || TO_CHAR(statement_timestamp() AT TIME ZONE 'EUROPE/ZURICH', 'TZD'));

        p_message_subject := v_subject_prefix || ' ' || v_subject_template;


        v_message_template := REPLACE(v_message_template, '$#EVENT_DATE#$', TO_CHAR(p_eventdate,'DD.MM.YYYY HH24:MI') || ' ' || TO_CHAR(statement_timestamp() AT TIME ZONE 'EUROPE/ZURICH', 'TZD'));
        v_message_template := REPLACE(v_message_template, '$#EVENT_TYPE_NAME#$', p_event_type_name);
        v_message_template := REPLACE(v_message_template, '$#TICKET_SUBJECT#$', p_ticket_subject);
        v_message_template := REPLACE(v_message_template, '$#EMERGENCY#$', v_emergency_text);

        IF (p_host_name IS NOT NULL AND p_host_name != 'unspecified') THEN
            v_message_template := REPLACE(v_message_template, '$#HOST_NAME#$', p_host_name);
        ELSE
            v_message_template := REPLACE(v_message_template, '$#HOST_NAME#$', '<unspecified service>');
        END IF;

        v_message_template := REPLACE(v_message_template, '$#TICKET_ID#$', p_ticket_id);

        v_message_template := REPLACE(v_message_template, '$#STATUS_VALID_UNTIL#$', TO_CHAR(p_status_valid_until_date,'DD.MM.YYYY HH24:MI') || ' ' || TO_CHAR(statement_timestamp() AT TIME ZONE 'EUROPE/ZURICH', 'TZD'));


        IF (p_event_type_id = 50008) THEN
            v_message_template := SUBSTR(REPLACE(v_message_template, '$#QUESTION#$', p_details_public), 1, 29000);
        END IF;


        
        IF (p_event_type_id = 30012) THEN
            
            v_details := SUBSTR(p_details_public, 1, 2000);
            v_message_template := REPLACE(v_message_template, '$#PUBLIC_DETAILS#$', v_details);
        ELSIF (p_event_type_id = 50004) THEN

            v_details := SUBSTR(p_details_private, 1, 2000);
            v_message_template := REPLACE(v_message_template, '$#PRIVATE_DETAILS#$', v_details);
        END IF;

        v_message := v_message || v_message_template || CHR(10) || CHR(10) ||  osag_notify.email_footer(p_ticket_id);

        p_message := v_message;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_notify.compose_email_msg (p_message_subject OUT text, p_message OUT text, p_ticket_id bigint, p_ticket_subject text, p_ticket_type_name text, p_customer_reference text, p_host_name text, p_event_type_id bigint, p_event_type_name text, p_event_subject text, p_eventdate timestamp(0), p_status_valid_until_date timestamp(0), p_details_public text, p_details_private text, p_emergency_flag tt.ticket.emergency%TYPE) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_notify.compose_sms_msg (p_ticket_id bigint, p_host_name text, p_event_type_id bigint, p_event_type_name text, p_eventdate timestamp(0), p_status_valid_until_date timestamp(0), p_ticket_subject text, p_emergency_flag tt.ticket.emergency%TYPE) RETURNS varchar AS $body$
DECLARE


        S_SMS_MSG_SIZE CONSTANT bigint := 160;

        v_message varchar(4000);
        v_message_template varchar(4000);
        v_sms_msg_template_id bigint;
        v_max_ticket_subject_size bigint;
        v_ticket_subject tt.ticket.subject%TYPE;
        v_emergency_text varchar(20) := '';


BEGIN
        SELECT sms_message_template_id
        INTO STRICT v_sms_msg_template_id
        FROM tt.event_type et
        WHERE et.id = p_event_type_id;

        SELECT  message_template
        INTO STRICT v_message_template
        FROM tt.event_type_message etm
        WHERE etm.id = v_sms_msg_template_id;

        IF p_emergency_flag = 1 THEN
            v_emergency_text := 'EM: ';
        END IF;

        IF (p_host_name IS NOT NULL AND p_host_name != 'unspecified') THEN
            v_message_template := REPLACE(v_message_template, '$#HOST_NAME#$', p_host_name);
        ELSE
            v_message_template := REPLACE(v_message_template, '$#HOST_NAME#$', '<unspecified service>');
        END IF;

        v_message_template := REPLACE(v_message_template, '$#EVENT_DATE#$', TO_CHAR(p_eventdate,'DD.MM.YYYY HH24:MI') || ' ' || TO_CHAR(statement_timestamp() AT TIME ZONE 'EUROPE/ZURICH', 'TZD'));
        v_message_template := REPLACE(v_message_template, '$#EVENT_TYPE_NAME#$', p_event_type_name);
        v_message_template := REPLACE(v_message_template, '$#TICKET_ID#$', p_ticket_id);
        v_message_template := REPLACE(v_message_template, '$#STATUS_VALID_UNTIL#$', TO_CHAR(p_status_valid_until_date,'DD.MM.YYYY HH24:MI') || ' ' || TO_CHAR(statement_timestamp() AT TIME ZONE 'EUROPE/ZURICH', 'TZD'));

        v_message_template := v_message_template ||  ' - Open Systems Mission Control';


        
        
        v_max_ticket_subject_size := S_SMS_MSG_SIZE - LENGTH(v_message_template) + LENGTH('$#TICKET_SUBJECT#$') - LENGTH(v_emergency_text);
        IF (LENGTH(p_ticket_subject) > v_max_ticket_subject_size) THEN
            v_ticket_subject := SUBSTR(p_ticket_subject, 0, v_max_ticket_subject_size -3) || '...';
        ELSE
            v_ticket_subject := p_ticket_subject;
        END IF;

        v_message_template := REPLACE(v_message_template, '$#TICKET_SUBJECT#$', v_ticket_subject);
        v_message_template := REPLACE(v_message_template, '$#EMERGENCY#$', v_emergency_text);

        v_message := v_message_template;

        RETURN v_message;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION osag_notify.compose_sms_msg (p_ticket_id bigint, p_host_name text, p_event_type_id bigint, p_event_type_name text, p_eventdate timestamp(0), p_status_valid_until_date timestamp(0), p_ticket_subject text, p_emergency_flag tt.ticket.emergency%TYPE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_notify.notify_local_contacts (p_event_id bigint, p_event_type_id bigint, p_ticket_id bigint, p_host_id bigint, p_host_name text, p_customer_reference text, p_company_id bigint, p_service_id bigint, p_eventdate timestamp(0), p_status_valid_until_date timestamp(0), p_ticket_subject text, p_notified_cust OUT boolean) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'tt.osag_notify.notify_local_contacts(): ';
        S_REPLY_TO_ADDR varchar(32)    := 'support@open.ch';
        S_FROM_ADDR varchar(32)        := 'monitoring@open.ch';

        v_message_subject varchar(4000);
        v_message varchar(4000);
        v_sms_message varchar(200);
        v_service_name mss.service_type.name%TYPE;
        v_company_name stop.company.name%TYPE;
        v_event_type_name tt.event_type.name%TYPE;
        v_envelope_from varchar(64);


        local_contact_cur CURSOR FOR
            SELECT c.*, lcn.event_notification_type_id
            FROM stop.contact c, mss.local_contact lc, mss.address a, mss.host h, mss.local_contact_notification lcn
            WHERE h.address_id = a.id
              AND a.id = lc.address_id
              AND lc.contact_id = c.id
              AND lc.local_contact_type_id = 1 
              AND lc.id = lcn.local_contact_id
              AND h.id = p_host_id
            ORDER BY lc.priority;


BEGIN

        SELECT st.name
        INTO STRICT v_service_name
        FROM mss.service_type st, mss.service s
        WHERE s.service_type_id = st.id
          AND s.id = p_service_id;

        SELECT name
        INTO STRICT v_company_name
        FROM stop.company
        WHERE id = p_company_id;

        SELECT name
        INTO STRICT v_event_type_name
        FROM tt.event_type
        WHERE id = p_event_type_id;

        v_message_subject := '[OS-' || p_ticket_id ||']' || osag_notify.format_customer_reference(p_customer_reference) || v_event_type_name;
        v_message := osag_notify.compose_local_contact_message(p_ticket_id, v_event_type_name, p_host_name, p_eventdate);
        v_sms_message := osag_notify.compose_sms_msg(p_ticket_id, p_host_name, p_event_type_id, v_event_type_name,
                                         p_eventdate, p_status_valid_until_date, p_ticket_subject, 0);

        p_notified_cust := FALSE;
        FOR local_contact_rec IN local_contact_cur LOOP
                IF (local_contact_rec.event_notification_type_id = 1 AND (local_contact_rec.mobile IS NOT NULL)) THEN

                    plog.notice(S_PREFIX || 'sending sms to local emergency contact: '||local_contact_rec.mobile);
                    CALL OSAG_MSG.send_sms(local_contact_rec.mobile, v_sms_message);
                    CALL TT.OSAG_NOTIFY.add_notification_event(p_ticket_id, 20003,
                                                          'sent to ' || local_contact_rec.mobile || ' (local contact sms notification)' || CHR(10) ||
                                                          CHR(10) || CHR(10) || v_sms_message, NULL, local_contact_rec.id);
                    p_notified_cust := TRUE;
                ELSIF (local_contact_rec.event_notification_type_id = 2 AND (local_contact_rec.email IS NOT NULL)) THEN

                    plog.notice(S_PREFIX || 'sending email to local emergency contact: '||local_contact_rec.email);
                    v_envelope_from := 'ttbounce+' || p_ticket_id || '@open.ch';
                    CALL OSAG_MSG.send_mail(S_REPLY_TO_ADDR, S_FROM_ADDR, v_envelope_from, local_contact_rec.email, v_message_subject, v_message);
                    CALL TT.OSAG_NOTIFY.add_notification_event(p_ticket_id, 20001,
                                                          'sent to ' || local_contact_rec.email || ' (local contact email notification)' || CHR(10) ||
                                                          v_message_subject || CHR(10) || CHR(10) || v_message, NULL, local_contact_rec.id);
                    p_notified_cust := TRUE;
                END IF;
            END LOOP;
    EXCEPTION
        WHEN no_data_found THEN
            plog.err(S_PREFIX || 'found no data for event ' || p_event_id);
            RETURN;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_notify.notify_local_contacts (p_event_id bigint, p_event_type_id bigint, p_ticket_id bigint, p_host_id bigint, p_host_name text, p_customer_reference text, p_company_id bigint, p_service_id bigint, p_eventdate timestamp(0), p_status_valid_until_date timestamp(0), p_ticket_subject text, p_notified_cust OUT boolean) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_notify.compose_local_contact_message (p_ticket_id bigint, p_event_type_name text, p_host_name text, p_eventdate timestamp(0)) RETURNS varchar AS $body$
BEGIN
        RETURN 'This is an automatically generated email to inform you that the following event has occurred:' ||
               CHR(10) || CHR(10) ||
               'Ticket:   ' || p_ticket_id || CHR(10) ||
               'Event:    ' || p_event_type_name || CHR(10) ||
               'Host:     ' || p_host_name || CHR(10) ||
               'Date:     ' || TO_CHAR(p_eventdate,'DD.MM.YYYY HH24:MI') || ' ' ||
               TO_CHAR(statement_timestamp() AT TIME ZONE 'EUROPE/ZURICH', 'TZD') || CHR(10) || CHR(10) ||
               'If you have access to the Open Systems Ticket System, you can view' || CHR(10) ||
               'the complete ticket using the following link:' || CHR(10) || CHR(10) ||
               'https://control.open.ch/mc/ticket/' || p_ticket_id || CHR(10) || CHR(10) ||
               osag_notify.email_signature();
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION osag_notify.compose_local_contact_message (p_ticket_id bigint, p_event_type_name text, p_host_name text, p_eventdate timestamp(0)) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_notify.notify_isp (p_event_id bigint, p_event_type_id bigint, p_ticket_id bigint, p_host_id bigint, p_host_name text, p_customer_reference text) AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'tt.osag_notify.notify_isp(): ';
        S_REPLY_TO_ADDR varchar(32)   := 'support@open.ch';
        S_FROM_ADDR varchar(32) := 'monitoring@open.ch';

        v_isp_link_id mss.isp_link.id%TYPE;
        v_isp_notification mss.isp_link.isp_notification%TYPE;
        v_isp_support_mail stop.contact.email%TYPE;
        v_isp_contact_id stop.contact.id%TYPE;
        v_isp_router_ip mss.isp_link.router_ip_address1%TYPE;
        v_message_subject varchar(4000);
        v_message varchar(4000);
        v_envelope_from varchar(64);



BEGIN

        v_isp_link_id := osag_notify.get_isp_link_id_for_host_id(p_host_id);

        IF (v_isp_link_id IS NULL) THEN
            RETURN;
        END IF;

        BEGIN
            SELECT i.isp_notification, i.router_ip_address1, c.email, c.id
            INTO STRICT v_isp_notification, v_isp_router_ip, v_isp_support_mail, v_isp_contact_id
            FROM mss.isp_link i, stop.contact c
            WHERE i.id = v_isp_link_id
              AND i.support_id = c.id;
        EXCEPTION
            WHEN no_data_found THEN
                v_isp_support_mail := NULL;
            WHEN OTHERS THEN
                plog.err(S_PREFIX||'unknown error: '||sqlerrm);
                v_isp_support_mail := NULL;
        END;

        IF (v_isp_notification = 0) THEN
            RETURN;
        END IF;


        IF (v_isp_support_mail IS NOT NULL AND v_isp_support_mail != 'unknown@during.import.tld') THEN

            IF p_event_type_id = 10003 THEN 
                v_message_subject := '[OS-' || p_ticket_id ||']' || osag_notify.format_customer_reference(p_customer_reference) ||
                                     ' ISP outage detected for ' || mss.osag_ip.num2ip(v_isp_router_ip);
                v_message := osag_notify.get_message_for_isp_outage(p_ticket_id, v_isp_link_id, p_host_id,
                                                        p_event_id, mss.osag_ip.num2ip(v_isp_router_ip), p_host_name);
            END IF;

            IF p_event_type_id = 10100 THEN
                v_message_subject := '[OS-' || p_ticket_id ||']' || osag_notify.format_customer_reference(p_customer_reference) ||
                                     ' connection up for ' || mss.osag_ip.num2ip(v_isp_router_ip);
                v_message := osag_notify.get_message_for_connection_up(p_ticket_id, v_isp_link_id, p_host_id,
                                                           p_event_id, mss.osag_ip.num2ip(v_isp_router_ip), p_host_name);
            END IF;
            v_envelope_from := 'ttbounce+' || p_ticket_id || '@open.ch';

            plog.notice(S_PREFIX || 'sending email to isp support contact: '||v_isp_support_mail);

            CALL OSAG_MSG.send_mail(S_REPLY_TO_ADDR, S_FROM_ADDR, v_envelope_from, v_isp_support_mail, v_message_subject, v_message);

            CALL TT.OSAG_NOTIFY.add_notification_event(p_ticket_id, 20001,
                                                  'sent to ' || v_isp_support_mail || ' (isp email notification)' || CHR(10) ||
                                                  v_message_subject || CHR(10) || CHR(10) || v_message, NULL, v_isp_contact_id);
        END IF;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_notify.notify_isp (p_event_id bigint, p_event_type_id bigint, p_ticket_id bigint, p_host_id bigint, p_host_name text, p_customer_reference text) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_notify.get_isp_link_id_for_host_id (p_host_id bigint) RETURNS bigint AS $body$
DECLARE


        S_PREFIX CONSTANT varchar(64) := 'tt.osag_notify.get_isp_link_id_for_host_id(): ';

        v_isp_link_id bigint;


BEGIN

        BEGIN

            SELECT mss.interface2isp_link.isp_link_id
            INTO STRICT v_isp_link_id
            FROM mss.host, mss.interface, mss.interface2isp_link
            WHERE mss.host.id = p_host_id
              AND mss.interface.host_id = mss.host.id
              AND mss.interface2isp_link.interface_id = mss.interface.id
              AND mss.interface.mgmtaccess = 1;

        EXCEPTION
            WHEN no_data_found THEN
                RETURN NULL;
            WHEN too_many_rows THEN
                plog.err(S_PREFIX||'host['||p_host_id
                    ||'] has too many ISP links');
                RETURN NULL;
            WHEN OTHERS THEN
                plog.err(S_PREFIX||'unknown error: '||sqlerrm);
                RETURN NULL;
        END;

        RETURN v_isp_link_id;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION osag_notify.get_isp_link_id_for_host_id (p_host_id bigint) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_notify.get_message_for_isp_outage (p_ticket_id bigint, p_isp_link_id bigint, p_host_id bigint, p_event_id bigint, p_isp_router_ip text, p_host_name text) RETURNS varchar AS $body$
DECLARE

        v_message varchar(4000);
        v_contact_list varchar(4000);
        v_acc_mgr_lastname stop.contact.lastname%TYPE;
        v_acc_mgr_firstname stop.contact.firstname%type;
        v_isp_account_number mss.isp_link.account_number%TYPE;
        v_isp_line_number mss.isp_link.line_number%TYPE;
        v_isp_company_id bigint;
        v_isp_company_name stop.company.name%TYPE;
        v_company_name stop.company.name%TYPE;
        v_city_name mss.city.name%TYPE;
        v_country_name mss.country.name%TYPE;
        v_connection_down_date varchar(40);


        
        
        contact_cur CURSOR FOR
            SELECT c.id, c.firstname, c.lastname, c.direct, c.email
            FROM stop.contact c, mss.host h, mss.local_contact lc
            WHERE h.id = p_host_id AND
                    lc.address_id = h.address_id AND lc.contact_id = c.id AND (c.direct IS NOT NULL OR c.email IS NOT NULL) AND
                    lc.local_contact_type_id = 1 
            ORDER BY lc.priority;


BEGIN
        BEGIN
            
            SELECT coalesce(stop.contact.lastname, ''), coalesce(stop.contact.firstname, ''), mss.isp_link.account_number,
                   mss.isp_link.line_number, mss.isp_link.company_id
            INTO STRICT v_acc_mgr_lastname, v_acc_mgr_firstname, v_isp_account_number, v_isp_line_number, v_isp_company_id
            FROM mss.isp_link
LEFT OUTER JOIN stop.contact ON (mss.isp_link.account_manager_id = stop.contact.id)
WHERE mss.isp_link.id = p_isp_link_id;
        EXCEPTION
            WHEN OTHERS THEN
                v_acc_mgr_lastname := '';
        END;


        IF v_isp_company_id IS NOT NULL THEN
            BEGIN

                SELECT company.name
                INTO STRICT v_isp_company_name
                FROM stop.company
                WHERE company.id = v_isp_company_id;
            EXCEPTION
                WHEN OTHERS THEN
                    NULL;
            END;
        END IF;

        BEGIN

            SELECT company.name, city.name, country.name
            INTO STRICT v_company_name, v_city_name, v_country_name
            FROM stop.company, mss.host, mss.country, mss.city, mss.address, host
LEFT OUTER JOIN address ON (host.address_id = address.id)
LEFT OUTER JOIN city ON (address.city_id = city.id)
LEFT OUTER JOIN country ON (city.country_id = country.id)
WHERE host.id = p_host_id AND host.service_company_id = company.id;
        EXCEPTION
            WHEN OTHERS THEN
                NULL;
        END;

        BEGIN

            
            
            
            SELECT to_char((cast(down_date as timestamp) AT TIME ZONE 'EUROPE/ZURICH')::timestamp with time zone, 'DD Mon YYYY, HH24:MI TZH:TZM')
            INTO STRICT v_connection_down_date
            FROM mc.connection_interrupt_open cio
            WHERE cio.host_id = p_host_id;
        EXCEPTION
            WHEN OTHERS THEN
                NULL;
        END;

        v_message := 'Dear ' || v_isp_company_name || ' support,' || CHR(10) ||
                     CHR(10) ||
                     'The following local loop';
        IF (v_isp_company_name IS NOT NULL) THEN
            v_message := v_message || ' operated by ' || v_isp_company_name;
        END IF;

        v_contact_list := '';


        FOR contact_rec in contact_cur LOOP
                v_contact_list := v_contact_list || CHR(10) || '- ' || contact_rec.firstname || ' ' || contact_rec.lastname || ' (';
                IF (contact_rec.direct IS NOT NULL) THEN
                    v_contact_list := v_contact_list || 'phone: ' || contact_rec.direct;
                END IF;
                IF (contact_rec.email IS NOT NULL) THEN
                    IF (contact_rec.direct IS NOT NULL) THEN
                        v_contact_list := v_contact_list || ', ';
                    END IF;
                    v_contact_list := v_contact_list || 'email: ' || contact_rec.email;
                END IF;
                v_contact_list := v_contact_list || ')';
            END LOOP;


        v_message := v_message ||
                     ' is currently down.' || CHR(10) ||
                     'The local loop details are provided below.' || CHR(10) ||
                     'Please investigate and resolve the ' ||
                     'problem according to the SLA provided.' || CHR(10) ||
                     CHR(10);

        IF (v_contact_list IS NOT NULL) THEN
            v_message := v_message || 'Should you need support by the affected customer site, please contact:' ||
                         v_contact_list || CHR(10) || CHR(10);
        END IF;

        v_message := v_message || 'In case of further technical information required, do not hesitate' || CHR(10) ||
                     'to contact Open Systems Mission Control by replying to this e-mail.' || CHR(10) ||CHR(10) ||
                     'Best regards,' || CHR(10) ||
                     'Mission Control' || CHR(10) ||
                     CHR(10) ||
                     'ISP Router IP: ' || p_isp_router_ip || ' (' || p_host_name || ')' || CHR(10) ||
                     'Location:      ';
        IF (v_city_name IS NOT NULL) THEN
            v_message := v_message || v_city_name || ', ' || v_country_name || CHR(10);
        ELSE
            v_message := v_message || 'n/a' || CHR(10);
        END IF;

        v_message := v_message ||
                     'Customer:      ' || coalesce(v_company_name, 'n/a') || CHR(10) ||
                     'Account no:    ' || coalesce(v_isp_account_number, 'n/a') || CHR(10) ||
                     'Line no:       ' || coalesce(v_isp_line_number, 'n/a') || CHR(10) ||
                     'Account mgr:   ';
        IF (v_acc_mgr_lastname IS NULL) THEN
            v_message := v_message  || 'n/a' || CHR(10);
        ELSE
            v_message := v_message || v_acc_mgr_lastname || ' ' || v_acc_mgr_firstname || CHR(10);
        END IF;

        v_message := v_message ||
                     'Outage start:  ' || coalesce(v_connection_down_date, 'n/a') || CHR(10) ||
                     CHR(10) ||
                     'This message was automatically generated.'|| CHR(10) || 'The Internet connectivity ' ||
                     'is measured from Zurich, Switzerland.' || CHR(10) ||
                     osag_notify.email_signature();

        RETURN v_message;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION osag_notify.get_message_for_isp_outage (p_ticket_id bigint, p_isp_link_id bigint, p_host_id bigint, p_event_id bigint, p_isp_router_ip text, p_host_name text) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_notify.get_message_for_connection_up (p_ticket_id bigint, p_isp_link_id bigint, p_host_id bigint, p_event_id bigint, p_isp_router_ip text, p_host_name text) RETURNS varchar AS $body$
DECLARE

        v_message varchar(4000);
        v_acc_mgr_lastname stop.contact.lastname%TYPE;
