                   mss.isp_link.line_number, mss.isp_link.company_id
            INTO STRICT v_acc_mgr_lastname, v_acc_mgr_firstname, v_isp_account_number, v_isp_line_number, v_isp_company_id
            FROM mss.isp_link
LEFT OUTER JOIN stop.contact ON (mss.isp_link.account_manager_id = stop.contact.id)
WHERE mss.isp_link.id = p_isp_link_id;
        EXCEPTION
            WHEN OTHERS THEN
                v_acc_mgr_lastname := '';
        END;


        IF v_isp_company_id IS NOT NULL THEN
            BEGIN

                SELECT company.name
                INTO STRICT v_isp_company_name
                FROM stop.company
                WHERE company.id = v_isp_company_id;
            EXCEPTION
                WHEN OTHERS THEN
                    NULL;
            END;
        END IF;

        BEGIN

            SELECT company.name, city.name, country.name
            INTO STRICT v_company_name, v_city_name, v_country_name
            FROM stop.company, mss.host, mss.country, mss.city, mss.address, host
LEFT OUTER JOIN address ON (host.address_id = address.id)
LEFT OUTER JOIN city ON (address.city_id = city.id)
LEFT OUTER JOIN country ON (city.country_id = country.id)
WHERE host.id = p_host_id AND host.service_company_id = company.id;
        EXCEPTION
            WHEN OTHERS THEN
                NULL;
        END;

        v_message := 'Dear support,' || CHR(10) ||
                     CHR(10) ||
                     'The following local loop,';
        IF (v_isp_company_name IS NOT NULL) THEN
            v_message := v_message || ' provided by ' || v_isp_company_name || ',';
        END IF;
        v_message := v_message ||
                     ' is up again. Thank you for your efforts.' || CHR(10) ||
                     CHR(10) ||
                     'Do not hesitate to contact Open Systems Mission Control by ' ||
                     'replying to this e-mail in case you require further information.' || CHR(10) ||
                     CHR(10) ||
                     'Best regards,' || CHR(10) ||
                     'Mission Control' || CHR(10) ||
                     CHR(10) ||
                     'ISP Router IP: ' || p_isp_router_ip || ' (' || p_host_name || ')' || CHR(10) ||
                     'Location:      ';
        IF (v_city_name IS NOT NULL) THEN
            v_message := v_message || v_city_name || ', ' || v_country_name || CHR(10);
        ELSE
            v_message := v_message || 'n/a' || CHR(10);
        END IF;

        v_message := v_message ||
                     'Customer:      ' || coalesce(v_company_name, 'n/a') || CHR(10) ||
                     'Account no:    ' || coalesce(v_isp_account_number, 'n/a') || CHR(10) ||
                     'Line no:       ' || coalesce(v_isp_line_number, 'n/a') || CHR(10) ||
                     'Account mgr:   ';
        IF (v_acc_mgr_lastname IS NULL) THEN
            v_message := v_message  || 'n/a' || CHR(10);
        ELSE
            v_message := v_message || v_acc_mgr_lastname || ' ' || v_acc_mgr_firstname || CHR(10);
        END IF;

        v_message := v_message ||
                     CHR(10) ||
                     'This message was automatically generated. The Internet connectivity ' ||
                     'is measured from Zurich, Switzerland.' || CHR(10) ||
                     osag_notify.email_signature();

        RETURN v_message;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
