-- Oracle package 'OSAG_PERMISSION' declaration, please edit to match PostgreSQL syntax.

DROP SCHEMA IF EXISTS osag_permission CASCADE;
CREATE SCHEMA IF NOT EXISTS osag_permission;





CREATE OR REPLACE FUNCTION osag_permission.check_access (p_full_table_name text, p_id bigint, p_check_update boolean, p_test_column_name text) RETURNS boolean AS $body$
DECLARE


        v_count bigint;
        v_query varchar(1000);
        v_return boolean := FALSE;

BEGIN
        
        IF (p_full_table_name IS NULL OR
            NOT regexp_match(UPPER(p_full_table_name), '^[A-Z_0-9]+\.[A-Z_0-9]+$','n') IS NOT NULL) THEN
            RAISE EXCEPTION '%', 'Incorrect format for full table name: ' || coalesce(p_full_table_name, '<NULL>') USING ERRCODE = OSAG_PERMISSION_STATE.S_ERRNO_INVALID_PARAMETER;
        END IF;

        IF (p_id IS NULL) THEN
            RAISE EXCEPTION '%', 'ID not allowed: <NULL>' USING ERRCODE = OSAG_PERMISSION_STATE.S_ERRNO_INVALID_PARAMETER;
        END IF;

        IF (p_check_update) THEN
            SAVEPOINT update_test;
            BEGIN
                v_query  := 'UPDATE ' || p_full_table_name || ' SET ' || p_test_column_name || ' = ' || p_test_column_name || '  WHERE id = ' || p_id;
                EXECUTE v_query;
                GET DIAGNOSTICS v_return = ROW_COUNT > 0;

                ROLLBACK TO update_test;
            EXCEPTION
                WHEN OTHERS THEN
                    ROLLBACK TO update_test;
                    IF SQLSTATE = -942 THEN

                        v_return := FALSE;
                    ELSE
                        RAISE EXCEPTION '%', 'Could not execute dynamic query: ' || v_query USING ERRCODE = OSAG_PERMISSION_STATE.S_ERRNO_INVALID_PARAMETER;
                    END IF;
            END;
        ELSE
            BEGIN
                v_query  := 'SELECT COUNT(*) FROM ' || p_full_table_name || ' WHERE id = ' || p_id;
                EXECUTE v_query INTO STRICT v_count;
                v_return := v_count > 0;
            EXCEPTION
                WHEN OTHERS THEN
                    IF SQLSTATE = -942 THEN

                        v_return := FALSE;
                    ELSE
                        RAISE EXCEPTION '%', 'Could not execute dynamic query: ' || v_query USING ERRCODE = OSAG_PERMISSION_STATE.S_ERRNO_INVALID_PARAMETER;
                    END IF;
            END;
        END IF;

        IF (NOT v_return) THEN
            RAISE EXCEPTION '%', CASE WHEN p_check_update THEN 'Write' ELSE 'Read' END ||
                                    ' access denied: ' || p_full_table_name || '[' || p_id || ']' ||
                                    ' to current login: ' || sys_context(OSAG_WEBCONTEXT_STATE.WEB_CONTEXT, OSAG_WEBCONTEXT_STATE.CURRENT_LOGIN_ID) ||
                                    ' (real login: ' || sys_context(OSAG_WEBCONTEXT_STATE.WEB_CONTEXT, OSAG_WEBCONTEXT_STATE.REAL_LOGIN_ID) || ')' USING ERRCODE = OSAG_PERMISSION_STATE.S_ERRNO_ACCESS_DENIED;
        END IF;

        RETURN TRUE;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
 STABLE;
-- REVOKE ALL ON FUNCTION osag_permission.check_access (p_full_table_name text, p_id bigint, p_check_update boolean, p_test_column_name text) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_permission.can_read (p_full_table_name text, p_id bigint) RETURNS boolean AS $body$
BEGIN
        RETURN osag_permission.check_access(p_full_table_name, p_id, FALSE, 'id');
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
 STABLE;
-- REVOKE ALL ON FUNCTION osag_permission.can_read (p_full_table_name text, p_id bigint) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_permission.can_write (p_full_table_name text, p_id bigint, p_test_column_name text DEFAULT 'id') RETURNS boolean AS $body$
BEGIN
        RETURN osag_permission.check_access(p_full_table_name, p_id, TRUE, p_test_column_name);
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
 STABLE;
-- REVOKE ALL ON FUNCTION osag_permission.can_write (p_full_table_name text, p_id bigint, p_test_column_name text DEFAULT 'id') FROM PUBLIC;
-- End of Oracle package 'OSAG_PERMISSION' declaration



