DROP SCHEMA IF EXISTS osag_plog CASCADE;
CREATE SCHEMA IF NOT EXISTS osag_plog;





CREATE OR REPLACE PROCEDURE osag_plog.publishtomcdbqueue (user text, loglevel integer, message text, caller_info text DEFAULT '') AS $body$
DECLARE

        o_payload MCDB_MONITOR.PLOG_MESSAGE_TYPE;
        r_enqueue_options    DBMS_AQ.ENQUEUE_OPTIONS_T;
        r_message_properties DBMS_AQ.MESSAGE_PROPERTIES_T;
        v_message_handle     bytea;
        v_session_id bigint;

BEGIN
        v_session_id := SYS_CONTEXT('USERENV','SID');
        r_message_properties.expiration := 3600;
        o_payload :=  MCDB_MONITOR.PLOG_MESSAGE_TYPE(
                severity => osag_plog.levelasstring(loglevel),
                loglevel => loglevel,
                message => message,
                sender_user => user,
                sender_session => v_session_id,
                sender_proc => caller_info
            );

        DBMS_AQ.ENQUEUE(
                queue_name => 'MCDB_MONITOR.plog_messages',
                enqueue_options => r_enqueue_options,
                message_properties => r_message_properties,
                payload => o_payload,
                msgid => v_message_handle
            );
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_plog.publishtomcdbqueue (user text, loglevel integer, message text, caller_info text DEFAULT '') FROM PUBLIC;

--
-- dblink wrapper to call function osag_plog.log() as an autonomous transaction
--
CREATE EXTENSION IF NOT EXISTS dblink;

CREATE OR REPLACE PROCEDURE osag_plog.log (loglevel bigint, message text) AS $body$
DECLARE
	-- Change this to reflect the dblink connection string
	v_conn_str  text := format('port=%s dbname=%s user=%s', current_setting('port'), current_database(), current_user);
	v_query     text;

BEGIN
	v_query := 'CALL osag_plog.log_atx ( ' || quote_nullable(loglevel) || ',' || quote_nullable(message) || ' )';
	PERFORM * FROM dblink(v_conn_str, v_query) AS p (ret boolean);

END;
$body$ LANGUAGE plpgsql SECURITY DEFINER;




CREATE OR REPLACE PROCEDURE osag_plog.log_atx (loglevel bigint, message text) AS $body$
DECLARE

        v_ident varchar(64);
        v_user  varchar(32);
        v_caller varchar(1000);
        oname all_objects.owner%TYPE;
        pname all_objects.object_name%TYPE;
        lnumb all_source.line%TYPE;
        t_msg_record MCDB_MONITOR.PLOG_MESSAGE_TYPE;
        callr t_msg_record.SENDER_PROC%TYPE;
BEGIN
           CALL osag_plog.who_called_my_caller(oname, pname, lnumb, callr);
          v_caller := oname || chr(10) || pname || chr(10) || lnumb || chr(10) || callr;
          v_user := LOWER(user);
          v_ident := 'oracle';
          CALL osag_plog.publishtomcdbqueue(v_ident,loglevel,'(' || v_user || ') ' || message, v_caller);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_plog.log (loglevel bigint, message text) FROM PUBLIC; -- REVOKE ALL ON PROCEDURE osag_plog.log_atx (loglevel bigint, message text) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_plog.lograw (loglevel bigint, message text) AS $body$
BEGIN
        CALL osag_plog.publishtomcdbqueue('oracle',loglevel,message, '');
