CREATE OR REPLACE FUNCTION osag_plog.levelasstring (loglevel bigint) RETURNS varchar AS $body$
DECLARE

        v_levelname varchar(16) := NULL;

BEGIN
        IF loglevel = 0 THEN v_levelname := 'EMERG';END IF;
        IF loglevel = 1 THEN v_levelname := 'ALERT';END IF;
        IF loglevel = 2 THEN v_levelname := 'CRIT';END IF;
        IF loglevel = 3 THEN v_levelname := 'ERR';END IF;
        IF loglevel = 4 THEN v_levelname := 'WARNING';END IF;
        IF loglevel = 5 THEN v_levelname := 'NOTICE';END IF;
        IF loglevel = 6 THEN v_levelname := 'INFO';END IF;
        IF loglevel = 7 THEN v_levelname := 'DEBUG';END IF;
        return v_levelname;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
 STABLE;
-- REVOKE ALL ON FUNCTION osag_plog.levelasstring (loglevel bigint) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_plog.levelasnum (loglevel text) RETURNS bigint AS $body$
DECLARE

        v_level smallint := NULL;

BEGIN
        IF UPPER(loglevel) = 'EMERG'   THEN v_level :=0;END IF;
        IF UPPER(loglevel) = 'ALERT'   THEN v_level :=1;END IF;
        IF UPPER(loglevel) = 'CRIT'    THEN v_level :=2;END IF;
        IF UPPER(loglevel) = 'ERR'     THEN v_level :=3;END IF;
        IF UPPER(loglevel) = 'WARNING' THEN v_level :=4;END IF;
        IF UPPER(loglevel) = 'NOTICE'  THEN v_level :=5;END IF;
        IF UPPER(loglevel) = 'INFO'    THEN v_level :=6;END IF;
        IF UPPER(loglevel) = 'DEBUG'   THEN v_level :=7;END IF;
        return v_level;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION osag_plog.levelasnum (loglevel text) FROM PUBLIC;

--
-- dblink wrapper to call function osag_plog.auditusage() as an autonomous transaction
--
CREATE EXTENSION IF NOT EXISTS dblink;

CREATE OR REPLACE PROCEDURE osag_plog.auditusage (p_owner text, p_object_type text, p_object_name text) AS $body$
DECLARE
	-- Change this to reflect the dblink connection string
	v_conn_str  text := format('port=%s dbname=%s user=%s', current_setting('port'), current_database(), current_user);
	v_query     text;

BEGIN
	v_query := 'CALL osag_plog.auditusage_atx ( ' || quote_nullable(p_owner) || ',' || quote_nullable(p_object_type) || ',' || quote_nullable(p_object_name) || ' )';
	PERFORM * FROM dblink(v_conn_str, v_query) AS p (ret boolean);

END;
$body$ LANGUAGE plpgsql SECURITY DEFINER;




CREATE OR REPLACE PROCEDURE osag_plog.auditusage_atx (p_owner text, p_object_type text, p_object_name text) AS $body$
DECLARE
qname utl_call_stack.UNIT_QUALIFIED_NAME;
        v_proc varchar(128);

BEGIN
        
        qname := utl_call_stack.subprogram(2);
        if qname.count > 1 then
            v_proc := utl_call_stack.subprogram(2)(2);
        else
            v_proc := null;
        end if;

        update osag.plsql_audit
        set last_used = statement_timestamp()
        where owner = p_owner
          and object_type = REPLACE(p_object_type, ' BODY', '')
          and object_name = p_object_name
          and (  (v_proc is null and procedure_name is null)
            or (v_proc = procedure_name))
          and (   (last_used is null)
            or (last_used < statement_timestamp() - 1));
        commit;
    EXCEPTION
        when others then
            rollback;
    END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE osag_plog.auditusage (p_owner text, p_object_type text, p_object_name text) FROM PUBLIC; -- REVOKE ALL ON PROCEDURE osag_plog.auditusage_atx (p_owner text, p_object_type text, p_object_name text) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_plog.who_called_my_caller ( owner out text, name out text, lineno out bigint, caller_t out text ) AS $body$
DECLARE

        call_stack  varchar(4096) := dbms_utility.format_call_stack;
        n           bigint;
        found_stack boolean := FALSE;
        line        varchar(255);
        t           varchar(255);
        cnt         bigint := 0;

        NL_CHAR constant varchar(10) := chr(10);

BEGIN
        
        loop
            n := position(NL_CHAR  in call_stack);
            exit when( cnt = 4 or n is NULL or n = 0 );

            line := ltrim(substr( call_stack, 1, n-1 ));
            call_stack := substr( call_stack, n+1 );

            if ( NOT found_stack ) then
                if ( line like '%handle%number%name%' ) then
                    found_stack := TRUE;
                end if;
            else
                cnt := cnt + 1;

                
                
                if ( cnt = 4 ) then
                    
                    
                    
                    n := position(' ' in line);
                    if (n > 0)
                    then
                        t := ltrim(substr(line, n));
                        n := position(' ' in t);
                    end if;
                    if (n > 0)
                    then
                        lineno := (substr(t, 1, n - 1))::numeric;
                        line := ltrim(substr(t, n));
                    else
                        lineno := 0;
                    end if;
                    if ( line like 'pr%' ) then
                        n := length( 'procedure ' );
                    elsif ( line like 'fun%' ) then
                        n := length( 'function ' );
                    elsif ( line like 'package body%' ) then
                        n := length( 'package body ' );
                    elsif ( line like 'pack%' ) then
                        n := length( 'package ' );
                    elsif ( line like 'anon%' ) then
                        n := length( 'anonymous block ' );
                    else
                        n:=0;
                    end if;

                    if (n = 0) then

                        caller_t := ltrim(rtrim(upper(substr(line, n+1))));
                    else
                        caller_t := ltrim(rtrim(upper(substr(line,1,n-1))));
                    end if;

                    line := substr( line, n );
                    n := position('.'  in line);
                    owner := ltrim(rtrim(substr( line, 1, n-1 )));
                    name  := ltrim(rtrim(substr( line, n+1 )));
                end if;
            end if;
        end loop;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_plog.who_called_my_caller ( owner out text, name out text, lineno out bigint, caller_t out text ) FROM PUBLIC;
-- End of Oracle package 'OSAG_PLOG' declaration



