CREATE OR REPLACE PROCEDURE osag_tt_webrls.change_deferral_date (p_ticket_id bigint, p_contact_id bigint, p_defer_date timestamp(0), p_details_public tt.event.details_public%TYPE) AS $body$
BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        IF ((WEBRLS.OSAG_PERMISSION.can_write('tt.ticket', p_ticket_id, 'priority')) AND (WEBRLS.OSAG_PERMISSION.can_read('stop.contact', p_contact_id))) THEN
            CALL TT.TICKET_INTERFACE.change_deferral_date(p_ticket_id,
