CREATE OR REPLACE PROCEDURE osag_tt_webrls.add_history_event (p_event_id OUT bigint, p_ticket_id bigint, p_event_type_id bigint, p_host_id bigint, p_company_id bigint, p_details_public text, p_details_private text DEFAULT NULL, p_public_event bigint DEFAULT 1, p_contact_id bigint DEFAULT NULL, p_eventdate timestamp(0) DEFAULT clock_timestamp()) AS $body$
DECLARE


        v_public_event_boolean boolean;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        IF (WEBRLS.OSAG_PERMISSION.can_write('tt.ticket', p_ticket_id, 'priority')) THEN
            IF (p_public_event = 1) THEN
                v_public_event_boolean := TRUE;
            ELSE
                v_public_event_boolean := FALSE;
            END IF;
            TT.CALL EVENT_INTERFACE.add_history_event(p_event_id,
                                                 p_ticket_id,
                                                 p_event_type_id,
                                                 p_host_id,
                                                 p_company_id,
                                                 p_details_public,
                                                 p_details_private,
                                                 v_public_event_boolean,
                                                 p_eventdate,
                                                 p_contact_id);
        END IF;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
