CREATE OR REPLACE FUNCTION osag_vpn.get_illegal_tunnel_info ( i_host_id bigint ) RETURNS varchar AS $body$
DECLARE

        c_prefix         CONSTANT varchar(32) := 'get_illegal_tunnel_info';
        l_info           varchar(255) := NULL;

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        SELECT h1.name || ':' || i1.name || '/' || i3.name || ' -- ' || h2.name || ':' || i4.name INTO STRICT l_info
        FROM mss.host h1, mss.host h2, mss.interface i1, mss.interface i2, mss.interface i3, mss.interface i4,
             vpn.vpn_member m1, vpn.vpn_member m2, vpn.vpn_member m3, vpn.vpn_member m4,
             vpn.tunnel t1, vpn.tunnel t2
        WHERE h1.id = i1.host_id AND h1.id = i3.host_id
          AND h2.id = i2.host_id AND h2.id = i4.host_id
          AND m1.INTERFACE_ID = i1.id AND m2.INTERFACE_ID = i2.id AND m3.interface_id = i3.id AND m4.interface_id = i4.id
          AND t1.vpn_member_id1 = m1.id AND t1.vpn_member_id2 = m2.id
          AND t2.vpn_member_id1 = m3.id AND t2.vpn_member_id2 = m4.id
          AND i1.id != i3.id AND i2.id = i4.id
          AND t1.id < t2.id
          AND h1.id = i_host_id
          AND t1.tunnelmode != 0 AND t2.tunnelmode != 0;
        RETURN l_info;

    EXCEPTION
        WHEN no_data_found THEN
            RETURN NULL;
        WHEN OTHERS THEN
            plog.err(c_prefix||'unexpected error: '||sqlerrm);
            RETURN c_prefix||'internal error: '||sqlerrm;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
 STABLE;
-- REVOKE ALL ON FUNCTION osag_vpn.get_illegal_tunnel_info ( i_host_id bigint ) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_vpn.get_tunnelcost_by_id ( i_tunnel_id bigint ) RETURNS bigint AS $body$
DECLARE

        c_prefix         CONSTANT varchar(32) := 'get_tunnelcost_by_id: ';
        c_defaultcost    CONSTANT bigint := 100;
        c_hubreduction   CONSTANT bigint := 1;
        l_cost           bigint := c_defaultcost;
        l_cost_tunnel    bigint := NULL;
        l_cost_member1   bigint := NULL;
        l_cost_member2   bigint := NULL;
        l_cost_partition bigint := NULL;
        l_hub1           bigint := 0;
        l_hub2           bigint := 0;
        l_vpnid          bigint := 0;

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);


        

        BEGIN
            
            
            
            SELECT vm1.hub, vm2.hub, t.ospf_cost, vm1.ospf_cost, vm2.ospf_cost, p.ospf_cost
            INTO STRICT l_hub1, l_hub2, l_cost_tunnel, l_cost_member1, l_cost_member2, l_cost_partition
            FROM vpn.vpn_member vm1, vpn.vpn_member vm2, vpn.partition p, vpn.tunnel t
            WHERE t.id = i_tunnel_id
              AND t.vpn_member_id1 = vm1.id
              AND t.vpn_member_id2 = vm2.id
              AND p.id = vm2.partition_id
              AND p.id = vm1.partition_id;
        END;


        
        
        
        
        
        
        

        IF ( l_cost_tunnel IS NOT NULL ) THEN
            l_cost := l_cost_tunnel;
        ELSE
            IF ( l_cost_member1 IS NULL ) THEN
                IF ( l_cost_partition IS NULL ) THEN
                    l_cost_member1 := c_defaultcost;
                ELSE
                    l_cost_member1 := l_cost_partition;
                END IF;
                IF ( (l_hub1 = 1) AND (l_cost_member1 > (1+c_hubreduction)) ) THEN
                    l_cost_member1 := l_cost_member1 - c_hubreduction;
                END IF;
            END IF;
            IF ( l_cost_member2 IS NULL ) THEN
                IF ( l_cost_partition IS NULL ) THEN
                    l_cost_member2 := c_defaultcost;
                ELSE
                    l_cost_member2 := l_cost_partition;
                END IF;
                IF ( (l_hub2 = 1) AND (l_cost_member2 > (1+c_hubreduction)) ) THEN
                    l_cost_member2 := l_cost_member2 - c_hubreduction;
                END IF;
            END IF;
            l_cost := TRUNC ( ( l_cost_member1 + l_cost_member2 ) / 2);

        END IF;

        RETURN l_cost;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(c_prefix||'unexpected error [pos99]: '||sqlerrm);
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION osag_vpn.get_tunnelcost_by_id ( i_tunnel_id bigint ) FROM PUBLIC;



CREATE OR REPLACE FUNCTION osag_vpn.get_tunnelcost_partition ( i_partition_id bigint, i_hostid1 bigint, i_hostid2 bigint ) RETURNS bigint AS $body$
DECLARE

        c_prefix         CONSTANT varchar(32) := 'get_tunnelcost_partition: ';
        c_defaultcost    CONSTANT bigint := 100;
        c_hubreduction   CONSTANT bigint := 1;
        l_cost           bigint := c_defaultcost;
        l_cost_tunnel    bigint := NULL;
        l_cost_member1   bigint := NULL;
        l_cost_member2   bigint := NULL;
        l_cost_partition bigint := NULL;
        l_hub1           bigint := 0;
        l_hub2           bigint := 0;
        l_interface1     bigint := 0;
        l_interface2     bigint := 0;
        l_interface1_name varchar(32) := NULL;
        l_interface2_name varchar(32) := NULL;
        l_vpnid          bigint := 0;
        i_first_tunnel   bigint := 0;
        tmp_cost         bigint := 0;

  v_tunnel_data RECORD;

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        
        BEGIN
            
            
            
            
            
            
            
            
            
            
            FOR v_tunnel_data IN (
                SELECT i1.id as id1, i1.name as name1, i2.id id2, i2.name as name2, p.vpn_id as vpn_id, t.ospf_cost as cost
                FROM vpn.vpn_member vm1, vpn.vpn_member vm2, mss.interface i1, mss.interface i2, vpn.tunnel t, vpn.partition p
                WHERE
                        p.id = i_partition_id
                  AND vm1.partition_id = i_partition_id
                  AND vm2.partition_id = i_partition_id
                  AND t.vpn_member_id1 = vm1.id
                  AND t.vpn_member_id2 = vm2.id
                  AND vm1.interface_id = i1.id
                  AND vm2.interface_id = i2.id
                  AND i1.host_id = i_hostid1
                  AND i2.host_id = i_hostid2
                )
                LOOP
                    IF ( ( i_first_tunnel = 0 ) OR ( v_tunnel_data.cost IS NOT NULL AND v_tunnel_data.cost < tmp_cost ) ) THEN
                        l_interface1 := v_tunnel_data.id1;
                        l_interface1_name := v_tunnel_data.name1;
                        l_interface2 := v_tunnel_data.id2;
                        l_interface2_name := v_tunnel_data.name2;
                        l_vpnid := v_tunnel_data.vpn_id;
                        tmp_cost := v_tunnel_data.cost;
                        i_first_tunnel := 1;
                    END IF;
                END LOOP;
        END;

        BEGIN

            
            
            
            

            SELECT vm1.hub, vm2.hub, t.ospf_cost, vm1.ospf_cost, vm2.ospf_cost, p.ospf_cost
            INTO STRICT l_hub1, l_hub2, l_cost_tunnel, l_cost_member1, l_cost_member2, l_cost_partition
            FROM vpn.vpn_member vm1, mss.interface i1, vpn.vpn_member vm2, mss.interface i2,
                 vpn.partition p, vpn.tunnel t
            WHERE vm1.partition_id = p.id AND vm2.partition_id = p.id
              AND t.vpn_member_id1 = vm1.id
              AND t.vpn_member_id2 = vm2.id
              AND vm2.interface_id = i2.id
              AND vm1.interface_id = i1.id
              AND i1.host_id = i_hostid1
              AND i2.host_id = i_hostid2
              AND i1.id = l_interface1
              AND i2.id = l_interface2
              AND p.vpn_id = l_vpnid;

        EXCEPTION
            WHEN too_many_rows THEN
                plog.err(c_prefix||'multiple vpn tunnels between hosts:interfaces '||i_hostid1||':'||l_interface1_name||' and '||i_hostid2||':'||l_interface2_name);
            WHEN no_data_found THEN
                NULL;
        END;


        
        
        
        
        
        
        

        IF ( l_cost_tunnel IS NOT NULL ) THEN
            l_cost := l_cost_tunnel;
        ELSE
            IF ( l_cost_member1 IS NULL ) THEN
                IF ( l_cost_partition IS NULL ) THEN
                    l_cost_member1 := c_defaultcost;
                ELSE
                    l_cost_member1 := l_cost_partition;
                END IF;
                IF ( (l_hub1 = 1) AND (l_cost_member1 > (1+c_hubreduction)) ) THEN
                    l_cost_member1 := l_cost_member1 - c_hubreduction;
                END IF;
            END IF;
            IF ( l_cost_member2 IS NULL ) THEN
                IF ( l_cost_partition IS NULL ) THEN
                    l_cost_member2 := c_defaultcost;
                ELSE
                    l_cost_member2 := l_cost_partition;
                END IF;
                IF ( (l_hub2 = 1) AND (l_cost_member2 > (1+c_hubreduction)) ) THEN
                    l_cost_member2 := l_cost_member2 - c_hubreduction;
                END IF;
            END IF;
            l_cost := TRUNC ( ( l_cost_member1 + l_cost_member2 ) / 2);

        END IF;

        RETURN l_cost;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(c_prefix||'unexpected error [pos99]: '||sqlerrm);
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION osag_vpn.get_tunnelcost_partition ( i_partition_id bigint, i_hostid1 bigint, i_hostid2 bigint ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_vpn.update_peer_status_sub ( i_host_id bigint, i_logdate timestamp(0), i_status bigint, i_csv text ) AS $body$
DECLARE

        c_prefix         CONSTANT varchar(64) := 'OSAG_VPN.update_peer_status_sub(): ';
        l_csv            varchar(16384);
        l_comma_pos      bigint := NULL;
        l_tunnel_id      varchar(64);

BEGIN

        l_csv := i_csv;
        WHILE( LENGTH(l_csv)>0 ) LOOP


                BEGIN
                    
                    IF ( NOT( l_csv LIKE 't4_%' OR l_csv LIKE 't6_%' ) )
                    THEN
                        RAISE EXCEPTION 'e_abort' USING ERRCODE = '50002';
                    END IF;

                    l_comma_pos      := INSTR(l_csv, ',', 1, 1);
                    IF ( l_comma_pos = 0 ) THEN
                        l_tunnel_id := l_csv;
                        l_tunnel_id := SUBSTR(l_csv,4);
                        l_csv := '';
                    ELSIF ( l_comma_pos < 5 ) THEN
                        RAISE EXCEPTION 'e_abort' USING ERRCODE = '50002';
                    ELSE
                        l_tunnel_id := SUBSTR(l_csv,4,l_comma_pos-4);
                        l_csv := substr(l_csv, l_comma_pos + 1);
                    END IF;
                EXCEPTION
                    WHEN OTHERS THEN
                        plog.err(c_prefix||'error parsing list of tunnel names: '||l_csv||', host_id='||i_host_id||', '||sqlerrm);
                        RAISE EXCEPTION 'e_abort' USING ERRCODE = '50002';
                END;


                BEGIN
                    UPDATE vpn.tunnel set status=i_status, status_date=i_logdate
                    WHERE id = l_tunnel_id;
                EXCEPTION
                    WHEN OTHERS THEN
                        plog.err(c_prefix||'unable to update tunnel: host_id='||i_host_id||', tunnel_id='||l_tunnel_id||': '||sqlerrm);
                END;
            END LOOP;
    EXCEPTION
        WHEN SQLSTATE '50002' THEN
            NULL;
        WHEN OTHERS THEN
            plog.err(c_prefix||'unexpected error: '||sqlerrm);
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_vpn.update_peer_status_sub ( i_host_id bigint, i_logdate timestamp(0), i_status bigint, i_csv text ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE osag_vpn.update_peer_status ( i_host_id bigint, i_logdate timestamp(0), i_default_status bigint, i_csv_unknown_peers text, i_csv_down_peers text, i_csv_up_peers text, i_csv_slow_peers text ) AS $body$
DECLARE

        c_prefix         CONSTANT varchar(32) := 'OSAG_VPN.update_peer_status(): ';

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        
        
        
        

        BEGIN
            UPDATE vpn.tunnel SET status=i_default_status, status_date=i_logdate WHERE id IN (
                SELECT t.id FROM vpn.tunnel t, vpn.vpn_member vm1, mss.interface i1
                WHERE t.vpn_member_id1 = vm1.id
                  AND vm1.interface_id = i1.id
                  AND i1.host_id = i_host_id
                  AND t.status IS NOT NULL
            );
        EXCEPTION
            WHEN OTHERS THEN
                plog.err(c_prefix||'cannot set default status to '||i_default_status||' for all tunnels of host '||i_host_id||': '||sqlerrm);
                RAISE EXCEPTION 'e_abort' USING ERRCODE = '50002';
        END;


        

        IF ( i_csv_unknown_peers IS NOT NULL ) THEN
            CALL osag_vpn.update_peer_status_sub(i_host_id,i_logdate,NULL,i_csv_unknown_peers);
        END IF;

        IF ( i_csv_down_peers IS NOT NULL ) THEN
            CALL osag_vpn.update_peer_status_sub(i_host_id,i_logdate,0,i_csv_down_peers);
        END IF;

        IF ( i_csv_up_peers IS NOT NULL ) THEN
            CALL osag_vpn.update_peer_status_sub(i_host_id,i_logdate,1,i_csv_up_peers);
        END IF;

        IF ( i_csv_slow_peers IS NOT NULL ) THEN
            CALL osag_vpn.update_peer_status_sub(i_host_id,i_logdate,2,i_csv_slow_peers);
        END IF;

    EXCEPTION
        WHEN SQLSTATE '50002' THEN
            NULL;
        WHEN OTHERS THEN
            plog.err(c_prefix||'unexpected error: '||sqlerrm);
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE osag_vpn.update_peer_status ( i_host_id bigint, i_logdate timestamp(0), i_default_status bigint, i_csv_unknown_peers text, i_csv_down_peers text, i_csv_up_peers text, i_csv_slow_peers text ) FROM PUBLIC;
