-- Oracle package 'SECONDARY_ISP' declaration, please edit to match PostgreSQL syntax.

DROP SCHEMA IF EXISTS secondary_isp CASCADE;
CREATE SCHEMA IF NOT EXISTS secondary_isp;






CREATE OR REPLACE PROCEDURE secondary_isp.get_next_token ( i_delim text, i_string text, o_token OUT text, o_rest OUT text ) AS $body$
DECLARE

        C_PREFIX      CONSTANT varchar(64) := 'SECONDARY_ISP.get_next_token(): ';
        l_pos         bigint;


BEGIN
        o_token := NULL;
        o_rest := NULL;


        IF (LENGTH(i_string) = 0) THEN
            RETURN;
        END IF;

        l_pos := INSTR(i_string, i_delim, 1, 1);


        IF (l_pos = 0) THEN
            o_token := i_string;
            RETURN;
        END IF;

        IF (l_pos != 1) THEN
            o_token := substr(i_string, 0, l_pos - 1);
        END IF;

        IF ((l_pos + LENGTH(i_delim)) <= LENGTH(i_string)) THEN
            o_rest := substr(i_string, l_pos + length(i_delim));
        END IF;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(C_PREFIX||'unexpected error 99: '||sqlerrm);
            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE secondary_isp.get_next_token ( i_delim text, i_string text, o_token OUT text, o_rest OUT text ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE secondary_isp.secondaryisp_parse_syslog ( i_host_id mss.host.id%TYPE, i_data syslog_message.message%TYPE, o_interface OUT text, o_peers OUT text, o_since OUT text ) AS $body$
DECLARE

        C_PREFIX           CONSTANT varchar(64) := 'SECONDARY_ISP.secondaryisp_parse_syslog(): ';
        l_before_token     syslog_message.message%TYPE;
        l_after_token      syslog_message.message%TYPE;

BEGIN
        
         CALL secondary_isp.get_next_token('NURSE:SECONDARYISP:', i_data, l_before_token, l_after_token);
        IF (l_after_token IS NULL) THEN
            plog.err(C_PREFIX||'can''t  parse NURSE:SECONDARYISP:ALERT line (1): '||i_data);
            RAISE EXCEPTION 'e_abort' USING ERRCODE = '50002';
        END IF;


         CALL secondary_isp.get_next_token('(interface=', l_after_token, l_before_token, l_after_token);
        IF (l_after_token IS NULL) THEN
            plog.err(C_PREFIX||'can''t  parse NURSE:SECONDARYISP:ALERT line (2): '||i_data);
            RAISE EXCEPTION 'e_abort' USING ERRCODE = '50002';
        END IF;


         CALL secondary_isp.get_next_token(', peers=', l_after_token, l_before_token, l_after_token);
        IF (l_after_token IS NULL) THEN
            plog.err(C_PREFIX||'can''t  parse NURSE:SECONDARYISP:ALERT line (3): '||i_data);
            RAISE EXCEPTION 'e_abort' USING ERRCODE = '50002';
        END IF;

        o_interface := l_before_token;


         CALL secondary_isp.get_next_token(') [state=', l_after_token, l_before_token, l_after_token);
        IF (l_after_token IS NULL) THEN
            plog.err(C_PREFIX||'can''t  parse NURSE:SECONDARYISP:ALERT line (4): '||i_data);
            RAISE EXCEPTION 'e_abort' USING ERRCODE = '50002';
        END IF;

        o_peers := l_before_token;


         CALL secondary_isp.get_next_token('observed=', l_after_token, l_before_token, l_after_token);
        IF (l_after_token IS NULL) THEN
            plog.err(C_PREFIX||'can''t  parse NURSE:SECONDARYISP:ALERT line (5): '||i_data);
            RAISE EXCEPTION 'e_abort' USING ERRCODE = '50002';
        END IF;


         CALL secondary_isp.get_next_token(']', l_after_token, l_before_token, l_after_token);
        o_since := l_before_token;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE secondary_isp.secondaryisp_parse_syslog ( i_host_id mss.host.id%TYPE, i_data syslog_message.message%TYPE, o_interface OUT text, o_peers OUT text, o_since OUT text ) FROM PUBLIC;



CREATE OR REPLACE FUNCTION secondary_isp.is_host_up ( i_host_id mss.host.id%TYPE ) RETURNS boolean AS $body$
DECLARE

        C_PREFIX           CONSTANT varchar(64) := 'SECONDARY_ISP.is_host_up(): ';

        l_con_int_type_id  mc.mon_server_connection.status%TYPE;

BEGIN
        
        
        
        

        SELECT status INTO STRICT l_con_int_type_id
        FROM mc.mon_server_connection
        WHERE mon_server_id IS NULL AND host_id = i_host_id;

        IF l_con_int_type_id IS NULL THEN
            RETURN TRUE;
        ELSE
            RETURN FALSE;
        END IF;

    EXCEPTION
        WHEN no_data_found THEN

            RETURN FALSE;
        WHEN OTHERS THEN
            plog.err(C_PREFIX||'error: '||sqlerrm);
            RAISE EXCEPTION 'e_abort' USING ERRCODE = '50002';
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION secondary_isp.is_host_up ( i_host_id mss.host.id%TYPE ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE secondary_isp.secondaryisp_interface_info ( i_host_id mss.host.id%TYPE, i_interface_name mss.interface.name%TYPE, o_interface_desc OUT mss.interface.description%TYPE, o_wan_managed OUT mss.isp_link.wan_managed%TYPE, o_isp_company OUT stop.company.name%TYPE ) AS $body$
DECLARE

        C_PREFIX           CONSTANT varchar(64) := 'SECONDARY_ISP.secondary_interface_info(): ';

BEGIN
        SELECT i.description,    isp.wan_managed, ispc.name
        INTO STRICT o_interface_desc, o_wan_managed,   o_isp_company
        FROM mss.interface i
                 JOIN mss.interface2isp_link i2isp ON i2isp.interface_id = i.id
                 JOIN mss.isp_link isp ON isp.id = i2isp.isp_link_id
                 JOIN stop.company ispc ON isp.company_id = ispc.id
        WHERE i.host_id = i_host_id AND i.name = i_interface_name;

    EXCEPTION
        WHEN no_data_found THEN
            plog.err(C_PREFIX||'can''t get information about interface '||i_interface_name||' of host '||i_host_id);
            RAISE EXCEPTION 'e_abort' USING ERRCODE = '50002';
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE secondary_isp.secondaryisp_interface_info ( i_host_id mss.host.id%TYPE, i_interface_name mss.interface.name%TYPE, o_interface_desc OUT mss.interface.description%TYPE, o_wan_managed OUT mss.isp_link.wan_managed%TYPE, o_isp_company OUT stop.company.name%TYPE ) FROM PUBLIC;



CREATE OR REPLACE FUNCTION secondary_isp.is_secondaryisp_all_peers_down ( i_peers text ) RETURNS boolean AS $body$
DECLARE

        l_before_token     syslog_message.message%TYPE;
        l_after_token      syslog_message.message%TYPE;
        l_peer_host_id     mss.host.id%TYPE;

BEGIN
        l_after_token := i_peers;
        WHILE l_after_token IS NOT NULL
            LOOP
                 CALL secondary_isp.get_next_token('|', l_after_token, l_before_token, l_after_token);
                l_peer_host_id := (l_before_token)::numeric;
                IF secondary_isp.is_host_up(l_peer_host_id) THEN
                    RETURN FALSE;
                END IF;
            END LOOP;

        RETURN TRUE;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION secondary_isp.is_secondaryisp_all_peers_down ( i_peers text ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE secondary_isp.comma_join ( io_string INOUT text, i_element text ) AS $body$
BEGIN
        IF io_string IS NULL THEN
            io_string := i_element;
        ELSE
            io_string := io_string || ', ' || i_element;
        END IF;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE secondary_isp.comma_join ( io_string INOUT text, i_element text ) FROM PUBLIC;



CREATE OR REPLACE FUNCTION secondary_isp.pretty_print_host_id_list ( i_peers text ) RETURNS varchar AS $body$
DECLARE

        l_before_token     syslog_message.message%TYPE;
        l_after_token      syslog_message.message%TYPE;
        l_host_id          mss.host.id%TYPE;
        l_host_name        mss.host.name%TYPE;
        l_pretty_string    varchar(4096) := '';

BEGIN
        l_after_token := i_peers;
        WHILE l_after_token IS NOT NULL
            LOOP
                 CALL secondary_isp.get_next_token('|', l_after_token, l_before_token, l_after_token);
                l_host_id := (l_before_token)::numeric;


                BEGIN
                    SELECT host.name INTO STRICT l_host_name
                    FROM  mss.host
                    WHERE host.id = l_host_id;


                    
                    
                     CALL secondary_isp.comma_join(l_pretty_string, l_host_name);

                EXCEPTION
                    WHEN no_data_found THEN

                         CALL secondary_isp.comma_join(l_pretty_string, 'unknown(hostid:'||l_host_id||')');
                END;
            END LOOP;

        RETURN l_pretty_string;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION secondary_isp.pretty_print_host_id_list ( i_peers text ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE secondary_isp.secondaryisp_alert ( i_host_id mss.host.id%TYPE, i_logdate syslog_message.log_date%TYPE, i_data syslog_message.message%TYPE ) AS $body$
DECLARE

        C_PREFIX           CONSTANT varchar(64) := 'SECONDARY_ISP.secondaryisp_alert(): ';
        l_interface        syslog_message.message%TYPE;
        l_peers            syslog_message.message%TYPE;
        l_down_since       syslog_message.message%TYPE;
        l_wan_managed      mss.isp_link.wan_managed%TYPE;
        l_interface_desc   mss.interface.description%TYPE;
        l_isp_company      stop.company.name%TYPE;
        l_event_id         bigint;

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

         CALL secondary_isp.secondaryisp_parse_syslog(i_host_id, i_data, l_interface, l_peers, l_down_since);


         CALL secondary_isp.secondaryisp_interface_info(i_host_id, l_interface,
                                    l_interface_desc, l_wan_managed, l_isp_company);


        IF l_wan_managed = 0 THEN
            plog.notice(C_PREFIX||'Ignoring secondary ISP outage, because not WAN managed (host: '||i_host_id||', interface: '||l_interface||')');
            RAISE EXCEPTION 'e_abort' USING ERRCODE = '50002';
        END IF;


        
        IF secondary_isp.is_secondaryisp_all_peers_down(l_peers) THEN
            plog.notice(C_PREFIX||'Ignoring secondary ISP outage, because all peers down (host: '||i_host_id||', interface: '||l_interface||')');
            RAISE EXCEPTION 'e_abort' USING ERRCODE = '50002';
        END IF;


        TT.CALL event_interface.newevent_new(
                l_event_id,
                current_setting('secondary_isp.c_sec_isp_outage_event_type')::bigint,
                i_host_id,
            
                'Secondary ISP Outage'||CHR(10)||
                CHR(10)||
                'All VPN tunnels through one ISP link are down. This could mean that the ISP link is down.'||CHR(10)||
                CHR(10)||
                'Open Systems Mission Control will start the WAN Management ISP Down process.'||CHR(10)||
                CHR(10)||
                'Host:       '||secondary_isp.pretty_print_host_id_list(i_host_id)||CHR(10)||
                'Interface:  '||l_interface||' ('||l_interface_desc||')'||CHR(10)||
                'ISP name:   '||l_isp_company||CHR(10)||
                'VPN peers:  '||secondary_isp.pretty_print_host_id_list(l_peers)||CHR(10)||
                'Down since: '||l_down_since||CHR(10)
            ,
            
                'This host is subscribed to WAN Management.'||CHR(10)||
                CHR(10)||
                'To Do:'||CHR(10)||
                CHR(10)||
                'Execute this process: https://control.open.ch/docs/x/wBlbB'
            );

    EXCEPTION
        WHEN SQLSTATE '50002' THEN
            NULL;
        WHEN OTHERS THEN
            plog.err(C_PREFIX||'unexpected error 99: '||sqlerrm);
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE secondary_isp.secondaryisp_alert ( i_host_id mss.host.id%TYPE, i_logdate syslog_message.log_date%TYPE, i_data syslog_message.message%TYPE ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE secondary_isp.secondaryisp_ok ( i_host_id mss.host.id%TYPE, i_logdate syslog_message.log_date%TYPE, i_data syslog_message.message%TYPE ) AS $body$
DECLARE

        C_PREFIX           CONSTANT varchar(64) := 'SECONDARY_ISP.secondaryisp_ok(): ';
        l_interface        syslog_message.message%TYPE;
        l_peers            syslog_message.message%TYPE;
        l_up_since       syslog_message.message%TYPE;
        l_wan_managed      mss.isp_link.wan_managed%TYPE;
        l_interface_desc   mss.interface.description%TYPE;
        l_isp_company      stop.company.name%TYPE;
        l_event_id         bigint;
        l_unresolved_ticket_id   tt.ticket.id%TYPE;

        l_unresolved_ticket_cur CURSOR FOR
            SELECT t.id
            FROM tt.ticket t
            WHERE t.status_id < 100 AND host_id = i_host_id
            ORDER BY t.id DESC;

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

         CALL secondary_isp.secondaryisp_parse_syslog(i_host_id, i_data, l_interface, l_peers, l_up_since);


         CALL secondary_isp.secondaryisp_interface_info(i_host_id, l_interface,
                                    l_interface_desc, l_wan_managed, l_isp_company);



        IF l_wan_managed = 0 THEN
            plog.notice(C_PREFIX||'Ignoring secondary ISP ok event, because not WAN managed (host: '||i_host_id||', interface: '||l_interface||')');
            RAISE EXCEPTION 'e_abort' USING ERRCODE = '50002';
        END IF;


        
        
        
        
        
        
        
        
        
        
        
        
        
        

        OPEN l_unresolved_ticket_cur;
        FETCH l_unresolved_ticket_cur INTO l_unresolved_ticket_id;
        CLOSE l_unresolved_ticket_cur;

        IF l_unresolved_ticket_id IS NULL THEN

            plog.notice(C_PREFIX||'Ignoring secondary ISP ok event, because no unresolved ticket was found (host: '||i_host_id||', interface: '||l_interface||')');
            RAISE EXCEPTION 'e_abort' USING ERRCODE = '50002';
        END IF;


        TT.CALL event_interface.newevent_new(
                l_event_id,
                current_setting('secondary_isp.c_sec_isp_ok_event_type')::bigint,
                i_host_id,
            
                'Secondary ISP OK'||CHR(10)||
                CHR(10)||
                'One or more VPN tunnels through one ISP link are up. The ISP link is thus apparently up.'||CHR(10)||
                CHR(10)||
                'The WAN Management ISP Down process will be stopped.'||CHR(10)||
                CHR(10)||
                'Host:       '||secondary_isp.pretty_print_host_id_list(i_host_id)||CHR(10)||
                'Interface:  '||l_interface||' ('||l_interface_desc||')'||CHR(10)||
                'ISP name:   '||l_isp_company||CHR(10)||
                'VPN peers:  '||secondary_isp.pretty_print_host_id_list(l_peers)||CHR(10)||
                'Up since:   '||l_up_since||CHR(10)
            ,
            
                'To Do:'||CHR(10)||
                CHR(10)||
                'Try to find a corresponding "Secondary ISP Outage" event. If there isn''t one, fast-resolve.'
            );
    EXCEPTION
        WHEN SQLSTATE '50002' THEN
            NULL;
        WHEN OTHERS THEN
            plog.err(C_PREFIX||'unexpected error: '||sqlerrm);
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE secondary_isp.secondaryisp_ok ( i_host_id mss.host.id%TYPE, i_logdate syslog_message.log_date%TYPE, i_data syslog_message.message%TYPE ) FROM PUBLIC;
-- End of Oracle package 'SECONDARY_ISP' declaration



-- Oracle package 'TICKET_INTERFACE' declaration, please edit to match PostgreSQL syntax.

DROP SCHEMA IF EXISTS ticket_interface CASCADE;
CREATE SCHEMA IF NOT EXISTS ticket_interface;





CREATE OR REPLACE PROCEDURE ticket_interface.newticket_new (p_ticket_id OUT bigint, p_event_id OUT bigint, p_ticket_type_id bigint, p_subject text, p_event_type_id bigint, p_host_id bigint, p_details_public text, p_details_private text DEFAULT NULL, p_contact_id bigint DEFAULT NULL, p_worker_id bigint DEFAULT NULL, p_public_event boolean DEFAULT TRUE, p_eventdate timestamp(0) DEFAULT clock_timestamp(), p_company_id bigint DEFAULT NULL, p_service_component_id bigint DEFAULT NULL) AS $body$
DECLARE


        v_pub_event bigint;
        v_company_id bigint;
        v_contact_id bigint;
        v_event_id bigint;
        v_event_source_id bigint;
        v_confirmed bigint;
        v_fast_resolvable bigint;
        v_contact_company_id bigint;
        v_details_public tt.event.details_public%TYPE;
        v_details_private tt.event.details_private%TYPE;
        v_mss_service_id mss.service.id%TYPE;
        v_count bigint;
        v_ticket_type_id bigint;
        v_create_cr bigint;
        v_cr_id bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        v_ticket_type_id := p_ticket_type_id;

        IF (p_public_event) THEN
            v_pub_event:=1;
        ELSE
            v_pub_event:=0;
        END IF;


        IF (p_company_id IS NOT NULL) THEN
            v_company_id := p_company_id;
        END IF;


        
        IF (p_host_id is not null) THEN
            SELECT h.service_company_id INTO STRICT v_company_id
            FROM mss.host h
            WHERE h.id = p_host_id;
            SELECT h2s.service_id INTO STRICT v_mss_service_id
            FROM mss.host2service h2s
            WHERE h2s.host_id = p_host_id;

        END IF;


        
        IF (p_contact_id is not null) THEN
            SELECT company_id INTO STRICT v_company_id
            FROM stop.contact
            WHERE contact.id = p_contact_id;
        END IF;


        
        v_contact_id := p_contact_id;
        IF (p_host_id is null AND p_contact_id is not null) THEN

            SELECT count(*) INTO STRICT v_count
            FROM auth.permission p, auth.login l
            WHERE p.login_id = l.id
              AND l.contact_id = p_contact_id
              AND p.role_id = 2
              AND p.company_unit_id IS NULL
              AND p.user_unit_id IS NULL
              AND p.service_id IS NULL;
            IF (v_count = 0) THEN

                v_contact_id := NULL;
            END IF;
        END IF;


        v_confirmed := 0;
        v_fast_resolvable := 0;
        SELECT source INTO STRICT v_event_source_id FROM tt.event_type WHERE id = p_event_type_id;
        IF (v_event_source_id = 1) THEN
            v_confirmed := 1;
            v_fast_resolvable := 1;
        END IF;


        IF (p_worker_id IS NOT NULL) THEN
            SELECT company_id INTO STRICT v_contact_company_id FROM stop.contact WHERE id = p_worker_id;

            IF (v_contact_company_id = 6) THEN
                v_confirmed := 1;
            END IF;
        END IF;


        SELECT nextval('ticket_sequence') INTO STRICT p_ticket_id;
        SELECT nextval('event_sequence') INTO STRICT p_event_id;


        v_details_public := ticket_interface.replace_id_placeholders(p_details_public, p_ticket_id, p_event_id);
        v_details_private := ticket_interface.replace_id_placeholders(p_details_private, p_ticket_id, p_event_id);


        
        
        IF p_event_type_id IN (30005, 30011, 50002) AND v_details_public IS NOT NULL THEN
            v_details_public := p_subject || CHR(10) || CHR(10) || v_details_public;
        END IF;


        v_create_cr := 0;

        
        
        
        
        
        
        
        
        
        IF (p_event_type_id = 30002 AND p_contact_id is not null AND p_contact_id IN (224019, 1150408, 235692, 371508, 458818, 430183, 430181, 3598, 796216)) THEN
            
            v_create_cr := 1;

            v_ticket_type_id := 2;
        END IF;


        INSERT INTO ticket(id, type_id, contact_id, worker_id, company_id, host_id, subject, last_status_change_date,
                            mss_service_id, service_confirmed, type_confirmed, fast_resolvable, service_component_id)
        VALUES (p_ticket_id,
                v_ticket_type_id,
                v_contact_id,
                p_worker_id,
                v_company_id,
                p_host_id,
                SUBSTR(p_subject, 1, 100),
                clock_timestamp(),
                v_mss_service_id,
                v_confirmed,
                v_confirmed,
                v_fast_resolvable,
                p_service_component_id);


        UPDATE tt.ticket SET ux_timeout_start = (cast(open_date as timestamp) AT TIME ZONE 'EUROPE/ZURICH')::timestamp with time zone WHERE id = p_ticket_id;
        CALL ticket_interface.update_ux_timeout_for_ticket(p_ticket_id, TRUE);


        IF (p_worker_id is not NULL) THEN
            v_contact_id := p_worker_id;
        ELSIF (p_contact_id is not NULL) THEN
            v_contact_id := p_contact_id;
        ELSE
            v_contact_id := NULL;
        END IF;


        INSERT INTO event(id,type_id,host_id,eventdate,details_public,details_private,public_event, ticket_id, contact_id)
        VALUES (p_event_id,
                p_event_type_id,
                p_host_id,
                p_eventdate,
                v_details_public,
                v_details_private,
                v_pub_event,
                p_ticket_id,
                v_contact_id);


        IF (v_pub_event > 0 AND v_event_source_id NOT IN (2, 10)) THEN
            UPDATE tt.ticket SET last_public_event_id = p_event_id WHERE id = p_ticket_id;
        END IF;


        
        IF (v_pub_event > 0 AND v_event_source_id NOT IN (1,2,6,10)) THEN
            UPDATE tt.ticket
            SET summary_relevant_events_count = 1,
                todo_relevant_events_count = 1
            WHERE id = p_ticket_id;
        END IF;


        CALL TT.OSAG_NOTIFY.event_notify(p_event_id, p_ticket_id);


        tt.CALL event_interface.add_history_event(v_event_id,
                                             p_ticket_id,
                                             101001,
                                             p_host_id,
                                             v_company_id,
                                             'New ticket created',
                                             NULL,
                                             TRUE, 
                                             clock_timestamp(),
                                             v_contact_id);


        CALL event_interface.exec_event_type_actions(p_event_id);


        IF (v_create_cr = 1) THEN
            SELECT nextval('changerequest_seq') INTO STRICT v_cr_id;


            INSERT INTO change_request(id, change_request_state_id, description, requester_id, approver_id, creation_date, approval_denial_date, ticket_id)
            VALUES (v_cr_id,
                    3, 
                    v_details_public, 
                    v_contact_id, 
                    v_contact_id, 
                    statement_timestamp(),
                    statement_timestamp(),
                    p_ticket_id);
        END IF;

        CALL ticket_interface.updateticketflow(p_ticket_id);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE ticket_interface.newticket_new (p_ticket_id OUT bigint, p_event_id OUT bigint, p_ticket_type_id bigint, p_subject text, p_event_type_id bigint, p_host_id bigint, p_details_public text, p_details_private text DEFAULT NULL, p_contact_id bigint DEFAULT NULL, p_worker_id bigint DEFAULT NULL, p_public_event boolean DEFAULT TRUE, p_eventdate timestamp(0) DEFAULT clock_timestamp(), p_company_id bigint DEFAULT NULL, p_service_component_id bigint DEFAULT NULL) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE ticket_interface.change_deferral_date (p_ticket_id bigint, p_contact_id bigint, p_defer_date timestamp(0), p_details_public tt.event.details_public%TYPE) AS $body$
DECLARE


        v_host_id bigint;
        v_ticket_status_id bigint;
        v_event_id bigint;

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        SELECT status_id INTO STRICT v_ticket_status_id
        FROM tt.ticket t
        WHERE t.id = p_ticket_id;


        IF (v_ticket_status_id = 60) THEN
            SELECT t.host_id INTO STRICT v_host_id
            FROM tt.ticket t
            WHERE t.id = p_ticket_id;

            UPDATE tt.ticket t
            SET t.status_valid_until_date = p_defer_date, t.last_deferral_date = p_defer_date
            WHERE t.id = p_ticket_id;

            CALL event_interface.addevent_new(v_event_id, p_ticket_id, 100003, v_host_id, p_details_public, NULL, p_contact_id);
        ELSE
            plog.warning('tt.ticket_interface.change_deferral_date(): called for ticket ' || p_ticket_id || ' but it is not deferred. status id: ' || v_ticket_status_id);
        END IF;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE ticket_interface.change_deferral_date (p_ticket_id bigint, p_contact_id bigint, p_defer_date timestamp(0), p_details_public tt.event.details_public%TYPE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE ticket_interface.change_status (p_ticket_id bigint, p_status_id bigint, p_contact_id bigint, p_details_public text, p_details_private text DEFAULT NULL, p_valid_until_date timestamp(0) DEFAULT null, p_defer_event bigint DEFAULT null, p_escalate_after_defer boolean DEFAULT NULL, p_hot_reason text DEFAULT NULL) AS $body$
DECLARE


        ev_id bigint;


BEGIN
        
         CALL ticket_interface.change_status_event_id_out(ev_id,
                                   p_ticket_id,
                                   p_status_id,
                                   p_contact_id,
                                   p_details_public,
                                   p_details_private,
                                   p_valid_until_date,
                                   p_defer_event,
                                   p_escalate_after_defer,
                                   p_hot_reason);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE ticket_interface.change_status (p_ticket_id bigint, p_status_id bigint, p_contact_id bigint, p_details_public text, p_details_private text DEFAULT NULL, p_valid_until_date timestamp(0) DEFAULT null, p_defer_event bigint DEFAULT null, p_escalate_after_defer boolean DEFAULT NULL, p_hot_reason text DEFAULT NULL) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE ticket_interface.change_status_event_id_out (event_id OUT bigint, p_ticket_id bigint, p_status_id bigint, p_contact_id bigint, p_details_public text, p_details_private text DEFAULT NULL, p_valid_until_date timestamp(0) DEFAULT NULL, p_defer_event bigint DEFAULT NULL, p_escalate_after_defer boolean DEFAULT NULL, p_hot_reason text DEFAULT NULL) AS $body$
DECLARE


        dets_pub varchar(2000);
        status_name varchar(100);
        v_cur_status_name varchar(100);
        l_ticket_type_id bigint;
        l_events_were_moved bigint := NULL;
        v_cur_status bigint;
        v_escalation_status_id bigint;
        v_cur_valid_until_date timestamp(0);
        v_cur_status_changed_date timestamp(0);
        v_details_private tt.event.details_private%TYPE;
        v_event_type_id bigint;
        v_handled_by_mcc bigint;
        v_hot_event_id bigint;
        v_last_public_event_id bigint;
        v_last_public_event_type_id bigint;
        v_now timestamp(0);
        v_last_deferral_date timestamp(0);
        v_ux_timeout_start TIMESTAMP WITH TIME ZONE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        plog.debug('changestatus called');

        SELECT t.status_id, t.handled_by_mcc, t.last_public_event_id, t.escalation_status_id, t.status_valid_until_date,
               t.last_status_change_date, t.last_deferral_date, clock_timestamp()
        INTO STRICT   v_cur_status, v_handled_by_mcc, v_last_public_event_id, v_escalation_status_id, v_cur_valid_until_date, v_cur_status_changed_date, v_last_deferral_date, v_now
        FROM   tt.ticket t
        WHERE  t.id = p_ticket_id;

        v_last_public_event_type_id := NULL;
        IF (v_last_public_event_id IS NOT NULL) THEN
            SELECT event.type_id INTO STRICT v_last_public_event_type_id
            FROM   tt.event
            WHERE  event.id = v_last_public_event_id;
        END IF;


        IF (v_cur_status = p_status_id) THEN
            RETURN;
        END IF;


        
        IF (v_cur_status IN (2, 11, 12, 60, 61, 101)) THEN
            CALL ticket_interface.updatetickettimestats(p_ticket_id, v_cur_status, v_cur_status_changed_date);
        END IF;


        UPDATE tt.ticket t
        SET    t.status_id = p_status_id,
               t.last_status_change_date = clock_timestamp()
        WHERE  t.id = p_ticket_id;

        IF (v_last_deferral_date < v_now) THEN
            UPDATE tt.ticket t SET t.last_deferral_date  = NULL WHERE t.id = p_ticket_id;
        END IF;


        SELECT name INTO STRICT status_name FROM status WHERE id = p_status_id;
        SELECT name INTO STRICT v_cur_status_name FROM status WHERE id = v_cur_status;

        dets_pub := 'New status: ' || status_name || CHR(10) || 'Previous status: ' || v_cur_status_name;
        dets_pub := dets_pub || CHR(10) || p_details_public;

        IF (p_escalate_after_defer) THEN
            dets_pub := dets_pub || ', escalation to os when reached.';
        END IF;


        IF (p_hot_reason IS NOT NULL AND p_status_id = 3) THEN
            
            v_details_private := 'Hot because: ' || p_hot_reason || CHR(10) || p_details_private;
        ELSE
            v_details_private := p_details_private;
        END IF;


        SELECT type_id INTO STRICT l_ticket_type_id FROM tt.ticket WHERE id = p_ticket_id;


        IF (p_status_id = 60 OR v_cur_status = 60) THEN
            IF (p_status_id = 60) THEN
                IF (p_escalate_after_defer) THEN
                    
                    UPDATE tt.ticket SET escalation_status_id = 20 WHERE ticket.id = p_ticket_id AND escalation_status_id NOT in (10,11);
                    UPDATE tt.ticket SET last_deferral_escalated = 1 WHERE ticket.id = p_ticket_id;
                ELSE
                    UPDATE tt.ticket SET last_deferral_escalated = 0 WHERE ticket.id = p_ticket_id;
                END IF;
            END IF;
            CALL ticket_interface.handledeferredtransitions(p_ticket_id,p_status_id,v_cur_status,p_valid_until_date, p_contact_id);
        END IF;


        v_event_type_id := 101000 + p_status_id;


        tt.CALL event_interface.add_history_event(event_id,
                                             p_ticket_id,
                                             v_event_type_id,
                                             NULL,     
                                             NULL,     
                                             dets_pub,
                                             v_details_private,
                                             TRUE,     
                                             clock_timestamp(),  
                                             p_contact_id);


        
        IF (p_status_id = 3 AND v_handled_by_mcc = 0) THEN
            
            tt.CALL event_interface.add_history_event(v_hot_event_id,
                                                 p_ticket_id,
                                                 100008,
                                                 NULL,
                                                 NULL,
                                                 NULL,  
                                                 'This non-MCC ticket just became hot.',
                                                 FALSE, 
                                                 clock_timestamp(),
                                                 p_contact_id);
        END IF;


        IF (p_status_id = 101) THEN
            UPDATE ticket SET last_resolved_date = clock_timestamp() WHERE ticket.id=p_ticket_id;
        END IF;


        
        IF (p_status_id = 120) THEN
            
            CALL TT.OSAG_NOTIFY.delete_ticket_notifications(p_ticket_id);

            UPDATE ticket SET last_resolved_date = clock_timestamp(), escalation_status_id = 0 WHERE ticket.id=p_ticket_id;
        END IF;


        
        
        
        IF (p_status_id IN (2, 4, 11, 12, 60, 61, 101) AND v_cur_status != 60 AND p_contact_id IS NOT NULL) THEN
            
            IF (v_escalation_status_id = 20) THEN
                CALL event_interface.addevent_new(event_id, p_ticket_id, 60102, null, 'Open Systems Mission Control engineer has acknowledged this ticket.'||CHR(10)||'The escalation process has finished.',null,p_contact_id);
                UPDATE tt.ticket SET escalation_status_id = 0 WHERE id = p_ticket_id;

            ELSIF (v_escalation_status_id IN (10,11)) THEN
                CALL event_interface.addevent_new(event_id, p_ticket_id, 60002, null, 'Open Systems Mission Control engineer has acknowledged this ticket.'||CHR(10)||'The escalation process has finished.',null,p_contact_id);
                UPDATE tt.ticket SET escalation_status_id = 0 WHERE id = p_ticket_id;
            END IF;
        END IF;


        IF (p_status_id IN (11, 12, 61) AND p_valid_until_date IS NOT NULL) THEN
            CALL tt.util.update_status_valid_until(p_ticket_id, p_valid_until_date);
        ELSE
            CALL tt.util.update_status_valid_until(p_ticket_id);
        END IF;


        
        IF (p_status_id IN (2, 3, 4) AND NOT v_last_public_event_type_id IN (30016)) THEN
            
            IF (v_cur_status = 101) THEN
                UPDATE tt.ticket SET recoverable_status_id = v_cur_status WHERE id = p_ticket_id;


                
            ELSIF (v_cur_status IN (11, 12, 61) AND (v_handled_by_mcc = 0 OR v_cur_valid_until_date > v_now)) THEN
                UPDATE tt.ticket SET recoverable_status_id = v_cur_status WHERE id = p_ticket_id;


            ELSIF (v_cur_status = 60 AND v_cur_valid_until_date > v_now) THEN
                UPDATE tt.ticket SET recoverable_status_id = v_cur_status WHERE id = p_ticket_id;
            END IF;
        ELSE
            UPDATE tt.ticket SET recoverable_status_id  = NULL WHERE id = p_ticket_id;
        END IF;


        
        IF (p_status_id IN (2, 3, 4) AND v_cur_status IN (11, 12, 60, 61, 101)) THEN
            
            SELECT (cast(eventdate as timestamp) AT TIME ZONE 'EUROPE/ZURICH')::timestamp with time zone INTO STRICT v_ux_timeout_start FROM tt.event WHERE id = event_id;
            UPDATE tt.ticket SET ux_timeout_start = v_ux_timeout_start WHERE id = p_ticket_id;
        END IF;
        CALL ticket_interface.update_ux_timeout_for_ticket(p_ticket_id, FALSE);


        CALL ticket_interface.updateticketflow(p_ticket_id, v_cur_status, v_cur_status_changed_date);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE ticket_interface.change_status_event_id_out (event_id OUT bigint, p_ticket_id bigint, p_status_id bigint, p_contact_id bigint, p_details_public text, p_details_private text DEFAULT NULL, p_valid_until_date timestamp(0) DEFAULT NULL, p_defer_event bigint DEFAULT NULL, p_escalate_after_defer boolean DEFAULT NULL, p_hot_reason text DEFAULT NULL) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE ticket_interface.update_ux_timeout_for_ticket (p_ticket_id tt.ticket.id%TYPE, p_is_initial boolean) AS $body$
DECLARE


        v_type_id bigint;
        v_emergency bigint;
        v_handled_by_mcc bigint;
        v_status_id bigint;
        v_ux_timeout TIMESTAMP WITH TIME ZONE;
        v_ux_timeout_start TIMESTAMP WITH TIME ZONE;
        v_service_window_end TIMESTAMP WITH TIME ZONE;
        v_ux_timeout_delta INTERVAL DAY TO SECOND;
        v_ticket_has_service_window bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        SELECT type_id, emergency, ux_timeout_start, handled_by_mcc, status_id
        INTO STRICT v_type_id, v_emergency, v_ux_timeout_start, v_handled_by_mcc, v_status_id
        FROM tt.ticket
        WHERE id = p_ticket_id;


        
        
        
        IF (v_type_id = 4 OR v_type_id = 5 OR v_handled_by_mcc = 0 OR v_status_id > 4) THEN
            UPDATE ticket SET ux_timeout  = NULL WHERE id=p_ticket_id;
            RETURN;
        END IF;


        IF (v_emergency = 1) THEN
            IF (p_is_initial) THEN
                v_ux_timeout_delta := INTERVAL '60' MINUTE;
            ELSE
                v_ux_timeout_delta := INTERVAL '120' MINUTE;
            END IF;
        ELSE

            IF (v_type_id = 1 OR v_type_id = 6) THEN
                IF (p_is_initial) THEN
                    v_ux_timeout_delta := INTERVAL '120' MINUTE;
                ELSE
                    v_ux_timeout_delta := INTERVAL '240' MINUTE;
                END IF;

            ELSIF (v_type_id = 2 OR v_type_id = 14 OR  v_type_id = 15 OR v_type_id = 8) THEN
                v_ux_timeout_delta := INTERVAL '480' MINUTE;

            ELSIF (v_type_id = 11) THEN
                v_ux_timeout_delta := INTERVAL '960' MINUTE;

            ELSIF (v_type_id = 9) THEN
                v_ux_timeout_delta := INTERVAL '720' MINUTE;

            ELSIF (v_type_id = 12) THEN
                SELECT COUNT(*) INTO STRICT v_ticket_has_service_window
                FROM tt.service_window s
                WHERE p_ticket_id = s.ticket_id;

                IF (v_ticket_has_service_window > 0) THEN

                    SELECT (cast(end_date as timestamp) AT TIME ZONE 'EUROPE/ZURICH')::timestamp with time zone
                    INTO STRICT v_service_window_end
                    FROM tt.service_window
                    WHERE ticket_id = p_ticket_id  LIMIT 1;

                    IF (v_service_window_end > v_ux_timeout_start) THEN

                        v_ux_timeout_start := v_service_window_end;
                        v_ux_timeout_delta := INTERVAL '60' MINUTE;
                    ELSE
                        v_ux_timeout_delta := INTERVAL '480' MINUTE;
                    END IF;
                ELSE
                    v_ux_timeout_delta := INTERVAL '480' MINUTE;
                END IF;

            END IF;
        END IF;

        v_ux_timeout := v_ux_timeout_start + v_ux_timeout_delta;
        UPDATE ticket SET ux_timeout = v_ux_timeout WHERE id=p_ticket_id;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE ticket_interface.update_ux_timeout_for_ticket (p_ticket_id tt.ticket.id%TYPE, p_is_initial boolean) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE ticket_interface.change_worker (p_ticket_id bigint, p_worker_id bigint, p_contact_id bigint, p_handled_by_mcc bigint DEFAULT 0, p_is_emergency bigint DEFAULT 0, p_reason text DEFAULT NULL) AS $body$
DECLARE


        cust_id bigint;
        new_shrt varchar(50);
        old_shrt varchar(50);
        new_mcc_flag varchar(20) := NULL;
        old_mcc_flag varchar(20) := NULL;
        v_handled_by_mcc bigint;
        v_status bigint;
        v_private_detail varchar(255);
        v_worker_id stop.contact.id%TYPE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        BEGIN

            SELECT short, id INTO STRICT new_shrt, v_worker_id
            FROM stop.contact
            WHERE id = p_worker_id;

        EXCEPTION
            WHEN no_data_found THEN
                new_shrt := 'MCC';
                new_mcc_flag := '';
                v_worker_id := NULL;
        END;

        BEGIN

            SELECT c.short, t.handled_by_mcc INTO STRICT old_shrt, v_handled_by_mcc
            FROM stop.contact c, tt.ticket t
            WHERE t.id = p_ticket_id AND
                    t.worker_id = c.id;

        EXCEPTION
            WHEN no_data_found THEN
                old_shrt := 'MCC';
                old_mcc_flag := '';
                v_handled_by_mcc := 1;
        END;


        UPDATE ticket
        SET worker_id = v_worker_id
        WHERE ticket.id = p_ticket_id;


        IF (v_handled_by_mcc != p_handled_by_mcc) THEN
            UPDATE ticket
            SET handled_by_mcc = p_handled_by_mcc
            WHERE ticket.id = p_ticket_id;

            CALL ticket_interface.update_ux_timeout_for_ticket(p_ticket_id, FALSE);
        END IF;


        SELECT company_id into STRICT cust_id
        FROM ticket WHERE id = p_ticket_id;


        IF (old_shrt != 'MCC') THEN
            IF (v_handled_by_mcc = 1) THEN
                old_mcc_flag := ' (MCC)';
            ELSE
                old_mcc_flag := ' (non-MCC)';
            END IF;
        END IF;


        IF (new_shrt != 'MCC') THEN
            IF (p_handled_by_mcc = 1) THEN
                new_mcc_flag := ' (MCC)';
            ELSE
                new_mcc_flag := ' (non-MCC)';
            END IF;
        END IF;


        v_private_detail := 'Engineer changed to: ' || new_shrt || new_mcc_flag || '. Was: ' || old_shrt || old_mcc_flag || '.';
        IF (p_reason IS NOT NULL) THEN
            v_private_detail := v_private_detail || CHR(10) || 'Reason: ' || p_reason;
        END IF;

        INSERT into event(id,public_event,type_id,host_id,company_id,ticket_id,contact_id,details_private)
        VALUES (nextval('event_sequence'),
                0,
                100003,
                NULL,
                cust_id,
                p_ticket_id,
                p_contact_id,
                v_private_detail);

        CALL ticket_interface.updateticketflow(p_ticket_id);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE ticket_interface.change_worker (p_ticket_id bigint, p_worker_id bigint, p_contact_id bigint, p_handled_by_mcc bigint DEFAULT 0, p_is_emergency bigint DEFAULT 0, p_reason text DEFAULT NULL) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE ticket_interface.change_service_host (p_ticket_id bigint, p_service_id bigint, p_host_id bigint, p_contact_id bigint) AS $body$
DECLARE


        cust_id bigint;
        v_host_label_old varchar(100);
        v_host_label_new varchar(100);
        v_service_id_old bigint;
        v_service_label_old varchar(300);
        v_service_label_new varchar(300);
        v_details_public varchar(600);


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        SELECT company_id into STRICT cust_id
        FROM tt.ticket WHERE id = p_ticket_id;

        BEGIN

            SELECT s.id, st.name INTO STRICT v_service_id_old, v_service_label_old
            FROM mss.service_type st, mss.service s, tt.ticket t
            WHERE t.id = p_ticket_id AND
                    t.mss_service_id = s.id AND
                    s.service_type_id = st.id;

            v_service_label_old := ' (' || v_service_label_old || ' [' || v_service_id_old || '])';

        EXCEPTION
            WHEN no_data_found THEN
                v_service_label_old := NULL;
        END;

        BEGIN

            SELECT st.name INTO STRICT v_service_label_new
            FROM mss.service_type st, mss.service s
            WHERE s.service_type_id = st.id AND
                    s.id = p_service_id;

            v_service_label_new := ' (' || v_service_label_new || ' [' || p_service_id || '])';

        EXCEPTION
            WHEN no_data_found THEN
                v_service_label_new := NULL;
        END;

        BEGIN

            SELECT h.name INTO STRICT v_host_label_old
            FROM mss.host h, tt.ticket t
            WHERE t.id = p_ticket_id AND h.id = t.host_id;

            v_host_label_old := ' ' || v_host_label_old;
        EXCEPTION
            WHEN no_data_found THEN
                v_host_label_old := ' <empty>';
        END;

        BEGIN

            SELECT name INTO STRICT v_host_label_new
            FROM mss.host
            WHERE  id = p_host_id;
            v_host_label_new := ' ' || v_host_label_new;
        EXCEPTION
            WHEN no_data_found THEN
                v_host_label_new := ' <empty>';
        END;

        v_details_public := 'service changed from' || v_host_label_old || v_service_label_old  || ' to' || v_host_label_new || v_service_label_new;


        INSERT into tt.event(id,type_id,company_id,details_public,contact_id,ticket_id)
        VALUES (nextval('event_sequence'),
                100003,
                cust_id,
                v_details_public,
                p_contact_id,
                p_ticket_id);


        UPDATE tt.ticket
        SET mss_service_id = p_service_id,
            host_id = p_host_id
        WHERE id = p_ticket_id;



    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE ticket_interface.change_service_host (p_ticket_id bigint, p_service_id bigint, p_host_id bigint, p_contact_id bigint) FROM PUBLIC;



