CREATE OR REPLACE PROCEDURE ticket_interface.change_label (p_ticket_id bigint, p_label_id bigint, p_contact_id bigint) AS $body$
DECLARE


        v_change_text varchar(100);
        v_company_id bigint;
        v_label_name varchar(100);

        v_old_label_id bigint;
        v_old_label_name varchar(100);


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        SELECT company_id, label_id INTO STRICT v_company_id, v_old_label_id FROM ticket WHERE id=p_ticket_id;


        IF (v_old_label_id IS NULL) THEN
            v_old_label_name := 'null';
        ELSE
            SELECT name INTO STRICT v_old_label_name FROM label WHERE id=v_old_label_id;
        END IF;


        IF (p_label_id IS NULL) THEN
            v_change_text := 'Ticket label removed (was: ' || v_old_label_name || ')';
        ELSE
            SELECT name INTO STRICT v_label_name FROM label WHERE id=p_label_id;
            IF (v_old_label_id IS NULL) THEN
                v_change_text := 'Ticket label ' || v_label_name || ' added';
            ELSE
                v_change_text := 'Ticket label changed to ' || v_label_name || ' (was: ' || v_old_label_name || ')';
            END IF;
        END IF;

        CALL ticket_interface.change_label(p_ticket_id,p_label_id);


        INSERT into event(id, public_event, type_id, company_id, ticket_id, contact_id, details_private)
        VALUES (nextval('event_sequence'),
                0,
                100003,
                v_company_id,
                p_ticket_id,
                p_contact_id,
                v_change_text);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE ticket_interface.change_label (p_ticket_id bigint, p_label_id bigint, p_contact_id bigint) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE ticket_interface.expire_status (p_ticket_id bigint, p_valid_until timestamp(0), p_last_change timestamp(0), p_status_id bigint, p_status_name text, p_label_id bigint) AS $body$
DECLARE


        v_private_details varchar(4000);
        v_time_difference bigint := 0;
        v_label_name varchar(10);


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        v_time_difference := 24 * (p_valid_until - p_last_change);
        v_private_details := 'Status changed to: hot (was ' || p_status_name || ' for ' || round((v_time_difference)::numeric,2) || ' hours)';

        CALL ticket_interface.change_status(p_ticket_id,3,NULL,NULL,v_private_details);
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE ticket_interface.expire_status (p_ticket_id bigint, p_valid_until timestamp(0), p_last_change timestamp(0), p_status_id bigint, p_status_name text, p_label_id bigint) FROM PUBLIC;



