CREATE OR REPLACE PROCEDURE ticket_interface.change_owner (p_ticket_id bigint, p_owner_id bigint, p_contact_id bigint) AS $body$
DECLARE


        cust_id bigint;
        first_name varchar(50);
        last_name varchar(50);
        v_details_public varchar(300);
        v_company_id bigint;



BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        IF (p_owner_id IS NOT NULL) THEN

            SELECT firstname, lastname into STRICT first_name, last_name
            FROM stop.contact
            WHERE id = p_owner_id;

            v_details_public := 'ticket owner changed to ' || first_name || ' ' || last_name;

            SELECT company_id INTO STRICT v_company_id
            FROM stop.contact
            WHERE id = p_owner_id;
        ELSE
            v_details_public := 'ticket owner changed to <empty>';


            SELECT company_id into STRICT v_company_id
            FROM tt.ticket WHERE id = p_ticket_id;
        END IF;


        UPDATE tt.ticket
        SET contact_id = p_owner_id,
            company_id = v_company_id
        WHERE id = p_ticket_id;


        INSERT into event(id,type_id,company_id,ticket_id, contact_id, details_public)
        VALUES (nextval('event_sequence'),
                100003,
                v_company_id,
                p_ticket_id,
                p_contact_id,
                v_details_public);

