CREATE OR REPLACE PROCEDURE ticket_interface.change_company (p_ticket_id bigint, p_company_id bigint, p_contact_id bigint) AS $body$
DECLARE


        v_ser_id bigint;
        v_companyshort varchar(40);
        v_old_company_short stop.company.short%TYPE;
        v_old_company_id stop.company.id%TYPE;
        v_old_host_name mss.host.name%TYPE;
        v_old_host_id mss.host.id%TYPE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        
        SELECT t.company_id, t.host_id INTO STRICT v_old_company_id, v_old_host_id FROM tt.ticket t WHERE t.id = p_ticket_id;

        IF (v_old_host_id IS NOT NULL) THEN
            SELECT h.name INTO STRICT v_old_host_name FROM mss.host h WHERE id = v_old_host_id;
        ELSE
            v_old_host_name := '<none>';
        END IF;

        IF (v_old_company_id IS NOT NULL) THEN
            SELECT c.short INTO STRICT v_old_company_short FROM stop.company c WHERE c.id = v_old_company_id;
        ELSE
            v_old_company_short := '<empty>';
        END IF;


        
        UPDATE ticket
        SET company_id = p_company_id, contact_id  = NULL, mss_service_id  = NULL, host_id  = NULL
        WHERE id = p_ticket_id;

        BEGIN

            SELECT short INTO STRICT v_companyshort
            FROM stop.company
            WHERE id=p_company_id;
        EXCEPTION
            WHEN no_data_found THEN
                v_companyshort := '<empty>';
        END;


        INSERT into event(id,type_id,company_id,ticket_id, contact_id,details_private,public_event)
        VALUES (nextval('event_sequence'),
                100003,
                p_company_id,
                p_ticket_id,
                p_contact_id,
                'company changed to ' || v_companyshort || CHR(10) || 'old company: '||v_old_company_short
                    ||CHR(10)||'old assigned host: '||v_old_host_name,
                0);


        DELETE FROM event_notification en
        WHERE EXISTS (SELECT en.id FROM auth.login l
                   WHERE en.ticket_id = p_ticket_id
                     AND en.login_id = l.id
                     AND l.company_id != 6);

        
        UPDATE tt.event_notification en
        SET en.company_id = p_company_id
        WHERE EXISTS (SELECT en.id FROM auth.login l
                   WHERE en.ticket_id = p_ticket_id
                     AND en.login_id = l.id
                     AND l.company_id = 6);


    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE ticket_interface.change_company (p_ticket_id bigint, p_company_id bigint, p_contact_id bigint) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE ticket_interface.change_emergency (p_ticket_id bigint, p_emergency bigint, p_contact_id bigint, p_is_new_ticket bigint DEFAULT 0) AS $body$
DECLARE


        change_text varchar(100);
        v_event_id bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        IF (p_emergency = 1) THEN
            change_text := 'ticket changed to emergency';
        ELSE
            change_text := 'ticket changed to non-emergency';
        END IF;

         CALL ticket_interface.add_status_change_event(v_event_id, p_ticket_id, change_text, p_contact_id);

        UPDATE ticket
        SET emergency = p_emergency, was_emergency = GREATEST(p_emergency, was_emergency)
        WHERE id=p_ticket_id;


        IF (p_is_new_ticket = 0) THEN
            CALL ticket_interface.update_ux_timeout_for_ticket(p_ticket_id, FALSE);
        ELSE
            CALL ticket_interface.update_ux_timeout_for_ticket(p_ticket_id, TRUE);
        END IF;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE ticket_interface.change_emergency (p_ticket_id bigint, p_emergency bigint, p_contact_id bigint, p_is_new_ticket bigint DEFAULT 0) FROM PUBLIC;



