CREATE OR REPLACE PROCEDURE ticket_interface.change_notification (p_ticket_id bigint, p_change_text_public text, p_change_text_private text, p_contact_id bigint) AS $body$
DECLARE


        EVENT_DETAILS_PREFIX CONSTANT varchar(64) := 'Notification settings changed' || CHR(10);

        v_event_id bigint;
        v_event_details_public varchar(4000);
        v_event_details_private varchar(4000);


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        IF (p_change_text_public IS NOT NULL) THEN
            v_event_details_public := EVENT_DETAILS_PREFIX || p_change_text_public;
        END IF;

        IF (p_change_text_private IS NOT NULL) THEN
            v_event_details_private := EVENT_DETAILS_PREFIX || p_change_text_private;
        END IF;

         CALL ticket_interface.add_status_change_event(v_event_id, p_ticket_id, v_event_details_public, p_contact_id, v_event_details_private);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE ticket_interface.change_notification (p_ticket_id bigint, p_change_text_public text, p_change_text_private text, p_contact_id bigint) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE ticket_interface.change_summary (p_ticket_id bigint, p_summary_private text, p_summary_public text, p_contact_id bigint) AS $body$
DECLARE


        old_summary_private varchar(16000);
        old_summary_public varchar(16000);
        v_event_id bigint;
        p_summary_rel_events_count bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        SELECT summary_private, summary_public, summary_relevant_events_count into STRICT old_summary_private, old_summary_public, p_summary_rel_events_count
        FROM ticket WHERE id = p_ticket_id;

        IF ((old_summary_private != p_summary_private OR
             old_summary_private IS NULL OR
             p_summary_private IS NULL) AND
            NOT(old_summary_private IS NULL AND p_summary_private IS NULL)) THEN

             CALL ticket_interface.add_status_change_event(v_event_id, p_ticket_id, NULL, p_contact_id,
                                    'private summary changed to:' || CHR(10) || SUBSTR(coalesce(p_summary_private, '<empty>'), 1, 3900));

            UPDATE ticket
            SET summary_private = p_summary_private
            WHERE id=p_ticket_id;
        END IF;

        IF ((old_summary_public != p_summary_public OR
             old_summary_public IS NULL OR
             p_summary_public IS NULL) AND
            NOT(old_summary_public IS NULL AND p_summary_public IS NULL)) THEN

             CALL ticket_interface.add_status_change_event(v_event_id, p_ticket_id,
                                    'public summary changed to:' || CHR(10) || SUBSTR(coalesce(p_summary_public, '<empty>'), 1, 3900), p_contact_id);
            p_summary_rel_events_count := 0;

            UPDATE ticket
            SET summary_public = p_summary_public,
                summary_relevant_events_count = p_summary_rel_events_count,
                last_summary_update = statement_timestamp()
            WHERE id=p_ticket_id;

        END IF;


    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE ticket_interface.change_summary (p_ticket_id bigint, p_summary_private text, p_summary_public text, p_contact_id bigint) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE ticket_interface.change_type (p_event_id OUT bigint, p_ticket_id bigint, p_type_id bigint, p_contact_id bigint) AS $body$
DECLARE


        v_company_id bigint;
        v_old_type_name varchar(40);
        v_type_name varchar(40);


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        SELECT company_id INTO STRICT v_company_id FROM ticket WHERE id=p_ticket_id;


        SELECT type.name INTO STRICT v_old_type_name FROM ticket_type type, ticket t WHERE type.id = t.type_id AND t.id = p_ticket_id;


        SELECT name INTO STRICT v_type_name FROM ticket_type WHERE id=p_type_id;


        UPDATE ticket SET type_id = p_type_id  WHERE id = p_ticket_id;


        INSERT into event(id,type_id,company_id,ticket_id, contact_id,details_public)
        VALUES (nextval('event_sequence'),100005,v_company_id, p_ticket_id, p_contact_id,'type changed from ' || v_old_type_name || ' to ' || v_type_name);


        SELECT currval('event_sequence') INTO STRICT p_event_id;

        CALL ticket_interface.update_ux_timeout_for_ticket(p_ticket_id, FALSE);
        CALL ticket_interface.updateticketflow(p_ticket_id);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE ticket_interface.change_type (p_event_id OUT bigint, p_ticket_id bigint, p_type_id bigint, p_contact_id bigint) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE ticket_interface.change_service_component (p_event_id OUT bigint, p_ticket_id bigint, p_service_component_id bigint, p_contact_id bigint) AS $body$
DECLARE


        v_company_id bigint;
        v_old_service_component_code varchar(40);
        v_old_service_component_name varchar(40);
        v_service_component_code varchar(40);
        v_service_component_name varchar(40);


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        SELECT company_id INTO STRICT v_company_id FROM ticket WHERE id=p_ticket_id;


        BEGIN
            SELECT sc.internal_code INTO STRICT v_old_service_component_code FROM mss.service_component sc, ticket t WHERE sc.id = t.service_component_id AND t.id = p_ticket_id;
            SELECT sc.name INTO STRICT v_old_service_component_name FROM mss.service_component sc, ticket t WHERE sc.id = t.service_component_id AND t.id = p_ticket_id;
        EXCEPTION WHEN no_data_found THEN
            v_old_service_component_code := '';
            v_old_service_component_name := '<empty>';
        END;


        BEGIN
            SELECT internal_code INTO STRICT v_service_component_code FROM mss.service_component WHERE id = p_service_component_id;
            SELECT name INTO STRICT v_service_component_name FROM mss.service_component WHERE id = p_service_component_id;
        EXCEPTION WHEN no_data_found THEN
            v_service_component_code := '';
            v_service_component_name := '<empty>';
        END;


        UPDATE ticket SET service_component_id = p_service_component_id  WHERE id = p_ticket_id;


        INSERT into event(id,type_id,company_id,ticket_id,contact_id,details_public,details_private)
        VALUES (nextval('event_sequence'),100003,v_company_id, p_ticket_id, p_contact_id,
                'service component changed',
                'service component changed from ' || v_old_service_component_name || ' (' || v_old_service_component_code || ') to ' || v_service_component_name || ' (' || v_service_component_code || ')');


        SELECT currval('event_sequence') INTO STRICT p_event_id;

        CALL ticket_interface.update_ux_timeout_for_ticket(p_ticket_id, FALSE);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE ticket_interface.change_service_component (p_event_id OUT bigint, p_ticket_id bigint, p_service_component_id bigint, p_contact_id bigint) FROM PUBLIC;



CREATE OR REPLACE FUNCTION ticket_interface.get_next_recent_ticket (p_last_ticket_id bigint, p_host_id bigint, p_ticket_type_id bigint, p_resolve_age bigint ) RETURNS bigint AS $body$
DECLARE


        c_prefix  CONSTANT varchar(64) := 'ticket_interface.get_next_recent_ticket(): ';
        v_ticketid  bigint := NULL;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);


        SELECT MIN(t.id) INTO STRICT v_ticketid
        FROM tt.ticket t
        WHERE ( t.status_id < 102 ) AND (t.status_id <> 60)
          AND ( p_last_ticket_id IS NULL OR ( t.id > p_last_ticket_id ))
          AND ( p_host_id IS NULL        OR ( t.host_id = p_host_id )      OR ( p_host_id = 0 AND t.host_id IS NULL ))
          AND ( p_ticket_type_id IS NULL OR ( t.type_id = p_ticket_type_id ))
          AND ( p_resolve_age IS NULL
            OR t.status_id < 60   
            OR ((t.last_resolved_date IS NULL ) OR (clock_timestamp()-t.last_resolved_date)*86400 <= p_resolve_age) );

        RETURN v_ticketid;

    EXCEPTION
        WHEN OTHERS THEN
            plog.err(c_prefix||'unexpected error 99: '||sqlerrm);
            RETURN NULL;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION ticket_interface.get_next_recent_ticket (p_last_ticket_id bigint, p_host_id bigint, p_ticket_type_id bigint, p_resolve_age bigint ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE ticket_interface.merge_tickets (p_ticket_id bigint, p_mticket_id bigint, p_contact_id bigint) AS $body$
DECLARE


        v_event_id bigint;
        v_status_change_event_id bigint;
        v_partner_ref varchar(50);
        v_mpartner_ref varchar(50);
        v_fast_resolvable bigint;
        v_mfast_resolvable bigint;
        v_last_public_event_id bigint;
        v_mlast_public_event_id bigint;
        v_mlast_public_event_id_before bigint;
        v_last_public_event_date tt.event.eventdate%TYPE;
        v_mlast_public_event_date tt.event.eventdate%TYPE;
        v_cust_rating_id tt.ticket_rating.id%TYPE;
        v_mcust_rating_id tt.ticket_rating.id%TYPE;
        v_eng_rating_id tt.ticket_rating.id%TYPE;
        v_meng_rating_id tt.ticket_rating.id%TYPE;
        v_mstatus_id bigint;
        v_mrecoverable_status_id bigint;
        v_ux_timeout_start TIMESTAMP WITH TIME ZONE;
        v_mux_timeout_start TIMESTAMP WITH TIME ZONE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        SELECT partner_reference, fast_resolvable, last_public_event_id, ux_timeout_start, customer_ticket_rating_id, engineer_ticket_rating_id
        INTO STRICT   v_partner_ref, v_fast_resolvable, v_last_public_event_id, v_ux_timeout_start, v_cust_rating_id, v_eng_rating_id
        FROM   ticket
        WHERE  id = p_ticket_id;

        IF (v_last_public_event_id IS NOT NULL) THEN
            SELECT eventdate INTO STRICT v_last_public_event_date FROM tt.event WHERE id = v_last_public_event_id;
        END IF;


        SELECT partner_reference, fast_resolvable, last_public_event_id, recoverable_status_id, status_id, ux_timeout_start, customer_ticket_rating_id, engineer_ticket_rating_id
        INTO STRICT   v_mpartner_ref, v_mfast_resolvable, v_mlast_public_event_id, v_mrecoverable_status_id, v_mstatus_id, v_mux_timeout_start, v_mcust_rating_id, v_meng_rating_id
        FROM   ticket
        WHERE  id = p_mticket_id;

        IF (v_mlast_public_event_id IS NOT NULL) THEN
            SELECT eventdate INTO STRICT v_mlast_public_event_date FROM tt.event WHERE id = v_mlast_public_event_id;
        END IF;


        
        IF (v_cust_rating_id IS NOT NULL) THEN
            UPDATE tt.ticket SET customer_ticket_rating_id = coalesce(GREATEST(v_cust_rating_id, v_mcust_rating_id), v_cust_rating_id) WHERE id = p_mticket_id;
        END IF;


        IF (v_eng_rating_id IS NOT NULL) THEN
            UPDATE tt.ticket SET engineer_ticket_rating_id = coalesce(GREATEST(v_eng_rating_id, v_meng_rating_id), v_eng_rating_id) WHERE id = p_mticket_id;
        END IF;


        
        UPDATE tt.event
        SET org_ticket_id = ticket_id
        WHERE ticket_id = p_ticket_id and org_ticket_id IS NULL;

        UPDATE tt.event
        SET ticket_id = p_mticket_id
        WHERE ticket_id = p_ticket_id;


        CALL event_interface.addevent_new(v_event_id,
                                     p_mticket_id,
                                     100004,
                                     NULL,
                                     'ticket ' ||  p_ticket_id || ' merged with ticket no ' || p_mticket_id,
                                     p_mticket_id,
                                     p_contact_id);


        
        
        

        INSERT INTO event(id, company_id, details_private, details_public, eventdate, public_event,type_id, ticket_id, contact_id, host_id)
        SELECT nextval('event_sequence'), company_id, details_private, details_public, eventdate, public_event, type_id, p_ticket_id, contact_id, host_id
        FROM event
        WHERE id = v_event_id;


        UPDATE tt.ticket set merged_into_ticket_id = p_mticket_id WHERE id = p_ticket_id;


        CALL ticket_interface.change_status(p_ticket_id,110,p_contact_id,NULL);
        UPDATE ticket
        SET close_date = clock_timestamp(), last_resolved_date = clock_timestamp(), last_public_event_id  = NULL
        WHERE id = p_ticket_id;


        DELETE FROM tt.event_notification en1
        WHERE en1.ticket_id = p_ticket_id
          AND EXISTS (SELECT * FROM tt.event_notification en2
                      WHERE en2.ticket_id = p_mticket_id
                        AND en2.event_notification_type_id = en1.event_notification_type_id
                        AND en2.login_id = en1.login_id
                        AND (
                              (( en2.event_type_id is null and en1.event_type_id is null) or (en2.event_type_id = en1.event_type_id))
                              OR
                              (( en2.event_type_group_id is null and en1.event_type_group_id is null) or (en2.event_type_group_id = en1.event_type_group_id))
                          ) );


        UPDATE event_notification
        SET ticket_id = p_mticket_id
        WHERE ticket_id = p_ticket_id;


        UPDATE change_request
        SET ticket_id = p_mticket_id
        WHERE ticket_id = p_ticket_id;


        IF (v_mpartner_ref IS NULL AND v_partner_ref IS NOT NULL) THEN
            v_mpartner_ref := v_partner_ref;
        END IF;


        IF (v_fast_resolvable = 0 AND v_mfast_resolvable = 1) THEN
            v_mfast_resolvable := 0;
        END IF;


        
        v_mlast_public_event_id_before := v_mlast_public_event_id;
        IF (v_last_public_event_id IS NOT NULL AND v_mlast_public_event_id IS NOT NULL AND v_last_public_event_date > v_mlast_public_event_date) THEN
            v_mlast_public_event_id := v_last_public_event_id;
            v_mrecoverable_status_id := NULL;

        ELSIF (v_last_public_event_id IS NOT NULL AND v_mlast_public_event_id IS NULL) THEN
            v_mlast_public_event_id := v_last_public_event_id;
            v_mrecoverable_status_id := NULL;
        END IF;


        
        IF (v_ux_timeout_start > v_mux_timeout_start) THEN
            v_mux_timeout_start := v_ux_timeout_start;
        END IF;


        
        IF (v_mstatus_id = 101) THEN
            v_mrecoverable_status_id := 101;
        END IF;


        UPDATE guma2.suppressed_signature
        SET ticket_id = p_mticket_id
        WHERE ticket_id = p_ticket_id;


        UPDATE tt.ticket
        SET    partner_reference = v_mpartner_ref, fast_resolvable = v_mfast_resolvable, last_public_event_id = v_mlast_public_event_id, recoverable_status_id = v_mrecoverable_status_id, ux_timeout_start = v_mux_timeout_start
        WHERE  id = p_mticket_id;


        CALL ticket_interface.change_status(p_mticket_id,3,p_contact_id,NULL,NULL,NULL,NULL,NULL,'ticket ' ||  p_ticket_id || ' merged into this ticket');

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE ticket_interface.merge_tickets (p_ticket_id bigint, p_mticket_id bigint, p_contact_id bigint) FROM PUBLIC;



CREATE OR REPLACE FUNCTION ticket_interface.replace_id_placeholders (p_text text, p_ticket_id bigint, p_event_id bigint) RETURNS varchar AS $body$
DECLARE

        v_text varchar(30000);


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        v_text := substr(REPLACE(p_text, '##ticket_id##', p_ticket_id), 1, 30000);
        v_text := substr(REPLACE(v_text, '##event_id##', p_event_id), 1, 30000);
        RETURN v_text;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON FUNCTION ticket_interface.replace_id_placeholders (p_text text, p_ticket_id bigint, p_event_id bigint) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE ticket_interface.add_status_change_event (event_id OUT bigint, p_ticket_id bigint, p_public_change_text text, p_contact_id bigint, p_private_change_text text DEFAULT NULL) AS $body$
DECLARE


        cust_id bigint;
        v_public_event bigint := 1;


BEGIN

        
        
        
        IF (p_public_change_text IS NULL AND p_private_change_text IS NOT NULL) THEN
            v_public_event := 0;
        END IF;



        INSERT into event(id,type_id,company_id,ticket_id, contact_id, details_public,details_private,public_event)
        VALUES (nextval('event_sequence'),
                100003,
                cust_id,
                p_ticket_id,
                p_contact_id,
                p_public_change_text,
                p_private_change_text,
                v_public_event);


        SELECT currval('event_sequence') INTO STRICT event_id;


        CALL TT.OSAG_NOTIFY.event_notify(event_id, p_ticket_id);

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE ticket_interface.add_status_change_event (event_id OUT bigint, p_ticket_id bigint, p_public_change_text text, p_contact_id bigint, p_private_change_text text DEFAULT NULL) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE ticket_interface.trigger_escalation (p_ticket_id bigint, p_contact_id bigint, p_triggering_event_id bigint) AS $body$
DECLARE


        c_prefix       CONSTANT varchar(64) := 'ticket_interface.trigger_escalation(): ';

        v_event_id bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        tt.CALL event_interface.add_history_event(v_event_id,
                                             p_ticket_id,
                                             100007,
                                             NULL,     
                                             NULL,     
                                             'Explicitly trigger escalation',
                                             'Escalation triggered by event '||p_triggering_event_id,
