;
-- REVOKE ALL ON PROCEDURE ticket_interface.trigger_escalation (p_ticket_id bigint, p_contact_id bigint, p_triggering_event_id bigint) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE ticket_interface.rate_ticket (p_rating_id OUT bigint, p_ticket_id bigint, p_rating_event_id bigint, p_contact_id bigint, p_by_engineer bigint, p_rating_value bigint) AS $body$
DECLARE


        v_history_event_id bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        SELECT nextval('ticketrating_seq') INTO STRICT p_rating_id;

        INSERT INTO ticket_rating(id, rating, event_id)
        VALUES (p_rating_id, p_rating_value, p_rating_event_id);


        IF (p_by_engineer > 0) THEN
            UPDATE ticket
            SET engineer_ticket_rating_id = p_rating_id
            WHERE id = p_ticket_id;

        ELSE
            UPDATE ticket
            SET customer_ticket_rating_id = p_rating_id
            WHERE id = p_ticket_id;

            IF (p_rating_value < 3) THEN
                CALL ticket_interface.change_status(p_ticket_id, 3, p_contact_id, NULL);
            END IF;
        END IF;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE ticket_interface.rate_ticket (p_rating_id OUT bigint, p_ticket_id bigint, p_rating_event_id bigint, p_contact_id bigint, p_by_engineer bigint, p_rating_value bigint) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE ticket_interface.add_docs_page (p_ticket_docs_page_id OUT bigint, p_ticket_id bigint, p_page_id bigint, p_page_version bigint, p_page_title text, p_hot_issue bigint, p_contact_id bigint) AS $body$
DECLARE


        v_details_private varchar(4000);
        v_event_id bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        SELECT nextval('ticketdocspage_seq') INTO STRICT p_ticket_docs_page_id;

        INSERT INTO ticket_docs_page(id, ticket_id, page_id, page_version, hot_issue)
        VALUES (p_ticket_docs_page_id, p_ticket_id, p_page_id, p_page_version, p_hot_issue);

        
        v_details_private := 'Docs Page "' || p_page_title || '" (ID ' || p_page_id || ', v' || p_page_version
            || ') has been added to the ticket.';
        IF (p_hot_issue > 0) THEN
            v_details_private := 'Hot issue ' || v_details_private;
        END IF;
        CALL event_interface.addevent_new(v_event_id, p_ticket_id, 100009, null, '', v_details_private, p_contact_id, false);

    EXCEPTION
        WHEN OTHERS THEN
            plog.err('tt.ticketInterface.add_docs_page: Unexpected error: ' || sqlerrm );
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE ticket_interface.add_docs_page (p_ticket_docs_page_id OUT bigint, p_ticket_id bigint, p_page_id bigint, p_page_version bigint, p_page_title text, p_hot_issue bigint, p_contact_id bigint) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE ticket_interface.remove_docs_page (p_ticket_docs_page_id bigint, p_page_title text, p_contact_id bigint) AS $body$
DECLARE


        v_details_private varchar(4000);
        v_page_id bigint;
        v_page_version bigint;
        v_ticket_id bigint;
        v_event_id bigint;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        SELECT page_id, page_version, ticket_id
        INTO STRICT v_page_id, v_page_version, v_ticket_id
        FROM ticket_docs_page
        WHERE id = p_ticket_docs_page_id;


