;
-- REVOKE ALL ON PROCEDURE ticket_interface.remove_docs_page (p_ticket_docs_page_id bigint, p_page_title text, p_contact_id bigint) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE ticket_interface.handledeferredtransitions (p_ticket_id bigint, p_new_status_id bigint, p_cur_status_id bigint, p_defer_date timestamp(0), p_contact_id bigint) AS $body$
DECLARE


        ora2pg_rowcount int;
c_prefix  CONSTANT varchar(64) := 'ticket_interface.handledeferredtransitions(): ';

        v_escalation_status bigint;
        v_event_id bigint;



BEGIN

        
        SELECT escalation_status_id INTO STRICT v_escalation_status FROM ticket WHERE id = p_ticket_id;


        
        IF (v_escalation_status = 20 AND p_cur_status_id = 60) THEN
            
            IF (p_new_status_id IN (3,11,12,60,61,101)) THEN

                CALL event_interface.addevent_new(v_event_id, p_ticket_id,60001,null,
                                             'Starting escalation to Open Systems Mission Control','Event added by tt.handleDeferredTransitions. The ticket had a pending escalation (deferred) and changed its status to status '||p_new_status_id||'.');


                
                UPDATE tt.ticket SET escalation_status_id = 10, last_escalation_date = clock_timestamp() WHERE id = p_ticket_id;


            ELSIF (p_new_status_id IN (2,4)) THEN

                UPDATE ticket SET escalation_status_id = 0 WHERE id = p_ticket_id AND escalation_status_id = 20;


                GET DIAGNOSTICS ora2pg_rowcount = ROW_COUNT;
IF ora2pg_rowcount > 0) THEN
                    CALL event_interface.addevent_new(v_event_id, p_ticket_id,60001, null,
                                                 'Starting escalation to Open Systems Mission Control','Event added by tt.handleDeferredTransitions. The ticket had a pending escalation (deferred) and changed its status');
                    CALL event_interface.addevent_new(v_event_id, p_ticket_id, 60002, null,
                                                 'Open Systems Mission Control engineer has acknowledged this ticket.'||CHR(10)||'The escalation process has finished.','Immediate acknowledgment of the escalation as the ticket status has been manually changed.',p_contact_id);
                END IF;


            ELSIF (p_new_status_id = 120) THEN

                UPDATE tt.ticket SET escalation_status_id = 0 WHERE id = p_ticket_id;

            END IF;
        END IF;


        IF (p_new_status_id = 60) THEN
            UPDATE tt.ticket SET status_valid_until_date = p_defer_date, last_deferral_date = p_defer_date WHERE id = p_ticket_id;
        END IF;
    EXCEPTION
        WHEN OTHERS THEN
            plog.err(c_prefix||'unexpected error: '||sqlerrm);
            RETURN;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE ticket_interface.handledeferredtransitions (p_ticket_id bigint, p_new_status_id bigint, p_cur_status_id bigint, p_defer_date timestamp(0), p_contact_id bigint) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE ticket_interface.add_related_ticket (p_ticket_id tt.ticket.id%TYPE, p_related_ticket_id tt.ticket.id%TYPE, p_contact_id stop.contact.id%TYPE) AS $body$
DECLARE


        c_prefix  CONSTANT varchar(64) := 'ticket_interface.add_related_ticket(): ';

        v_details_private varchar(500);
        v_counter bigint;
        v_event_id tt.event.id%TYPE;

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        SELECT COUNT(*) INTO STRICT v_counter FROM tt.ticket t
        WHERE t.id IN (p_ticket_id, p_related_ticket_id);

        IF (v_counter != 2) THEN
            plog.err(c_prefix || 'One of the tickets involved does not exist or they are equal. Aborted!');
            RETURN;
        END IF;


        INSERT INTO ticket2related_ticket(ticket_id, related_ticket_id)
        VALUES (p_ticket_id, p_related_ticket_id);


        v_details_private := 'Related ticket ' || p_related_ticket_id || ' has been added to the ticket.';
        CALL event_interface.addevent_new(v_event_id, p_ticket_id, 100016, null, null, v_details_private, p_contact_id, false);
    EXCEPTION
        WHEN OTHERS THEN
            plog.err(c_prefix || 'Unexpected error: ' || sqlerrm );
            RETURN;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE ticket_interface.add_related_ticket (p_ticket_id tt.ticket.id%TYPE, p_related_ticket_id tt.ticket.id%TYPE, p_contact_id stop.contact.id%TYPE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE ticket_interface.remove_related_ticket (p_ticket_id tt.ticket.id%TYPE, p_related_ticket_id tt.ticket.id%TYPE, p_contact_id stop.contact.id%TYPE) AS $body$
DECLARE


        c_prefix  CONSTANT varchar(64) := 'ticket_interface.remove_related_ticket(): ';

        v_counter bigint;
        v_details_private varchar(500);
        v_event_id tt.event.id%TYPE;

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        SELECT COUNT(*) INTO STRICT v_counter FROM tt.ticket2related_ticket rt
        WHERE rt.ticket_id = p_ticket_id AND rt.related_ticket_id = p_related_ticket_id;

        IF (v_counter > 0) THEN

            DELETE FROM tt.ticket2related_ticket
            WHERE ticket_id = p_ticket_id AND related_ticket_id = p_related_ticket_id;


            v_details_private := 'Removed ticket ' || p_related_ticket_id || ' from the list of related tickets.';
            CALL event_interface.addevent_new(v_event_id, p_ticket_id, 100017, null, null, v_details_private, p_contact_id, false);
        END IF;


    EXCEPTION
        WHEN OTHERS THEN
            plog.err(c_prefix || 'Unexpected error: ' || sqlerrm );
            RETURN;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE ticket_interface.remove_related_ticket (p_ticket_id tt.ticket.id%TYPE, p_related_ticket_id tt.ticket.id%TYPE, p_contact_id stop.contact.id%TYPE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE ticket_interface.add_related_file (p_ticket_id tt.ticket.id%TYPE, p_related_file_id mc.mc_file.id%TYPE, p_contact_id stop.contact.id%TYPE) AS $body$
DECLARE


        c_prefix  CONSTANT varchar(64) := 'ticket_interface.add_related_file(): ';

        v_file_display_name mc.mc_file.display_name%TYPE;
        v_details_private varchar(500);
        v_event_id tt.event.id%TYPE;

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        
        
        SELECT f.display_name INTO STRICT v_file_display_name FROM mc.mc_file f, mc.mc_file_release r, tt.ticket t
        WHERE t.id = p_ticket_id AND f.id = p_related_file_id and r.mc_file_id = f.id
          AND t.company_id = r.company_id;


        INSERT INTO tt.ticket2mc_file(ticket_id, mc_file_id)
        VALUES (p_ticket_id, p_related_file_id);


        v_details_private := 'Related file "' || v_file_display_name || '" (' || p_related_file_id || ') has been added to the ticket.';
        CALL event_interface.addevent_new(v_event_id, p_ticket_id, 100018, null, null, v_details_private, p_contact_id, false);

    EXCEPTION
        WHEN no_data_found THEN
            plog.err(c_prefix || 'MC File or ticket does not exits or they belong to different companies.');
            RETURN;

        WHEN OTHERS THEN
            plog.err(c_prefix || 'Unexpected error: ' || sqlerrm );
            RETURN;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE ticket_interface.add_related_file (p_ticket_id tt.ticket.id%TYPE, p_related_file_id mc.mc_file.id%TYPE, p_contact_id stop.contact.id%TYPE) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE ticket_interface.remove_related_file (p_ticket_id tt.ticket.id%TYPE, p_related_file_id mc.mc_file.id%TYPE, p_contact_id stop.contact.id%TYPE) AS $body$
DECLARE


        c_prefix  CONSTANT varchar(64) := 'ticket_interface.remove_related_file(): ';

        v_counter bigint;
        v_details_private varchar(500);
        v_event_id tt.event.id%TYPE;
