CREATE OR REPLACE PROCEDURE util.check_resolved_tickets () AS $body$
DECLARE


        cur_resolved CURSOR FOR
            SELECT tt.ticket.id
            FROM tt.ticket
            WHERE status_id = 101
              AND (clock_timestamp() - last_resolved_date) >= 14;

        rec_resolved  cur_resolved%ROWTYPE;
        v_eventdate timestamp(0);


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        FOR rec_resolved in cur_resolved

            LOOP
                CALL tt.ticket_interface.change_status(rec_resolved.id,102,NULL,'ticket resolved for more than 2 weeks, closing it automatically');
                UPDATE tt.ticket
                SET close_date = clock_timestamp()
                WHERE id = rec_resolved.id;


                CALL TT.OSAG_NOTIFY.delete_ticket_notifications(rec_resolved.id);

            END LOOP;


    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE util.check_resolved_tickets () FROM PUBLIC;



CREATE OR REPLACE PROCEDURE util.check_ticket_status () AS $body$
DECLARE



        
        
        t_cur_valid_date_not_null CURSOR FOR
            SELECT t.id as t_id,
                   t.status_valid_until_date as t_valid_until,
                   s.name as s_name,
                   t.last_status_change_date as t_last_change,
                   t.status_id as t_status_id,
                   t.label_id as label_id
            FROM   tt.ticket t, tt.status s
            WHERE  t.status_id = s.id AND t.status_id IN (11,12,60,61) AND t.status_valid_until_date < clock_timestamp();

        c_prefix CONSTANT varchar(64) := 'tt.util.check_ticket_status(): ';

        t_rec2 t_cur_valid_date_not_null%ROWTYPE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        FOR t_rec2 in t_cur_valid_date_not_null
            LOOP
                CALL ticket_interface.expire_status(t_rec2.t_id, t_rec2.t_valid_until,
                                               t_rec2.t_last_change, t_rec2.t_status_id,
                                               t_rec2.s_name, t_rec2.label_id);
            END LOOP;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE util.check_ticket_status () FROM PUBLIC;



CREATE OR REPLACE PROCEDURE util.update_status_valid_until (p_ticket_id bigint, p_valid_until_date timestamp(0) DEFAULT null) AS $body$
DECLARE


        l_type_id bigint;
        l_status_id bigint;
        l_emergency bigint := NULL;
        l_handled_by_mcc bigint := NULL;
        v_period_15min bigint := 1/96;
        v_period_30min bigint := 1/48;
        v_period_1h bigint := 1/24;
        v_period_2h bigint := 1/12;
        v_period_4h bigint := 1/6;
        v_period_8h bigint := 1/3;
        v_period_1d bigint := 1;
        v_period_2d bigint := 2;
        v_period_4d bigint := 4;
        v_period_7d bigint := 7;
        v_period_20d bigint := 20;
        v_period_60d bigint := 60;
        v_period_to_add bigint := 0;
        v_valid_until_date timestamp(0) := NULL;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        SELECT type_id, status_id, emergency, handled_by_mcc INTO STRICT l_type_id, l_status_id, l_emergency, l_handled_by_mcc
        FROM   tt.ticket
        WHERE  id = p_ticket_id;


        IF (l_status_id = 60) THEN
            RETURN;
        END IF;


        IF (l_status_id IN (11, 12, 61)) THEN
            
            IF (l_emergency = 1) THEN
                IF (p_valid_until_date IS NOT NULL
                    AND p_valid_until_date - clock_timestamp() > 0
                    AND p_valid_until_date - clock_timestamp() <= v_period_1d) THEN
                    v_valid_until_date := p_valid_until_date;
                    v_period_to_add := 0;
                ELSE
                    v_period_to_add := v_period_4h;
                END IF;

            ELSE
                IF (p_valid_until_date IS NOT NULL
                    AND p_valid_until_date - clock_timestamp() > 0
                    AND p_valid_until_date - clock_timestamp() <= v_period_60d) THEN
                    v_valid_until_date := p_valid_until_date;
                    v_period_to_add := 0;
                ELSE
                    v_period_to_add := v_period_20d;
                END IF;
            END IF;
        END IF;


        IF (v_period_to_add > 0) THEN
            UPDATE tt.ticket t SET t.status_valid_until_date = (clock_timestamp() + v_period_to_add) WHERE t.id = p_ticket_id;
        ELSIF (v_valid_until_date IS NOT NULL) THEN
            UPDATE tt.ticket t SET t.status_valid_until_date = v_valid_until_date WHERE t.id = p_ticket_id;
        ELSE

            
            UPDATE tt.ticket t SET t.status_valid_until_date  = NULL WHERE t.id = p_ticket_id;
        END IF;


        
        IF (l_status_id IN (11, 12, 61)) THEN
            UPDATE tt.ticket t SET t.last_deferral_date = p_valid_until_date WHERE t.id = p_ticket_id;
        END IF;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE util.update_status_valid_until (p_ticket_id bigint, p_valid_until_date timestamp(0) DEFAULT null) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE util.check_dnids_tickets_to_resolve () AS $body$
DECLARE


        cur_to_resolve CURSOR FOR
            SELECT t.id
            FROM tt.ticket t, tt.event e
            WHERE (clock_timestamp() - e.eventdate > 7 OR REGEXP_INSTR(e.details_public,'^DNIDS:SCAN:INFO:ALLCLEAN',1,1,0,'im') +
                                                REGEXP_INSTR(e.details_public,'^DNIPS:SLOWDOWN:ALLCLEAN',1,1,0,'im') > 0)

              AND e.id = t.last_public_event_id and  t.type_id = 5 and t.status_id < 101 AND e.type_id = 10020;

        rec_resolved  cur_to_resolve%ROWTYPE;


BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
        FOR rec_resolved in cur_to_resolve

            LOOP
                CALL tt.ticket_interface.change_status(rec_resolved.id,101,NULL,'Automatically resolving ticket.');
            END LOOP;


    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE util.check_dnids_tickets_to_resolve () FROM PUBLIC;



CREATE OR REPLACE PROCEDURE util.despam_ticket (p_ticket_id integer, p_limit integer DEFAULT 1000) AS $body$
DECLARE

      v_min integer;
      v_max integer;

  t RECORD;

BEGIN
      plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);
      for t in (select type_id, count(*)
                from tt.EVENT e
                where e.TICKET_ID = p_ticket_id
                group by type_id
                having count(*) > p_ limit) loop

          select min(e.id), max(e.id) into STRICT v_min, v_max
          from tt.EVENT e
          where e.TICKET_ID = p_ticket_id
            and e.TYPE_ID = t.TYPE_ID;

          delete
          from tt.EVENT e
          where e.TICKET_ID = p_ticket_id
            and e.TYPE_ID = t.TYPE_ID
            and e.id != (SELECT t.LAST_PUBLIC_EVENT_ID from tt.TICKET t where t.id = e.TICKET_ID)
            and e.id != v_min
            and e.id != v_max
            and not exists (select 1 from mc.ISP_LINK_HISTORY lh where lh.EVENT_ID = e.ID)
;
        end loop;
    end;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE util.despam_ticket (p_ticket_id integer, p_limit integer DEFAULT 1000) FROM PUBLIC;

--
-- dblink wrapper to call function util.close_old_dev_tickets() as an autonomous transaction
--
CREATE EXTENSION IF NOT EXISTS dblink;

CREATE OR REPLACE PROCEDURE util.close_old_dev_tickets () AS $body$
DECLARE
	-- Change this to reflect the dblink connection string
	v_conn_str  text := format('port=%s dbname=%s user=%s', current_setting('port'), current_database(), current_user);
	v_query     text;

BEGIN
	v_query := 'CALL util.close_old_dev_tickets_atx ()';
	PERFORM * FROM dblink(v_conn_str, v_query) AS p (ret boolean);

END;
$body$ LANGUAGE plpgsql SECURITY DEFINER;




CREATE OR REPLACE PROCEDURE util.close_old_dev_tickets_atx () AS $body$
DECLARE
c CURSOR FOR
          SELECT t.ID
          FROM tt.ticket t
          WHERE t.HANDLED_BY_MCC = 1
            AND t.STATUS_ID NOT IN (2, 102)
            AND t.STATUS_ID < 100 
            AND t.OPEN_DATE < ( clock_timestamp() - interval '30 days');

        v_is_dev bigint;
        v_ticket_to_close  c%ROWTYPE;

  r RECORD;

BEGIN
        plog.AuditUsage($$PLSQL_UNIT_OWNER, $$PLSQL_UNIT_TYPE, $$PLSQL_UNIT);

        SELECT count(*) into STRICT v_is_dev FROM V$INSTANCE WHERE HOST_NAME LIKE '%-dev-%';
        if v_is_dev = 0 THEN

            ROLLBACK;
            RETURN;
        END IF;


        FOR v_ticket_to_close IN c
            LOOP
                CALL tt.ticket_interface.change_status(v_ticket_to_close.ID, 102, null, 'Automatically closed after 30 days');

        END LOOP;


        FOR r in (SELECT e.TICKET_ID, count(*)
                  from tt.event e
                  group by e.TICKET_ID
                  having count(*) > 5000 
                  order by e.TICKET_ID desc) LOOP
            CALL util.despam_ticket(r.TICKET_ID, 100);
            COMMIT;
        END LOOP;
    END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE util.close_old_dev_tickets () FROM PUBLIC; -- REVOKE ALL ON PROCEDURE util.close_old_dev_tickets_atx () FROM PUBLIC;
-- End of Oracle package 'UTIL' declaration

